module("engagement_text", package.seeall)
data = {
  [100111] = {
    diary_text = "Interviewing me? I'm not exactly camera-shy, but I don't make a habit of appearing on screen, either."
  },
  [100121] = {
    diary_text = "I'm dressed like a Plain Jane when even Goldman is spiffed up! Hope no one notices..."
  },
  [100131] = {
    diary_text = "Why, God, my period just come?! I don't care about having my soul ripped apart, come take every last piece as long as it's painless! But I've totally ruined it now… Why do I have the knack for screwing things up?!"
  },
  [100141] = {
    diary_text = "Victor looks so dashing when he buries himself in work! I'm pretty sure his colleagues all feel the same way. We might complain now and then, but everyone in LFG is all in it together."
  },
  [100211] = {
    diary_text = "Everyone in LFG is gossiping about Victor hooking up with someone. They said he keeps calling the same woman and whispers sweet nothings to her."
  },
  [100221] = {
    diary_text = "I'm curious, what kind of girl would make someone so serious like him be attracted to?"
  },
  [100231] = {
    diary_text = "I've never seen Victor so sentimental like this. I can't tell which is the real him: The one who would stop at nothing to save a small animal, the one who just gave me his umbrella at the expense of himself getting soaked, or the one who spoke so romantically on the phone."
  },
  [100241] = {
    diary_text = "The drenched Victor looked like a pathetic wet cat without a thread of dignity. But I'd like to cheer him up since he was so nice. Hey, why are you giggling?"
  },
  [100311] = {
    diary_text = "Mastering French in two months is as inconceivable as going around the world in 80 days in the past."
  },
  [100321] = {
    diary_text = "But even though it's nigh impossible, I still have to give it my all. Who know what may happen?"
  },
  [100331] = {
    diary_text = "Victor might have given me the resources for the banquet out of the goodness of his heart, but what I really wanted is the assignment to France! I'll remember this, Victor!"
  },
  [100341] = {
    diary_text = "I did it, I really did it! All these months of working overnight were not in vain! Victor has no idea how to motivate his people, though, giving me the project but still handing me backhanded compliments before he left!"
  },
  [100411] = {
    diary_text = "Goldman is great at making a mountain out of a molehill. I thought it was something really serious and got scared for a second."
  },
  [100421] = {
    diary_text = "Victor only cracked a smile, don't read more into that."
  },
  [100431] = {
    diary_text = "My last comment to Victor was off-the-cuff that I thought he'd disregard as usual, but it might've actually struck a chord. He's now jovial toward the staff."
  },
  [100441] = {
    diary_text = "It's not my fault. Obviously, a lot of people aren't used to a smiling Victor yet, but this is a lot better than his tyrannical self who could explode at the drop of the hat! I just wanted him to relax more, but he's probably taking it too far…"
  },
  [100511] = {
    diary_text = "Finally, time off to enjoy the bright sunshine after so many days of work!"
  },
  [100521] = {
    diary_text = "I had things planned for such a lovely day, until I got a call from Goldman. I couldn't talk my way out of it, so here I am in LFG."
  },
  [100531] = {
    diary_text = "Sometimes it feels like I'm destined to work my behind off. I finally got through helping Goldman with the files and before I could get back to my awesome day off, Victor hijacked me. To thank him, I made him a \"special\" coffee, but he actually thought it tasted fine! What's wrong with him?"
  },
  [100541] = {
    diary_text = "At last, everything was done, leaving me with barely enough time for a movie. Then, Victor offered to go with me, and that was when I realized he drank the coffee because he didn't want to hurt my feelings... I got warm and fuzzy all of a sudden."
  },
  [100611] = {
    diary_text = "I could feel the tension as soon as I set foot inside the building. Goldman told me to watch out because Victor is in a bad mood."
  },
  [100621] = {
    diary_text = "My report kept getting interrupted by Victor' phone calls, so he told me to make the report tonight in his home."
  },
  [100631] = {
    diary_text = "After stuttering through the report, I was fixated on the piano in the living room. Victor said I could play it as my reward. What kind of reward is that?"
  },
  [100641] = {
    diary_text = "Victor fell asleep by the time I finished playing. I tried to put a blanket on him, only for him to wake up and see it."
  },
  [100711] = {
    diary_text = "Anna told me she needed me to dance with a top television director at the charity event. That puzzled me, but as a producer for the studio, I must comply for the sake of potential partnership."
  },
  [100721] = {
    diary_text = "Me with two left feet, the prospect of dancing worried me, to say the least. Imagine my surprise, however, when Victor offered to teach me out of the blue. I mean, at least I won't embarrass myself with a mentor like him, right?"
  },
  [100731] = {
    diary_text = "I couldn't even stand how clumsy I was, but Victor was extremely patient with me going through the steps. I was curious about how happy Victor seemed, though. Was he that enthused about me dancing with the director?"
  },
  [100741] = {
    diary_text = "I practiced hard and dolled myself up to the nines just so I could give a decent account of myself, but the director ended up no-showing the event. I gave a sigh of relief and before I could leave, Victor extended a hand to me with a smile, suave and graceful, inviting me to dance."
  },
  [100811] = {
    diary_text = "I ran into Leo at the airport on a business trip. I agreed with his suggestion to travel together since neither of us knew the lay of the land."
  },
  [100821] = {
    diary_text = "But the steward brought me right to Victor, who didn't take the news of me traveling with Leo well, even forbidding me from going back to my seat in economy class. What was wrong with him again?"
  },
  [100831] = {
    diary_text = "Watching Victor enjoying a glass of brandy, I told him I'd like to try it too but he shot that down unceremoniously. He seemed so intent on taking charge, yet when a turbulence hit, he held my hand gently and calmed me down. I just don't get him at all."
  },
  [100841] = {
    diary_text = "I discreetly asked the flight attendant for my own brandy, only to choke on the burning sensation as it went down my throat. How could Victor drink this? And he saw me getting tipsy from one sip. I didn't know whether I heard it wrong or he was drunk too, but did he say he would always be there for me?"
  },
  [100911] = {
    diary_text = "Victor has a knack for breaking up my fun. Just when I was about to dig into the strawberry ice cream, his phone call pulled me back to reality."
  },
  [100921] = {
    diary_text = "Maybe he got the wrong number, but he wasn't his normal self, telling me how much he missed me in a soft, sentimental voice that any girl would love to hear."
  },
  [100931] = {
    diary_text = "I tried to avoid him but still bumped into him. He mentioned the call this morning. Recalling his emotional words, I wanted to console him, even though I felt conflicted inside. I told him not to let distance constrain his love, but that infuriated him."
  },
  [100941] = {
    diary_text = "It wasn't until later when I found out he misdialed the number of his dearly departed mother. Seeing the loneliness on his face, I got this sudden urge to embrace him. But he asked me if the call was for another unrelated woman instead, would I say the same thing to him?"
  },
  [101011] = {
    diary_text = "The cruise was a dream vacation… until Victor went missing."
  },
  [101021] = {
    diary_text = "Not to spoil the trip for others, I set off to find him alone and spotted him leisurely reading a magazine by the pool! But I just lost my temper when seeing his face."
  },
  [101031] = {
    diary_text = "Felt like Victor was an entirely different person today, as if it was someone else in his skin. He was the polar opposite of the meticulous president of the company he had been. I believe behind that stuffy title he is just a big aloof boy with a heart of gold."
  },
  [101041] = {
    diary_text = "Victor must have either read my romance novels or learn it online to rattle off lines like that! Or maybe he got hacked… I don't know, but I couldn't help but turn into a babbling mess in front of him."
  },
  [101111] = {
    diary_text = "Finished the assignment Victor gave me. He uncharacteristically gave me days off. I noticed he's been working really hard too, so maybe I can take him there?"
  },
  [101121] = {
    diary_text = "Victor turned dour when he heard it's an animal cafe. From our conversation, he said he actually had a panda when he was little."
  },
  [101131] = {
    diary_text = "I forced him into the café to get him closer to animals. Didn't figure the kittens would love him so much!"
  },
  [101141] = {
    diary_text = "As I watched them play, I got sleepy and dozed off."
  },
  [101211] = {
    diary_text = "I waited for Victor at the Souvenir for his birthday until 5 p.m., but he didn't come. I ran to LFG to ask him. Actually it's just because his cell phone was out of power."
  },
  [101221] = {
    diary_text = "Finally, I found a reason to bring Victor to the Souvenir, but Goldman, Kiki and Mr. Mills, who had agreed to celebrate together, disappeared."
  },
  [101231] = {
    diary_text = "It's time to cut the cake. Victor asked me to make wishes for him, but it's his birthday. He's really strange."
  },
  [101241] = {
    diary_text = "I stepped on the line of the colored lights, and Victor fell to the ground with me in order to catch me. Because he protected me, I was not injured. And then he kept looking at me deeply."
  },
  [101411] = {
    diary_text = "Everyone went home for New Year's Eve, but I came to the East Coast alone to negotiate a major deal and an unexpected blizzard got me trapped in the airport. Then, Victor showed up…"
  },
  [101421] = {
    diary_text = "He shoved me into his car and told me this was his hometown. I was both giddy and nervous about meeting his family. Victor's father was succinct but kind. He told me a lot about Victor, so now I understand him better."
  },
  [101431] = {
    diary_text = "His aunt's arrival relaxed me. She excitedly showed me photos of Victor when he was a kid. Victor seemed more personable in his home, telling me his family liked me because I'm a nice girl. Suddenly, the snow hung still in the air and I felt his soft lips on my eyes."
  },
  [101441] = {
    diary_text = "We started playing mahjong after dinner with a rule that the loser must answer a question truthfully from the winner. I kept losing while Victor kept winning. I thought the Q&A brought us closer. I fell asleep on the couch from playing all night, with Victor next to me. A great start to the new year."
  },
  [101511] = {
    diary_text = "I learned that this weekend there's a lantern festival, with the lanterns all being made by famous craftsmen. On a whim, I decided to make a new show out of it, and Anna suggested that I take a date along with me. She said it'd be fun, but more importantly, everyone else at the company already had plans for the weekend. As I worried about finding someone to go with me, I thought of Chinese New Year's Eve..."
  },
  [101521] = {
    diary_text = "To thank Victor for helping me at the airport on New Year's Eve, I dialed his number and invited him to the lantern festival. At first I thought he would be his usual self and call me childish and boring, but on the contrary, he actually accepted. At the festival, I gifted Victor a lantern as a thank you, and to my surprise discovered a secret..."
  },
  [101531] = {
    diary_text = "I decided to get Victor a floating sky lantern. After buying one, as I started to write down my wish, I ran into a snag. I wanted so many things, I didn't know which one to wish for. I turned my head and snuck a glance at Victor standing beside me, only to see him writing particularly earnestly, one stroke at a time..."
  },
  [101541] = {
    diary_text = "After that little interlude, Victor and I returned to the stall selling the sky lanterns. As Victor helped me launch the lantern, my attention was caught by the huge lantern behind him-- it was a sky lantern used for marriage proposals. I was transfixed by it briefly, and when I snapped back to attention, I found that Victor was looking at me..."
  },
  [101611] = {
    diary_text = "Because of the storm causing flights to be cancelled, I booked a room at the hotel airport; and I also ran into a soaking-wet Victor, himself unable to book a room. I invited him to my room to dry himself off. He hesitated a bit but finally accepted."
  },
  [101621] = {
    diary_text = "To drown out the sound of the rain outside, I decided to turn on some music. Oddly enough, Victor also went along with my suggestion. I slowly inched closer, and he didn't seem to pull away... although I really don't know what's going on his head. Does he like me or hate me?"
  },
  [101631] = {
    diary_text = "The rained fell heavier and heavier, and suddenly the lights in the room went out. In the darkness, I was falling into a full-blown panic, but then suddenly, a firm pair of hands held me still. It was Victor. He was comforting me in a low voice, his hands caressing my shoulders. It was a tenderness I had never seen before. The wind outside blew stronger and stronger, but his baritone voice and his warm hands made me feel safe."
  },
  [101641] = {
    diary_text = "When the lights came back on, we played Truth or Dare. Because I was playing a bit unfair, he seemed a little unhappy... I really wanted to make him like me more, to confess what was in his heart under such romantic circumstances. Victor's answer made my heart race. Was he sincere? And was he serious about the \"end of the world\" promise he made?"
  },
  [101711] = {
    diary_text = "Today, I had the good fortune to witness negotiations between two large conglomerates, and I saw a completely unfamiliar side of Victor..."
  },
  [101721] = {
    diary_text = "Originally I thought the Victor I usually saw was already extremely harsh and domineering. Little did I know, at this negotiation, I would see an even more terrifying side of him. And then during a coffee break, I heard a confidential secret of LFG's..."
  },
  [101731] = {
    diary_text = "Victor was acting a little strange, calling me into the office to explain. He seemed to have discovered something, and he looked like he wanted to say something but was holding his tongue. It made me anxious. At the end of the day, I was preparing to leave when Victor intercepted me. Apparently he yelled at me about booking the restaurant all because..."
  },
  [101741] = {
    diary_text = "I never thought Victor would actually agree to go to the snack street with me. Seeing his looks soften in the presence of all the delicious foods, I suddenly felt that this really was the most beautiful scene. Even more beautiful was what he said..."
  },
  [101811] = {
    diary_text = "When I got to Victor's pool, I felt absolutely nothing could compel me to get in. But under Victor's intimidating stare, I worked up the courage to dip my foot in. Who knew---"
  },
  [101821] = {
    diary_text = "Victor let me acclimate myself in the shallow end, and he even threw me a swimming ring. It was printed with a childish design, and to be honest I didn't feel like accepting it."
  },
  [101831] = {
    diary_text = "Under Victor's instruction, I began to initiate myself in the art of swimming. I didn't expect that as soon as he let go, I would instantly be floundering around chaotically..."
  },
  [101841] = {
    diary_text = "Victor fetched my pendant from the water and then threatened to only return it after I learned to swim. I panicked and immediately went after him, totally forgetting that I was standing on the slippery ceramic floor. When he called out to me in warning, I had already slipped and lost my balance.."
  },
  [101911] = {
    diary_text = "With my quarterly proposal finally approved, I jokingly asked Victor for a reward. Surprisingly, he took me seriously."
  },
  [101921] = {
    diary_text = "I never would've imagined Victor would actually take me to an amusement park! To get him into the spirit, I sneakily put cat ears on him and found a surprisingly cute side of him."
  },
  [101931] = {
    diary_text = "After a stroll, he took me on a breathtaking ride through space and time. I was so scared I could hardly open my eyes, but he held my hand tight, making my heart race even more."
  },
  [101941] = {
    diary_text = "After the \"Time Traveler\", the parade started. More than the dazzling spectacle, what really shook me was when Victor gently kissed my hand and whispered a promise in my ear."
  },
  [102011] = {
    diary_text = "Finally came the day for Mr. Victor's examination after the 17-day Q&A test. It was at my home, but I still felt quite nervous as if making a report in LFG."
  },
  [102021] = {
    diary_text = "Victor seemed to be happy when finding the gilded camel and \"Couple Mug\" on my desk. My report went surprisingly well so I asked him to play game with me as a reward."
  },
  [102031] = {
    diary_text = "As I guessed, Victor had never used a controller so I had to teach him from scratch. It was my first time to discover that Victor could be cute when he frowned."
  },
  [102041] = {
    diary_text = "It didn't take much time before Victor went from entry to proficiency. Maybe for a genius like him, nothing is difficult. To celebrate the victory, I gave him a big bear hug, but…"
  },
  [102111] = {
    diary_text = "I wanted to scare Victor with a ghost story, but I ended up scaring myself. For dignity's sake, I must find something that Victor's afraid of during this vacation!"
  },
  [102121] = {
    diary_text = "Even though just looking at the ad for the new cliffside glass skywalk made me weak in the knees, I was determined to go with Victor. Too bad my plan backfired again."
  },
  [102131] = {
    diary_text = "Since the beach was packed, Victor took me in his yacht to a nearby deserted isle of spooky repute. Then a heavy storm arose, giving me a chance to test Victor's courage again! "
  },
  [102141] = {
    diary_text = "After one harrowing ship adventure, the weather finally cleared up. We had some nice, quiet hammock time, but in the end he still never told me what he's afraid of."
  },
  [102211] = {
    diary_text = "Victor didn't seem thrilled about having to put on traditional clothes for the role-playing game. Good thing he said he'd never back out on any of his promises to me!"
  },
  [102221] = {
    diary_text = "I selfishly chose this activity just to see what he looked like in traditional clothing-- and it did not disappoint. He drew the role of King of Liang, and I was a physician."
  },
  [102231] = {
    diary_text = "I realized that \"King of Liang\" had hidden a key item in the course of the game, and my suspicions led me to go after his wine decanter, but he ended up taking my hair pin instead."
  },
  [102241] = {
    diary_text = "This despicable King of Liang was not like what I saw in my dream! And he-- he actually ended up wedded to the physician?! No matter what, something just didn't seem to add up..."
  },
  [102311] = {
    diary_text = "Attracted by the pictures, I invited Victor to visit an ancient town with me. Although Victor refused my suggestion to go to the Taoist temple to pray for marriage, I was still curious about the marriage tree the moment I saw it..."
  },
  [102321] = {
    diary_text = "I wanted to persuade Victor to go to the Taoist Temple, but he showed the least interest. Suddenly, it began to rain, bringing a little pleasing coolness."
  },
  [102331] = {
    diary_text = "When we were sheltering from the rain, Victor seemed to have paused time. After the rain, Victor surprisingly agreed to go to the Taoist Temple. We came across an old Taoist priest who predicted for me my fate of love. He told me that my Mr. Right was between heaven and earth, within time."
  },
  [102341] = {
    diary_text = "The journey made me exhausted and listening to the rainfall, I fell asleep. I woke up to find myself leaning on Victor's back. Towards the colorful neon lights, we seemed to be walking together to the end of the world."
  },
  [102411] = {
    diary_text = "I was invited to the flower-themed pavilion today, but met with the mysterious investor there unexpectedly..."
  },
  [102421] = {
    diary_text = "The mysterious investor turned out to be Victor, who seldom attends such activities. After my persistent questioning, only did he tell me that Curator Kim and his father were close friends."
  },
  [102431] = {
    diary_text = "The pavilion had a fairytale themed zone and many other interesting themed zones. All of them could be used for the promotional video. But the funniest part had to be Victor wearing a camellia flower on his head. Later, I made a wish about Victor by the wishing pond."
  },
  [102441] = {
    diary_text = "I'd finally reached the huge maze but it scared me. Thanks to Victor, the maze trip was going on smoothly until we met a forked road. I took the challenge and separated with Victor, taking different paths. It ended well despite the miserable process. Only then did I know that Victor made the same wish as I did by the wishing pond."
  },
  [102511] = {
    diary_text = "I thought I'd have a quiet time while Victor was away on business, but then he moved up my deadline! I had no choice but to roll up my sleeves and get to work."
  },
  [102521] = {
    diary_text = "As a reward for turning in my report early, Victor actually flew me to London. The next day we toured  Borough Market, and this little foodie ate her fill!"
  },
  [102531] = {
    diary_text = "After the food market, I decided to go to a flea market to get a holiday surprise. We were only separated an hour, but Victor still accompanied me via phone."
  },
  [102541] = {
    diary_text = "Victor's phone ran out of battery, and right when I was going to find him, he called me again from a pay phone. I pretended to be lost and watched him panic."
  },
  [102611] = {
    diary_text = "World-famous Astra Circus is coming to Loveland, and I didn't get tickets! I felt I had nothing left to live for, but two days before the show Victor invited me to go with him."
  },
  [102621] = {
    diary_text = "On the way to the show, Victor-- exhausted from travel-- fell asleep, and I put my coat over him. After he woke, he was afraid I was cold and gave me his scarf..."
  },
  [102631] = {
    diary_text = "The circus had ended, but the night was just beginning. I dragged Victor around buying all kinds of circus trinkets and snacks, and then a rose stall caught my eye..."
  },
  [102641] = {
    diary_text = "Naturally I had to reciprocate for Victor's rose, but he helped me buy me the \"Shiba Inu candy\" I liked. Not to be defeated, I bought some candy from a nearby stall for him…"
  },
  [102711] = {
    diary_text = "Victor became the new \"Ideal CEO\" online after the charity gala. He called me about the light show right when I was depressed about that."
  },
  [102721] = {
    diary_text = "It took me quite a while to get dressed so we were stuck in traffic as the light show was about to begin. Victor got off the car with me, made our way through the crowd toward LFG's newly-built branch office."
  },
  [102731] = {
    diary_text = "I grabbed Victor's wine glass by mistake while enjoying the light show at his office on the top floor. After the light show, he took me to the terrace to get some air, but I accidentally pushed him into the pool."
  },
  [102741] = {
    diary_text = "Victor put a pair of earrings on me after getting out of the water and said they were a present for me. It turned out that he had figured out how to comfort me when I was upset. We kissed in the pool and could feel the warmth of each other even in the cold night breeze."
  },
  [102811] = {
    diary_text = "Victor was on a business trip before his birthday. Though I couldn't celebrate with him, I sneaked into his house to prepare for a birthday surprise."
  },
  [102821] = {
    diary_text = "I woke up Victor, who came back ahead of time, and my lie was also exposed by him, but he still agreed to celebrate his birthday at his house."
  },
  [102831] = {
    diary_text = "I could not open the jar of ribbons and ran to the bathroom to ask Victor for help, but accidentally witnessed how he looked while shaving. While he was looking at my decorations, I secretly turned off the light, held the cake I had made in front of him, and sang him a birthday song."
  },
  [102841] = {
    diary_text = "Victor accepted the birthday crown. When I took out the gift , he did not mock me for being childish but asked me why I gave him this gift."
  },
  [102911] = {
    diary_text = "Although every young girl imagines how her wedding dress and wedding ceremony will be, when the time comes, she doesn't know where to start from."
  },
  [102921] = {
    diary_text = "When Victor told me at the beginning, he only mentioned that it was a temporary wedding rehearsal for his relatives and didn't say it would be so formal!"
  },
  [102931] = {
    diary_text = "When it's time to make vows and exchange wedding rings, I was so nervous that my mind went completely blank. I took a peek at Victor and found that he was not as calm as I had imagined."
  },
  [102941] = {
    diary_text = "After the whole ceremony, I could finally rest for a bit, but I never expected that Victor would say that to me..."
  },
  [103011] = {
    diary_text = "It's been over 2 weeks since I've been sending daily gifts to Victor. Just as I was preparing the last surprise for him, I got a call from him..."
  },
  [103021] = {
    diary_text = "Mr. Shenk said that my interview was a success, and that he'd like to invite me to a dinner at the club this weekend. I accepted the invitation without hesitation, only to find Victor there as well."
  },
  [103031] = {
    diary_text = "When we were alone, Victor suggested a pool game. Remembering my pending proposal with him, I asked him to approve it if I won the match."
  },
  [103041] = {
    diary_text = "A bobby pin dropped out of Victor's pocket as he wanted to exchange his business card with others. It was a gift hidden there by me as a surprise..."
  },
  [103111] = {
    diary_text = "Due to a temporary arrangement, I had to give up my weekend date with Victor and work extra hours at home. But he came straight to my house and declared that he wanted to spend the weekend here..."
  },
  [103121] = {
    diary_text = "I showed him my proposal but surprisingly, he knows nothing about variety shows. It's rare to find his knowledge blind spot plus gaining his approval, so I felt complacent."
  },
  [103131] = {
    diary_text = "In order to select a more appropriate game, we played poker. After my failed divination, we began playing Old Maid. As a punishment for losing, Victor wrote a word on my face..."
  },
  [103141] = {
    diary_text = "Repeated defeats did not dampen my will. Finally, I managed to win the third game. Extreme joy begets sorrow. I accidentally fell into Victor's arms..."
  },
  [103211] = {
    diary_text = "I planned to call Victor when I landed but he actually came to pick me up at the airport..."
  },
  [103221] = {
    diary_text = "I suddenly felt sleepy as I comfortably sat slanted in Victor's car but wanting to take in more of Victor's attractive face, I didn't want to fall asleep."
  },
  [103231] = {
    diary_text = "Victor brought the hungry me to the supermarket. While he was selecting ingredients, I was struggling with which snacks to choose..."
  },
  [103241] = {
    diary_text = "Although Victor had other plans and we had only 4 hours together, I seemed to have found a way to enjoy our busy lives together."
  },
  [103311] = {
    diary_text = "To fulfill my aunt's last wish, I attended the Double Seventh banquet held by CR company. Just as I vowed to take back the drawings from CR's boss, he showed up..."
  },
  [103321] = {
    diary_text = "As the host of the banquet, Victor was mobbed by the crowd, which gave me a chance to slip into his office for the drawings. While I was secretly observing him, our eyes met!"
  },
  [103331] = {
    diary_text = "I was rummaging around Victor's office when he suddenly appeared! I took out a folding knife, intending to seize him, but was buckled in his arms instead. Right then, the door was pushed open again."
  },
  [103341] = {
    diary_text = "The mystery of the story was solved, and Victor and I no longer need to be limited to the roles in the script. As we walked along the street late at night, I asked him to take a rickshaw ride with me..."
  },
  [103411] = {
    diary_text = "During my monthly report I planned to invite Victor to the banquet my company was hosting. However, I learned that he had a finance meeting to attend that day."
  },
  [103421] = {
    diary_text = "Due to a sudden occurrence before the banquet started, I had to walk the runway in the place of another model. To my surprise, while I was onstage, I spotted Victor in the crowd..."
  },
  [103431] = {
    diary_text = "I saw Victor talking to another girl and felt inexplicably annoyed. After that, I got drunk, mistook the real Victor as an illusion and dragged him to dance."
  },
  [103441] = {
    diary_text = "I finally realized that I was making a fool of myself in front of the real Victor! Though my mind cleared up, my heart was still intoxicated by the night."
  },
  [103511] = {
    diary_text = "As I was busy working on a show, I was told that someone was asking for me. I walked into the lounge and was surprosed to find Victor sitting inside, who returned after a long business trip."
  },
  [103521] = {
    diary_text = "The familiar restaurant brought back memories. I remembered coming to this restaurant to report to Victor when he was still an unreasonable capitalist in my eyes."
  },
  [103531] = {
    diary_text = "Victor and I were stuck in a small restaurant due to heavy rain. The owner welcomed us warmly. Out of guilt, I made a bowl of noodles for Victor, but he seemed to dislike it."
  },
  [103541] = {
    diary_text = "After a long time, the relationship between Victor and I had gradually deepened. Now I understood that it wasn't just the food itself that made me nostalgic, but it was also the memories associated with it."
  },
  [103611] = {
    diary_text = "When I woke up in darkness, I found a scarlet mark on my neck...the legendary \"Kiss of Bloodbond\"."
  },
  [103621] = {
    diary_text = "To protect the residents in the town, I was forced to become the \"bride\" of a vampire and offered as a sacrifice in the name of \"wedding\". In the deserted graveyard, I met the man who showed up in my dream."
  },
  [103631] = {
    diary_text = "After awaking from a coma, I found myself in a strange town, and kept dreaming about that vampire for these days. To undo the Kiss of Bloodbond, I decided to revisit the graveyard to find him."
  },
  [103641] = {
    diary_text = "Victor helped me undo the Kiss of Bloodbond, but before I could make the decision to leave or not, the knights templar arrived. Why did I still dream about him after returning to the human society?"
  },
  [103711] = {
    diary_text = "The sudden business trip before Christmas fouled up my plan to spend Christmas with Victor. I liked festivals, but I was looking forward to celebrating Christmas with him more."
  },
  [103721] = {
    diary_text = "I couldn't wait to see Victor, but I couldn't find him in LFG or Souvenir. When I was about to spend this Christmas alone in frustration, I saw him."
  },
  [103731] = {
    diary_text = "I never thought I would walk on the street with Victor in the snow, but it turned out to be especially interesting. The street seemed to twinkle, and my heart was filled with warmth."
  },
  [103741] = {
    diary_text = "We went back to Souvenir and decorated it with colored lights. I imitated the movie scenes and told Victor how important he was to me. I wish we could spend every holiday together."
  },
  [103811] = {
    diary_text = "It was Victor's birthday! I started preparing for the occasion way ahead of time, but something unexpected came up... Victor asked me to accompany him on a business trip to Paris!"
  },
  [103821] = {
    diary_text = "I was used to having to work on holidays, but it was Victor's birthday after all and I planned to celebrate it anyway when we had some free time. Unexpectedly, Victor asked me to come see someone with him..."
  },
  [103831] = {
    diary_text = "Victor brought me to his mother's past residence. The cozy-looking home was full of tender memories, but I was still nervous. Did this count as... my first meeting with my future in-laws?"
  },
  [103841] = {
    diary_text = "Under the sunset of the River Seine, we passed by a bridge lined with heart-shaped locks. I bought one for Victor as a joke, and he played along, letting me have the key..."
  },
  [103911] = {
    diary_text = "SE, a portfolio company of LFG, went through a heavy operational loss. After several sleepless nights, Victor finally came to a decision on how to handle the matter. He was exhausted."
  },
  [103921] = {
    diary_text = "As I tossed and turned wondering if something major had happened to LFG, I received a phone call from Victor. His usually calm voice eased my anxiety and put me to sleep."
  },
  [103931] = {
    diary_text = "After Victor came back in the afternoon, we started doing our separate work. But I couldn't focus. I kept finding my eyes drawn to him, and that took a toll on my efficiency. Just then, Victor got a phone call. Was that another emergency calling him away?"
  },
  [103941] = {
    diary_text = "When I got back from doing chores, Victor was already lying in bed. He had been worn out by work and I felt sorry for him. So I decided not to disturb him; I just silently watched him sleep."
  },
  [104011] = {
    diary_text = "I was sitting in a cafe on a foreign street, waiting for Victor. I started to feel a little sick from the stuffy heat, but I dismissed it as nothing."
  },
  [104021] = {
    diary_text = "As Victor and I were walking down the street, I offered to take a picture of him. The moment the shutter clicked, a wave of dizziness came over me..."
  },
  [104031] = {
    diary_text = "Because of the sudden heatstroke, we had to suspend our trip and checked in a hotel nearby. I dozed off as Victor prepared lunch. When I woke up, I found him lying next to me..."
  },
  [104041] = {
    diary_text = "After finishing the belated lunch, I took an interest in the red wine Victor brought back. In an attempt to snatch it from his hand, I accidentally tackled him on the bed. At the end of this short trip, I found the most beautiful rose in town."
  },
  [104111] = {
    diary_text = "影视文化峰会之后，我还犹豫着要不要邀请李泽言一起去游乐园，他居然先一步开了口，提出邀请……"
  },
  [104121] = {
    diary_text = "李泽言居然包下了整个园区！还没从这个惊喜中缓过神来，游乐园的工作人员递给了我一本写了谜题的小册子，想到解开谜题后可能获得的奖励，我越发期待这趟乐园之旅……"
  },
  [104131] = {
    diary_text = "跟随小册子的提示，和李泽言一起解开了一个又一个谜题。在乐园中，似乎不论是谁都会渐渐融入氛围，找到心底的那份快乐。"
  },
  [104141] = {
    diary_text = "在旅途的最后，李泽言的几句话，让我解开了所有的谜题。看着夜空中绽放的烟花，我知道，守护我的“恶龙先生”，不论何时都不会让魔法结束。"
  },
  [104211] = {
    diary_text = "The moment I got off the plane, I learned from Kiki that the famous entertainment firm YL was losing an important partner. I hurried to the company, hoping to redeem the situation, but to no avail."
  },
  [104221] = {
    diary_text = "At the LFG office, my brief moment alone with Victor gave me a respite. But misfortunes never come singly, and soon I received a phone call from Willow summoning me back to the company to handle a difficult guest on the show."
  },
  [104231] = {
    diary_text = "The partnership ended in failure. I finished work late and shuffled out of the company, exhausted. Suddenly it started pouring, but I didn't bring my umbrella. Forgetting Victor's exhortation, I braved the downpour and made my way back home. Then a string of mishaps followed..."
  },
  [104241] = {
    diary_text = "When I was at my most helpless, I met Victor and he took me to his home. He tried to comfort me and cheer me up, and it worked. My mood brightened up and I got out of my emotional abyss."
  },
  [104311] = {
    diary_text = "I'm in a one-sided cold war with Victor! For almost five days, we haven't contacted each other. Then, I learned he's going on a business trip, which means we have no time to meet..."
  },
  [104321] = {
    diary_text = "The next day, I went the park to prep a \"protect the environment\" event with Anna. Surprisingly, Victor showed up. I pretended not to recognize him behind my bunny mask..."
  },
  [104331] = {
    diary_text = "Victor was only pretending not to recognize me! Realizing that he'd actively sought me out, I felt my \"cold war\" was pretty childish."
  },
  [104341] = {
    diary_text = "The event came to an end. I skipped dinner with the staff to spend the end of cherry blossom season with Victor. I worked up my courage and did something I never dared to do before."
  },
  [104411] = {
    diary_text = "I'm so surprised when Goldman asks me to fill-in as Victor's temporary Assistant. Everything goes smoothly, in spite of my nerves, until we try to leave the convention center and are faced with a terrible snowstorm."
  },
  [104421] = {
    diary_text = "The driver messages from the street outside. Realizing the storm's not going to stop, Victor decides to head out and meet him. I don't really want to leave the warmth of the building, but all I can do is grit my teeth and follow."
  },
  [104431] = {
    diary_text = "I almost freeze to death on the street. The business clothes do nothing to keep the cold out. Just at that moment, Victor rips off his overcoat and wraps it roughly around my head. It's not the most elegant solution, but it provides a sanctuary from the storm."
  },
  [104441] = {
    diary_text = "Victor takes even less care of himself than I do! Looking at his thin cotton shirt, I decide to lend him my blanket, never expecting him to spurn it! Mustering courage I didn't know I had, I tip-toe over to Victor and throw my blanket over his shoulders. Tea in hand, looking out at the falling snow, inside the room it feels very warm."
  },
  [104511] = {
    diary_text = "I got drunk at the beach's Barbecue Festival. On our way back to the hotel room, with a muddle head, I told Victor about what happened during the trip. At that moment, Victor revealed that he was my client."
  },
  [104521] = {
    diary_text = "To confirm whether I was dreaming yesterday, I went to Victor to reaffirm his response but was surprised to see that he was playing tennis..."
  },
  [104531] = {
    diary_text = "Victor approved my proposal but rejected one element of it. To change his mind, I pulled out my old trick and put everything on the line with a tennis match..."
  },
  [104541] = {
    diary_text = "After an intense back-and-forth, I managed to defeat Victor! Now he had no choice but to accept my proposal. Although between the results and playing with him, I would always choose the latter in a heartbeat..."
  },
  [104611] = {
    diary_text = "I woke up in a daze and found myself in an underground facility with Victor next to me. After we quickly identified the situation, he suddenly told me that he had lost his sight."
  },
  [104621] = {
    diary_text = "Despite losing his sight, Victor was still remarkably calm. After earning his trust, I used a transceiver to get him out of here first. Everything went relatively smoothly, but just when I was hopeful that we could leave without any problems, a figure appeared on the concrete floor..."
  },
  [104631] = {
    diary_text = "We managed to dodge the axeman's attack and analyzed the current situation in a dark corner. As expected, at precisely 7 pm, the attack came to an end."
  },
  [104641] = {
    diary_text = "By the time we escaped the abandoned experimental site, Victor's men met up with us just in time. We headed to a winery in a car and completed a deal on the spot. Everything seemed to be finally over while seeming like it just got started."
  },
  [104711] = {
    diary_text = "After learning that LFG invested in my company, I once again stood outside the LFG building wanting to sneak a peek at Victor. Unfortunately, he didn't show up. When I was about to leave, I saw him on the other side of the road that we once met, but another voice appeared in my ears..."
  },
  [104721] = {
    diary_text = "Invisible hands pushed me forward, but Victor stopped time to save me once again. As I introduced myself, a mysterious man suddenly appeared..."
  },
  [104731] = {
    diary_text = "The bar we were brought to seemed to be run by BS. Victor didn't seem surprised, but he kept me close as he didn't trust them. The other man proposed to play a game with Victor."
  },
  [104741] = {
    diary_text = "Victor easily passed the test and we were sent back. He said he would look forward to my performance. Eight months later, when I returned to the BS building, I saw Victor there. Everything seemed to be only starting..."
  },
  [104811] = {
    diary_text = "When I took back my Peach Wood sword from an unscrupulous Sword Dealer, he sent armed men after me. I fled into the forest and dived into a small stream. As I was about the leave, I met the Black Dragon, the Divine Guardian. He chased my pursuers away and asked me to open the barrier again for him."
  },
  [104821] = {
    diary_text = "I explained to the Black Dragon why the men were chasing me and asked him for help. He agreed, and as we approached the city, I asked him what I should call him... however, he seemed very reluctant to reveal his name."
  },
  [104831] = {
    diary_text = "The Sword Dealer recruited a gang of thugs and waited for me outside my home. He wanted the sword to subdue and control the Black Dragon. I refused, the Black Dragon helped me to diffuse the situation and we delivered the Sword Dealer to the Courthouse. Afterwards the Black Dragon revealed to me the thing that could really control him."
  },
  [104841] = {
    diary_text = "We exchanged names, creating a special bond or \"Lock\". I expected he would leave the moment he gained his freedom. However, I never imagined he would choose to remain at my side. We then exchanged vows on a special day."
  },
  [104911] = {
    diary_text = "Receiving an unexpected message from Ronan, Victor and I were invited to the Hanging Garden and attend the preview of his new movie."
  },
  [104921] = {
    diary_text = "The preview went smoothly. I strolled around the garden and found a \"surprise\" from Victor..."
  },
  [104931] = {
    diary_text = "When Victor asked me my suggestions for modifying the garden, I blurted out everything on my mind: If possible, I wanted to build him an oasis that gives him peace."
  },
  [104941] = {
    diary_text = "The rocking flower bed and lost balance resulted in me falling on the flower bed. That night, Victor confessed to me the deepest feelings in his heart..."
  },
  [105011] = {
    diary_text = "I signed up for a fencing trial class. After the warm-up, the coach left and was replaced by another person. Before I knew what was happening, he suddenly launched an attack on me..."
  },
  [105021] = {
    diary_text = "After we took off the masks, the person across turned out to be Victor. It turned out he was a skilled regular in the fencing club. Despite complaining that I was difficult to teach, he took the initiative to introduce fencing to me instead of the coach."
  },
  [105031] = {
    diary_text = "Victor taught me some basic techniques in the usual \"Mr. Victor\" style as I remembered. After the practice, we had a practice match. I tried to find his weakness and managed to score."
  },
  [105041] = {
    diary_text = "To thank Victor for being a \"substitute coach\", the coach invited him to a match. Despite being an amateur player, Victor's score was on par with the coach's, making it a tight match. After watching the game, I was worried that I might not be able to keep up with Victor this time, yet he believed in my promise and gave me the courage to face the future again."
  },
  [105111] = {
    diary_text = "As one of the promotional collaborators of the \"Snail Courier\" event, I decided to inspect the venue at Camellia Hall one last time."
  },
  [105121] = {
    diary_text = "I ran into Victor at the door. He didn't say what he was here for, just handed me a bouquet of camellias and inspected the place with me."
  },
  [105131] = {
    diary_text = "Things were looking good in the hall. I filled Victor in on the theme and concept behind the event, but he simply replied with something I didn't understand. I was about to convince him to try out filming a video when a staff member appeared."
  },
  [105141] = {
    diary_text = "When we got home, Victor took out a courier gift—I almost forgot myself, but it was the essential oil and letter I sent after exiting the Camellia Hall maze sometime ago. Desperate to stop Victor from reading the letter out loud, I jumped up and accidentally ripped off his button, and things began to heat up..."
  },
  [105211] = {
    diary_text = "Six months ago, Victor sent an invitation to over a dozen young, LFG-backed entrepreneurs to have an internal business competition, the winner of which would get a new round of $5 million in funding. I took part in it too. The competition took place in a completely sealed off environment, with all the participants staying in one of LFG's hotels. Victor drove me to the hotel."
  },
  [105221] = {
    diary_text = "The case study topic for the competition was to analyze the reason for the failure of the SE platform. This one the most well-known of all of LFG's investment losses. It was a bit of a surprise that Victor chose that as the topic, but also quite reasonable. As I read page after page of documents, I felt like I was seeing Victor sitting in front of the computer day and night, re-analyzing every aspect of the business."
  },
  [105231] = {
    diary_text = "The competition really put me through the ringer, and each day I was exhausted. While I was agonizing over the case study report, the doorbell sounded: Victor had suddenly arrived. In his relaxing embrace, I rested for a short while in comfort."
  },
  [105241] = {
    diary_text = "I had drawn a big circle around the SE logo on the first page of the report. When I realized that Victor had never breathed a word of his SE investment failure to me, it began to dawn on me that he had always treated me as someone he had to protect. The feeling of not being needed by someone you love hit me harder than my own failed shows, so I instantly set a goal to surpass him."
  },
  [105311] = {
    diary_text = "One day, a horrifying honey badger took me away. A man saved my life from the brink of death... then suddenly I turned into a human!"
  },
  [105321] = {
    diary_text = "On my way to a human village, danger lurked once more. The same man saved my life again. I learned that his name was Victor. He wanted my help to break his curse, and he offered that I could ask for anything in return. I gladly agreed and asked him to teach me to be a real human."
  },
  [105331] = {
    diary_text = "As I was learning how to be a human, many unexpected things happened—a rose grew on the top of my head, and Victor turned into a beast before my very eyes..."
  },
  [105341] = {
    diary_text = "Gradually, I began to realize my heartbeat only accelerates because of Victor. As we spent time in each other’s company, I slowly discovered the true answer within me, and he told me that... his answer was the same as mine."
  },
  [105411] = {
    diary_text = "After the meeting ended, I tried to feel out Victor's plans for Christmas. To my surprise, he'd already planned to spend Christmas Eve with me."
  },
  [105421] = {
    diary_text = "Back at Victor's, I noticed there was actually a fire in the long-unused fireplace. Was he subtly ticking all the boxes of my perfect Christmas? I got busy decorating the house."
  },
  [105431] = {
    diary_text = "I never expected Pudding to mess up my special Christmas surprise for Victor. He even trampled Victor's cake... that's how we ended up giving Pudding a bath on Christmas Eve."
  },
  [105441] = {
    diary_text = "I fell asleep with my head on Victor's leg, but when I woke up, he was on the balcony. I was confused until... it starting snowing! Making my perfect Christmas complete."
  },
  [105511] = {
    diary_text = "A few days ago, when I was worried about how to best present the theme of \"New Year's Voices\", an exhibition notification was pushed to me. This might give me some inspiration, so here we came."
  },
  [105521] = {
    diary_text = "Victor and I went to the second floor, where there's a love-themed exhibition recommended by the cafe owner. I was at once attracted by an exhibit called \"Trace\"."
  },
  [105531] = {
    diary_text = "A mouse hidden in a painting, a short paragraph in a diary, or a statue of a lover's face... \"Traces exist to express unspoken feelings\". Looking at Victor, I had a better understanding of this."
  },
  [105541] = {
    diary_text = "It started to drizzle when we walked out. Victor went to redeem the gift umbrella, while I got quite emotional. Feelings hidden in traces should be expressed more straightforwardly..."
  },
  [105611] = {
    diary_text = "I went to Victor's house for birthday decorations but accidentally received a delivery from the zoo for him. I was so curious about the pandas he adopted in the zoo. Hope that we could go and see them together in the future."
  },
  [105621] = {
    diary_text = "Victor's birthday was on a workday. He arranged a holiday for both of us and took me to the zoo to see pandas."
  },
  [105631] = {
    diary_text = "Victor can always figure out the two pandas under his adoption, which surprises me every time he does it. I accidentally found out that Vic-Vic and Victor's birthdays are on the same day. I took this chance to express my greetings to both of them."
  },
  [105641] = {
    diary_text = "When we were back, I asked Victor to look for my hidden gift. He found the tie under the quilt with my help. Very unusually, he was frank about his satisfaction with my gifts always. He even made a promise that belonged to me only."
  },
  [105711] = {
    diary_text = "I invited Victor to \"my\" ice rink to ice-skate together and relax. I always assumed that Victor excelled in everything and never thought he would not know how to skate..."
  },
  [105721] = {
    diary_text = "I could finally be Victor's \"coach\" for once. When I was teaching him how to ice-skate, I made some mischief and saw him losing his cool for the first time. Victor was very cute like this."
  },
  [105731] = {
    diary_text = "Victor was a quick learner. When I was about to show off in front of him, I accidentally crashed into a kid, and Victor quickly took hold of me. I only realized later that he never let go of my hands as we agreed..."
  },
  [105741] = {
    diary_text = "When we left the ice rink, I chatted to Victor about feeling lost recently and he lifted me out of the fog. He said he knew he was my goal, so he wouldn't stop in order to give me the motivation to move forward. He would always hold my hand on our way toward the goal."
  },
  [105811] = {
    diary_text = "When flying to the neighboring city to attend the annual conference, I kept pondering on the fact that I was criticized by a senior not long ago. To make things worse, Victor told me that that senior will also attend the annual conference......"
  },
  [105821] = {
    diary_text = "As expected, my peers all mentioned that to me on the conference. I told Victor about my disagreement with the senior. Victor encouraged me to take the initiative to consult this senior before he went on stage to give a speech."
  },
  [105831] = {
    diary_text = "I didn't expect that I just sat next to the senior, and I mustered the courage to clear the misunderstanding between us. When the annual conference concluded, I invited Victor to have a cup of coffee and played a trick on him by the way."
  },
  [105841] = {
    diary_text = "When I got back to the hotel and finished bathing, I found that the hair dryer was broken. I asked Victor next door to borrow the hair dryer, but he helped dry my hair voluntarily. It turned out that he had long known what kept troubling me for so many days ......"
  },
  [105911] = {
    diary_text = "Before I could introduce the self-catering feature to Victor, he already beat me to it. It turned out he found out about it when the investment proposal somehow got into his hand earlier..."
  },
  [105921] = {
    diary_text = "We were about to cook from the food we found in the fridge when a chicken stumbled across the courtyard. A delicious idea came to mind and urged me to take Victor to the courtyard..."
  },
  [105931] = {
    diary_text = "After our stomachs were filled, we went for a stroll in the resort and soon came across an orchard. We then got invited to join an activity."
  },
  [105941] = {
    diary_text = "On the way back, we ran into the farmer we met earlier, who invited us to their barbecue party. They told us many thought-provoking stories, and Victor also spilled out his mind as we chatted..."
  },
  [106011] = {
    diary_text = "Taking in the beautiful gardens and festive atmosphere, I couldn't help but think of Victor and gave him a call. He seemed to detect something in my tone..."
  },
  [106021] = {
    diary_text = "My heart swirled with the joy reuniting with Victor. The streets were filled with streamers, balloons, and oddly-dressed people. I informed Victor this was a \"Carnival\" celebration..."
  },
  [106031] = {
    diary_text = "I planned to take Victor to the garden I'd mentioned on the phone with him, but our way was blocked by a crowd of people on the main street..."
  },
  [106041] = {
    diary_text = "A worker at the garden came up and helped take a picture for us. Looking at the photo of us, Victor asked me why I took him there. I came out and told him my true feelings..."
  },
  [106111] = {
    diary_text = "In the desert, I saved a man buried in the sand, who then gave me a bag of rubies in return. I accepted one ruby and said I was glad that he was safe. The man seemed a little surprised, then he told me his name was Victor."
  },
  [106121] = {
    diary_text = "I fainted from overusing my ability and woke up in a palace. It turned out that Victor was the owner of the palace, who offered me a deal."
  },
  [106131] = {
    diary_text = "Because of my ability, I was targeted by another tribe and was kidnapped to the desert. At the critical moment, Victor appeared with his army and rescued me, but then a sandstorm struck..."
  },
  [106141] = {
    diary_text = "Together with Victor, we managed to revive the Sosthia River. I also found the legendary desert roses. At the sacred ceremony, Victor grabbed hold of my wrist when I was about to leave..."
  },
  [106211] = {
    diary_text = "On the sixth day of Victor's business trip, he phoned to ask me to find a document for him. I then tried on his glasses left on the desk and wondered what time looked like in his eyes."
  },
  [106221] = {
    diary_text = "During my interview at a tailor shop, I met Victor who returned early from his trip. Looking at him surrounded by store clerks, I suddenly realized that he had lost weight..."
  },
  [106231] = {
    diary_text = "During our conversation, I caught Victor playing with my hair. He noticed that my hair had grown. He said that these subtle changes were the evidence of time and that perhaps \"reunion\" would allow us to rediscover the times we took for granted."
  },
  [106241] = {
    diary_text = "There were some hiccups at the charity gala. After they were resolved, Victor said I could receive a phase reward. Understanding his intentions, I found that our closer relationship did not prevent him from seeing my growth and changes."
  },
  [106311] = {
    diary_text = "At an international conference, I was told I'd have to share a car from the airport with another guest. To my surprise, the other guest was none other than Victor."
  },
  [106321] = {
    diary_text = "Victor asked why I'd come, and I told him to win over more investors, then jokingly said I should try to get on his good side. Victor laughed and said he'd look forward to it."
  },
  [106331] = {
    diary_text = "After the first day of the conference, I ran into Victor on my way back to my lodgings. As we walked back to the resort, we ran into a friendly little cat."
  },
  [106341] = {
    diary_text = "With some porridge and a kitty, I went to check on Victor, who was still up working. The cat jumped into his room, and I hopped through the window too, to Victor's amusement."
  },
  [106411] = {
    diary_text = "Victor and I had plans to watch TV this weekend at my house, but he had too much business to take care of, so I had to watch my anime alone. Knowing that I had disturbed him, I cut up some fruit for him and discovered an invitation letter sent to LFG."
  },
  [106421] = {
    diary_text = "I took part in LFG's career fair as a volunteer. During a break, Victor took me to the coffee shop to get a snack and take part in a little activity. It was then Victor played a little joke on me..."
  },
  [106431] = {
    diary_text = "Unexpectedly, we found ourselves sitting at the table with two kids, and I got the bright idea to pretend to be Victor's boss in front of them. But in short order, Victor took back the title of \"CEO\"."
  },
  [106441] = {
    diary_text = "After the exhibition ended, we decided to walk to a restaurant. On the way, Victor explained his idea about \"only living once\". It struck me as profound, and I got curious about what dreams he had as a kid."
  },
  [106511] = {
    diary_text = "I listen quietly to the judgment of souls, after which I come before the Underworld God and tell him I will be graduating soon from an apprenticeship to god of love."
  },
  [106521] = {
    diary_text = "Victor is evidently surprised that I'll be leaving, and even seems uncharacteristically upset. I think back to all the little things we'd been through since I took this task. All those memories with him stand out so clear and deep. I hope that in my last moments asapprentice of god of love, I can make Victor happy."
  },
  [106531] = {
    diary_text = "Victor and I sit on a hillside facing the gates of the underworld chatting. He tells me those points of light are the lives of souls, and when the lights fall to the earth of the underworld and become flowers, that's the love that has accompanied them their whole life. But in this world, everything turns to dust. Whether mortal or divine, they all meet their end. I want to leave something for Victor in this world."
  },
  [106541] = {
    diary_text = "The flower Victor gave me has never withered. With only a few days left before I become human, I come to the boundary between the human world and the underworld. To my surprise, the three-headed dragon that always follows Victor around appears behind me..."
  },
  [106611] = {
    diary_text = "At the entrance of the Masterpiece Painting Experience Museum, Victor asked me what kind of work matter this was. I said he would find out as I dragged him in."
  },
  [106621] = {
    diary_text = "After the staff explained the rules, Victor and I watched a few demonstrations, which were very intriguing indeed. I told Victor that I intended to buy their video and broadcast rights to promote them with a program."
  },
  [106631] = {
    diary_text = "We chose the painting \"Dance in the City\". After getting changed, Victor stood in front of the clock tower backdrop, who looked so noble and composed that I simply couldn't take my eyes off him. After posing the same way as in the painting, we started our dialogue."
  },
  [106641] = {
    diary_text = "The first two lines were provided, while the rest was all improvisation. The dialogue seemed almost inspired, and our rendition was funny and heartwarming. We managed to get the prize. On the way out, Victor told me what made this experience special was actually..."
  },
  [106711] = {
    diary_text = "After finishing a proposal report, Victor seemed to have something he wanted to say. While I was worried there was something wrong with the proposal, it turned out he wanted my help to go take care of his relative's kitten together."
  },
  [106721] = {
    diary_text = "When we got to his relative's home, we saw that the place was a mess, which was when I realized that taking care of this kitty might present a bit of a \"challenge\". Victor and I had to start with cleaning up the room..."
  },
  [106731] = {
    diary_text = "When we coaxed the kitty into making an appearance, I learned that Victor and this kitty had some \"history\". I never would've imagined that the high and mighty Mr. Victor could suffer defeat at the hands of a tiny animal. With the kitten fed, we were getting ready to bathe it when the unexpected happened..."
  },
  [106741] = {
    diary_text = "After a knock-down drag-out battle, we finally got the kitten bathed. Having been looked after by Victor, the kitten didn't put up any more resistance. Human and kitten had finally buried the hatchet. In the evening breeze, I suddenly realized that the attention I always got from Victor was perhaps even more meaningful than I thought..."
  },
  [106811] = {
    diary_text = "During my six hours on the date, I took Victor to the Mr. Cat Theme Exhibition and waved the tickets at him smugly."
  },
  [106821] = {
    diary_text = "I told Victor that Mr. Cat was my favorite cartoon as a child and the most powerful person on Planet Meow. I was hoping to take sneaky photos of him, but he took some photos for me instead."
  },
  [106831] = {
    diary_text = "When we got to the game room, Victor took the game seriously. I couldn't resist pulling funny faces behind him and pinching his face when photos were taken."
  },
  [106841] = {
    diary_text = "I was satisfied after having two ice creams and recording \"A Different Side of Victor\". It was time for Victor's section of the date. The scenery before my eyes became increasingly familiar. It turned out the place Victor wanted to take me to was..."
  },
  [106911] = {
    diary_text = "I came to Victor's shop to ask about the restoration of my phoenix hairpin. He was a jeweler who repairs jewelry I met a month ago, who was also the young master of Prosperity Trading. Victor said a gemstone was still missing from the phoenix hairpin, and I told him that I would bring it tomorrow."
  },
  [106921] = {
    diary_text = "In the evening, I took the opportunity to retrieve the stolen jewel from my family's heirloom when I sang in Golden Pavilion. But it was Victor who stepped in to help me when I also got caught."
  },
  [106931] = {
    diary_text = "Victor said he wanted to promote me. Was he just helping me be free from Golden Pavilion? After knowing about Victor's plan to put an end to the Golden Pavilion's illegal trades. With the hidden feelings in my heart, I told Victor I would be willing to help him, but Victor seemed reluctant to drag me into this crisis."
  },
  [106941] = {
    diary_text = "On the day the plan was carried out, I was invited to the Golden Pavilion as a hostage. Victor said he would keep me safe, but he got into danger when the plan was in progress. In the nick of time, I determinedly shattered the family jewels on the stage to get him the chance to fight back."
  },
  [107011] = {
    diary_text = "Because of company expansion, I had to redo the office layout. As I was cleaning, I found some \"expired\" items. Victor came to help me move things, and we started talking about a failed past project. I bemoaned missed opportunities, but Victor didn't see it that way..."
  },
  [107021] = {
    diary_text = "Victor noticed the beer and other things that should've been tossed long ago. I stopped him because I couldn't bear to part with them. Learning about how I felt regret at missing out on a date, Victor decided to make up for it."
  },
  [107031] = {
    diary_text = "Victor took me to an open-air drive-in movie theater. The movie happened to be the same director of the one I wanted to take him to. I got him to drink the beer I'd brought, then thanked him for helping me appease my regret. Victor said as long as he's around, I can always make up for a regret."
  },
  [107041] = {
    diary_text = "My tolerance was still nothing to speak of, but Victor said if I needed, he would always be my \"shield\". I realized that he really would do that, because no matter what, he always gave me the newest and best. I would never have to worry about anything expiring. I also expressed my feelings, that maybe what people call eternal love is just your heart beating anew for another, again and again and again."
  },
  [107111] = {
    diary_text = "The recommended events on the desert brochure got me very excited. I thought Victor should have tried it all, but I didn't expect him to be a \"newbie\" too, so I naturally became the tour guide."
  },
  [107121] = {
    diary_text = "After a day of fun, we returned to our accommodation exhausted but learned that there would be a meteor shower the next day. Victor agreed to camp with me to see it. We chatted and bantered again, but I knew it would be difficult for us to have real conflicts with him spoiling me."
  },
  [107131] = {
    diary_text = "The satellite navigation suddenly failed on the way to the campsite, so we had to find our way back the old-fashioned way. When we finally arrived at our destination, we saw two newlyweds taking wedding photos, and I suddenly felt empathetic—The world was so vast, yet it was romantic enough to rely on each other alone."
  },
  [107141] = {
    diary_text = "As night fell, the newlyweds came to us for a chat. The bride gave me a special bouquet, which she saw as a blessing to send them away from home. Under the starry sky, I leaned against Victor, feeling that snuggling gave us the courage to be on a long journey away. He replied saying that we could go anywhere as long as two people were together."
  },
  [107211] = {
    diary_text = "After two or three weeks of business trips, Victor took me to a place on a rare day off, which turned out to be the newly-completed resort he invested in, and he was there to evaluate."
  },
  [107221] = {
    diary_text = "The resort looked great, but it didn't seem to have any unique selling points. Victor then asked if I wanted to throw sandbags to win a surprise."
  },
  [107231] = {
    diary_text = "The surprise for hitting the bullseye was a large lavender field. The resort owner told us that it was not easy to cultivate such a large area of lavender in Loveland City. Thanks to Victor's willingness to fund the experiment of lanvender varieties, the cultivation succeeded."
  },
  [107241] = {
    diary_text = "Victor and I walked into the romantic endless flower field, and we also took a rest on the fun Bouncy Cloud. The reason why Victor was willing to fund the lavender experiments made me feel that perhaps he didn't bring me here for evaluation, but for..."
  },
  [107311] = {
    diary_text = "Disguised as an auction item at the demon auction, I managed to approach Victor. When I was alone with him, I bound him with chains and tried to torture him to find out the whereabouts of the Seed of Hope."
  },
  [107321] = {
    diary_text = "To my surprise, Victor saw through my trap and he turned out to be the missing Chief Angel... To fight for the chance to stay, I agreed to use a month to prove my ability by passing his test."
  },
  [107331] = {
    diary_text = "With Victor's help, I passed the test on time. On the night of the demon gathering, Victor and I left during the chaos and entered the territory of the demon who hid the Seed of Hope..."
  },
  [107341] = {
    diary_text = "Victor and I walked through the fog and reached the tower where the Seed of Hope was hidden, only to find that the Seed of Hope can only be retrieved by corrupting someone's wings, and the contaminated angel would never be able to return to heaven again..."
  },
  [107411] = {
    diary_text = "After our respective business trips, Victor and I planned to attend the New Year's celebration at Mengshan Ancient Town and spend the first day of our vacation there. I wore the hairband I bought on our last trip to the town, especially for this journey."
  },
  [107421] = {
    diary_text = "For the celebration, Mengshan Ancient Town was decorated with lanterns and colored streamers everywhere. Drawn to the view in front of me, I suddenly realized that my hairband had gone missing..."
  },
  [107431] = {
    diary_text = "Our participation in the celebration did not go smoothly. When we finally got the wish card, I closed my eyes and made a wish devoutly. Unexpectedly, Victor blindfolded me..."
  },
  [107441] = {
    diary_text = "Under the Marriage Tree, Victor and I wrote down our expectations for each other on the wish card. But what he wrote struck me as a surprise..."
  },
  [107511] = {
    diary_text = "Midnight is near. I received a call from Victor when I was on the way to LFG. As usual, he found out this year's surprise again!"
  },
  [107521] = {
    diary_text = "Victor showed me LFG's strategic plan for the next few years, confessing that the wish that must be achieved has been fulfilled long ago, and now he wished to continue his present life."
  },
  [107531] = {
    diary_text = "It was midnight. The skyscrapers outside lit up one after another. This was the birthday surprise I had prepared for Victor. At the same time, I put a paper-folded rose into his pocket."
  },
  [107541] = {
    diary_text = "Victor was touched by my gifts and told me that I had made a difference in his life. He wanted me to be part of his future to feel the significance of every moment."
  },
  [107611] = {
    diary_text = "After attending several weddings in a row, I could basically know the wedding process like the back of my hand. Weddings were happy occasions despite the physical tiredness. When I remarked how much nicer it would have been to have caught a bouquet, Victor told me my wish could be fulfilled at his cousin Vera's wedding."
  },
  [107621] = {
    diary_text = "We arrived at the coastal town where the wedding was and we're warmly welcomed by Vera and Auntie Alice. That night, Vera sought my help for a game called \"Spot the Bride\" at the wedding, while Victor was given a \"mission\" by the groom..."
  },
  [107631] = {
    diary_text = "I found Victor in a record store, which offered a special service of recording the noises of the wedding on an album. On the next day, the game went smoothly, and Victor also recognized me effortlessly. Just as Vera said, she knew her partner would recognize her, so she wasn't worried that he would get deceived appearances."
  },
  [107641] = {
    diary_text = "Everything at the wedding reminded us of the wedding rehearsal we did, so Victor took the opportunity to put the \"ring\" back on my finger. Eager to hang on to this happy atmosphere, I found an excuse to take a bike trip with him. As we rode on the path to the sea, we exchanged vows of courage, peeking at what our lives together would look like."
  },
  [107711] = {
    diary_text = "The pet program my company recently produced had been getting great reviews. The guest who was originally scheduled to join Saturday's mukbang livestream had to cancel at the last minute and asked me to take her place instead. Just as I was upset about having to cancel my date with Victor the next day, he told me he'd come along..."
  },
  [107721] = {
    diary_text = "When we arrived at the guest's house, we found the living room in disarray and discovered that Tornado, the star of the livestream, was covered in red \"stains\" and lying still on the floor. Panicked, I was about to call the police, but Victor stepped forward and noticed something odd..."
  },
  [107731] = {
    diary_text = "The elaborate meal that had been prepared for the livestream was ruined by Tornado, so at Victor's suggestion, we decided to make a \"dog cake\" for him instead. What we thought would be a simple task turned out to be surprisingly tricky."
  },
  [107741] = {
    diary_text = "When the livestream started, Tornado lived up to his reputation and devoured the food like a true tornado, leaving the audience amazed. I asked Victor to pass me a tissue, but when his hand briefly appeared on the screen, the comment section exploded with excitement..."
  },
  [107811] = {
    diary_text = "After attending a routine briefing of LFG, I met Victor on the side of the road. He told me that he had come to pick me up on his way back from a meeting nearby. On the way back, I kept receiving messages from work..."
  },
  [107821] = {
    diary_text = "After the meeting, I was surprised to see Victor in the pantry opposite the meeting room! Just before I sat down to say something to him, messages from work flooded in once again. It dawned on me that Victor's words... had a hidden meaning."
  },
  [107831] = {
    diary_text = "Victor behaved unlike himself today because... for three days I had not replied to one single message from him! So I went into his office, trying to figure out if he would tell me the truth...!"
  },
  [107841] = {
    diary_text = "Seeing how unmoved Victor was, I had to admit defeat. By asking him to help me review my proposal, I launched constant \"offensives\" against him. After several rounds of mutual tests, we confessed to each other and let our hidden desires go unchecked."
  },
  [107911] = {
    diary_text = "I set the alarm clock to wake me early in the morning. But little did I know it would be an oversleeping Victor that prevented me from getting out of bed."
  },
  [107921] = {
    diary_text = "Just as I was reminiscing about the first time Victor and I came here, Victor presented me with a small surprise."
  },
  [107931] = {
    diary_text = "Victor used a little trick and found the tomatoes he and I planted. Then, I confessed to Victor why I had chosen to plant tomatoes over everything else..."
  },
  [107941] = {
    diary_text = "After we had finished, Victor tricked me into eating a still-sour tomato. Then, while we rested, I told Victor how I felt about the collaboration. In exchange, Victor told me what he had learned from me."
  },
  [108011] = {
    diary_text = "I was agonizing over a photo wall in the house, feeling like it was missing something. After listening to me grumble, Victor suddenly took out two invitations."
  },
  [108021] = {
    diary_text = "A film that LFG funded was holding a publicity event and invited Victor to attend. The next day, Victor took me to the event. While he talked with the director, I went ahead into the venue."
  },
  [108031] = {
    diary_text = "To my surprise, they had set up an immersive experience for the publicity event. The whole place was suddenly plunged into darkness. Amidst virtual disasters and tsunamis, I found myself looking for Victor; and he was looking for me too."
  },
  [108041] = {
    diary_text = "I crept up behind Victor to prank him, but little did I know, he already knew. When the lights came back on again, I saw an incomparably stunning \"Mighty CEO\" amidst the blighted landscape. I had found the scenery that my photo wall had been missing, but Victor said what it was missing most was me holding his hand."
  },
  [108111] = {
    diary_text = "I couldn't believe that after all that waiting and hard work, I still didn't pass the director's audition. Just as I stressed over it, Victor told me that he was taking me on a vacation to Platinum Beach."
  },
  [108121] = {
    diary_text = "Is it real that nothing escapes Victor's eyes? I've got most of the work done. For the unfinished one, maybe if I just procrastinated a little more...? It's not every day I get to go on a vacation! I might as well enjoy the moment at hand!"
  },
  [108131] = {
    diary_text = "The excitement to see the whales covered up my anxiety for a while. Unfortunately, Victor saw through everything. He told me that he was going to help me overcome my procrastination. His encouraging words gave me the confidence I needed to overcome my problems!"
  },
  [108141] = {
    diary_text = "I was going to spend the entire day working on my proposal, but Victor insisted on taking me on a boat ride. As I lay beside him, riding on the calm and gentle wave, a spark of inspiration suddenly filled my mind."
  },
  [108211] = {
    diary_text = "In reporting to Victor about the shooting of Dawn Market, I told him that the market would be open for business tomorrow. And I asked him to show our support with his presence, to which he said yes."
  },
  [108221] = {
    diary_text = "There was a long queue in the Dawn Market. It turned out coupons could be redeemed by playing the games. I excitedly suggested joining the contest. Victor agreed resignedly and won all the games!"
  },
  [108231] = {
    diary_text = "Victor and Mrs. Jeanne answered all the questions correctly, therefore calling for overtime. The contestants were asked to pick the in-season food ingredients, but Victor's choice puzzled me. After hearing his explanation, I realized how meticulous he was in life."
  },
  [108241] = {
    diary_text = "After two rounds of contests, Victor won a one-month coupon for purchases at the market. I told Victor that I'd like to take life seriously like he did, to which he said proper meals were a way of taking life seriously."
  },
  [108311] = {
    diary_text = "Due to a long business trip, Victor and I haven't seen each other in ages. But after letting my disappointment show during a phone call, I suddenly got a knock at my door..."
  },
  [108321] = {
    diary_text = "I was still buzzing with the joy of seeing him when Victor told me his flight out was tomorrow morning. That meant we only had six hours together..."
  },
  [108331] = {
    diary_text = "As it poured outside and I lay in Victor's arms telling him about my days, I somehow fell asleep. When I woke up, there was no one next to me. He must've already left..."
  },
  [108341] = {
    diary_text = "Although it was just a false alarm, I suddenly knew what I wanted. Tonight there would be no regrets. I got on my tiptoes and leaned into Victor's embrace, giving him a soft kiss."
  },
  [108411] = {
    diary_text = "At a routine LFG meeting, the presence of animal ears and tails made things a little weird. And when I went up to the podium, Victor's reaction surprised everyone..."
  },
  [108421] = {
    diary_text = "Back at home, I felt like Victor was acting a little strange. I was going to help him call off his promise with the cat cafe owner, but he told me not to panic. The next day, we arrived at the cat cafe, and Victor was mobbed by kitties..."
  },
  [108431] = {
    diary_text = "In the cat cafe, we saw all sorts of customers; and I realized that Victor wasn't the only one vexed by cat ears and a tail. I took the cards from the customers and then prepared the special \"vibe drinks\" with Victor, coincidentally revealing what was in my heart."
  },
  [108441] = {
    diary_text = "After the event ended, I accidentally spilled some treats which the cats got all excited over. Thankfully, the cat-king Victor got there in time and quelled the kitties using catnip. When our work was done, he proposed giving me a special reward..."
  },
  [108511] = {
    diary_text = "Wanting to surprise Victor, I arrived early at the bus stop where we'd planned to meet. A little too early, it turned out—I was a full hour ahead of schedule. With nothing else to do, I started planning out the rest of the day to pass the time."
  },
  [108521] = {
    diary_text = "Victor showed up and took me straight to the ranch's \"Bunny Bistro\". When the server brought out the eggs, a tiny chicken design on the top brought my memory back to Souvenir a month ago. It was then that I realized Victor was one of the investors behind the ranch."
  },
  [108531] = {
    diary_text = "We joined the ranch's most popular event, the \"Cow Milking Challenge\". Before we began, I decided to test out my grip on Victor. He humored my little experiment, and during the actual challenge, his soft and affectionate gaze stirred my curiosity."
  },
  [108541] = {
    diary_text = "As the day neared its end, we stumbled upon an injured lamb hidden among the alfalfa flowers. After rescuing it together, Victor finally shared the real reason he poured his efforts into saving this town—and in that quiet moment, everything began to make sense."
  },
  [108611] = {
    diary_text = "After successfully signing a deal with Prisme, I asked Victor about his later plan. However, Victor told me he was going to keep it a secret. Through an email, I found out that Victor was going to take me to a seminar hosted by the great entrepreneur Mr. Morris!"
  },
  [108621] = {
    diary_text = "Mr. Morris' first question for us was to write down something that affected our emotions the most. Without hesitation, I scribbled down Victor's name. While I did so, Victor was already flipping his notebook to a new page..."
  },
  [108631] = {
    diary_text = "I ordered some midnight snacks and prepared for the simulation project from the seminar with Victor. To keep me from falling asleep after eating, Victor made a cup of coffee for me. While we were resting on the patio, I ended up finding closure on something I never had the chance to do back in college..."
  },
  [108641] = {
    diary_text = "After the seminar, Victor and I roamed the streets of Lyon. He told me about the answer he scribbled down in his notebook. As for him, the most precious \"investment\" was already firmly within his grasp."
  },
  [108711] = {
    diary_text = "我兴致勃勃地等着李泽言发现我今日的特别之处，没想到他始终淡定从容，不动如山。最后在我的一步三回头下，他终于问我其中的缘由。于是我得意地对他扬起下巴，邀请他参与我的豪华野餐活动，并告诉他——我中彩票了！"
  },
  [108721] = {
    diary_text = "在前去营地的路上，面对李泽言的淡定，我有些不服气地向他重复着自己的中奖经历。等我们来到营地后，我假装自然地环视四周，实则是在搜索小黑猫的踪迹，没想到它真的出现了！"
  },
  [108731] = {
    diary_text = "我开心地用小零食跟小黑猫打招呼，李泽言通过它的体貌特征推测，这只小黑猫应该是附近的家猫。"
  },
  [108741] = {
    diary_text = "作为野餐的邀请者，我自然准备担起准备餐食的工作，而李泽言也完全没推脱，一边站在旁边撸猫一边陪我说话，不过随着我们的交谈，手里的活儿又回到了李泽言的手上。虽然有些不服气，但在打闹过后，我还是乖乖等在一旁。望着李泽言的背影，我对小黑猫再次掏出了彩票——只不过这次，我的奖品是李泽言亲自发给我的。"
  },
  [108811] = {
    diary_text = "While infiltrating the [i]Eternity[/i], I blew my cover and was brought by the crew to face Captain Victor. I was going to use the opportunity to launch a sneak attack, but Victor pushed me down onto a chair..."
  },
  [108821] = {
    diary_text = "Not willing to admit defeat, I slipped into the captain's quarters to challenge Victor once again, but was sent packing again. I thought I would die by his hand, but Victor let me go, allowing me to continue challenging him every day."
  },
  [108831] = {
    diary_text = "During each successive challenge, I gradually found the joy of sailing and was no longer driven by my obsession to find the Tear of the Gods. But after fighting alongside Victor once, his questioning uncovered the scar of my memory..."
  },
  [108841] = {
    diary_text = "In a panic, I sailed away from the [i]Eternity[/i], only to discover it had fallen into the Siren's trap. To break the illusion, I bit the bullet and set fire to my own ship. The moment I rushed to Victor's side, I seemed to undo a knot that had been tied in my heart for a long time..."
  },
  [108911] = {
    diary_text = "Victor didn't seem to get a break from his recent streak of bad luck. His company just recently suffered a major loss, putting a sign of agitation on his usually unflappable face."
  },
  [108921] = {
    diary_text = "To cheer him up, I secured tickets to a piano recital of his favorite pianist and placed a lucky charm in his bag. Even the blooming dendrobium orchids at the door seemed to signal that good luck was on its way..."
  },
  [108931] = {
    diary_text = "Attempting to recoup the losses, Victor arranged a meeting to discuss a potential partnership with another company. I sneaked close to the hotel where his meeting was held and arranged a small surprise for him at a nearby boba tea shop."
  },
  [108941] = {
    diary_text = "Unfortunately, the deal didn't go through, and we missed the recital. Back home, I offered to give Victor a facial massage. Sensing that he was trying to digest his feelings on his own, I expressed my feelings with honesty and told him that I wanted to be there for him whenever he needed it..."
  },
  [109011] = {
    diary_text = "The company keeps on growing! But that also means more new hires and bigger gaps in age and culture among personnel. I asked Victor if he had any way to navigate this issue."
  },
  [109021] = {
    diary_text = "Victor actually got a little jealous at a stray remark of mine. I never imagined Victor could get petty like this, but sweet-talking him out of his bad mood was simple~"
  },
  [109031] = {
    diary_text = "After a series of activities, the morale of the company's staff was gradually improving. Now there was just one more \"hipster party\" to really get everyone to open up. But why was Victor suddenly asking me what time I was coming home...?"
  },
  [109041] = {
    diary_text = "This was the first time I'd ever seen Victor looking so \"hip\"! He looked so suave I almost didn't recognize him. What delighted me even more were those little shows of emotions under the neon lights that were all for me..."
  },
  [109111] = {
    diary_text = "While location scouting, a friend and I set foot in an old mansion in the mountains. In between taking photos, I was led by a bizarre thread to the backyard where I encountered a somewhat dangerous man..."
  },
  [109121] = {
    diary_text = "After waking up in a bed-and-breakfast, I was frightened to learn that what I'd just encountered may be a fabled mountain wraith. While rejoicing that I was still in one piece, I was pulled by a strange force back to the old mansion and saw him again. But this time, I didn't seize my chance to escape..."
  },
  [109131] = {
    diary_text = "I racked my brains for a bargaining chip to get Victor to help me, but I came up with nothing. During one conversation, I shared with him the sights I'd captured with my lens and wanted to make a pact with him to go traveling together in the future. After a moment of silence, Victor proposed a trade condition that surprised me..."
  },
  [109141] = {
    diary_text = "The bind of the old mansion was thus broken. But I finally learned the price Victor needed to pay for rescuing me. With my long-awaited freedom at hand, I looked into Victor's deep gaze and finally made up my mind to take a step..."
  },
  [109211] = {
    diary_text = "A happy summer vacation started with seeing the sunrise from an airplane. It turned out, this sudden vacation was Victor's attempt to make up for the imperfect end to my summer."
  },
  [109221] = {
    diary_text = "I was surprised to discover that Victor was wearing a vacation shirt I had given to him before. It was such a pleasant surprise. His laptop never left his side. I guess he still had to work?"
  },
  [109231] = {
    diary_text = "Victor couldn't stop worrying about me and brought his work to the beach to be with me. An errant soccer ball rolled up to us, giving me a chance to personally witness Victor take a shot on goal..."
  },
  [109241] = {
    diary_text = "It was time to \"sign off\" for the summer, but to my surprise, Victor brought things to a climax again. Drones twinkled in the night sky like stars, illuminating all my fantasies about the end of summer."
  },
  [109311] = {
    diary_text = "With a rare chance to take a long road trip, I was determined to show Victor my driving skills! I was driving smoothly and following all the rules. The only problem was... I think I missed the exit I was supposed to take..."
  },
  [109321] = {
    diary_text = "We finally made it to the town for a rest, but then they told us all the rooms were occupied? We'll never travel during the busy season again... Although fortunately, a local told us about a place where we can park and camp..."
  },
  [109331] = {
    diary_text = "Despite challenging road conditions, we unexpectedly lucked into catching some beautiful glacier scenery. What made me even happier was seeing Victor's panicked side... so, so cute."
  },
  [109341] = {
    diary_text = "Being able to calmly face the unexpected helps keep one grounded much better than constantly dwelling on past faults. As I watched the snow with Victor, I was keenly aware that what really kept me grounded was this person right next to me."
  },
  [109411] = {
    diary_text = "I was responsible for LFG's New Year's proposal but it was much more difficult than I expected to make any changes. To console me, Victor said that I could make a requirement for a New Year gift. As I wanted to see if the otherwise infallible Mr. Victor would also find requests difficult to cope with, I came up with a vexing one."
  },
  [109421] = {
    diary_text = "I saw the things on Victor's desk and discovered that he was preparing a gift for me. On the way back, I tried to pry on what it was but Victor told me to have some confidence in him."
  },
  [109431] = {
    diary_text = "On the last day of the year, Victor and I both took part in LFG's New Year's party. I waited with bated anticipation for Victor's gift all evening, yet the night went on and we went to bed as usual. Seeing my puzzled expression, Victor simply stated that now wasn't a good time for the gift."
  },
  [109441] = {
    diary_text = "I went to sleep, thoughts of the gift wracking my mind. Victor woke me up the next morning and led me to a mountain behind the hotel. There, I saw the gift he had prepared for me. He had managed to complete the vexing problem I gave him, and even better than I'd thought possible."
  },
  [109511] = {
    diary_text = "On his birthday, Victor was swamped preparing for the shareholders' meeting. Pretending to be too busy to return to Loveland City, I planned a surprise for later. But I didn't expect to see Goldman waiting for me as soon as I landed..."
  },
  [109521] = {
    diary_text = "Due to days of relentless work, Victor seemed a little weary. With some persuasive effort on my part, he finally agreed to take a walk with me in the viewing gallery for some much-needed relaxation. But as we neared the venue, we unexpectedly ran into someone..."
  },
  [109531] = {
    diary_text = "After learning the reason behind it, I realized that there had never been a breather in Victor's life, which left me feeling somewhat melancholic. Just before he was due on stage, I straightened his attire and made a promise."
  },
  [109541] = {
    diary_text = "Once the shareholders' meeting concluded, Victor and I boarded his private jet, where he witnessed the array of surprises I had arranged. Against the backdrop of the endless night sky outside the porthole, he whispered his birthday wish into my ear."
  },
  [109611] = {
    diary_text = "公司里新来的实习生工作有些马虎，但我却狠不下心批评。正当我苦恼如何树立老板的“威严”时，李泽言却提出，可以让我从驯服寄养在家里的萨摩耶“椰宝”开始，练习如何树立威严。"
  },
  [109621] = {
    diary_text = "刚进家门，我们就受到了椰宝的热情迎接。看着它无辜的眼睛，我发现自己又“凶”不起来了。这时李泽言提议带椰宝出门散步，让我收拾垃圾。等我收拾好出门时却发现一人一狗都在电梯前等着我。"
  },
  [109631] = {
    diary_text = "我提出宠物都会观察家里的“食物链”，如果椰宝知道我是家里的“老大”，说不定就会听我的了。于是我让李泽言配合我在椰宝面前演了一出凸显“家庭地位”的戏码，但不知为什么，椰宝对此似乎无动于衷……"
  },
  [109641] = {
    diary_text = "我约谈了这位马虎的实习生后，她很快将检查完毕的剪辑发给了我，我邀请李泽言和我一同观看。我似乎以自己的方式，在公司和椰宝面前都成功树立了“威信”……"
  },
  [109711] = {
    diary_text = "While Victor and I had made plans to meet at Souvenir in the evening to try out his new special winter menu, my curiosity got the better of me, and I arrived early. When I came, I found Victor in the kitchen."
  },
  [109721] = {
    diary_text = "Victor and I took to the streets in order to help him find inspiration for the final dessert on the menu to represent winter. We came upon rows upon rows of food stalls, and that made me recall the past winters."
  },
  [109731] = {
    diary_text = "Upon returning, Victor decided to use the tangerines we'd just bought as the main ingredient for his special menu. Acquiescing to his request, I began assisting him in the creation of this new dessert."
  },
  [109741] = {
    diary_text = "With the special winter menu complete, Victor and I ensconced ourselves on the sofa for some well-deserved rest. While lounging there, Victor told me about his thoughts regarding the dessert..."
  },
  [109811] = {
    diary_text = "Victor's last-minute business trip threw a wrench in our Valentine's Day vacation plans. I was at a bit of a loss, but I still hoped Victor's work would go smoothly. Victor seemed to be able to tell that I was hiding my emotions around him. After some questioning, I finally came out with the truth."
  },
  [109821] = {
    diary_text = "On Valentine's Day, I came to the airport to help a colleague. However, between interviews, I saw Victor's silhouette. He seemed travel-worn and weary, apparently having made a special trip back."
  },
  [109831] = {
    diary_text = "Victor \"borrowed\" me away from work and took me to Lakeheart Island where I was shocked to discover he had a Valentine's Day surprise all planned out for me. It turns out he had taken to heart the true feelings I had confessed to him that night."
  },
  [109841] = {
    diary_text = "Seeing Victor do all this, a greedy notion sprouted up in my mind. On this special day, I wanted to hear Victor confess for once... his true feelings."
  },
  [109911] = {
    diary_text = "我提前来到青森公园，为李泽言送去惊喜。汇合的时候，我却发现他有一丝疲惫。循着记忆中的路线前行，我们来到了森林火车前。"
  },
  [109921] = {
    diary_text = "火车依旧是旧时的路线，我们在车上互相讲述着彼此曾经在这里的经历。在发掘回忆的过程中，李泽言的心情也好了起来，讲了很多大学时期的趣事……"
  },
  [109931] = {
    diary_text = "火车抵达了终点站，将我们送到了湖边，然而这里已经不是我和李泽言熟悉的模样。我们坐上船只，我用相机捕捉下了最为动人的好春光……"
  },
  [109941] = {
    diary_text = "旅程的后半段由我来带路，我来到了多年前遗憾没能去的奶茶店，在这里，李泽言告诉了我这次旅程之于他的意义。我和他约定，在这个春天里，我们还要书写更多美好的故事……"
  },
  [110011] = {
    diary_text = "Victor went out to celebrate after making big progress on a project. Meanwhile, after he came home, a series of actions indicated he was clearly tipsy."
  },
  [110021] = {
    diary_text = "While intoxicated, he bought two tickets to France. When he sobered up, he explained to me the reason for doing this and promised he would compensate me for his erratic behavior."
  },
  [110031] = {
    diary_text = "We arrived at Victor's mother's house in France and found a journal from a study tour he took in France when he was little. The stories inside and the images of him as a child touched my heart."
  },
  [110041] = {
    diary_text = "The next day, Victor took me to the seaside. I realized this was his \"compensation\" to me, and I also realized he'd put a lot of thought into it. And so, I couldn't resist speaking to him from the heart on that shore."
  },
  [110111] = {
    diary_text = "After getting through a busy period at work, Victor and I took part in a competitive role-playing game together. On the first day, I got a little cocky when it seemed like I was outplaying Victor. I taunted him mercilessly and managed to get his name tag."
  },
  [110121] = {
    diary_text = "In an effort to win and avoid any suspicion, our little team all agreed that we wouldn't meet with our significant others outside of the game too. That night, I tried to give Victor a call, but to my surprise, he had come looking for me. To avoid getting found out by my teammate, I hid Victor in my room. Sure enough, the teammate that had come looking for me showed up..."
  },
  [110131] = {
    diary_text = "On day two of the game, I saw that Victor still didn't seem to have his mind on the game, so I relaxed. After easily getting the name tags of all the other team, Stanley told me about a special mission that I was raring to take on. After some looking around, I discovered a secret button near the fountain. Little did I expect that I'd end up chained to the column, and that... Victor would show up!"
  },
  [110141] = {
    diary_text = "All I could do was gladly take the bait of Victor's little subterfuge. Victor gave his thoughts on the theme of the game, and it actually got me fired up. I thought I was going to beat Victor, but I ended up getting fooled by \"time\". In the elevator, I wanted an answer..."
  },
  [110211] = {
    diary_text = "Beneath a radiant sky, on sands as white as pearls, I wielded a branch with the flair of an artist, scrawling awkwardly yet earnestly across the sand: \"Victor is the number 1.\" It was at the moment of inscribing the final flourish that Victor emerged like a shadow behind me."
  },
  [110221] = {
    diary_text = "It was during our last oceanic venture that we chanced upon and saved a beached dolphin. Today is the day we returned the creature to the ocean's embrace. Amidst our conversation, Victor subtly expressed his support for Miracle Finder's filming out at sea."
  },
  [110231] = {
    diary_text = "Embarking on this filming journey meant I had to leave Victor for a while. As we reached a silent accord, a school of dolphins arrived, a sight that Victor captured with his camera."
  },
  [110241] = {
    diary_text = "In my awe at the dolphins' profound sentience, Victor expressed his belief that such behavior is an innate drive found in all living things, just like how he felt moved to reciprocate the boundless adoration and care I bestowed upon him. And I, too, experienced a deep recognition of Victor's significant imprint on my life."
  },
  [110311] = {
    diary_text = "Victor received a commemorative photo album from his old school. As I flipped through its pages, I came across an adorable old photo of him. While I admired it, he mentioned his plan to donate a building to the school and suggested we visit his alma mater together."
  },
  [110321] = {
    diary_text = "After finalizing the donation, Victor unexpectedly came across a wish he had written down on a note as a child. Guided by the old photos in the album, we strolled through the campus, retracing the memories captured in the pictures."
  },
  [110331] = {
    diary_text = "We didn't manage to find the spot where his adorable photo was taken, which left me feeling a bit disappointed. Noticing my mood, Victor brought me back to his old house. While we were playfully exploring, I stumbled upon the \"secret\" written on his childhood wish note."
  },
  [110341] = {
    diary_text = "That \"secret\" stirred a myriad of emotions within me, but Victor seemed unaware. Instead, he invited me to celebrate his childhood wish coming true. It wasn't long, however, before I discovered that the \"secret\" from his past was, surprisingly, connected to me..."
  },
  [110411] = {
    diary_text = "I convinced Victor to help me find inspiration for our variety show at the amusement park. We tried loads of attractions and still wanted more. Seeing through my ulterior motive, Victor asked me to draft a proposal by next week."
  },
  [110421] = {
    diary_text = "I managed to submit the draft on time, but I wasn't really satisfied with it. When Victor learned that my aim was to make an addictive game, he suggested a small tweak. I needed his help, but he refused, saying he needed to leave work early."
  },
  [110431] = {
    diary_text = "It turned out that Victor wanted to try making sea urchin salad again, hoping to make up for a previous failure. As I watched him cook, I realized how much he valued my opinion. Although he complained about my tendency to challenge him, I knew he'd be up for the challenge."
  },
  [110441] = {
    diary_text = "I found the perfect game for our show and wanted to try it out myself. Victor patiently joined me in these silly games, and through his actions, he showed me what he was truly \"addicted\" to."
  },
  [110511] = {
    diary_text = "On the way to a business meeting abroad, Victor was shot at by one of the parties, and outside, there were plenty of eyes monitoring us."
  },
  [110521] = {
    diary_text = "After I dressed Victor up as a \"mafia boss\", we managed to elude the sights of our watchmen and get to a jeep. But then I found a sniper rifle in the back seat."
  },
  [110531] = {
    diary_text = "We finally got out of town, but then we encountered a massive sandstorm. We parked on the roadside and hid inside the jeep behind a windproof cloth. The cramped space actually turned into a cozy little harbor."
  },
  [110541] = {
    diary_text = "Once the sandstorm passed, we put the pedal to the metal and finally came close to the town where the meeting was. But then a bunch of vehicles suddenly came out of the town, apparently to stop us from entering. Just then, Victor picked up the sniper rifle and took aim in the direction of the town."
  },
  [110611] = {
    diary_text = "为了给出差的李泽言一个“归家惊喜”，我织了一块玫瑰钩花，谁知意外频出，不仅还没完工时就被布丁叼走了，李泽言也提前回来了。"
  },
  [110621] = {
    diary_text = "鉴于布丁将李泽言的衬衫抓脱丝的“犯罪行径”，我们决定给它洗个澡再剪个指甲。李泽言前往浴室放水，我则趁机继续找钩花，但一无所获。"
  },
  [110631] = {
    diary_text = "虽然有一些小状况，但我和李泽言总算默契地给布丁洗好了澡。趁李泽言换衣服的工夫，我偷偷用罐头“诱惑”布丁指出钩花的位置，这时，身后忽然响起李泽言的声音……"
  },
  [110641] = {
    diary_text = "看着相册里从手忙脚乱到默契配合照顾布丁的照片，我不由有些感慨。就在这时，布丁突然叼来了我的钩花，而李泽言的眼神也变得意味深长……"
  },
  [110711] = {
    diary_text = "Victor and I got stranded on an uncharted island due to an incident at sea. After a long search, we found a random fishing village that took us in. The only problem was, there was no guesthouse in the village, so we were forced to move into the clinic."
  },
  [110721] = {
    diary_text = "Conditions in the clinic were worse than we imagined. Victor and I cleaned for most of the day, and when we finally got a chance to lie down and rest, the constant sound of rain made it hard for me to fall asleep. Then, Victor came over and squeezed into bed with me, helping me sleep with a special method."
  },
  [110731] = {
    diary_text = "The next day, Victor and I got on a boat and cruised around the local waters. After Victor did some diving, I realized that he got sunburned, so I helped him apply sunscreen. However, as I was rubbing him down, Victor did something out of the ordinary..."
  },
  [110741] = {
    diary_text = "After several days of touring around, today Victor took me by bike to a lighthouse. Apparently, he remembered a casual comment I made when we first came to the village, and he wanted to try cooking for me here. Then, after I had left for just a brief moment, a thick plume of black smoke came billowing out..."
  },
  [110751] = {
    diary_text = "After dinner, Victor took me to the roof of the clinic to put a soundproof barrier on it. With the renovation complete, he and I lay shoulder to shoulder on the sunset-bathed rooftop making idle chit-chat. Then, I really opened up to him, saying that no matter what he did for a living or where he did it, he and I would always end up together."
  },
  [110761] = {
    diary_text = "A sudden storm forced us back inside the clinic. In the humid room, Victor and I simultaneously thought of a way to cool down. As he wiped me down, I grabbed the ice cube and tried to pull a fast one, but he easily turned the tables on me. He took all my provocations in stride and regained the upper hand until I willingly lowered all my defenses for him."
  },
  [110811] = {
    diary_text = "The first day of school is always full of excitement, like some wonderful secret waiting to be unlocked. Starting the semester with a new look, it feels like school and life are full of possibility. After getting my materials and summer vacation homework ready before the first class, I proceeded to the practice field with speech in hand to do a final run-down of the procedure for the flag-raising ceremony."
  },
  [110821] = {
    diary_text = "The results of a mock test and our rankings came out, and thankfully I was pretty firmly within my target range. Looks like I'll need to keep it up. Next, it was almost time for the fall sports meet. Once I signed up for something, there was no backing out, but I needed to balance time spent on my studies and my training. That meant no more wasting time on meaningless things."
  },
  [110831] = {
    diary_text = "The recipe I'd been researching finally all came together Friday night. It's nice to be able to give my busy father a break in this small way. In the blink of an eye, it was time to ramp up for the fall sports meet, and work with the public relations department was gradually picking up too..."
  },
  [110841] = {
    diary_text = "Even though I was already mentally prepared for my sponsorship pitch to get rejected, the experience still gave me plenty to reflect on. With everyone looking on, the fall sports meet was about to begin..."
  },
  [110911] = {
    diary_text = "After watching the grand finale of a historical romance drama with me and then listening to me tell about the legend of Loulan, Victor accepted my invitation to take a trip to the ancient ruins of Loulan for the Double Seventh holiday."
  },
  [110921] = {
    diary_text = "On our road trip, a series of unexpected events ended up with us wearing local traditional garb. Then, due to inclement weather, we were invited into the historic preservation center and even given a gift."
  },
  [110931] = {
    diary_text = "The weather cleared, and the Loulan ruins were right nearby. Victor took me on camelback to our destination. We joked along the way, the previous haze swept aside."
  },
  [110941] = {
    diary_text = "After entering the ruins, I discovered the ancient monuments had been severely eroded, making it practically impossible to find the fabled rose. Seeing my disappointment, Victor took me to an inconceivable place..."
  },
  [111011] = {
    diary_text = "I was in the royal chamber with the unconscious Victor talking to myself when he suddenly awakened—and he'd heard everything that I just said. Faced with this crafty monarch, I chose to come clean and tell all..."
  },
  [111021] = {
    diary_text = "Outside the palace, I discovered that Victor had been plotting in secret for a long time. I learned that the Church has been making blood sacrifices of commoners, and I stated my wish to carry on the legacy of my parents and join forces with Victor. After that, we walked down the wintertime streets, and I discovered that Victor wasn't as cold and ruthless as I imagined..."
  },
  [111031] = {
    diary_text = "Thanks to Victor's lightning-quick methods, we soon collected evidence of the blood sacrifices. On the eve of the national convention, I was nervously pacing back and forth. During a discussion with Victor, I confessed my feelings for him and received his deep, devoted response."
  },
  [111041] = {
    diary_text = "After the Church was done away with, Victor worked night and day making reforms, and his health improved steadily. Today, he suddenly woke up and said he wanted to see the snow with me. He and I shared a drink together in the wind and snow, just as the sun seemed about to set..."
  },
  [111111] = {
    diary_text = "Late one night, I was being raked over the coals by a business partner, so I dove on Victor in search of solace. In response to my outburst, he was unusually assuring and gave me endless motivation."
  },
  [111121] = {
    diary_text = "Having gotten through another busy morning, I was leaning on the windowsill and chatting away with Victor on the phone. Although I was literally listening to his voice, I still couldn't help missing him. And so, after my meeting, I grabbed two coffees and ran over to LFG where I just happened to see Victor across the street."
  },
  [111131] = {
    diary_text = "I checked into the hotel Victor had booked near my film site, but I underestimated how comfortable it would be. Victor held me so I could sleep after pulling an all-nighter. Even with just two hours, because I was by his side, I felt recharged."
  },
  [111141] = {
    diary_text = "While we were scrambling to do on-site rehearsals, the chief business officer of our former sponsor paid a special visit and started giving me a hard time, but I calmly and firmly stood my ground and fired back. With lots of things coming to a close for now, Victor and I holed up at home, cherishing a brief period of downtime."
  },
  [111211] = {
    diary_text = "我来到李泽言办公室倾诉了工作的烦恼，实则是给他埋下了一个“小陷阱”。李泽言似乎早已看穿，但并没有揭穿我。"
  },
  [111221] = {
    diary_text = "为了说服李泽言成为传统文化活动的“板块代言人”，我给他下载了短视频软件，却被他看到了我记录他烹饪时的视频。"
  },
  [111231] = {
    diary_text = "我带李泽言来到了一个二胡工作室，在这里为他拍摄了一段视频，向他证明我的方案的可行性，而他的高度配合让我有些意外。"
  },
  [111241] = {
    diary_text = "正式拍摄短视频的当天，李泽言吐露出了他的心声——他之所以如此配合我，是因为在他心里，我已经是十分成熟的被投资方和伴侣。"
  },
  [111311] = {
    diary_text = "Tonight coming back from a dinner party, I saw Victor at the door waiting for me. As we talked, I learned that this \"big brother\" figure who I thought would always be around was going to be leaving home soon..."
  },
  [111321] = {
    diary_text = "I mustered everything I had to hide my sadness in front of my father and gracefully raised a parting glass to Victor. After the others were asleep, I hesitated a long time before deciding to go to Victor's room and try to convince him to stay."
  },
  [111331] = {
    diary_text = "Victor didn't acquiesce to my plea. Instead, he told me there were some things he could only achieve by leaving. After he said goodbye to his home, I stopped hearing news about him. Then, a good friend suddenly gave me an idea that might get Victor to appear..."
  },
  [111341] = {
    diary_text = "The moment I saw him again, I finally understood my own feelings. While helping him pick out a tie, I seized the opportunity to take Victor to the closet and ask him something from the bottom of my heart..."
  },
  [111411] = {
    diary_text = "The moment Victor awoke, I greeted him with a warm and joyful birthday wish, accompanied by Pudding. When I revealed that today's adventure would take us back to the little park where we first met, he was momentarily taken aback."
  },
  [111421] = {
    diary_text = "The park had undergone a complete transformation due to the city's redevelopment, now gleaming with new life and showing no trace of its past. Yet, I had carefully placed countless blessings and heartfelt messages hidden within this renewed landscape, waiting for him to discover them one by one."
  },
  [111431] = {
    diary_text = "As we wandered through the park, following the trail of memories and surprises, I stumbled upon an unexpected surprise. From the very beginning, it was always Victor who gave this place its special meaning."
  },
  [111441] = {
    diary_text = "As dusk settled, I led him to a bubble house I had decorated in advance, where I offered my heartfelt birthday wishes. Yet it would appear fate has more surprises in store for us..."
  },
  [111511] = {
    diary_text = "I went with the vacation resort staff to the pier to meet the LFG employees coming for a retreat during the holiday. Just as I was searching for Victor in the crowd, I suddenly heard a subtle \"click\" behind me..."
  },
  [111521] = {
    diary_text = "Even though this was a company retreat, the LFG employees were still as nervous as ever around Victor. To lighten the atmosphere, I had the clever idea to invite Victor onstage to be our first audience participant."
  },
  [111531] = {
    diary_text = "I tried scuba diving with Victor, which I'd been wanting to do for a long time, and we even brought back some fish to cook. While taking seasoning over to meet up with Victor, I suddenly heard an employee ask for help. I stopped in my tracks..."
  },
  [111541] = {
    diary_text = "After a heavy downpour, I planned to sneak off while Victor slept and check on the item stashed nearby. However, Victor realized something was fishy and followed along, thereby \"accidentally\" getting an item."
  },
  [111551] = {
    diary_text = "Today while lounging around, I happened to hear Victor still working on the scavenger hunt event I had planned. I suddenly had an urge to investigate the situation and found Victor acting abnormally, which piqued my curiosity more."
  },
  [111561] = {
    diary_text = "After beating me in a card game, Victor took me to the highest point in the resort to redeem his \"wish\". I thought he'd ask where the final item was, but to my surprise, his request was unusually simple..."
  },
  [111611] = {
    diary_text = "I was sitting on the couch one evening, restlessly juggling work from different projects. When Victor approached, I couldn't resist the urge to playfully seek some \"encouragement\" from him."
  },
  [111621] = {
    diary_text = "Later, while I was in the shower, I got a call from Anna, who informed me that one of our partner companies had breached their contract. Frustrated, I ended up bumping my knee. When Victor came over, he soothed my pain in his own way."
  },
  [111631] = {
    diary_text = "Victor appeared as a guest in our company's final episode of business interviews. While we were getting ready, he used the excuse of a loose lapel pin to pull me close, asking for a bit of encouragement himself. During the interview, he made a point to say that everyone needed a source of support and that relying on someone was completely normal..."
  },
  [111641] = {
    diary_text = "After the shoot, we had a celebratory event at the office, and I ended up having a few drinks. Later, I felt a bit tipsy, and Victor led me to a quiet break room. His words gradually dissolved the stubborn worries in my heart. I confessed that he would always be my first choice, but he teased me for taking so long to admit it. When I asked how I could make him happier, he simply pulled me into his embrace..."
  },
  [111711] = {
    diary_text = "因上月工作过于高效，一时“清闲”的我决定帮请假的同事照顾小狗。我和布丁陪着小狗小不点在客厅里疯玩，李泽言从书房出来却吐槽我这几天没有一刻是闲下来的。"
  },
  [111721] = {
    diary_text = "他的话让我想起前两天我在家里大扫除后，央求他给我找点事做的情景。此时小不点又想出去玩，我刚要穿衣服带它出门，李泽言便要求和我们一起出去。"
  },
  [111731] = {
    diary_text = "李泽言带我们来到了一家宠物友好型超市。这是我们第一次“漫无目的”地逛超市，却意外收获了有趣的经历。"
  },
  [111741] = {
    diary_text = "小不点选中了一个不实用的玩具，在李泽言的提醒下我才发现我也不知不觉中选了很多华而不实的商品，但李泽言却阻止了我退掉它们，他希望我能单纯地享受这段清闲的时光……"
  },
  [111811] = {
    diary_text = "Because of the unforeseen situation at the Souvenir, Victor took me to the supermarket to pick up the fresh ingredients we needed. As we arrived, the big screen at the nearby mall was already featuring my latest show. The lively Valentine's Day atmosphere, along with Victor's calm and reassuring presence, began to lift my spirits about the day ahead."
  },
  [111821] = {
    diary_text = "To save time, I helped Victor with our feast. We had to scramble a little bit, but we managed to get it done. Just as we were about to relax, a mysterious package was delivered."
  },
  [111831] = {
    diary_text = "It turned out Victor changed his plan with a chocolate fountain for the occasion, but he jokingly called it \"taking the easy way out\" because the set-up was very simple. I was pleasantly surprised by the idea, and told him that paying attention to tiny details was what really made me happy."
  },
  [111841] = {
    diary_text = "When the elderly woman in the show reminisced about her past, I couldn't help but think about our future. To cement a bet with him that wouldn't be settled for decades, I made a golden ring with the wrappers from the chocolates. Even without the bet, however, I knew that today would be forever etched in our memory."
  },
  [111911] = {
    diary_text = "尽管前期做了不少准备工作，华锐新购入商厦的人流量却并不如预期。席间管理层进行复盘时，我意外听到了一个有些玄妙的原因。"
  },
  [111921] = {
    diary_text = "趁李泽言睡觉的时候，我偷偷拿出手机，搜索起了有关石狮子和风水球的都市传说。正听到关键的时候，耳畔忽然传来一阵温热……"
  },
  [111931] = {
    diary_text = "趁着夜色，我和李泽言依照视频中的方法，向石狮子张口的方向前进。尽管有些困倦，但因为李泽言在身边，我反而得以实现了大学时的某个愿望……"
  },
  [111941] = {
    diary_text = "虽然不明白双层巴士和石狮子之间有什么关系，我和李泽言还是坐上了返程的巴士。阳光迎面而来，我正惬意地靠在他身边的时候，广播中的某条语音不经意间解答了我们的困惑……"
  },
  [112011] = {
    diary_text = "Today, since I've been away on a business trip, I video chatted with Victor. We were talking as usual when he noticed a Shiba Inu ornament I'd hidden in a cabinet. Finally unable to contain his curiosity, he asked me why on earth I had hidden so many of these things around the house."
  },
  [112021] = {
    diary_text = "To keep the suspense, I didn't reveal much at all about this \"find the Shiba Inu\" game. We started discussing the topic, and I asked him which place he was most surprised to find the ornament. His answer actually surprised me, and there were lots of feelings of longing tied up in it."
  },
  [112031] = {
    diary_text = "After almost a month of being away on business, I finally returned home. When I saw him, I wrapped him up in a bear hug. Meanwhile, he found the final Shiba Inu that I'd hidden in my pocket."
  },
  [112041] = {
    diary_text = "After he'd finally assembled the whole collection of them, I smiled and gave him a kiss as a reward. However, a little hitch arose in the process. It seemed the bangs I'd trimmed that morning left a little to be desired, and in trying to fix my handiwork, I only made it worse... That's when Victor the Hair Stylist came to the rescue!"
  },
  [112111] = {
    diary_text = "和李泽言一起学舞已经过去了很久的时间，我们逐渐变得熟练又默契。正巧最近有一场业余斗牛舞表演赛，老师建议我们参加，可我却因为担心结果而犹豫了。"
  },
  [112121] = {
    diary_text = "因为我们很快就要去欧洲出差，会耽误不少练习时间，我对比赛的结果没有把握，便不想再用这种方式纪念我们的阶段性成果。得知我的顾虑后，李泽言表示也有其他留下纪念的方式，却暂时对我保密。"
  },
  [112131] = {
    diary_text = "由于这次出差的目的地是斗牛舞的兴盛地，我萌生了在这里留下纪念的想法，于是偷偷为李泽言置办了一身“斗牛士”的装扮。没想到李泽言竟然也把我的红裙子带来了，没有让我错过和他一起“漂漂亮亮跳舞”的机会。"
  },
  [112141] = {
    diary_text = "李泽言在阳台上为我准备了一个“蓄谋已久”的惊喜，也是他一直向我保密的纪念方式。我们在夜幕下共舞，他让我意识到，即使不够完美也无需担忧，因为这个不完美的我，早已被他全部接纳了。"
  },
  [112211] = {
    diary_text = "一想到又可以和李泽言体验结婚了，我就开心得睡不着觉。李泽言好像也很开心，早早陪我出门等候婚礼的开始。可我们的满心期待却只换来了不可抗力、活动取消的坏消息。"
  },
  [112221] = {
    diary_text = "为了扫清空欢喜带来的不甘和遗憾，我用了很多办法，但收效并不明显。就在这时，李泽言告诉我，他为我准备了一场婚礼。"
  },
  [112231] = {
    diary_text = "这场婚礼比我想象中要正式不少，每个步骤似乎都是按照着古代礼制进行的。而在被李泽言迎下花轿后，我惊喜地发现了一位特殊的婚礼来宾。"
  },
  [112241] = {
    diary_text = "婚礼太过真实，让我有些恍惚。我尝试着用“夫君”称呼李泽言，却怎么都觉得有些别扭。晨起后出门散步，在纷扬的白雪中，我们梳理起了这两日的种种心绪，而方才的微妙氛围也早已在不知不觉中被纾解了……"
  },
  [112311] = {
    diary_text = "在年底前的工作汇报中，我和李泽言讨论起了最后正要收尾的案子。我希望能在展览之后举办一场烟花秀，并顺势邀请了李泽言一起参加。"
  },
  [112321] = {
    diary_text = "展会当天，本来在紧锣密鼓准备的我却收到了烟花秀因为天气原因取消的消息。一时陷入失落的我有些没有头绪，却没想到李泽言在此刻突然提出了一个新的“烟花计划”。"
  },
  [112331] = {
    diary_text = "用屏幕绽放烟花的计划虽然成功推进，但还需要一些时间调试，为了延长原本的展览时间，我决定和李泽言一同进入会场，吸引宾客们的注意力。"
  },
  [112341] = {
    diary_text = "活动结束，客人们也逐渐离开了天空餐厅，此刻的天空却捉弄般地放晴了。正准备离开，李泽言却提议让我们走一走观光楼梯。在楼梯上，李泽言点燃的烟火染尽了夜色，此时便是最好的庆祝。"
  },
  [112411] = {
    diary_text = "清晨，在李泽言睡醒之前，我到了游轮集控室做生日惊喜的最终确认。由于调错了音轨，整艘游轮的华锐职员都知道了今天是李泽言的生日。"
  },
  [112421] = {
    diary_text = "我们正在小镇游玩时，有职员热情地对李泽言送上了祝福。这下，知道他过生日的人越来越多了。于是，他单方面让我帮忙收下了纷至沓来的祝福。"
  },
  [112431] = {
    diary_text = "在华锐职员们为李泽言庆生的现场，他自然地以家属身份介绍了我。我也因为上午的冒失向大家表达了歉意。"
  },
  [112441] = {
    diary_text = "在李泽言主动发问后，我才意识到原来他一直在期待我准备的生日惊喜，于是便牵着他跑去了游轮最顶层的甲板。那里，有一份特别的生日礼物正在等着他……"
  },
  [112511] = {
    diary_text = "为董事会忙了一天之后，李泽言又参加应酬，迟迟没有回家。我放心不下跑去接他。不过我的担心也许是多余的，因为散场后的李总看起来好像心情不错……？"
  },
  [112521] = {
    diary_text = "回家之后李泽言看起来一切如常，但还是被我发现了泄露他醉意的“证据”。得知他是因为影视板块得到了肯定，才高兴得多喝了点，我也跟着开心起来。然而睡到半夜，我忽然发现身边的人不见踪影……"
  },
  [112531] = {
    diary_text = "我听见楼下传来弹奏钢琴的声音，原来是布丁在琴上“跑酷”。可更离谱的是，李泽言居然从厨房出来，也坐在琴边偷偷弹奏我的乐谱。一番询问后我才知道，他是在等给我的“奖励”出炉……"
  },
  [112541] = {
    diary_text = "坏消息是，李泽言半夜做的布丁造型不佳；好消息是，我还是如愿吃到了这份心意。作为回礼，我想要把先前偷偷练习的歌曲唱给他听，而他答应为我伴奏。和煦的暖阳中，音符悦动，琴瑟和鸣，想要让对方感到幸福快乐的心情，也在此刻共振。"
  },
  [112611] = {
    diary_text = "我和李泽言给某家新开的民宿当体验官，在当地的步行街上，一位古风打扮的大娘突然召开相亲大会，还声称她脚边的小哈士奇富贵拥有给有缘人牵线的特殊能力。"
  },
  [112621] = {
    diary_text = "富贵通过了参加者的测试，成功在台下找到了对方故意藏起来的另一半。我跃跃欲试，想让富贵认证我和李泽言也是“最最般配”的一对，但它似乎有另外的想法……"
  },
  [112631] = {
    diary_text = "富贵咬走我的烤乳鸽后逃窜而去，相亲大会也因此终止。我和李泽言本要继续原本的行程，不料却在途中和大娘再次撞上——原来她仍没有把富贵找回。"
  },
  [112641] = {
    diary_text = "我和李泽言加入大娘的寻狗队伍，最后在市区公园里找到了卡在树桩里的富贵。同时，我也知道了富贵特殊能力背后的秘密……"
  },
  [112711] = {
    diary_text = "我在巨人国的展览上展示自己的羽毛工艺品时，终于见到了梦寐以求的黑羽燕子。他就是传说中的\"天际收藏家\"李泽言，虽然态度高傲，但对羽毛的见解却让我折服。为了能多了解他，我提出用羽毛护理秘方换取他讲述的故事。"
  },
  [112721] = {
    diary_text = "李泽言带我参观了他的收藏室，那里的珍稀羽毛令我大开眼界。当我因太过专注工作而忘记吃饭时，他居然亲自下厨为我煮了一锅粥。填饱肚子后，我提出我想去南岛看看，却遭到了他的反对……"
  },
  [112731] = {
    diary_text = "我们和巨人国王告别，出发去了南岛。在红树林休整的夜晚，月光下，李泽言向我展现了他对羽毛的独特理解。听着他温柔的讲述，我不知不觉靠在了他肩上。这一刻，我才发现自己的心意似乎已经悄然改变。"
  },
  [112741] = {
    diary_text = "抵达南岛后，我们因暴风雨躲进山洞。看着黑钻石的光芒与他羽毛交相辉映的瞬间，我终于明晰了自己的心意。雨过天晴后，我将这份心意向他剖白，还给了他一个特别的“礼物”。从今以后，我们将一起去到更远的地方，继续探索更广阔的世界。"
  },
  [112811] = {
    diary_text = "在一场冗长的商谈后，我愈发相信自己的判断——只有把目光投向那片浩瀚大海，才能赚取无限的财富。而要实现这份野心，人鱼的帮助不可或缺。"
  },
  [112821] = {
    diary_text = "半年前，我偶然遇到了这条叫做李泽言的人鱼。在我完美的计划里，他会成为我打开海洋贸易市场的关键，这段时间以来，我们的关系确实在美食的作用下渐渐靠近。就在我准备向他提起做生意的话题时，他却突然消失了。"
  },
  [112831] = {
    diary_text = "出于担心，我去海底寻找李泽言，却不慎遇上海底内乱。跟随李泽言前往神殿后，我看到了李泽言被钉在王座上的奇异画面，并救了他。"
  },
  [112841] = {
    diary_text = "即便在李泽言的帮助下，我和人鱼的贸易事业发展得如火如荼，但我的心里却有许多说不清道不明的不满足。而在我故意踩了合约红线后，他居然出现了……"
  },
  [112911] = {
    diary_text = "节目组邀请了富豪的家人们上岛进行最后的“物资寻宝”游戏，每组人员都可以从上岛的三样物品中保留一样作为工具。作为唯一一组有载具的队伍，我和李泽言毫不犹豫地选择了越野车。"
  },
  [112921] = {
    diary_text = "没想到还没到达第一个物资点，我们的车子便出了无法修复的故障，还被路上遇到的戴维斯先生告知附近的物资点已经被清空。就在我倍感失落时，李泽言却叫住了戴维斯先生……"
  },
  [112931] = {
    diary_text = "一番交涉后，我们用故障的车子和戴维斯先生换了一只硕大的鸵鸟蛋，李泽言似乎打算用易物的方式再换取别的物资，并且已经锁定了下一任的交易对象。"
  },
  [112941] = {
    diary_text = "我们的鸵鸟蛋竟然换来了“华服券”！其他富豪知道后也提出了交换的请求。然而在众多诱人的选项中，李泽言却选择了“营地使用券”，只因他想换的，是能够和我度过的、更美好的时光。"
  },
  [113011] = {
    diary_text = "清早，作为给自己半年以来辛苦行骗的犒赏和离开前的庆功宴，我斥巨资买了一个牛肉罐头。只是我没想到，在享用罐头前，刚被我骗了武器的新晋军火商李泽言会突然出现在我的秘密仓库里……！"
  },
  [113021] = {
    diary_text = "眼睁睁看着李泽言处置完一名工人，我不禁感到恐惧。而更令我胆寒的是他似乎超乎寻常地了解我——无论是我的行骗方式，还是我的预知Evol，甚至是只有我自己知道的生平……但我们分明只见过两面。面对我的试探，他却荒唐地说所有事都是我自己告诉他的。"
  },
  [113031] = {
    diary_text = "被巨大的绝望和压迫裹挟下，我决定与李泽言鱼死网破，却发现他似乎根本没有囚住我的打算。茫然间，我愈发好奇他的目的。我悄悄观察着他，逐渐察觉到他的掌控感并不单单是针对我，而是对于今天会发生的每一件事。"
  },
  [113041] = {
    diary_text = "末日天灾不断，在一场突如其来的地震里，李泽言带我死里逃生。而他也终于向我揭开了所有的秘密。原来在我不知道的日子里，我们已经认识很久很久了……"
  },
  [114011] = {
    diary_text = "在解决雷教授的案件后，我们跟着福尔摩斯第二封信件的指引，来到了一家咖啡店，从而进入了VR游戏中。而此刻醒来的我们乘着马车，来到了豪斯顿庄园。伴随着车夫递交给我们J.M的信件，我们也得知此行的目的是寻找“神秘财宝”。"
  },
  [114021] = {
    diary_text = "豪斯顿将我们请入屋内，在确认了我们的确是福尔摩斯所介绍的侦探后终于放下戒心，开始讲述了他们家族的历史。而他的弟弟威尔斯似乎对我们颇有敌意，兄弟二人也并不和睦。对方向我们展示了带有四签名的藏宝图，在了解了四幅画像和童谣后，我和李泽言决定正式展开对财宝的调查。"
  },
  [114031] = {
    diary_text = "李泽言分析了当前豪斯顿庄园的形式，并让这次找寻之路更有种扑朔迷离的气质。我们跟随藏宝图来到一条死路后，在天花板上成功发现了一处阁楼。而后我们又在阁楼里找到了四幅画像，发现它们的视线都指向这一本航海日记。"
  },
  [114041] = {
    diary_text = "我们凭借着从日记上获得的信息成功解开了“童谣的秘密”，带着豪斯顿兄弟找到了真正的财宝。而此刻我们也将日记带上，达成了任务。在李泽言用计制服车夫后，我们也得以离开庄园，而当离开游戏后，J.M则真的出现在了我们面前。"
  },
  [115011] = {
    diary_text = "As I made my way to him, heavy traffic slowed me down. The storm had already begun, rain pelting against the windshield. Yet, when I told Victor about the delay, he simply reassured me, saying that my safety mattered more than being on time—he was willing to wait as long as it took."
  },
  [115021] = {
    diary_text = "On the drive home, the rain intensified, and Victor took over the wheel. As I recorded the dramatic scene outside the window, Victor glanced at me and remarked that I seemed much braver than before. But I knew the truth—it was because he had always been by my side that I was able to grow little by little."
  },
  [115031] = {
    diary_text = "The storm raged on, and when we finally arrived home, the house was dark. I couldn't find Pudding anywhere, and unease crept in. Despite everything, I realized I still hadn't fully let go of my fears. Just as I was about to sink into that familiar anxiety, a faint glow appeared—Victor had handed me a small lamp..."
  },
  [115041] = {
    diary_text = "Then, with a soft smile, he leaned in and brushed away my lingering unease with a gentle kiss. The next morning, as he got ready for work, I caught a fleeting hesitation in his expression, a reluctance to leave. Without thinking, I wrapped my arms around him, holding him close. I wanted him to know that no matter how tiring life became, I would always be there for him."
  },
  [116011] = {
    diary_text = "为了准备第二期“拯救黑暗料理”节目，我在家好好研究了一番菜谱搭配，并拉上李泽言做我的试吃员。在一番努力后，我的创新料理也总算得到了李泽言的认可，随即便顺势向他发起嘉宾邀约，并参与明天的彩蛋拍摄。"
  },
  [116021] = {
    diary_text = "李泽言和我早早来到小西餐厅准备彩蛋的拍摄工作。就在我打理厨房的时候，发现了餐厅原本的店主夫妻留下的便签，上面真挚的话语让我颇受打动。结束准备的我们将那不勒斯意面定为今天的特别菜单，却发现门口不知什么时候已经排起了长队。"
  },
  [116031] = {
    diary_text = "随着客人渐渐增多，店铺在我和李泽言的共同努力下运转还算正常。终于忙里偷闲在厨房休息了会，顺便向李泽言转达客人们对他手艺的夸赞。此刻咕噜噜叫起的肚子打断了我们对话，李泽言随后将他特制的员工餐放到了我面前。"
  },
  [116041] = {
    diary_text = "结束一天录制回到家，我和李泽言开始翻看今天所录制的素材。不止有我略显生涩的厨艺展示，更有李泽言在厨房中奔波的身影。而这段看似平凡的素材背后，蕴藏着我们一直以来共同珍视的时光。"
  },
  [116111] = {
    diary_text = "厨房中的洗碗机突然罢工，我和李泽言只得开始收拾残局。然而看着李泽言在水槽前挽起袖子的身影，我的脑海里冒出了一个主意。"
  },
  [116121] = {
    diary_text = "原本以为凭借之前的练习，我可以稳操胜券，没想到李泽言也迅速掌握了毛绒球的射击技巧。关键的平局时刻，布丁突然扑了出来……"
  },
  [116131] = {
    diary_text = "我和李泽言前往超市购买清洁用品，居然碰到了“猫先生”的联名商品展示活动！一番采购过后，我开心地拜托李泽言帮我跟猫先生拍合照，他的表现却有些微妙……"
  },
  [116141] = {
    diary_text = "回到家中后，我和李泽言便开始洗碗。在渐渐氤氲的饭香中，计时器的时间一点点流逝。而我看着李泽言的眼睛，也忍不住说出了心中的想法……"
  },
  [117111] = {
    diary_text = "Legend has it that on Southern Mountain there is a blessing tree known to be quite effective. While heading there to make a prayer, I realized that the tree's guardian, Victor, wasn't afraid that I was a Stray. Unfortunately, when I proposed guarding the holy tree with him, he threw me out of the courtyard."
  },
  [117121] = {
    diary_text = "I learned from the village leader that Victor's clan had been protecting the pagoda tree going back 2,000 years. Consequently, I decided to try bribing Victor; but I accidentally dug up some cordyceps he'd been raising. My misstep worked out in my favor though because I was allowed to stay there in order to work off my debt."
  },
  [117131] = {
    diary_text = "On the day of the Double Seventh Festival, I followed Victor down the mountain to collect a debt, and we happened upon a Double Seventh fair. For some reason, he bought lots of things. That night after I fell asleep, I had a strange dream. When I awoke, I was surprised to see Victor."
  },
  [117141] = {
    diary_text = "In the middle of the night, a Taoist Master came calling. He was on my trail. At the moment everything was about to go up in smoke, the only regret in this life I felt was that I wouldn't get to see Victor again. Just then, Victor stepped up and saved me. That's when I realized his identity..."
  },
  [118111] = {
    diary_text = "While making a speech at the Youth Development Conference, I was surprised to see Victor in the audience. Soon, during the host's introduction, I learned that the organizers had invited him as a special guest and that he would attend the \"OHU Special Luncheon\" event."
  },
  [118121] = {
    diary_text = "After being unable to shorten the distance between us this whole time, I couldn't help but let a tiny bit of self-doubt start creeping in. As if to prove something, I decided to try for a seat at the OHU special luncheon."
  },
  [118131] = {
    diary_text = "To get into the luncheon, I spent practically all my time on the summit. Today, after completing the whole agenda, I finally had time to meet up with Victor. As we chatted, I suddenly realized that he had somehow been there with me in spirit the whole time."
  },
  [118141] = {
    diary_text = "I got a notification that I'd been selected for the special luncheon, and during the partner selection phase, Victor and I both independently opted not to select each other. It was another way that we \"ran toward each other.\" After the conference ended, I invited him to the beach for a meal with just the two of us."
  },
  [118151] = {
    diary_text = "He knew full well this was the ocean where he learned to swim as a kid, so he took me out on a swim. Without even me realizing it, he led me far away on our swim, just like how he led me on my path forward all those years ago."
  },
  [119111] = {
    diary_text = "I put on a mature, refined outfit to take part in the \"parent-teacher conference\" for Victor's elementary school. I had no idea I'd actually get to see Victor's final exam sheet! As a \"parent\", of course I had to give little Victor a thorough lecture..."
  },
  [119121] = {
    diary_text = "They said this was a parent-teacher conference, so why was it seeming more like a parent examination? As I worked hard filling out the paper the homeroom teacher passed out, it felt like I was writing a fill-in-the-blank love letter to Victor. Little did I expect, the \"lecture\" I'd given him moments before now all came back around onto me."
  },
  [119131] = {
    diary_text = "After the conference, Victor and I were in the little convenience store that his retired homeroom teacher had opened, and we got a big taste of childhood. An inadvertent comment from me garnered a \"Class Monitor Victor Storytime\" from the teacher. I was giddy with excitement to dig up more of his past!"
  },
  [119141] = {
    diary_text = "While helping the teacher mind the store, Victor asked me why I was so insistent on \"digging up dirt\" on him. Honestly, I just wanted to know more about his past and share more of our journey in life together. Hearing my answer, Victor proposed we play mahjong, and the loser had to tell a story."
  },
  [119151] = {
    diary_text = "We played game after game, and I heard one story after another. I felt closer than ever to that older boy from my childhood. Victor told me that we were already standing in front of the same window and seeing the same sights. And those gifts I wanted to give to the little Victor had already found their way to him on a summer day like this one."
  },
  [120011] = {
    diary_text = "为了露露的安全，我不愿意让它玩水晶球，结果弄巧成拙被小猫咬了。李泽言带我去医院打疫苗，劝慰我面对小猫有时就是多做多错。"
  },
  [120021] = {
    diary_text = "李泽言想要帮我在露露面前重建“威信”，没想到被它耍了。面对格外“狡猾”的小猫，我们不禁重新思索起它的真实意图……"
  },
  [120031] = {
    diary_text = "原来露露喜欢的不是水晶球本身，而是它在阳光下的影子。我也蹲下身，从小猫的视角去理解它们。本以为事情完美解决，没想到两只小猫突然打了起来……"
  },
  [120041] = {
    diary_text = "理解了小猫，也要帮助小猫理解人类。李泽言使出杀手锏“美食诱惑”，终于驯服了露露，让它和我重归于好。而在这个过程中，我发觉自己和李泽言的默契也在不断加深……"
  },
  [120211] = {
    diary_text = "今天和李泽言一起去马术俱乐部，本以为是久违的遛马，却看见了他训练马球的帅气身影，原来他要去参加某场重要的社交午宴，需要为此准备，而我也收到了他的“倾情邀请”。"
  },
  [120221] = {
    diary_text = "在加紧培训了几天马球技术后我腰酸背痛，面对可能会上场的境况心中颇有压力，而李泽言却用他的方式抚平了我的紧张，但宴会当天还是发生了让我出乎意料的事情……"
  },
  [120231] = {
    diary_text = "我从李泽言的神色中察觉到所谓随机并非巧合，他对这个猜想不置可否，随着比赛开始，我和所有观众一样，都被他的登场和表现紧紧吸引着……"
  },
  [120241] = {
    diary_text = "第二小节开始时，我恍然发现李泽言的位置换人了，便无心观赛前去找他。他举重若轻地说出了那些复杂的“不上场”理由，尽管如此，在纷扰之外，他也为我开辟了一场特殊的马球比赛……"
  },
  [120311] = {
    diary_text = "灯火摇曳的街区中，我不动声色地跟一对已经变异“死神”情侣交谈着，为李泽言拿取道具争取时间。见我独自一人，对方似乎动了将我拉走一起转化的念头。就在这时，李泽言的声音忽然响起……"
  },
  [120321] = {
    diary_text = "我们循着道具给出的地点信息，前往了污染源所在的地铁。然而刚走入地下便撞见了一道诡异的影子，站台的灯也不约而同的熄灭。我本能地想去抱住李泽言，黑暗中却跟他撞到了一起……"
  },
  [120331] = {
    diary_text = "我跟李泽言登上了姗姗来迟的地铁，通过一系列机关后，终于到达了驾驶室的位置。我兴高采烈地拉开车门，想要向李泽言展示胜利，却意外落入了陷阱之中……"
  },
  [120341] = {
    diary_text = "想到我跟李泽言马上要分开，为了各自阵营的任务行动，我不由有些沮丧。然而李泽言却抓住了我，提出与我一起转化为“变异者”——在他看来，游戏更大的乐趣在于与我一起。无论我们在哪个阵营，都会赢得胜利。"
  },
  [120411] = {
    diary_text = "我来到南城湾的时候，李泽言也谈完了他的事情，我们正好一起去吃G市的隐藏美食——说起来，每次看到他戴着安全帽的模样，都觉得格外可爱呢！"
  },
  [120421] = {
    diary_text = "李泽言居然在吃饭的时候走神了，是不是他在工作上有什么烦恼呢，不过我很怀疑，世界上真的有能难倒李泽言的事吗？"
  },
  [120431] = {
    diary_text = "李泽言烦恼的与其说是工作上的事，不如说是烦恼那些冗杂的社交，原来他在某种时候也会“社恐”呀！既然知道李泽言能处理好一切，我只需要让他提振心情就好了，比如和他明天一起去吃好吃的早茶？"
  },
  [120441] = {
    diary_text = "我们享受着G市早茶时，意外遇见了我的采访对象段老先生，没想到对方居然也是李泽言的合作对象之一，这算不算我提前送了李泽言一个“人情”？"
  },
  [120511] = {
    diary_text = "我正一边期待着奶酪大会，一边思考着今天的时间应该如何安排，李泽言竟早有准备般向我发来了一份已经规划好的日程表。眼前的他穿着平时不太常见的亮色衣服，带我一同踏入奶酪的世界。"
  },
  [120521] = {
    diary_text = "抵达会展中心后，我惊讶于眼前来自世界各地的奶酪，也忍不住向李泽言询问起一块好奶酪的评分标准……"
  },
  [120531] = {
    diary_text = "李泽言推荐的三款奶酪都获得了不错的成绩，我正打算拉他一起去颁奖典礼，不想这人却觉得奶酪获奖和自己毫无关系。我灵机一动，想到了一个合情合理让他也参与到热闹里的方法……"
  },
  [120541] = {
    diary_text = "颁奖结束，我们也正式投入到“奶酪节”的氛围中，一辆辆奶酪主题的花车从眼前驶过，一整个城市等待我们探索……"
  },
  [150111] = {
    diary_text = "I saw some negative news related to LFG and thought Black Swan Collective was behind them, so I quickly called Victor. His response was rather indifferent, but at least he agreed to meet me!"
  },
  [150121] = {
    diary_text = "I didn't expect Goldman to be the one who came to fetch me. From our chit-chat, I learned that Victor wanted me to attend today's charity banquet. When I arrived, I saw many reporters and staffs who were protesting at LFG outside the banquet venue. It felt strange to me and I planned to sneak into the crowd and get some news."
  },
  [150131] = {
    diary_text = "I met Victor, but he didn't want me to meddle in this situation. Later, while he was gone for a bit, I wandered to a quiet terrace where a man I don't know mistook me as his \"acquaintance\" and told me some shocking inside story of LFG. After accidentally revealing my identity, I was trapped in the reception room by him."
  },
  [150141] = {
    diary_text = "I finally managed to escape and, luckily, met Victor when I exited the elevator! After hearing me out, he was somehow not surprised and only reprimanded me for my recklessness. Relieved, I followed him to another room and met the man just now who planned everything."
  },
  [150151] = {
    diary_text = "I figured out from their conversation that it was a business battle in which Victor emerged the victor. After the evening party, we watched the light show on the top floor of the hotel, which reminded me of the bits and pieces of the past. Although Victor didn't recognize me now and was considered decisive and merciless by other, I still found him appealing in some way."
  },
  [150211] = {
    diary_text = "Our new intern Vivian was growing fast. When we worked till late evening one day, she accidentally revealed that she had a crush on someone out of her reach. Just then, I received a call from Victor."
  },
  [150221] = {
    diary_text = "Victor had accepted an invitation to shoot a short film about wedding traditions in an old town in the south. I was so surprised that I did not realize until much later that he was going to bring me along."
  },
  [150231] = {
    diary_text = "Victor and Director Ronan's friendship reminded me of all the friends I had lost over the years. C'est la vie, I guess. Most of the people we meet are only in our lives for a fragment of time. I felt a little sentimental and subconsciously told Victor that I did not want my relationship with him to be short and temporary."
  },
  [150241] = {
    diary_text = "After we finished filming, I went to the hotel with Victor. When we discussed the theme of the film, my interpretation was people subconsciously idolize those who they deeply love. In reality, I was no exception. However, Victor responded in a different way."
  },
  [150251] = {
    diary_text = "My one-day tryout of being a bride was over. Even after removing all the makeup and hairdo, I still could not help myself but to admire the exquisite wedding gown. Victor came out of the shower room and saw me trying to take a selfie with the veil on. He showed approval when I mentioned that I would like to send Director Ronan off so that they could spend more time together in each other's lives."
  },
  [150311] = {
    diary_text = "On the same day that we crushed the ratings, I also got an invite to an award ceremony and learned ahead of time that I won for \"Outstanding Impact\"."
  },
  [150321] = {
    diary_text = "Keeping my award a secret, I invited Victor to attend. Upon arrival, we ran into the president of the Film and Television Association, and I invited her to sit and chat."
  },
  [150331] = {
    diary_text = "As we chatted, I learned Victor had already been invited! I asked the president to keep my award a secret, but then my dress got ruined by a little boy."
  },
  [150341] = {
    diary_text = "Wearing a back-up dress, Victor and I went out to mingle. Award time was quickly approaching, but Victor was gone. Suddenly, there he was on stage! He presented me with my award!"
  },
  [150351] = {
    diary_text = "Outside, I told Victor why I wore these earrings, and how I'd strived to belong by his side. I joked about giving him an award as a gift, and he gave me a \"thank-you gift\"..."
  },
  [150411] = {
    diary_text = "Victor and I were in his father's place for the Festival. During our stay, Victor's aunt and I talked a lot about her nephew. Victor overheard our chat but didn't say anything—it seemed he had gotten used to that. Then it suddenly occurred to me that Victor hadn't been shy because of me in a long time."
  },
  [150421] = {
    diary_text = "I planned to use the red wine and sugar at hand to tease him a little, hoping it would trigger his other side. But it turned out I overestimated my ability to improvise: I not only messed up the plan, but also gave him a chance to \"fight back.\""
  },
  [150431] = {
    diary_text = "At night, when I passed his room, he was still up, probably waiting for me. The room would have seemed deserted if not for the stationery from his school days and the football in the corner that he played as a child. We reminisced about our dramatic encounter as kids. He reacted strangely when I unintentionally mentioned his childhood nickname—was he being shy...?"
  },
  [150441] = {
    diary_text = "Back in Loveland City, Victor took me to his house in the suburbs for a vacation. Since I couldn't find my pajamas, I used that as an excuse to borrow his shirt in an attempt to bring out his shy side again. But before I could act on my plan, I fell asleep."
  },
  [150451] = {
    diary_text = "Early next morning I got up to prepare breakfast, having forgotten about my little plan. I thought Victor would pick off where he left off yesterday, but instead he started talking about the night we spent in his father's—he helped me relive every detail of that night. Then I realized what he really wanted. In the end, my wish came true and I finally saw him get shy because of me."
  },
  [150511] = {
    diary_text = "A university recently invited me to be an external lecturer as a film and TV producer, but then I ran into Victor. After he sat in on my class, I invited him to attend my class as a \"student\"."
  },
  [150521] = {
    diary_text = "A \"storm\" was stirred when Victor walked into the classroom. After I calmed the class down, I started to teach today's lesson on—desires in movie characters. During the lesson, Victor and I couldn't take our eyes off each other."
  },
  [150531] = {
    diary_text = "After class, Victor came to the multi-function room with me to prepare for my lesson. I asked Victor to help me perfectly demonstrate the tension of the character's desires under the camera. To do this, I pulled out the \"secret tool\" in my plan..."
  },
  [150541] = {
    diary_text = "The kiss marks on Victor's lips made my heart pound. It seemed that we unknowingly found the answer to my lesson plan... But just when we were about to finish, a knock on the door interrupted us."
  },
  [150551] = {
    diary_text = "After the lesson preparation, we went to wait in the VIP lounge. After changing into my gown, I noticed that Victor naturally prepared a pair of disposable slippers for me. I seemed to only ever feel such warmth whenever Victor was around. We began to talk about our desires..."
  },
  [150611] = {
    diary_text = "Seeing that the main army had Unipolis tightly surrounded, Victor finally decided to launch the assault. With battle looming, I thought back on all the little events of the past five years, and my hand clutched tighter around my blade."
  },
  [150621] = {
    diary_text = "On the day of the assault, the battlefield was chaos. I, along with a small squad, scaled ladders and climbed the city walls, trying to take out the city garrison in one fell swoop. But the garrison commander was a fierce fighter. I was held back by his blade, unable to make progress. Just then, Victor fired an arrow."
  },
  [150631] = {
    diary_text = "Lord Chen fell from power. Victor found a horse whip that I had stashed in the palace in my youth, telling me: Whatever had its grip on you, be it enmity or something else, in this moment, it was scattered to the winds. From this day on, I would do exactly what I wanted to do and would not let anything hold me back."
  },
  [150641] = {
    diary_text = "Victor and I had fought hand-in-hand for five years and shared an unspoken connection; but when it came to marriage, I worried that I would become trapped in the palace and lose my freedom. Knowing how I felt, Victor did not try to force me. He said he could carry out the sacrificial offering ceremony by himself."
  },
  [150651] = {
    diary_text = "Under the dazzling lantern lights of Unipolis, who knows how many secret plots are brewing. I could not take it as I thought of how Victor would have to face all these by himself. I decided to ride my horse into the palace and bare my heart to him."
  },
  [150711] = {
    diary_text = "On the top floor of the luxurious hotel, Victor and I began our holiday. Victor told me about his opinion on his investment in this hotel, which revealed his liking for \"delayology.\" So we decided to make a bet."
  },
  [150721] = {
    diary_text = "After making our bet, I enjoyed the breakfast he made for me the next morning. The kiss under the bet made this holiday even more romantic."
  },
  [150731] = {
    diary_text = "The kisses these two days had made it impossible to take my eyes off Victor, but I didn't want to give in so easily. I pretended to take a bath before the party started and called out to Victor."
  },
  [150741] = {
    diary_text = "I was trying to tantalize Victor, yet I still couldn't help drawing close to him. I stole a kiss and planned to run, yet I got pinned down by Victor."
  },
  [150751] = {
    diary_text = "On the last night at the hotel, I enjoyed Victor's meticulously prepared candlelight dinner. We enjoyed a glass of wine afterward. And after a few days' wait, it was time to enjoy the ripe, sweet fruit."
  },
  [150811] = {
    diary_text = "The end of the year was crazy. I worked late every night. I went to bed at midnight and couldn't stop thinking about work. But Victor stepped in. He made me see I was forgetting important things, like my dance classes."
  },
  [150821] = {
    diary_text = "The next day, Victor took me shopping for dance clothes. He told me he'd signed us up for dance classes, hoping it would help me find my center in all this chaos."
  },
  [150831] = {
    diary_text = "After the first class, I felt out of my depth, especially with the whole \"conquer the male dance partner\" stuff. While waiting for the instructor, Victor did something unexpected..."
  },
  [150841] = {
    diary_text = "That evening, I was practicing dance in my home dance studio. Victor, fresh from the shower and in his robe, joined me. Aware of his current vulnerable state, I couldn't resist teasing him. But he turned the tables on me and led us into a bit of spontaneous chaos."
  },
  [150851] = {
    diary_text = "Getting better with work, I wanted to thank Victor. I booked a garden villa just for us and planned a surprise. As we danced, we opened up about our feelings."
  },
  [160011] = {
    diary_text = "互助乡的宴席上觥筹交错。在几位乡长不着声色的注视中，我笑着给李泽言倒了一杯酒，暗中却轻轻勾了下他的掌心：就像前段日子我跟他视频时透露的一样，这个地方并没有看上去那么简单……"
  },
  [160021] = {
    diary_text = "李泽言原本想要和我连夜离开，却得知互助乡的山路和信号塔都因为暴雨“意外”损毁了，只得继续留下。回到房间后，我被他深深地拥在怀中。然而藏在台灯中的窃听器却让我们警醒，眼下还处于危险当中。"
  },
  [160031] = {
    diary_text = "与李泽言商定好接下来的行动后，我终于安心地在他怀中睡去。次日醒来，却发现互助乡的人已经迫不及待地开始了试图洗脑李泽言的行动。然而三名乡长之间的行动，却似乎存在着矛盾。"
  },
  [160041] = {
    diary_text = "备份好隐形摄像机中的证据后，我伪装成虔诚忏悔的样子成功骗过乡长，终于见到了被限制行动的李泽言。尽管有所预期，但他的伤势却比我想象中更加严重……"
  },
  [160051] = {
    diary_text = "次日早上，我和李泽言成功见到了另两名乡长。趁着李泽言跟他们去会议室交谈的时机，我在楼中开始小心探查，却发现了互助乡更黑暗的秘密……"
  },
  [160061] = {
    diary_text = "成功向当地执法军提供线索后，我和李泽言终于从互助乡离开，却还是有些恍惚。在他安抚的怀中，我按捺不住提出了心中的疑问，得到的却是一个意外而温暖的回答……"
  },
  [190211] = {
    diary_text = "I helped the owner of the Three Dreams Quarter to get some groceries. I saw Victor on the way back and even got wine on him everywhere..."
  },
  [190221] = {
    diary_text = "To make amends, I took Victor back to the small courtyard of the Three Dreams Quarter to clean the wine stains. I invited him to try the flower cakes with nine flavors, but Victor tricked me into eating a green pepper-flavored cake."
  },
  [190231] = {
    diary_text = "When I went to deliver the groceries to the kitchen, Victor left with a message. But in the evening, I suddenly found myself in front of Victor because of the Demon King's Pact."
  },
  [190241] = {
    diary_text = "We watched a puppet show together. The show didn't have a good ending for the sorceress, which made me feel low. But Victor told me not to care what other people think. His comforting words cheered me up."
  },
  [190311] = {
    diary_text = "I came to the demon realm to share the last batch of osmanthus cake with Victor, but then noticed something different. I came to Victor's palace, but he happened to be setting off to the demon realm's altar. I then asked him to bring me with him out of curiosity."
  },
  [190321] = {
    diary_text = "On the way to the altar, I was spooked by some plants that resembled the carnivorous flowers in some fiction, and Victor even scared me with it... It started to rain on the way, but it saddened me to see the flowers being battered by the weather. Victor seemed to notice my sadness and protected the flowers with some force..."
  },
  [190331] = {
    diary_text = "The journey was cold and damp. When Victor saw me shudder, he took me to a clearing to take a break. I offered to build a fire, roasted the sugar cake I brought with me, and let Victor try it. Sitting by the fire, he seemed to have something to say, then he draped his cape over me..."
  },
  [190341] = {
    diary_text = "Victor held me by my hand as we reached the altar at the top of the mountain. Seeing the withered plants around me prompted me to offer my help to repair the altar. Victor and I worked together to bring life back to the demon realm again. We stood by each other on the peak, overlooking the miraculous sight..."
  },
  [190411] = {
    diary_text = "From behind a curtain, I tasted the special cakes I was preparing to serve at the Demon Feast; but to my surprise, Victor accurately described their flavors from the other side of the curtain. This once again proved that something was going wrong with the Demon King's Pact between us."
  },
  [190421] = {
    diary_text = "Ever since learning there were shared sensations between Victor and me, every day I experienced wondrous sensations I'd never felt before. Since there was no time to figure out how to disentangle us, that was just the way it had to be for the time being. Today I went to a flower shop on Ninth Heaven Avenue, preparing to pick out the flowers that would adorn the feast, when I fell into a befuddled haze."
  },
  [190431] = {
    diary_text = "After many great struggles, the feast finally got underway as scheduled. Not only were there people from the demon realm at the feast, but also a crowd of demons I'd seen at Dark Moon Market. Just as everyone was waiting for the feast's opening toast, Victor placed the wine cup in my hand."
  },
  [190441] = {
    diary_text = "After the feast, a somewhat tipsy Victor dragged me outside to take a stroll. We walked over Chasm Bridge looking at the flame flowers blooming in the distance, and Victor mentioned that promise from before to help name the flowers. With Victor's reminder, I suddenly thought of the perfect name. I made a promise to tell him, although any promise made with the Demon King always came with a price."
  },
  [200111] = {
    diary_text = "To show my appreciation for Lucien's help on the program, I went on a date with him to the local firefly exhibit."
  },
  [200121] = {
    diary_text = "The exhibit was set up as sparkling corridors to make me feel like I stepped into a tunnel of stars."
  },
  [200131] = {
    diary_text = "We ran across someone selling fireflies. I wanted to save those poor things but was afraid it would encourage the peddler and others even more. Lucien, though, spooked him into releasing them by elaborating on the illegality of his action. Very admirable job, professor!"
  },
  [200141] = {
    diary_text = "Lucien was not the person I know tonight. He stared off into the distant as if he was speaking to someone else. But I still held out hope that these small glimmers will still bring warmth to a cruel world."
  },
  [200211] = {
    diary_text = "It started downpouring on my way home from working overtime. I was already in a lousy mood so I decided to just run home in the rain."
  },
  [200221] = {
    diary_text = "Someone grabbed me as I was about to charge into the deluge. It was Lucien! He saw me shiver and promptly put his coat on me, held an umbrella over my head and walked me home."
  },
  [200231] = {
    diary_text = "The rain got worse. He did his best to cover me with the umbrella, letting his own shoulders get thoroughly soaked. On the way, we found a poor, wet, frozen and trembling kitty."
  },
  [200241] = {
    diary_text = "The rain finally stopped and a beautiful rainbow appeared. Surprise flashed on his face but vanished just as quickly. He is as hard to fathom as stormy sea."
  },
  [200311] = {
    diary_text = "Calls from Lucien always caught me off-guard. This time he asked me to pretend to be his girlfriend. I didn't know why, but I agreed without even thinking."
  },
  [200321] = {
    diary_text = "The date that worried me so much turned out to be a threesome. Anna left her nephew with me, and if you didn't know any better, we looked like a family of three out for a night in the town."
  },
  [200331] = {
    diary_text = "So, Lucien was so popular with the ladies that he \"used\" me as a shield to discourage their advances. But why me, and what am I to him?"
  },
  [200341] = {
    diary_text = "Lucien was short on cold shoulders and long on heart today. Was it the real him? I'm not sure. All I wanted was to just test the water, but before I know it, I'm already in too deep."
  },
  [200411] = {
    diary_text = "Lucien volunteered to take me to the library in the countryside to do research for my show, but his car picked now to break down."
  },
  [200421] = {
    diary_text = "The bus I figured would be empty was packed like sardines. How tired Lucien looked made me feel guilty. I didn't know he knew the bus would be crowded. He even said he liked riding the bus with me. I wonder how he feels about me?"
  },
  [200431] = {
    diary_text = "I tripped on the bus and was sure I would kiss the floor, except he caught me. I felt safe around him. I didn't realize how tired he was, for when we got to the library, he promptly fell asleep on the desk. I followed suit, but caught him waking up and smiling sweetly at me. Oh God, I think I like him..."
  },
  [200441] = {
    diary_text = "I do feel bad about having to bother Lucien all the time, but he said he didn't mind at all and even liked it! He also asked me if I could teach him about love. I wasn't sure whether he was joking or serious…"
  },
  [200511] = {
    diary_text = "Spent three hours making cream puffs last night. Since I had no idea his preferences, I made them in several flavors. "
  },
  [200521] = {
    diary_text = "I was so anxious and full of anticipation when I went to see Lucien at the research center, but another female teacher beat me to it with her own dessert! He declined since he didn't like sweets... What should I do now?"
  },
  [200531] = {
    diary_text = "The tri-leveled lecture hall was full of students. Is neuro-science really that hot these days or are they there for Lucien? I was captivated by the presentation and annoyed by the sun in my eyes at the same time. He moved and stood in a spot to block the sun. Did he do that for me?"
  },
  [200541] = {
    diary_text = "Lucien said he would only eat sweets I made! Good thing I didn't ran off too soon or I would've missed it! Again, was he joking or serious? He ate a puff I took a bite out of, guess that could count as an indirect kiss... I think I can still taste the cream out of the corner of my mouth."
  },
  [200611] = {
    diary_text = "Can't reach Lucien by phone or text for days now. I'm very concerned and worried."
  },
  [200621] = {
    diary_text = "I was hoping to use the Loveland University party as an excuse to talk to Lucien, but saw he sprawled out on a table in deep sleep. His brows were knit so he must be under a lot of pressure lately. Somehow, I got the feeling that something was about to happen."
  },
  [200631] = {
    diary_text = "I went to the party alone and heard everyone speculating about Lucien conducting unauthorized research on his own. I couldn't stand them spreading more lies about him and summoned up the courage to defend him. Just then, he showed up and exonerated himself in just a few words like only he could."
  },
  [200641] = {
    diary_text = "Lucien thought I didn't know but I knew. He dropped his fork so he could bend down and tie my loose anklet under the table. I brought him to the park my dad used to bring me to when I was little. I told him I trust him unconditionally. He looked so devilishly winsome and intoxicated me with his eyes."
  },
  [200711] = {
    diary_text = "To prep for an adventure show, a photographer and I went into the mountains."
  },
  [200721] = {
    diary_text = "The photographer had to leave early and left me to shoot by myself. I got so into it that I got lost. It was too remote to call for any help and, running out of ideas, I was certain I was doomed... until Lucien appeared like a guardian angel before me!"
  },
  [200731] = {
    diary_text = "Turned out he was here doing a study. Lucky me, or I would be sleeping in the wild with the animals! He taught me different ways to get out of here and we followed them to a T. I sprained my ankle in my excitement. Lucien had to carry me off the mountain, but I wish I could freeze that moment."
  },
  [200741] = {
    diary_text = "After we finally got off the mountain, I saw the night market that I often visited when I was little. I brought Lucien to an old shop where the owner handed me a comic book my dad had bought for me when he was alive. Tears filled my eyes, but Lucien consoled me about the past. Will he be my future?"
  },
  [200811] = {
    diary_text = "I was being followed on the way home so I found a place to hide. I probably needed to work on my ninjutsu since a hand soon covered my mouth."
  },
  [200821] = {
    diary_text = "The man asked me to help him lay low, and I struggled until I realized it was Lucien! I brought him home discreetly and noticed there were bloodstains all over his clothes and a long laceration on his arm. What happened to him?"
  },
  [200831] = {
    diary_text = "I couldn't bear seeing Lucien’s injuries. I could only fumble my way through binding the wounds of a pale professor who was normally so dapper and personable. Fortunately, the wounds weren't too deep, and he regained his senses soon enough. That was when I realized how much I cared about him..."
  },
  [200841] = {
    diary_text = "He told me he was in danger because drug runners were involved in his latest project. I felt it was more complicated than that, but chose not to pursue it. After a harrowing night, I found myself in my own bed instead of the couch as I had insisted. He left a while before, but still made me breakfast."
  },
  [200911] = {
    diary_text = "Better not tell Liz that guy's true intention. It will hurt her…"
  },
  [200921] = {
    diary_text = "Seeing Lucien made me all warm and fuzzy inside on snow days, especially when he held me in his arms. I think I'm way past the point of no return. Hope he will like my gift."
  },
  [200931] = {
    diary_text = "Can't believe Lucien doesn't celebrate his birthdays. Did I just accidentally hit a sore spot? Never thought the truth would be like this, but he was happy so that's all I wanted. Sharing his past with me brought us even closer. Hope he'll share more secrets with me and not bottle them all up inside him."
  },
  [200941] = {
    diary_text = "It was so nice celebrating Lucien's birthday in snow. I want to do this not just today, but every year on the day. I can feel the loneliness in him, and I hope I can make that disappear."
  },
  [201011] = {
    diary_text = "Lucien took me to the aquarium, where I've never been to. I suddenly empathized with the feeders trapped in the tank, preys to be hunted and eaten."
  },
  [201021] = {
    diary_text = "Lucien said this is how the world is like. This is a topic I could never get a grip on with him, as if the Lucien I knew was not the real him. Suddenly I remembered the dream from last night... Was it an omen?"
  },
  [201031] = {
    diary_text = "Maybe I was too tired, but I napped on his shoulder. In my dream I saw a mob of men in black circling him. I wanted to help him but couldn't move a muscle. I screamed but he ignored it. All the while, though, I felt warm hands gently stroking my forehead, calming me down and I finally drifted off."
  },
  [201041] = {
    diary_text = "After waking up I saw Lucien next to me, watching me. Were those hands his? I told him about the dream and told him to be careful, only for him to retort what if he is the danger? He touched me irresistibly. I realized I was willing to trust him wholeheartedly, even our journey ahead may be perilous."
  },
  [201111] = {
    diary_text = "Got a tough project I just couldn't wrap my head around, so I decided to talk to Lucien about it."
  },
  [201121] = {
    diary_text = "Finally got through to him, but he sounded he was sick on the phone. Since he helped me out so many times, I figured I'd return the favor with a nice home-cooked meal."
  },
  [201131] = {
    diary_text = "He put a brand new apron on me, probably specifically for this occasion. I felt content watching him gulping down the food I made. "
  },
  [201141] = {
    diary_text = "We pared an apple hand-in-hand. I felt the long, uninterrupted peel signified a quick recovery, although his hot-and-cold mood swings made me think he was a somewhat different person today."
  },
  [201311] = {
    diary_text = "Chinese New Year is almost here and I asked Lucien what he has planned. He said the same-old, same-old. Since I don't want to be alone again for another new year's, I decided to spend it with him."
  },
  [201321] = {
    diary_text = "On the day of New Year's Eve, Lucien gave me a bouquet of forget-me-nots. We then started making dumplings. He seemed to be in a great mood, even letting me put an apron on him."
  },
  [201331] = {
    diary_text = "I blabbered on about the fun things I did with dumplings from my childhood but he clung on to every word. He gently wiped away the flour that got on my face. Something came over me and I playfully put some flour on his nose. We laughed and... romance is so sweet!"
  },
  [201341] = {
    diary_text = "Lucien asked me to teach him how to make dumplings, grabbing my hands and starting without even pausing for my answer. He told me his childhood secrets for the first time, and said he wished into the dumplings before feeding them to me. Then he promised he'd never leave me."
  },
  [201411] = {
    diary_text = "Everyone worked really hard on the company's first show of the year, and when it was finally finished, I was told that Lucien had helped out on it too. But hadn't he turned me down?"
  },
  [201421] = {
    diary_text = "I remember that day. I asked Lucien for help, and he coldly refused. So why did he help me in the end? It really didn't seem like him."
  },
  [201431] = {
    diary_text = "At first I thought Lucien wouldn't accept my invitation to attend our team-building outing, but that day, he showed up. He said he was worried about me because he couldn't reach me on the phone. We started playing Truth or Dare, and Lucien admitted for the first time there was someone he liked."
  },
  [201441] = {
    diary_text = "I also said the person who was most important to me, but Lucien was drunk and didn't seem to understand. I rarely get up and sing in front of others, so I don't know why I decided to sing a duet with Lucien. In his eyes, I saw that he believed in me."
  },
  [201511] = {
    diary_text = "Our gardenia finally bloomed. I couldn't help but feel satisfied. Lucien used the occasion to plan an outing. We decided to go check out the peach blossoms."
  },
  [201521] = {
    diary_text = "We got to the park, and all around was a riotous profusion of peach blossoms. Lucien quoted poetry to me, and I shyly thought he was joking. But he told me he wasn't joking at all."
  },
  [201531] = {
    diary_text = "We rode a two-seater bike, and Lucien talked about his high school years in England. Then, we ate the picnic I'd prepared. I was embarrassed, but Lucien said he loved it."
  },
  [201541] = {
    diary_text = "We ran into Lucien's colleagues. In front of them, Lucien acted just like I was his real girlfriend. After parting ways, we came to a peach tree grove where I saw the real Lucien."
  },
  [201611] = {
    diary_text = "In the hopes of a long-term partnership with the city council, I accepted an invitation from the Loveland City Council. But I was stressing out because I couldn't think of a better subject matter. While I was moping, Lucien suddenly appeared. What was he doing here?"
  },
  [201621] = {
    diary_text = "It turned out Lucien knew about my troubles and had come to look after me. He was so kind. Not only did he listen to my worries, encourage me, and make me feel better, but he also slowly coaxed a new idea out of me. But then when he demanded that I let him bring me home to get some rest, I seemed to see yet another side of him, which gave me quite a stir."
  },
  [201631] = {
    diary_text = "The maple leaf promise with Lucien made me blush. Hearing Lucien introduce me also made me blush... He always makes me blush or makes my heart pound so easily. What's that all about? The wine in the winery was delicious, and the owner Eileen's story was so moving. I don't want to end up like her, letting love slip through my fingers. I wonder what Lucien thinks?"
  },
  [201641] = {
    diary_text = "Through talking with Eileen, the show was slowly taking shape in my mind, thanks in large part to Lucien's help. Apparently I just can't do without him. On the ride back, Lucien said people would return like clockwork, but I wasn't sure who he was talking about. He really kept you on your toes."
  },
  [201711] = {
    diary_text = "After a week of working around the clock on the production site, I finally ended up in the hospital. But I still wanted to get some things done. The more I could do, the more at ease I would feel."
  },
  [201721] = {
    diary_text = "In my hospital room, I saw Lucien, whom I hadn't seen in over half a month. And then when I woke up, Lucien was long gone again. I also received word that things at the production site were out of control. I was extremely anxious and even felt somehow dejected. After I walked out, I fell into Lucien's arms, but he seemed to look angry..."
  },
  [201731] = {
    diary_text = "To try to salvage the situation, I decided to ignore my condition and go to the site and take care of things, but I was stopped by Lucien. I tried to persist, but he stayed angry, and even became distant and estranged. After he brought me back home, I watched him walking away feeling very unhappy."
  },
  [201741] = {
    diary_text = "The day of the annual fireworks had arrived, and I found the two tickets I had bought ahead of time, but I didn't have the guts to ask Lucien. As I was preparing to take the plunge, I got a call from him instead. He had already prepared special fireworks just for me. The sparkler in my hand was dazzling like a star-filled night sky."
  },
  [201811] = {
    diary_text = "Lately in meetings my mind was always drifting. It had already been like this for awhile, and it all started that day at Lucien's research center..."
  },
  [201821] = {
    diary_text = "I discovered that Lucien was going away, and it made me think of my recent, unsettling dreams. Lucien told me it was something very important, and he promised he would return."
  },
  [201831] = {
    diary_text = "With Lucien gone, I plunged myself into my work, but I still thought of him all the time. Time dragged on, so slowly I'd forgotten he agreed before to go on our picnic..."
  },
  [201841] = {
    diary_text = "I saw countless balloons, and ran off towards the research institute. When I saw Lucien's figure, the tears came streaming out of me. I trust him, and I trust in our future."
  },
  [201911] = {
    diary_text = "After finishing the overtime work, I went back to home as usual but got followed. When I didn't know what to do, Lucien appeared again and saved me from danger. He looked very tired, but still insisted on taking me somewhere to relax on the weekend."
  },
  [201921] = {
    diary_text = "In the weekend morning, Lucien came to pick me up. But his tender expression couldn't conceal his fatigue. In order that he could take a rest for a while, I forced him to sit in the passenger seat to have a good sleep."
  },
  [201931] = {
    diary_text = "When we arrived, Lucien told me the place was an Archery Stadium. I had no talent in sports, so I followed him into the stadium uneasily and witnessed the thrilling archery game between him and the stadium owner."
  },
  [201941] = {
    diary_text = "After the game, Lucien began to teach me archery. At first, I was enchanted by his charm and totally forgot the detailed moves he showed me. He taught me step by step. Then I gradually got the hang of it and enjoyed the fun of archery."
  },
  [202011] = {
    diary_text = "Woken up by a nightmare and fearing it was a premonition, I ran over to Lucien's room. I knocked and knocked but no one answered. Finally, Lucien appeared at the end of the hall."
  },
  [202021] = {
    diary_text = "We got up early to watch the sunrise, making some art in the sand as we waited. At sunrise, Lucien turned his camera on me, saying this was the most beautiful sunrise view to him."
  },
  [202031] = {
    diary_text = "In the afternoon, Lucien took me to a pitch black cave, saying that if a couple could pass all the way through, then it meant they would grow old together. I decided to try it."
  },
  [202041] = {
    diary_text = "I hooted for joy upon making it out of the cave, and a spooked flock of bats made me fling my arms around Lucien. Turns out he had just made up the \"growing old together\" story..."
  },
  [202111] = {
    diary_text = "Lucien has been on business trips frequently in recent days. This time he even left me the key to his home and asked me to take care of his plants. We agreed that he would return when the daisies bloomed."
  },
  [202121] = {
    diary_text = "I tried hard to win the chance to work in Denmark collecting materials for a show, and found Lucien's address by drawing it out of him. I waited for him in the park full of blooming purple hydrangeas, but as soon as I relaxed, I pass out and fell in his arms due to a cold."
  },
  [202131] = {
    diary_text = "Waking up in the midnight, I found that Lucien had been by my side. Due to the illness, my mood fluctuated a little, which he considered as a blame for his previous failure to keep the promise, so he committed seriously that he wouldn't leave me alone any more."
  },
  [202141] = {
    diary_text = "Lucien asked me if there's any place I wanted to go. I finally decided to revisit the park of hydrangeas. Despite the abrupt sun rain, we embraced freely in the rain, feeling the love flowing between us."
  },
  [202211] = {
    diary_text = "Though he arrived late, Lucien still got a warm welcome from the children. Clearly all the little girls wanted to help him fix his hair, but he still made me come help."
  },
  [202221] = {
    diary_text = "After helping the children put on their intricate traditional clothing, I became entranced by Lucien's performance in traditional clothing. Later he helped me apply lip makeup."
  },
  [202231] = {
    diary_text = "Because the children were tired of the usual Double Seventh tale, Lucien told them the story of the Peony Pavilion and answered questions about love, life, and death."
  },
  [202241] = {
    diary_text = "After saying goodbye to the children, Lucien took me to a mountain stream to admire lotus lanterns. We each wrote down a wish for our lantern, and they were the same!"
  },
  [202311] = {
    diary_text = "I was mobbed by a bunch of reporters after Lucien's speech at the conference but I didn't have the heart to respond. When I finally got off work, I was dragged into a strange car and to my surprise, it was Lucien."
  },
  [202321] = {
    diary_text = "Lucien reminded me not to get involved into this and told me to protect myself, but somehow, he felt so indifferent. I wanted to return him everything he left at my place, but he drove away when I went upstairs to pack."
  },
  [202331] = {
    diary_text = "Kiki and my friends came to my house to cheer me up and found the video disc that Lucien lent me. I brought the disc to his new address, wanting to completely end things between us."
  },
  [202341] = {
    diary_text = "But it rained heavily when I tried finding his villa, and met him when I was in a mess. He took me home to watch a movie for the last time but it turned out to be a new beginning to our relationship instead of the end."
  },
  [202411] = {
    diary_text = "Among the people coming and going at Loveland University, a peculiar new flower caught my attention. Originally I had come to ask Lucien something, but he had disappeared seemingly without a trace. Feeling uneasy, I randomly snapped pictures and went in search of the head researcher of this project."
  },
  [202421] = {
    diary_text = "I finally found the head researcher and learned that the project had temporarily been handed over to Lucien's research facility! I rushed out and finally saw him in the plant exhibition area under an oleander tree."
  },
  [202431] = {
    diary_text = "Lucien looked very tired, which made me worried. But perhaps because I finally found him, I felt that all my troubles were clearing up."
  },
  [202441] = {
    diary_text = "I accidentally bumped into a genetically-modified oleander which produced hallucinations and dizziness for a time. Lucien told me this was the reason he was researching this, because it contained a highly-effective anesthetic which was extremely useful to his research. Lucien was the same as usual today, but still something was a little different. But no matter what, as long as I'm by his side, I feel at ease for some reason."
  },
  [202511] = {
    diary_text = "It was already afternoon when Lucien and I came to the hot spring resort. His solemn look was a bit different than usual, and I asked him to let me take care of the rest of the day."
  },
  [202521] = {
    diary_text = "We got into the wrong room at the hotel, but managed to see the wonderful setting sun over the lake. Then we went to the open-air hot spring, and saw the same snow scene  we saw on his first \"birthday\" with me."
  },
  [202531] = {
    diary_text = "After dinner, I took out the cake to celebrate but broke it. I planned to buy a new one myself, but he went out with me. It was dark and cold along the mountain road, but we saw a beautiful starry sky unexpectedly."
  },
  [202541] = {
    diary_text = "We came back with the cake 1 hour before the day ends. I was busy with preparing the room, but he just stood aside and took photos of me. Together, we held hands and made a wish in the room lit by candles."
  },
  [202611] = {
    diary_text = "We randomly found an out-of-print book! What luck! Leaving the bookshop, we walked down a surreal foreign street. Lucien said we were going to a quiet place to read."
  },
  [202621] = {
    diary_text = "As we read in a peaceful, riverside park, I happened upon a poem about separation. To boost my spirits, Lucien read me a children's story and said we could go to a \"sugar shack\"."
  },
  [202631] = {
    diary_text = "We made maple sugar lollipops and ended up in a sweet embrace due to an accident. Leaving the sugar shack, I finally put together the reason for this trip and felt uneasy..."
  },
  [202641] = {
    diary_text = "Not being able to ride the bike in the mud had me flustered, but Lucien knew how to soothe me. I gave him a maple leaf, but he said there was something else he wanted more..."
  },
  [202711] = {
    diary_text = "I asked Lucien to go see a movie, both as a thank you and also… because I hadn't seen him in a long time. Lucien saw that I was sick though and suggested we stay in instead."
  },
  [202721] = {
    diary_text = "I dozed off watching the movie, and when I awoke, Lucien was asleep too. While putting a blanket on him, I fell on top of him and actually left a lipstick mark on his neck?!"
  },
  [202731] = {
    diary_text = "Under Lucien's grilling, I fessed up to the lipstick. Since the movie date didn't pan out, I asked him what I could give him as a thank you. His answer surprised me."
  },
  [202741] = {
    diary_text = "We made a date to go calendar shopping the next day, but now Lucien had caught my cold. Still, he insisted we go out anyway, and he even made up a calendar quote to convince me."
  },
  [202811] = {
    diary_text = "Me, in a wedding gown, and Lucien, in a suit, strolled down the wisteria corridor side by side and surprisingly, passersby around sent us good wishes..."
  },
  [202821] = {
    diary_text = "A little girl we met asked us how Lucien and I ended up together. When I was going to make up a story, Lucien talked about how he proposed."
  },
  [202831] = {
    diary_text = "Walking on the trail with only a few people, I told Lucien the origin of this wedding gown. After reading the letter of the donor, he pointed out the key points that I had ignored."
  },
  [202841] = {
    diary_text = "We accidentally walked into a quiet little garden, where there were more wisteria flowers, and I felt like this familiar scene is the place mentioned in the letter..."
  },
  [202911] = {
    diary_text = "After posting info online about the data leakage of special gene carriers, I came alone to the abandoned facility of Ultima Bioresearch. To my surprise, the person who had been occupying my mind was already right there, waiting for me."
  },
  [202921] = {
    diary_text = "Lucien was distant and aloof as usual. I confronted him, trying to give him a taste of his own medicine, but was just reminded again by how undisturbed he was that, he no longer knows me."
  },
  [202931] = {
    diary_text = "To my surprise, the carved sentence on the wall we saw when we first came was now gone, as if it never existed. My throbbing head hinted that something was wrong. During the stalemate of our confrontation, we heard trouble stirring outside the door."
  },
  [202941] = {
    diary_text = "My post also drew Black Swan agents, but Lucien saved the day using the same Evol they used. I was hurt when I pushed Lucien away, which made him immediately dubious of my identity. I was slightly distressed but there was a firm voice deep down. We promise to trade his gratitude for my answer when we meet again."
  },
  [203011] = {
    diary_text = "In the unfamiliar environment, everything had to start over. While I was at a loss, Lucien suddenly invited me to go hiking. I wasn't sure if he remembered our spring promise, but I still agreed with anticipation."
  },
  [203021] = {
    diary_text = "We finally decided to hike on a working day. The scenery was beautiful, but I was underwhelmed by the silence between us. Finally he broke the silence first as I was too proud to..."
  },
  [203031] = {
    diary_text = "We encountered a kite booth, but he really didn't remember the promise of us flying a kite together. I pulled him away from the dishonest booth but accidentally walked hand in hand the whole way."
  },
  [203041] = {
    diary_text = "Near the top of the mountain, we came across a pinwheel booth. A sudden gust of wind blew the pinwheels away, but it gave me the chance to listen to his innermost thoughts."
  },
  [203111] = {
    diary_text = "Lucien buried himself in his research late at night. When his train of thought was directed to the shortcut to success again, he got a text message from her on his phone..."
  },
  [203121] = {
    diary_text = "After receiving Lucien's reply, I decided to meet him at the bookstore. Basking in the sunshine, coffee, and his tenderness, I felt like I was reliving all the good things in the past..."
  },
  [203131] = {
    diary_text = "I was anxious as I didn't know what happened to Lucien, and stopped him as he was about to leave. Since he refused to go to the hospital, I decided to take him back home..."
  },
  [203141] = {
    diary_text = "After a long ordeal and wait, Lucien's condition finally stabilized. I wanted to carry him to the bedroom to get some when he suddenly pressed me down..."
  },
  [203211] = {
    diary_text = "I got a surprise call from Lucien, during which he brought up the lost puzzle pieces. I invited him to go buy a new set, thinking he'd refuse due to work, but he actually accepted..."
  },
  [203221] = {
    diary_text = "Lucien looked like he'd just hurried over from work. I told him I didn't want to go buy a puzzle, and he suggested going somewhere else. Then we got separated on the busy street..."
  },
  [203231] = {
    diary_text = "Lucien took me to a gallery. We made a painting, but I accidentally got yellow dots on the nearly-finished canvas. I was downhearted, but Lucien turned them into cheery fireflies..."
  },
  [203241] = {
    diary_text = "I got up my courage and told Lucien that I'd actually found the puzzle pieces. Then I gave him a gift -- a glass bottle with a firefly puzzle inside, to always guide his way."
  },
  [203311] = {
    diary_text = "After an afternoon of hard work, I finally overcame all obstacles and reached the stage before the final one. Victory was so near, but since I hadn't seen Lucien the whole day, I couldn't get myself to cheer up."
  },
  [203321] = {
    diary_text = "The token of this stage was a gardenia and I quickly guessed that it pointed to somewhere Lucien once showed me to. Following the clue, I arrived at the indicated office and unexpectedly met Lucien!"
  },
  [203331] = {
    diary_text = "The third stage was called \"Search Among the Crowd\", where. Lucien and I went back and forth among the lantern alleys to find the key clue, but to no avail. Just as we were about to give up, we realized the destination for this stage had always been just before us. However, to our surprise, there was a hidden stage waiting ahead."
  },
  [203341] = {
    diary_text = "Following the clues, Lucien and I arrived at the library, where the final stage was. The quiet dark library reminded me of scary campus legends. Just then, we actually heard heavy footsteps drawing near..."
  },
  [203411] = {
    diary_text = "Two years ago, my family went missing due to a vampire assault. As the lone survivor with the help of Lucien, I have been living in this town with him."
  },
  [203421] = {
    diary_text = "I was in bad condition. Thanks to the medicine Lucien made for me, I started to recover, though not fully. We talked about the recent vampire assault at dinner..."
  },
  [203431] = {
    diary_text = "More were attacked in the town. The dark clouds of unease hung over the town. Lucien was invited to a banquet while I was resting at home. At midnight, I walked out of the room in the pale moonlight and saw a startling scene..."
  },
  [203441] = {
    diary_text = "It turned out that I was not the one who was staying at home and waiting for Lucien. It was him who was waiting for me to remember the past and my promise. Maybe Lucien was right about the cunning of humans. But from today, he wouldn't have to wait and be alone anymore."
  },
  [203511] = {
    diary_text = "As soon as I arrived in the UK in the early morning, I ran into Lucien in the airport! Shouldn't he be in a conference? Why would he be \"getting coffee\" in the airport at daybreak?"
  },
  [203521] = {
    diary_text = "Lucien brought me to the apartment he was staying in during the trip. Somehow, the place gave me a strange feeling. I ignored it as there were more important matters at hand... namely how did he see through my plans so easily?"
  },
  [203531] = {
    diary_text = "I began preparing Lucien's birthday present: a home-made cake baked by myself. That was when I noticed an old picture of Lucien as a child on the bookshelf. Did this mean that... this apartment actually used to be his home once upon a time? Perhaps he had stayed here while studying in the UK?"
  },
  [203541] = {
    diary_text = "Lucien and I flipped through an old photo album together. After that, we decided to create more new memories together. I taught him to decorate the cake, and he was quite a quick learner! Using the icing, we wrote down our messages to each other on the cake."
  },
  [203611] = {
    diary_text = "I was anxious because I couldn't find a taxi to get there on time. Lucien called and told me not to hurry."
  },
  [203621] = {
    diary_text = "Due to the heavy traffic jam, I chose to walk instead. Guided by the video message sent by Lucien, I finally found him in the crowd..."
  },
  [203631] = {
    diary_text = "I was immersed in joy with Lucien but realized I forgot my ticket to the next event. Lucien looked at me and smiled, saying he would take me somewhere else."
  },
  [203641] = {
    diary_text = "Lucien took me to a private garden. While enjoying the precious moment of relaxation, my hair was entangled by branches. As Lucien helped to free my hair, we found mistletoe hanging overhead..."
  },
  [203711] = {
    diary_text = "I gave Lucien a call, hoping he could go with me to a publishing house to see an old friend of my father's. When he heard its name, he hesitated a moment, but in the end agreed."
  },
  [203721] = {
    diary_text = "A few days later, I went to the lab looking for Lucien, but I discovered leaves of the flower we planted before were fading yellow. I thought it just needed water, but Lucien told me it was already withered. He told me not to feel bad, that this was part of nature. But I got the feeling that he wasn't taking it in stride either. And so I didn't end up asking what was on my mind."
  },
  [203731] = {
    diary_text = "In secret, I met again with my father's old friend and the head of the publishing house, Uncle Eugene. And I asked him to bring that important book -- He may have some connection to Lucien's past. As we talked, I grew more and more certain. So, after parting with Uncle Eugene, I sprinted to Lucien's lab, only to find it empty..."
  },
  [203741] = {
    diary_text = "In a dream world that at times seemed real, I learned a bit about Lucien's past, and the deeper story behind the book. When the time was right, I gave a flower seed to Lucien, and I told him that no matter if it was flowering, fruiting, or wilting, I would be by his side to witness it together. But did something actually happen in this all-too-realistic place, or was it all just a dream I had?"
  },
  [203811] = {
    diary_text = "I woke up in the morning to find myself in Lucien's house. The heat rose in my cheeks as I recalled how I had to crash here last night because of a broken pipe in my home."
  },
  [203821] = {
    diary_text = "Lucien was sleeping in the living room. After sneaking a read of his book, I felt the urge to touch the different objects around me. Then, as I looked at Lucien's sleeping face, a mischievous plan began to form in my mind..."
  },
  [203831] = {
    diary_text = "Lucien was explaining the relationship between the sense of touch and dopamine with examples, but my mind had wandered off. As I watched and listened to him, my heart fluttered."
  },
  [203841] = {
    diary_text = "I accompanied Lucien as he worked. After a while, we started eating the cherries I had brought. As I recalled what happened this morning and how he asked me about my feelings, I inched toward him..."
  },
  [203911] = {
    diary_text = "I planned to secretly hang up a box of dreamcatchers while Lucien was still asleep, but he entered the room just as I unpacked the box. Since the surprise plan failed again, I had no choice but to hang up the dreamcatcher with him."
  },
  [203921] = {
    diary_text = "The room full of dreamcatchers was as light as a dream. Lucien remembered the blank puzzle we hadn't complete and suggested drawing our most beautiful dream on the puzzle. I couldn't help but wonder—can dreams be drawn?"
  },
  [203931] = {
    diary_text = "Seeing the note Lucien didn't throw into the sea, I wondered how many deep secrets he kept from me, but then felt that they were not important. Like the coin I threw into the wishing pool carrying one wish—may he be safe."
  },
  [203941] = {
    diary_text = "Listening to Lucien describing his most beautiful dream, I felt as if I fell into a bizarre sea world. Lucien painted himself as a lonely little fish, so I couldn't help but pick up the brush and added a sea for him, then he asked me a question that made me blush..."
  },
  [204011] = {
    diary_text = "I went to Loveland University and sat in the corner of a lecture hall to sign in for Kiki's cousin, but I never would have thought that Lucien would be the teacher of this class. He seemed a little different today."
  },
  [204021] = {
    diary_text = "It turned out that Lucien was a substitute teacher for this class. I thought I could get away with the register, but I was exposed and was told to sit in the front row... Must he do this?"
  },
  [204031] = {
    diary_text = "Lucien's lesson was as interesting as ever. It's been a long time since I sat in his class, so I couldn't help but sneakily take a picture of him. It brought me back to the first time I went to his lecture. When I was spacing out, Lucien called me up to help with a small experiment, which was then interrupted by some late-coming student."
  },
  [204041] = {
    diary_text = "After the lesson, Lucien and I sat in the lecture hall chatting. He found the doodles I drew on my notes. I was slightly embarrassed, but I thought it was a decent portrait of him. I remembered the interrupted experiment, so I shared my thoughts with Lucien and we did a small practical."
  },
  [204111] = {
    diary_text = "连轴转的项目令我状态十分低迷，许墨见状提出第二天一起去游乐园的邀约。本想去图书馆充电的我起初有点犹豫不决，最终还是雀跃地答应了他。"
  },
  [204121] = {
    diary_text = "天公不作美，我和许墨在游乐园外面的商店屋檐下躲雨，没想到这正好是周边店。里面的玩偶令我十分欣喜，但是当许墨提出一人一只的时候，我却红着脸拒绝了他……"
  },
  [204131] = {
    diary_text = "入园后，我和许墨在园区里闲逛，感受着游乐园欢乐的魅力。天色慢慢暗下来，当我们在旋转茶杯项目排队的时候，天空忽然划过了好几道流光。我感到不可思议，许墨却说，在游乐园里没有什么是不可能的。"
  },
  [204141] = {
    diary_text = "我这才意识到，原来这些流光竟是许墨变出来的。更令我意外的是，他悄悄买下了之前的玩偶，给了我一个难忘的惊喜！当音乐响起，我和许墨依偎着坐在旋转茶杯里，感觉许墨比游乐园本身还要神奇。只要在他身边，我就能永远被幸福和欢乐包围……"
  },
  [204211] = {
    diary_text = "This morning, I went to deliver breakfast to Lucien in the research center. On my way, I heard Ming and other researchers saying Lucien was friendly but always seemed so distant. They asked me what kind of person Professor Lucien was. After pondering about it, I gave them a firm answer from the bottom of my heart."
  },
  [204221] = {
    diary_text = "I found Lucien in a lounge. He was deep in thoughts with a cup of coffee in his hand, seeming slightly cold with his emotionless face. But he seemed lonely rather than distant to me. I pulled up the shutters and welcomed the sunlight in through the windows, warming every single inch of the room."
  },
  [204231] = {
    diary_text = "I told him about the problem I faced while preparing the show, and he answered as patiently as always. But soon enough, Lucien managed to expose my lie—he knew that I was only using the problem as an excuse to see him. He then began to expose all the little secrets I did for him during this time. I knew I couldn't hide it from him, so I just admitted it."
  },
  [204241] = {
    diary_text = "After the filming was over, I rushed to see Lucien, but to my surprise, Lucien’s experiment had failed. I watched in shock when he shredded his work page by page. However, he said this was just like any other day in his job. Although he was slightly discouraged, it was also important to learn from his failure. I then offered to go for a walk together. He then told me not only did he know about my secret gifts these days, but he also followed me quietly to walk me home. I hoped to care for him but turned out to cause him more trouble. I immediately felt a sting in my heart... Luckily, the sweet ice cream melted away all our feelings of missing each other."
  },
  [204311] = {
    diary_text = "Lucien and I got up early to make a full English breakfast. Fried eggs, bacon, baked beans... Just as I was triumphantly plating the food, Lucien said I was missing something."
  },
  [204321] = {
    diary_text = "I argued that I know how to brew tea, but Lucien still took me by the hand and taught me. Lucien then made a joke that he could retire early if every day was like this."
  },
  [204331] = {
    diary_text = "After breakfast, I suggested reading upstairs. Lucien said he needed to find something first. It was time capsule letters from a bookstore. Emotions came flooding back."
  },
  [204341] = {
    diary_text = "We finally revealed our answers to each other: \"lack of freedom\" and \"don't be afraid\". From now on, there will be no more secrets between us."
  },
  [204411] = {
    diary_text = "I get an invitation to attend one of Lucien's public lectures. Arriving at the campus early, I head to the library to reminisce, never expecting to find Lucien fast asleep on a desk..."
  },
  [204421] = {
    diary_text = "Quietly I watch Lucien sleeping. A cherry blossom floats into the space and lands on the tips of his hair. Deciding to keep it, I place it between the leaves of a book, not realizing... a petal has also landed on my own head."
  },
  [204431] = {
    diary_text = "A boy at the lecture asks to learn CPR so he can help his sick grandma. I reach out and hug the boy. Lucien approaches the group with a first-aid kit. What is he planning?"
  },
  [204441] = {
    diary_text = "Lucien starts explaining the meaning of life to children in an upfront but compassionate way. I can't help thinking of my Dad. Sensing the change in my mood, Lucien gives me a warm and gentlemanly hug."
  },
  [204511] = {
    diary_text = "Lucien and I sat on the table thinking of what to paint, when a beam of light shone on Lucien, giving me inspiration to create a reflected light \"fantasy\"."
  },
  [204521] = {
    diary_text = "Now inspired, Lucien took me to a mirror shop, where I saw a \"round-headed Lucien\" and \"square-headed me\". After buying the mirrors, we realized we'd need a place to set them up."
  },
  [204531] = {
    diary_text = "Deciding to make it right in the gallery, after one sweet little hiccup, we got down to work. But what to do about the painting itself? Lucien told me his definition of fantasy."
  },
  [204541] = {
    diary_text = "We completed the painting, then set up the mirrors. The light reflected a subtle luster onto the canvas, in a moment of fantasy that belonged only to us."
  },
  [204611] = {
    diary_text = "A new member of the organization recently reached out to me, boasting about this \"Big Fish\" that he had caught. However, the \"Big Fish\" claimed that he would only speak to me in person to tell an important message. When I saw his photo, I immediately rushed over."
  },
  [204621] = {
    diary_text = "Turned out this \"Big Fish\" was Lucien... Why was I not surprised? But how did he end up here? I walked into the interrogation room in panic and saw him locked up with some injuries. However, he seemed very calm. When asked about the important \"message\", he tried to talk me over to his side instead..."
  },
  [204631] = {
    diary_text = "Knowing that other members of the organization were watching us, I tried to stay calm and hinted Lucien to not disclose our relationship. He didn't seem convinced though, as all my attempts were easily deflected or dodged. Did he really want everyone to know what was going on between us?"
  },
  [204641] = {
    diary_text = "The interrogation was interrupted by an assault from the Special Task Force. It was all within Lucien's plan. He then escaped the room with me. When we met again the next day, Lucien still had the same smile on his face when he looked at the knot he put on my wrist."
  },
  [204711] = {
    diary_text = "On this day, I returned to Loveland City to spend time with my father and learned from his phone about Lucien's return, which stirred up many emotions in me. Before I knew it, I came to the newly completed Lucien Bioscience Research Center."
  },
  [204721] = {
    diary_text = "I walked around the center as I had done many times before. When I walked past the laboratory, memories of my first encounter with him flooded back. Suddenly, footsteps sounded from downstairs. I then hurriedly pushed open the door and ran into Lucien! This encounter, after many years, made my heart race."
  },
  [204731] = {
    diary_text = "The familiar past seemed to have happened again. I didn't expect Lucien to remember me and what happened at the orphanage. I invited him to be a guest on the show when I became a producer."
  },
  [204741] = {
    diary_text = "An unexpected change in the weather caused some incidents in this encounter. I secretly wished time would slow down slightly while being glad that I could get alongside him sooner this time. Our goodbye wasn't forever. This time, I knew we would see each other again soon."
  },
  [204811] = {
    diary_text = "During a free afternoon, Lucien and I choose books to donate to charity. I look all around and pull down some comics for young girls that I haven't flipped through in years."
  },
  [204821] = {
    diary_text = "As I flip through the book, I think about how Lucien got anything out of these inscrutable treatises when he was little, and how it led to an interest in science and on to today. It felt like a mystery wrapped in a conundrum, so I just kept flipping through the book. Lucien probably felt the same as me, and he picked up one of my maiden comics and started reading it."
  },
  [204831] = {
    diary_text = [[
In a short half an hour, Lucien had read several volumes and was still engrossed in reading. There was a smile on his lips, and he seemed completely absorbed in the comic.
Noticing my gaze, he plopped down onto my crossed legs and discussed the plot with me.]]
  },
  [204841] = {
    diary_text = "Lucien turned to a full-page insert of the male protagonist and showed it to me. I couldn't remember how I felt back then, but I'd actually drawn little hearts all around him in pencil. Hearing me compliment the male protagonist for being handsome, and kind, and protecting the heroine, Lucien frowned. I couldn't tell if it was just jealousy..."
  },
  [204911] = {
    diary_text = "The Priests chased me into a house, where I told the owner if he turned me over to them, I would make him regret it..."
  },
  [204921] = {
    diary_text = "The master of the house helped me give my pursuers the slip. He told me his name was \"Lucien\". The next day, on my way home, I met him again. While we were walking and chatting, we discovered that someone had set fire to my house...!"
  },
  [204931] = {
    diary_text = "As the flames grew higher and higher, I told Lucien to leave and headed into the forest to put out the fire. I was on the verge of collapsing when he reappeared. Rain started to fall as he played his flute, and green growth sprouted again on the dead wood."
  },
  [204941] = {
    diary_text = "My lost memories gradually returned. Finally I remembered seeing Lucien when I was a child, only at that time he was not human, but a beast. Lucien claimed I still owed him for something from that time and told me to figure out a way to pay him back..."
  },
  [205011] = {
    diary_text = "I rejected Lucien's invitation for the weekend. He didn't say anything apart from telling me to get some rest. But when the weekend came, I ran into Lucien when I met with my business partner at the gallery."
  },
  [205021] = {
    diary_text = "The business partner didn't seem to want to talk about work. He even asked to take pictures with me, but I never would've thought that the person he asked to help take pictures would be Lucien."
  },
  [205031] = {
    diary_text = "Lucien helped me out, but I sensed that he came to the gallery on purpose. After being pressed with questions, Lucien finally let on that here was where the Special Task Force found some illegal transactions. I offered to investigate with him, to which he agreed."
  },
  [205041] = {
    diary_text = "We did not manage to find a single clue. At this point, I noticed something strange. I pretended to have spotted a clue to test Lucien, but he saw right through my pretense and told me the real purpose of his visit to the gallery..."
  },
  [205111] = {
    diary_text = "As Lucien began a new research project, I secretly prepared a lunchbox of love for him, but it turned out he already knew about it..."
  },
  [205121] = {
    diary_text = "As it turned out, I accidentally synced our phone albums, from which he saw the photos I took of the lunchbox, as well as my sneaky pictures of him..."
  },
  [205131] = {
    diary_text = "The base of Lucien's research base was very special this time, which was restored to the style of the '70s. Lucien and I decided to relax at the base and experience the life of the '70s for once."
  },
  [205141] = {
    diary_text = "We planned to sunbathe together, but we could only find one lounger... Lucien came up with a way to allow both of us to lie down at the same time, only this method made me blush..."
  },
  [205211] = {
    diary_text = "Imprisoned in the castle, I was woken up one day by the exiled prince. He seemed to have accidentally broken the curse that trapped me here."
  },
  [205221] = {
    diary_text = "I made an offer to the prince: I would help him to return to the palace, and he would help me to break the curse once and for all. The prince didn’t agree immediately, but instead he asked if I knew what his name was."
  },
  [205231] = {
    diary_text = "The prince and I came to an agreement. I drove away many hunters sent by the queen to assassinate him. As time went by, the prince noticed something’s wrong with me."
  },
  [205241] = {
    diary_text = "I wanted to cancel our agreement, and the prince forced me to reveal my secret—I cheated, because the cost of completely breaking my curse was..."
  },
  [205311] = {
    diary_text = "It was Lucien's birthday. In the morning, Lucien would be giving a presentation on a topic he had been doing research on for years. I sat at the very back of the conference hall, witnessing this historical moment with academics and researchers from all over the world."
  },
  [205321] = {
    diary_text = "It was noon when the presentation was over. I told Lucien that he could customize his birthday celebration however he liked, and I'd happily accompany him to anything he chose to do. We ended up on an empty lot near an old street."
  },
  [205331] = {
    diary_text = "Lucien described to me what this empty lot used to be like. Eyes closed, I imagined myself following Lucien into the old cottage. Though it was now an empty lot, the old cottage would remain forever glowing in Lucien's memory."
  },
  [205341] = {
    diary_text = "Finally, we came to the observation platform on a hill and celebrated a simple, quiet birthday together. I made the wish that Lucien would always be the kind of person he wanted to be."
  },
  [205411] = {
    diary_text = "The students called out to us in the middle of the filming. They profusely thanked me and Lucien for our help, and invited us to host their play..."
  },
  [205421] = {
    diary_text = "Lucien and I accepted the invitation. Since tomorrow would be the official rehearsal, we hurried to the outfit rental shop to pick out evening attire for us. From a sea of evening dresses, Lucien picked a breezy white one and brought it to me."
  },
  [205431] = {
    diary_text = "On the first day of rehearsal, a lot of accidents happened on stage, dampening the students' enthusiasm. As I was trying to comfort the students, Lucien did something out of the blue that cheered them up."
  },
  [205441] = {
    diary_text = "Right before the show began, I prepared a little something for the students. On my way to the backstage area, my clothes came off! Before I knew how to react, Lucien pulled me into a corner behind the curtain. What happened in that cramped space made my face red and my heart pound..."
  },
  [205511] = {
    diary_text = "After deciding to enter the event, Lucien and I discussed how to make a \"creative booth\". After some thought, I had a Lucien-inspired idea: we'll open a \"Christmas Wish Booth\"!"
  },
  [205521] = {
    diary_text = "On Christmas, we showed up early to decorate and encountered our first snow of the season. In that moment, Lucien gave his definition of first snow."
  },
  [205531] = {
    diary_text = "The wish booth was about to open, and I was naturally a bit nervous. Lucien played the part of a customer to help me relax and exchanged for his wish card with a surprise."
  },
  [205541] = {
    diary_text = "When the Christmas fair finally ended, I got to open my surprise from Lucien -- an exquisite snowflake. I also made Lucien's Christmas wish come true."
  },
  [205611] = {
    diary_text = "I was watching a movie with Lucien in the living room during the holiday when a phone call interrupted asking him to work overtime. I decided to go to work with Lucien to see what \"Professor Lucien\" in the office was like."
  },
  [205621] = {
    diary_text = "Sitting on the sofa in Lucien's office watching him work, I could feel that such an ordinary and unusual day made me assured and happy. His office had accumulated many things I gave him over time. Did I make his life better as well?"
  },
  [205631] = {
    diary_text = "Lucien had more work to do than unexpected, which he didn't finish even until noon. Being determined to \"observe\" Lucien's daily life, I went to the fast-food restaurant next to Ultima Bioresearch with him to see what kind of food Lucien usually had."
  },
  [205641] = {
    diary_text = "We shared our food, tried the efficient but not-so-tasty sandwiches and the strange but surprisingly delicious pizza. When being with each other, we could always find the small sparkles in life."
  },
  [205711] = {
    diary_text = "Recently I was working on a dating variety show. On the first day of shooting, Lucien happened to have a lecture nearby, so we met in the park for lunch."
  },
  [205721] = {
    diary_text = "I mentioned a female guest wanting to confess to a male guest, and Lucien said that it's very courageous to express one's feelings frankly."
  },
  [205731] = {
    diary_text = "The shooting ended early, and I went to Lucien's house. There I saw a row of paintings on the wall, all being my monotonous portraits, so I decided to draw a new one."
  },
  [205741] = {
    diary_text = "Speaking of \"crush\", Lucien said frankly that it's a sense of happiness when desire was satisfied and worries dissipated. He could not resist but yield to this instinct."
  },
  [205811] = {
    diary_text = "On the weekend, I hung out with Lucien at the research center while he worked overtime, flipping through his new book. Lucien suddenly told me the Loveland University president asked him to hold a book launch party..."
  },
  [205821] = {
    diary_text = "Lucien was skeptical about the efficacy of the launch party. But after chatting with me, he accepted the invitation."
  },
  [205831] = {
    diary_text = "On the day of the launch party, I arrived at the venue after finishing up work. Just then, the host asked Lucien a question that embarrassed me..."
  },
  [205841] = {
    diary_text = "After the launch party, I took Lucien to a spot by the window, where there were tea and snacks. I also prepared a little \"surprise\" for Lucien..."
  },
  [205911] = {
    diary_text = "It had been a long time since I saw Lucien. Ming told me that he had a lecture at the bookstore on the weekend, so I arrived early to meet him. As I was about to talk to him, I was interrupted by an audience."
  },
  [205921] = {
    diary_text = "The audience asked Lucien to recommend some neuroscience books. When Lucien was looking for the books, I noticed that he had lost weight. It seemed that he probably had not been resting well due to the experiment."
  },
  [205931] = {
    diary_text = "After the lecture, Lucien walked me home. I told Lucien that all his plants were under my care and that many of them were in bloom. Lucien agreed to take a look at them. He then asked if I could teach him how to prune."
  },
  [205941] = {
    diary_text = "I told Lucien that I missed him and was worried about him. Lucien admitted that the experiment did make him a little tired, but he was surprised that I would be so worried. Lucien finally told me that I was the one who pulled him out of the experiment and showed him the spring light in this tiny corner."
  },
  [206011] = {
    diary_text = "I overheard that the sorcerer wanted to offer me as a sacrifice to invoke rain, so I escaped from the tribe in the night. After I fell down a steep slope in the woods, I stumbled into a garden palace where a young man resided."
  },
  [206021] = {
    diary_text = "The young man named Lucien seemed very gentle. He offered me a medical kit to treat my wounds, which put me at ease. Lucien suggested having a game of mancala with me, then I proposed that Lucien had to take me in for a while if I won, to which he agreed."
  },
  [206031] = {
    diary_text = "During my stay, I found that he had a massive library with books which were unheard of. He also had a room full of equipment that could make gold flow out of stones and flowers bloom on cardboard trees. I became more and more curious about Lucien and the world he saw."
  },
  [206041] = {
    diary_text = "I was captured by the sorcerer's calvaries back to the tribe. The sorcerer decided to sacrifice me without permission, but Lucien rescued me. When everything was resolved, he invited me to go home with him. My face heated up, and my eyes widened in surprise..."
  },
  [206111] = {
    diary_text = "With a curious mind, I went into the dim room. Dividing the room in two was a misty glass, and I saw someone resembling Lucien. But he didn't see me, and just walked on by."
  },
  [206121] = {
    diary_text = "I was still mulling over what happened, when I heard Lucien's voice. How did he get around to here so fast? As I was wondering, Lucien told me that was him from 15 minutes ago."
  },
  [206131] = {
    diary_text = "We walked around all the various installations in the mall, and I couldn't resist asking his view of the theme. But I didn't expect to find us connected again."
  },
  [206141] = {
    diary_text = "After separating, we met again at opposite sides of a long escalator. I understood this was keeping with the theme, but I decided not to let Lucien slip by me again."
  },
  [206211] = {
    diary_text = "In order to take part in a show, Lucien did some homework ahead of time. It made me a little jealous. Lucien noticed, so he promised he would ask me before doing any more shows."
  },
  [206221] = {
    diary_text = "In the show, Lucien chose an audience letter from a middle school student. He consoled the listener, saying that possessiveness wasn't a psychological problem, but an instinct of love."
  },
  [206231] = {
    diary_text = "Lucien chose a monologue from a play. I was drawn in by his vivid portrayal and got curious -- what kind of possessive streak did Lucien have himself?"
  },
  [206241] = {
    diary_text = "After the show, the director invited Lucien and I to record a dialogue as special content. In the dialogue, Lucien answers why he brought be here in the first place, and that question I most wanted to ask."
  },
  [206311] = {
    diary_text = "Lucien had been busy again lately, and I went looking for him at the research center. I didn't find him, but found a peculiar book on his desk?! Suddenly, in a daze, I found myself in an old European manor..."
  },
  [206321] = {
    diary_text = "This \"Count Faust\" before me was clearly Lucien, but some of his mannerisms didn't seem like him at all... Had Lucien been subsumed by the character in the book?"
  },
  [206331] = {
    diary_text = "Lucien recouned for me the peculiarities of this book and his research efforts. I remembered what Pete said and suddenly felt like Lucien was oddly distant."
  },
  [206341] = {
    diary_text = "I told Lucien what I firmly believe in my heart, and surprisingly, it took us out of the book and wrote an ending to the story. Perhaps for both \"Count Faust\" and us, the story went on."
  },
  [206411] = {
    diary_text = "On a Saturday morning, I set off with Lucien to the countryside. We were there a year ago for a counseling project for children living in the mountains. Yet this time, Lucien was going to revisit Yara, an introverted little girl who used to fear going to school because of bullying. Curious about how Yara is doing now, I took Lucien's advice and decided to see the results for myself."
  },
  [206421] = {
    diary_text = "To my delight, Yara has become quite outgoing now, all thanks to the counseling provided by Lucien and his colleagues. Since she has learned to affirm herself, what Lucien needed to do was only make regular revisits. With the task completed, Lucien asked me where I planned to explore next. Just then, Yara's grandmother warmly invited us to join them for a meal."
  },
  [206431] = {
    diary_text = "During the meal, Yara's grandma served us liquor brewed out of local green plums, and I was attracted by its sour, sweet, and slightly spicy taste. Hearing the plums were a regional specialty on the hills, I showed interest in picking some myself, but Yara's grandma said they had gone out of season a week ago. After the meal, Lucien suggested we still visit the grove of green plums anyway. As expected, there were no plums left. We rested by the stream for a while, and while Lucien wasn't paying attention, I sneakily splashed a bit of water on his face."
  },
  [206441] = {
    diary_text = "Lucien suggested we try the mountainside following the stream's flow, theorizing that there might still be green plums there. We decided to continue exploring, and to our surprise, we actually found some wild green plums on the next hill. Excitedly, Lucien and I started picking them. As we savored this tranquil afternoon, inspiration suddenly struck, flooding me with new ideas for my show..."
  },
  [206511] = {
    diary_text = "At threat of sword-point from my crew, I leap into the sea. Luckily, a sailor I helped before hides me in a little boat, which carries me to unknown waters where there are strange snow flurries. Just as the little boat is about to be overturned by a huge wave, a man appears in the water and saves me."
  },
  [206521] = {
    diary_text = "The man who saves me is named Lucien. He lives in an abandoned temple on the island, and the melodies he plays can make the laurels burst into bloom. He can also manipulate water. All kinds of signs point to him being a mythical, enchanting siren of the sea... but he doesn't seem exactly the same as the legends."
  },
  [206531] = {
    diary_text = "While I'm in the temple, some mysterious force brings me back into the past, and I see a sea god that once protected the oceans. Legends say a siren slayed the sea god, but Lucien tells me that the sea god's fall was due to the loss of belief in him. In the past, the sea god had many believers. I warn him to beware the inconstancy of humans, but he seems more curious about me..."
  },
  [206541] = {
    diary_text = "The snow on the sea fell heavier, and meanwhile, Lucien's long hair turned whiter and whiter. When it was completely white, Lucien cleared a path for me on the sea and sent me away from the island. Not long after I'd left, the power sustaining the little island seemed to fade, and it was slowly swallowed by the sea. Still worried about Lucien, I turned my boat back toward him. When I saws him, two faces from my memory began to overlap..."
  },
  [206611] = {
    diary_text = "While I was anxiously waiting for the review results, Lucien and I came to a tea garden in the countryside. But I was disappointed when it started raining on our \"tea-picking trip\"."
  },
  [206621] = {
    diary_text = "The owner took us to the tea room on the hill. I then learned the real reason Lucien brought me here..."
  },
  [206631] = {
    diary_text = "Tea-tasting with Lucien in the tea room was such leisure it seemed to gradually ease my anxiety..."
  },
  [206641] = {
    diary_text = "The sky gradually cleared up, so Lucien and I headed to pick tea leaves. I then spotted the slogan on a sign—Good things will come at the right time. This moved me to confess my suppressed feelings to Lucien."
  },
  [206711] = {
    diary_text = "This morning, I left a homemade lunchbox at Lucien's doorstep, but he didn't contact me all day and the lunchbox remained untouched. As I was getting worried, I heard a kitten meowing from the elevator area—it turned out Lucien had rescued a stray cat during a downpour."
  },
  [206721] = {
    diary_text = "We ended up having a small argument out of my concern for Lucien. After retrieving some cat food from the storage room, I found Lucien asleep on the sofa..."
  },
  [206731] = {
    diary_text = "I was about to express my feelings to Lucien when the kitten caused a commotion in the bedroom. Lucien took on the task of soothing the mischievous cat, but the little fur ball wasn't cooperative at all. Watching Lucien's rare display of clumsiness, I couldn't help but let out a chuckle."
  },
  [206741] = {
    diary_text = "I eventually explained to Lucien why I was feeling upset, and he admitted that he had already guessed as much. In the end, he confided that in this world, I was the person he needed the most."
  },
  [206811] = {
    diary_text = "I was ordered by the organization to disguise as Mr. Lucien's blind date. After he invited me to board the train heading away from the city with him, I suddenly received a new order from my boss..."
  },
  [206821] = {
    diary_text = "I knew all along that Mr. Lucien was a dangerous person, but when he said he wanted to eliminate the core member of my organization, \"snow fox\", my heart couldn't help but shudder—Am I really able to approach such a person?"
  },
  [206831] = {
    diary_text = "After spending three days together, I gained nothing from Mr. Lucien, but Mr. Lucien caught me and invited me to the Double Seventh dinner on the train. To protect my organization from being exposed and for \"snow fox\", I finally made a decision..."
  },
  [206841] = {
    diary_text = "During the Magpie Festival dinner, Mr. Lucien and I lured the real traitors out with the smoke of the explosion and plan failure. Despite the enemy's ambush and more evil in the dark with their eyes on the inextinguishable starlight, I would fear no more this time because Lucien was by my side."
  },
  [206911] = {
    diary_text = [[
After countless days and sleepless nights working on the S+ class project, I was close to my limit. I felt I was a pin-drop away from shattering into a million pieces. I sat exhausted on the subway and thought about Lucien, finding brief solace in the comforting thoughts.
Suddenly, Lucien's hand touched my cheek and brought me back to reality.]]
  },
  [206921] = {
    diary_text = "Lucien stopped me from getting off the subway, which surprisingly sent a wave of relief in me. He told me to choose a random number and led me off the subway at an unfamiliar station. As soon as we stepped out of the subway station, the glaring sun poured its warmth on us."
  },
  [206931] = {
    diary_text = "We wandered around and sat down at a bus stop as we chatted about work. I lamented how my obsession with work had made me miss the journey on the way. Then a double-decker bus pulled up before us."
  },
  [206941] = {
    diary_text = "I got on the bus with Lucien without knowing where we were heading, yet I felt safe because of Lucien. He was always here with me on the way, searching for answers to all sorts of questions."
  },
  [207011] = {
    diary_text = "A video that Kiki shared gets Lucien and I talking about a \"composure challenge\" that's gone viral. I proposed that the two of us take the challenge, to which Lucien said that the hardest \"composure challenge\" to pass was right in front of him..."
  },
  [207021] = {
    diary_text = "As I watched the spy character in the challenge video, I couldn't help thinking of what Lucien would look like in that outfit and cracked a smile. Seeing my smile, a subtle expression came over Lucien's face... Oh no, he wouldn't get the wrong idea, would he?"
  },
  [207031] = {
    diary_text = "I explained myself to Lucien and told him I thought he was the best-looking. He said this was because I saw him with a \"halo effect\". Remembering Lucien's challenge, I had a wild idea to set him up with a smart watch with a heart rate monitor..."
  },
  [207041] = {
    diary_text = "Naturally, I still didn't manage to see Lucien get flustered. But as long as I got to enjoy a leisurely day with him, the result of the challenge didn't matter. However, Lucien is always so in-demand and eventually got a phone call. Seeing how serious he looked, I drew near..."
  },
  [207111] = {
    diary_text = "The day before Lucien's birthday, I finished my Venice \"field trip\" and was getting ready to head to the airport when I got a call from Lucien. While still a bit stunned, I clearly made out a familiar figure across the canal."
  },
  [207121] = {
    diary_text = "Lucien's simple, straightforward response to why he was here made my cheeks burn. He seemed to be showing his sincerity and willfulness to me more and more often. When I mentioned that I didn't turn up much on this trip, Lucien suggested that he could look with me."
  },
  [207131] = {
    diary_text = "Before that, Lucien took me to repair my busted camera. Apparently, he'd done something similar all those years ago. These uncanny coincidences were maybe what made time such a marvelous mystery. A sudden drizzle imparted the Bridge of Sighs with an extra, hazy beauty. We sat in a gondola, and as the clock tolled, the camera captured a cover photo for our fourth keepsake album."
  },
  [207141] = {
    diary_text = "As dusk set in, Lucien and I bought a cake, then passed a bookshop he'd been to before. We decided to send each other a postcard one year in the future. Out of my expectations, I'd found a precious, time-spanning gift. It was an echo of that former time, and also a new imprint of our constant journey of discovery."
  },
  [207211] = {
    diary_text = "I looked at Lucien imprisoned before me and solemnly announced his next fate—to be judged after enduring a month-long divine punishment. But my heart wrenched for some reason when he approached me."
  },
  [207221] = {
    diary_text = "Whenever I saw him being punished, I felt like my heart was being torn apart. I didn't understand why I felt this pain, but a voice inside was crying out: I didn't want him to be hurt at all..."
  },
  [207231] = {
    diary_text = "The time for judgement was brought forward. I hurried there, only to enter Lucien's vision—it was a wonderful world. He then told me the truth. This was the world he and I had once created, but Master would not allow it and took away my memories..."
  },
  [207241] = {
    diary_text = "I got all my memories back. Seeing that Lucien was about to fall into wilderness, I leaped down into his embrace. No one could separate us this time, whatever the future would bring."
  },
  [207311] = {
    diary_text = "A group of researchers in the Research Center who were about to leave after completing the program organized a team-building activity in the ancient town and invited Lucien and me to go along. It was not until then that I got to know Lucien had turned them down multiple times because of me."
  },
  [207321] = {
    diary_text = "Lucien would like to choose some gifts for his colleagues. While shopping, I found that Lucien was more involved in \"festive things\" than before. So I decided to leave the goodies acquisition task to him."
  },
  [207331] = {
    diary_text = "We bought a pair of cute tiger dolls. Lucien said he would like to hold his \"good luck\" as the tigers did. Then we found something suitable as a farewell gift to Lucien's colleagues..."
  },
  [207341] = {
    diary_text = "At dinner, Lucien received a mysterious New Year's gift from his colleagues. Lucien confided in me his thoughts on New Year's wish. I took out my handwritten greeting card, just to find that he had prepared the same, in which he expressed his wish to work with me on a lifetime program."
  },
  [207411] = {
    diary_text = "Lucien invited me to go to a \"cherished beauty\"-themed exhibit. The strange thing was that this exhibit was held in a virtual space."
  },
  [207421] = {
    diary_text = "In the virtual exhibit room, Lucien and I helped each other put on our equipment. Then we entered the virtual space together, and a romantic and wonderful world unfolded before us. It was so immersive that I actually forgot some of the exhibit's rules..."
  },
  [207431] = {
    diary_text = "In the exhibit, we came across a maple tree, which reminded me of that beautiful time I once spent with Lucien. Little did I expect, in a little building at the end of the exhibit, there was a surprising \"exhibit item\" waiting for us in the sunshine..."
  },
  [207441] = {
    diary_text = "After viewing the entire exhibit, Lucien and I both coincidentally realized that leaving behind an object of beauty wasn't important. The most important thing was to have a person in our lives creating those moments of beauty worth cherishing, which we already both had by our sides."
  },
  [207511] = {
    diary_text = "On the picturesque island, I walked down the street alone in a wedding dress, heading to a stall to buy a bouquet. The gaze of the people around me made me a little embarrassed, but it was part of the event..."
  },
  [207521] = {
    diary_text = "As I expected, Lucien and I ran into each other on the street. The island was full of tourists. Just as I was wondering how to get a cab, Lucien had an idea."
  },
  [207531] = {
    diary_text = "It was not hard to find the cape we saw on the poster. Following the event agenda, Lucien and I entered a building called \"Love Post Office.\" To our surprise, this post office delivered neither letters nor postcards but a unique newspaper..."
  },
  [207541] = {
    diary_text = "On the beach, Lucien opened the box he had been carrying, which contained a gift for me—a veil embroidered with snowflake patterns. The beautiful beach scenery was our witness as he told me the meaning behind the gift."
  },
  [207611] = {
    diary_text = "Seated on the bench on the rooftop, Lucien and I were overlooking the center of the city. Before sunrise, I took a photo—the first one I used to describe him—and titled it \"Before Sunrise\"."
  },
  [207621] = {
    diary_text = "After sunrise, I dragged Lucien away from the rooftop and walked into the lively street. We discussed the assignment over breakfast."
  },
  [207631] = {
    diary_text = "I tried to answer the question \"What impression Lucien left on me\", but failed. In the end, we had to browse through the photos I took of him and search for the answer there."
  },
  [207641] = {
    diary_text = "It was silent in the reading room in the depth of the corridor. I took a picture of the peach blossoms at the window and told Lucien that, \"spring\" was the impression he left on me."
  },
  [207711] = {
    diary_text = "For the past few nights, I had been waking up to weird sounds. The situation was getting even more bizarre—snacks mysteriously disappeared when I woke up. With all these strange occurrences, I decided to share my suspicions with Lucien."
  },
  [207721] = {
    diary_text = "After hearing my theory, Lucien offered a different take. To get to the bottom of it, we decided to video call that night, and he would observe me while I fell asleep."
  },
  [207731] = {
    diary_text = "After finishing some work with Lucien on the call, I finally drifted off to sleep. But I was soon startled awake by the sound of something shattering. I gasped and sat up, only to find that the vase that had been on my bedside table was now shattered across the floor..."
  },
  [207741] = {
    diary_text = "When I watched the footage Lucien had recorded, everything was finally clear. I was both frustrated and amused. When I was about to lecture the little dog, Lucien suddenly spoke up, saying he had recorded another very interesting scene..."
  },
  [207811] = {
    diary_text = "I arrived at a cafe early in the morning to complete the final task on Lucien's list—to go to this cafe we often walk to and buy a hot cocoa on the day before he returns. While there, I heard a familiar voice..."
  },
  [207821] = {
    diary_text = "To my surprise, Lucien had finished up his conference a day early and was waiting for me in the cafe. I pointedly asked him why he came back early, to which he replied he knew he'd miss me. That's why he gave me this hot cocoa task and came here early for our \"chance encounter\"."
  },
  [207831] = {
    diary_text = "Because the season's final big snow came much earlier than expected, Lucien wasn't able to complete the task of watching it with me. To make it up to me, he took me to a park outside of the city to bid farewell to winter."
  },
  [207841] = {
    diary_text = "Lucien split up from me on purpose and created a beautiful winter scene in the park for me so that I could say a nice goodbye to this winter season. As I looked at the \"snowflakes\" filling the sky, it dawned on me that Lucien always filled my world with beautiful things."
  },
  [207911] = {
    diary_text = "When we finally had success with the experiments, the colors turned out a little creepy. Since our company hired lighting technicians, I volunteered to tackle the color scheme challenge."
  },
  [207921] = {
    diary_text = "The color scheme designed by the lighting technicians looked just like the real fireworks one would see on New Year's Eve, but I still felt something was missing. Lucien suggested we look for inspiration from our previous landscape photos. To our surprise, even though we chose the same backgrounds for many of our shots, our pictures turned out very differently..."
  },
  [207931] = {
    diary_text = "Today, I came to the lab to film the fireworks experiments as usual. When the shooting was over, Lucien asked me to stay and do him a \"favor.\" After completing a few romantic chemistry experiments with his guidance, I realized the chemical reactions in the lab were the most beautiful \"scenery\" in his eyes."
  },
  [207941] = {
    diary_text = "Lucien helped me understand that condensed fireworks were not about replicating traditional fireworks but about giving a glimpse into the future. And to me, \"dawn\" represents the future."
  },
  [208011] = {
    diary_text = "As I read comments online about the pyramid scheme cult, I couldn't help but think back to that time. Just then, Lucien called to invite me to a mountain hot springs for a change of scenery..."
  },
  [208021] = {
    diary_text = "To my chagrin, I heard people discussing it in the hot springs resort too. As for how I got out of it, only Lucien knew, because he went through it with me..."
  },
  [208031] = {
    diary_text = "Sensing that I was having bad dreams, Lucien comforted me, after which I truly calmed down. Compared to the steamy hot springs, his kiss was actually more soothing..."
  },
  [208041] = {
    diary_text = "It turned out Lucien isn't always so calm and collected. He had some PTSD too, so of course I had to comfort him. And if any similar situation pops up in the future, we'll always give each other lots and lots of hugs."
  },
  [208111] = {
    diary_text = "After getting off the ferry, I gave Lucien a ring to confirm that his work was wrapping up. I then notified him that I had kidnapped \"the thing he valued the most\" and demanded the ransom. When I was waiting on the beach, Lucien showed up with the ticket and suitcase. This was when I told him that he would be kidnapped for three days."
  },
  [208121] = {
    diary_text = "During check-in at the hotel, Lucien was mistaken for someone else's boyfriend because of their matching outfits. I didn't want him to notice my resentment, but he seemed to have guessed and got changed as soon as we got to the hotel room. Then I told him what I demanded of him for the next three days."
  },
  [208131] = {
    diary_text = "We did nothing these three days, while I made sure Lucien got some rest. When I saw him sleeping on the hammock, I told him what was bothering me, only to realize that he was awake the whole time."
  },
  [208141] = {
    diary_text = "It was the final day before we knew it. Before we departed, Lucien and I went for a walk along the beach, confiding in each other all the feelings that flooded us these few days."
  },
  [208211] = {
    diary_text = "I woke up in bed to find Lucien's fox tail wrapped around my waist, and to the scent of his rich aroma. I just had to get a closer whiff, but Lucien woke up and caught me losing control of myself."
  },
  [208221] = {
    diary_text = "Lucien and I arrived at Cloud Cafe as agreed, and the owner explained what \"Spring is for Animals Too\" means. Apparently, the purpose of the cafe is to provide a place for mingling, where customers can try to attract each other without feeling self-conscious. But then the owner told me that the staff can't let themselves be enticed."
  },
  [208231] = {
    diary_text = "I couldn't help being sucked in by the cafe's lively atmosphere. Just then, Lucien handed me a cup of coffee and suggested we take a break. Seeing Fox Lucien in a butler's uniform, I wanted to get my paws on him, but then I suddenly remembered the owner's rules. As a conscientious employee, I resisted Lucien's allure, but that only made him more determined..."
  },
  [208241] = {
    diary_text = "This game of patience ended with a show of weakness from Lucien, and I saw how helpless Lucien could be when captivated by me. Who knew under his cool and collected demeanor there lurked such intense emotion."
  },
  [208311] = {
    diary_text = "Lucien and I were cleaning the house when I found a hard drive containing a lot of precious memories of when I was a college student. After opening it, Lucien and I discovered a romantic promise I had made long ago on a beautiful island."
  },
  [208321] = {
    diary_text = "Lucien and I went to the island to make good on that promise. I even put on the old skirt that I wore at the time. I wanted to find the perfect closure to that old promise."
  },
  [208331] = {
    diary_text = "On our way there, I realized much had changed on the island. Not only did the island change a lot, but I was also different from the person I was all that years ago."
  },
  [208341] = {
    diary_text = "Lucien and I arrived before sunset. To my surprise, the place was completely unchanged compared to the rest of the island. It was here that Lucien told me no matter how much the future changed, his feelings for me would never falter."
  },
  [208411] = {
    diary_text = "We stayed at a retro-decorated B&B that was reminiscent of childhood days. Listening to Lucien's explanations about brainwaves, I was excited to witness changes in my own brainwaves..."
  },
  [208421] = {
    diary_text = "After a bath, I couldn't resist capturing the moment with my camera. Lucien, watching me, recalled a true story. But as I listened with curiosity, a chill ran down my spine..."
  },
  [208431] = {
    diary_text = "Lucien and I came to the pond to pick lotuses. The pleasant surroundings made us relax. Watching his graceful figure, I hatched a plan and suggested a competition."
  },
  [208441] = {
    diary_text = "Back in the room, I eagerly pulled up Lucien's brainwave data and started observing it. I munched on watermelon while talking about the moments that made him relax. His gaze on me softened. In the next second, his gentle lips met mine. Right then, we were in our most relaxed state."
  },
  [208511] = {
    diary_text = "我帮大学室友训练小猫，希望它能顺利通过一档宠物节目的海选。眼看离海选没几天了，小猫无法完成我教的动作，看到我苦恼的样子，许墨忽然问了我一个奇怪的问题。"
  },
  [208521] = {
    diary_text = "在一连串的问题后，许墨根据我的回答试图用图像来分析出小猫什么时候最活跃，并称在它最积极的时候进行训练说不定效果会更好。有了许墨的帮助，陷入瓶颈的小猫训练终于出现了一丝曙光。"
  },
  [208531] = {
    diary_text = "海选当天，小猫完成了训练的动作，眼看一切就要顺利结束时，小猫却因为突发意外受到惊吓，从门缝中逃走了！"
  },
  [208541] = {
    diary_text = "好不容易找到了小猫，回到家后，我却不由自主地想到了海选时评审的一句话，不禁有些自责自己是不是没有照顾好小猫。而在许墨的引导下，我渐渐解开了困惑……"
  },
  [208611] = {
    diary_text = "I made plans to meet up with Lucien at the botanical garden this afternoon. I arrived a little earlier than him to film some stock materials for work later. As I got up to go for a cup of boba tea, an arguing couple caught my attention. As I gave up my seat, I unexpectedly arrived at the cafe shop next to the entrance, where to my surprise, I ran into Lucien."
  },
  [208621] = {
    diary_text = "It turned out that Lucien ended his work early to avoid keeping me waiting. We were going to pick up some flowers when bumping into the young man from earlier, who turned out to be Lucien's intern in the research center..."
  },
  [208631] = {
    diary_text = "Lucien took me to the paleontology exhibit, where we encountered a fossil imprinted with the shape of a butterfly that gave us a whole new insight."
  },
  [208641] = {
    diary_text = "Lucien said that he was going to take me somewhere special. Inside the metasequoia jungle, the activating fountain gave us quite a pleasant surprise. Lucien asked me to close my eyes before shocking me with the butterfly fossil as a present! That was the moment I realized that there was an element of certainty between me and Lucien. No matter how the butterfly fluttered its wings, Lucien and I would be together in every single outcome."
  },
  [208711] = {
    diary_text = "To lure the [i][i]Bellflower[/i][/i], my family purposefully threw a spectacular banquet feast. We did it so that the pirates would steal a fake map fragment of a mysterious continent, allowing me to stow away on board and retrieve pirate intelligence. And all of this was at my own behest, so I could secure my freedom. I never thought a dashing man would disrupt my plan, nor that he would be the pirate captain!"
  },
  [208721] = {
    diary_text = "I was taken aboard the ship by the captain and learned that he was none other than that genius former baron, Lucien. In order to stay, I fooled him into believing I was an admiring maidservant who wanted to learn to be a pirate from him."
  },
  [208731] = {
    diary_text = "My work aboard the ship was to attend to Lucien's living quarters, which kept delaying my opportunity to send out the intelligence I'd gathered. In order to get pen and paper to write down what I knew, I implored Lucien to teach me to read. Unexpectedly, I heard an immensely interesting and improbable tale from him."
  },
  [208741] = {
    diary_text = "After my conversation with Lucien, although I'd sent off my intelligence, my heart had begun to waver. Finally, on the eve before my family was set to attack, I realized my true feelings. Meanwhile, Lucien seemed to have known all along my identity and plan, and he invited me to remain on his ship forever."
  },
  [208811] = {
    diary_text = "One weekend afternoon, I was lying in Lucien's arms and chatting on my phone in my work group chat. We started discussing the auditions for this fashion program, and Kiki joked that Professor Lucien should give it a try, but I thought Lucien wasn't a good fit for a reality show. As we chatted, I got a little drowsy and fell asleep in Lucien's arms."
  },
  [208821] = {
    diary_text = "When I woke up, I realized I had a blanket over me. Just when I was about to get up, Lucien pressed me down on the sofa. Apparently, he saw my chat just now and gave me a very pressure-packed \"interrogation\"."
  },
  [208831] = {
    diary_text = "The next day, I arrived at work and continued the auditions. After auditioning people all day and feeling exhausted, my coworkers suddenly started making a hubbub. Kiki gestured for me to look at the entrance, which is when I discovered that the figure standing in the doorway was apparently Lucien..."
  },
  [208841] = {
    diary_text = "His outfit today was extremely trendy, and he positively shined among the crowd. I jokingly asked Lucien if he was here to audition, to which he said he was there to pick up his \"girlfriend\" from work. On the way home, I asked Lucien why he suddenly changed his style. He looked at me and said he just wanted to prove that any facet of him could attract my full attention."
  },
  [208911] = {
    diary_text = "When Lucien and I were watching a movie, he suddenly got a text from work. He told me apologetically that he had to go to the research center and had me go with him. After all, with a rare weekend free, we both wanted to spend every possible second that we could together."
  },
  [208921] = {
    diary_text = "It turned out that a newly developed piece of equipment was on the fritz. This equipment could record what a person is thinking when their nerves are calm and then have it played back on a projector. Seeing that Lucien needed to test the equipment, I prepared to go, but Lucien had me stay and watch his \"consciousness images\" with him through the machine."
  },
  [208931] = {
    diary_text = "I watched Lucien's consciousness images with relish and realized during that time when we were both too busy to see each other, we both felt the same emotions and longed for each other."
  },
  [208941] = {
    diary_text = "While Lucien went out to attend a meeting, I waited bored in his office. Little did I expect, my consciousness images were being recorded by the machine. Meanwhile, Lucien did notice this when he returned. I couldn't resist asking if he wanted to look at my consciousness images together..."
  },
  [209011] = {
    diary_text = "Today, after making a deal with a headless ghost for his love story, a \"painted skin ghoul\" named Lucien came to me hoping that I'd write a story about his kind. The strange thing was, he said he was a ghoul without any stories."
  },
  [209021] = {
    diary_text = "Recently, I often visited Lucien to get material and finally saw the way he looked as a ghoul. I wrote about this dangerous yet alluring version of him, but never imagined he'd read it aloud in my presence!"
  },
  [209031] = {
    diary_text = "To help me through a tough bout of writer's block, Lucien proposed we go to one of his favorite places. On the sunset-soaked cliffside, I felt the emotions hidden in Lucien's heart for the first time."
  },
  [209041] = {
    diary_text = "The story was finally complete, but when I took it to Lucien, he'd already vanished. A feeling of loneliness overtook me in the empty, still courtyard. Then, a demonic tenderness entwined around me..."
  },
  [209111] = {
    diary_text = "At our camping site in Naples, we saw Mount Vesuvius from afar as Lucien educated me on its history. I expressed my unease at the powerlessness of men in the face of such overwhelming power, but Lucien managed to reassure me with his answer. Whatever uncertainty we might face, I feel safe as long as he is with me."
  },
  [209121] = {
    diary_text = "Upon returning to Loveland City, we made our first stop at the Biotech Center. There, I accidentally discovered an experiment that Lucien was conducting on himself. He informed me that the result was a failure. However, I convinced Lucien that I would answer his hypothesis by using this year's birthday present."
  },
  [209131] = {
    diary_text = "Back at home, I unveiled Lucien's birthday present, which I had prepared for a long time, providing an answer to his experiment in my own way. As he stared with fixation, I told him that there was still more to this present."
  },
  [209141] = {
    diary_text = "I took Lucien to the storage room, where I presented him with a unique birthday wish that only I could give. As we locked our hands, I could feel a sense of wonder as new memories and strength welled up from within us. Basked in the light from the sunset in the storage room, Lucien and I savored this blissful moment of warmth and affection."
  },
  [209211] = {
    diary_text = "The romance variety show organized by the company and other studios went awry. In exigent circumstances, Lucien and I had to film for the test-run episode of the show. To make sure the script of the show stayed consistent and the filming went smoothly, we were required to pretend to be going through a rough patch and conceal our romantic relationship in the show."
  },
  [209221] = {
    diary_text = "In the show, I intentionally kept Lucien at arm's length, but when playing a game, Lucien resorted to some \"little trick\" and earned us a \"sofa date.\""
  },
  [209231] = {
    diary_text = "When giving an interview on the show, I realized that the love between me and Lucien could be the most beautiful thing in the world. During the subsequent \"sofa date,\" Lucien's acting was flawless when he pretended to \"try to get back with his girlfriend.\" Though aware it was not real, I still found my heart aflutter."
  },
  [209241] = {
    diary_text = "After we quickly got back together in the show and finished the shooting, I had my long-desired good night's sleep. When having breakfast, I received a demo of the pre-recorded show and learned that Lucien had solemnly regarded our love as \"destiny.\""
  },
  [209311] = {
    diary_text = "Lucien and I decided to hold a home photo exhibition to ring out the old year and ring in the new. As I thought the photos we'd taken weren't perfect enough, I took the opportunity to invite Lucien to take couple photos at a self-service photo studio."
  },
  [209321] = {
    diary_text = "On the day of our photo shoot, Lucien and I got up early to prepare. I found Lucien standing amid a heap of clothes in the cloakroom, vexation painted on his face. He quickly asked me to help him with a matching couple outfit."
  },
  [209331] = {
    diary_text = "At the studio, I taught Lucien to strike up popular couple poses, and we ended up with photos stiffer than a log. Luckily, thanks to Lucien's help, we managed to get a few good photos. We then took part in a New Year's parade while the photos were being developed."
  },
  [209341] = {
    diary_text = "As Lucien gently explained each of the photos at the exhibition, my thoughts floated back to all of the happy moments we've had together. Nearing the end of his explanation, I felt like I had grasped Lucien's photographic secrets."
  },
  [209411] = {
    diary_text = "我正躺在沙发上思考接下来和许墨的放松之旅去哪时，却意外接到了许墨的电话，询问我下午要不要去参加有关他最新研究的公开课程。"
  },
  [209421] = {
    diary_text = "在许墨的课堂上大家都很专注，可就在这时我却发现脚边出现了一只叼着木头玩具的可爱小狗，这位特别的“旁听生”究竟是从哪来的呢？"
  },
  [209431] = {
    diary_text = "跟着汪酱来到了恋语大学附近的公园，许墨和我讲述了他第一次在这里与汪酱相遇的经历，就在这时草丛里突然探出了汪酱的小脑袋。"
  },
  [209441] = {
    diary_text = "带着一脸伤心的汪酱和它不小心弄坏的玩具来到宠物店，本想给汪酱挑选一个新的玩具，但是它好像并不开心，就在这时许墨猜测起了汪酱的真实想法……"
  },
  [209511] = {
    diary_text = "It was evening, and Lucien and I were sprawled on the sofa watching a movie. Seeing the ill protagonist do crazy things to leave no regrets touched a chord in me. But just as I was about to make a proposition, Lucien guessed what was on my mind!"
  },
  [209521] = {
    diary_text = "Tired and bored, Lucien and I began talking about sanity and eccentricity. All the while, I saw moonlight cascading through the transparent dome atop the rotating staircase. We shifted to the stairs to admire the beautiful and dazzling array of stars."
  },
  [209531] = {
    diary_text = "Perhaps it was the drinks I'd had or the feelings stirred by the movie, but I suddenly had the urge to rush to the sea, even at this late hour. Lucien had the same thought, as he asked me if I wanted to go. It was as if eccentricity had us in its grip."
  },
  [209541] = {
    diary_text = "Upon waking the day after, the day of the party, Lucien selected my attire and jewelry with extreme care. And as he picked up a sea-scented balm, yesterday's memories flooded my mind once more... I couldn't help but draw myself closer to him and share with him the sudden yearnings of my heart."
  },
  [209611] = {
    diary_text = "After checking into the hotel, I pulled Lucien out to the balcony to relax and enjoy a rare vacation. While Lucien was explaining the phrase \"intimacy distance\" in a poem, Lucien suddenly closed the gap between us. As our breaths mingled, I seemed to hear a whispered \"I love you\"..."
  },
  [209621] = {
    diary_text = "To hear it again, I started hinting with feigned casualness that I wanted him to recite me a love poem. Little did I expect, Lucien was a little \"unromantic\" this time..."
  },
  [209631] = {
    diary_text = "Hanging onto this idea to create an opportunity, Lucien and I went to an in-home art gallery the hotel had recommended. Maybe as an homage to the film, many people painted portraits of lovers here. Meanwhile, Lucien suddenly asked if I would paint a painting for him..."
  },
  [209641] = {
    diary_text = "As he looked at my love-infused painting, Lucien didn't seem to sense the emotion within. Seeing me put down my brush dejectedly, Lucien hugged me from behind with a sigh and candidly told me what he thought..."
  },
  [209711] = {
    diary_text = "As I got home, I saw Lucien and a neighbor gathered at his doorway. Then I learned that his living room was flooded by a leak and had turned into a mini pool... After a discussion, I invited Lucien to stay with me for a while."
  },
  [209721] = {
    diary_text = "When leaving his home, Lucien only took a few things and told me that he'd throw away the rest. I was surprised and exchanged my opinions about \"tidying up\" with him."
  },
  [209731] = {
    diary_text = "It was just one day, and Lucien's living room was bare. After work that day, I found him sitting in the empty living room, watching old videotapes..."
  },
  [209741] = {
    diary_text = "Unexpectedly, Lucien invited me to help redecorate his living room that weekend. He shared his ideas in detail and hoped the space would also reflect my style. Thus, together, we began to flesh out a home."
  },
  [209811] = {
    diary_text = "Lucien accepted an invitation from a couple at the bioresearch institute to act as a witness at their engagement party. But after we arrived, the party was canceled at the last minute. The couple very generously offered for us to follow the original plan and stay the weekend at the wildlife luxury hotel."
  },
  [209821] = {
    diary_text = "We began our vacation with an unexpected turn of events. A few unlucky incidents in a row had me in a funk. So, when we passed by a wishing well, I pulled Lucien over and tossed in a coin, wishing for a good omen."
  },
  [209831] = {
    diary_text = "Noticing what I was up to, Lucien helped me find the good omen I was wishing for. His consolation also lifted me totally out of my doldrums. But then Lucien said he wanted to give me a \"little test\"."
  },
  [209841] = {
    diary_text = "The intimacy of the garden led me to quickly find the answer to the \"test\". But rather than just meekly supply the answer, I turned the tables and tested him."
  },
  [209911] = {
    diary_text = "In the office conference room, while the magazine's editor-in-chief and I discussed the shoot, I inadvertently learned that the \"Person of the Year\" recipient was Lucien. Keeping in line with the tone of the magazine, I proposed a spicy photo shoot, and the meeting ended on good terms. Lucien came to pick me up from work and brought me flowers."
  },
  [209921] = {
    diary_text = "When Lucien and I got to the restaurant, he just so happened to receive word that he had won an award and would have to do a photo shoot. Lucien had no interest in it at the outset, but I managed to convince him."
  },
  [209931] = {
    diary_text = "On the day of the shoot, I showed up on set in disguise and introduced myself to Lucien as a stranger. I nervously observed Lucien's reaction, and I didn't think he realized. After basic small talk, Lucien changed into the sexy outfit we were using for the shoot, which drew my attention."
  },
  [209941] = {
    diary_text = "I naughtily suggested Lucien try letting loose more during the shoot, and his question in response caught me off guard. In a panic, I made up an excuse to leave, but Lucien pulled me into the dressing room. It turned out, he'd known it was me all along, but he wanted me to continue playing our game. Back at the set, Lucien's performance during the shoot made my cheeks blush and heart race. Perhaps it was a foregone conclusion who the winner of this game was going to be."
  },
  [210011] = {
    diary_text = "With a butterfly's guidance, I succeeded in finding Lucien in his inner world. Meanwhile, as the experiment was designed, he already had lost all memory of me. Now that he saw me as a stranger, I surprised him with the things I said and piqued his interest."
  },
  [210021] = {
    diary_text = "As we talked, Lucien discovered that I knew him very well, and so he got curious about my identity. At the same time, he used the information gleaned from conversation to uncover the true nature of this world. Under his manipulation, the inner world changed massively before my eyes."
  },
  [210031] = {
    diary_text = "I never imagined this experiment would actually be so dangerous. Lucien put up many obstacles in his inner world. These traps were elaborate and ingenious and seemingly designed just for me. Faced with the dilemma he posed me, I had no choice but to make a decision..."
  },
  [210041] = {
    diary_text = "I still couldn't see through to Lucien's secret, but he chose to give me one last chance. We spent an entire four seasons in the inner world. When the snow dissipated, I finally knew that Lucien's secret existed in our long relationship with each other."
  },
  [210111] = {
    diary_text = "I arrived at the greenhouse with a pot of jasmine I had grown myself and a handmade wooden sign for the grand opening. While I was exploring the place alone, Lucien appeared behind me—his outfit was strikingly different from usual. Surrounded by lush greenery, he invited me to officially become his assistant."
  },
  [210121] = {
    diary_text = "He gave me a tour of the greenhouse and let me try out the experimental device in the flower hall. As we worked together, not only did it become clear how much I meant to him, but he also confessed how deeply he had missed me."
  },
  [210131] = {
    diary_text = "With his guidance, the process of transplanting the calla lilies went smoothly. At one point, I accidentally got some soil on my face, and he gently wiped it off, his touch filled with care..."
  },
  [210141] = {
    diary_text = "When it was time to close up, Lucien handed me a pot of flowers labeled \"Reserved\". It turned out he had secretly set them aside just for me. At that moment, I felt as if something soft and beautiful had bloomed in my heart..."
  },
  [210211] = {
    diary_text = "Tomorrow, Lucien is attending a new academic conference in Europe, and so we came a day early to tour around. After seeing one of the many bustling market fairs, Lucien took me to a stall with prizes."
  },
  [210221] = {
    diary_text = "Holding my \"spoils\", I fell into a deep sleep, and the next day, I started work full of vim and vigor. Midway through, I discovered that the first floor of the exhibition also had an indoor market fair. Simultaneously, Lucien and I both had our eyes on a cute bunny doll inside a claw machine..."
  },
  [210231] = {
    diary_text = "After managing to snag the bunny, I prepared to keep working when I suddenly lost control of my body, and a string of foreign words came out of my mouth. Was someone controlling me?! Hearing gunshots ring out around the exhibition, it seemed some terrible assault was taking place..."
  },
  [210241] = {
    diary_text = "While being \"kidnapped\" by my own self, the temperature around me plummeted, and a sheet of ice covered everything. Lucien quickly found the Evolver controlling me and used his actions to tell this person what the consequences would be..."
  },
  [210311] = {
    diary_text = "最近，我们公司发起了一个“给一百名老人拍摄全家福”的公益项目，我跟许墨开玩笑说，如果恋语大学里有退休的教授对这个项目感兴趣，可以邀请他们过来拍摄。但许墨却提出了另一个人选，教我们编平安结的文婆婆。"
  },
  [210321] = {
    diary_text = "当天，许墨开车载着我来接文婆婆。为了拍照，文婆婆特意换上了她丈夫生前亲手给她缝制的衣裙，我对这套衣裙的精美程度惊叹不已。"
  },
  [210331] = {
    diary_text = "但文婆婆担心许墨一人应付不来调皮捣蛋的猫咪，就让我一起带着小猫玩耍。我向许墨暗示，婆婆已经偷偷告诉我了他的秘密，他之前曾一个人去过月老庙，而是不止一次。"
  },
  [210341] = {
    diary_text = "文婆婆拍照时，许墨提起了之所以会提出让文婆婆来拍照的理由：两个人一起过完了一辈子是件值得纪念的事，应该要有一张照片。当拍摄结束，我们送文婆婆到家之后，我和许墨决定再次前往月老庙，我在恰当的时机拿起手机，拍下了一张属于我们的照片。"
  },
  [210411] = {
    diary_text = "Lucien has been hired to give lectures at HU's summer camp, and after those three days, he and I made plans to have fun at the beach. Little did I expect, the school's A/C broke, so Lucien demonstrated a little trick to beat the heat."
  },
  [210421] = {
    diary_text = "While Lucien was in class, I roamed around campus waiting for him to \"clock out\". As I waited in the lecture hall with its tiered seating, I felt like I was back in college... When he heard that afterward, he shared his own flights of fancy with me..."
  },
  [210431] = {
    diary_text = "We sat in the back row of Professor Lawson's class making furtive \"little movements\". For the following two days, we continued enjoying this feeling of being back in our \"college days\". When we were together, even wasting time seemed romantic."
  },
  [210441] = {
    diary_text = "We finally began our summer vacation in earnest, but while we were indulging in fun, Lucien seemed out of sorts... I thought maybe he had a heat stroke, but he denied it..."
  },
  [210451] = {
    diary_text = "Lucien totally had a heat stroke. He finally realized the problem too and became much more docile. While caring for him, I realized he would often stare at me. I didn't know what he might be thinking..."
  },
  [210461] = {
    diary_text = "Lucien was finally feeling better and even proposed we go swimming. Considering his health, we ended up going to our B&B's swimming pool, and in a splash-filled world, I listened to his words from the heart."
  },
  [210511] = {
    diary_text = "My curiosity-fueled trip with Lucien had only just begun when I started getting altitude sickness. As Lucien tended to me, he told me to settle down and rest up because he was ready to be my \"oxygen\" anytime."
  },
  [210521] = {
    diary_text = "After a good night's sleep, I woke up feeling refreshed, and Lucien and I drove for Namsto. A stunning vista soon unfolded before us, and as the sun went down, Lucien and I decided to spend the night in the car out in the wilderness. The next day, we looked forward to seeing \"sunlit golden mountains\"."
  },
  [210531] = {
    diary_text = "Morning the next day, we didn't get a \"sunlit golden mountain\", so we just kept driving to our next stop. Because of a snowstorm, we stopped in at a nearby guesthouse. Inside, we braided each other's hair, hoping it would bring good luck."
  },
  [210541] = {
    diary_text = "As we cruised around, we came again to the foot of the sacred mountain by the lake. As we looked at the snow-capped mountain, I couldn't resist folding my hands together and praying for Lucien, and Lucien did the same... then, in a flash, we finally saw that miracle."
  },
  [210611] = {
    diary_text = "I'm going to take part in an art exhibition themed \"The Beauty of Touch\", but I didn't feel moved by my current piece, and it was troubling me. I consulted with Lucien about what \"touch\" meant, but he didn't give me a direct answer."
  },
  [210621] = {
    diary_text = "Lucien invited me to go tour around a public garden, but before heading out, I was delayed by a work call. As I anxiously sought a solution, Lucien suddenly held me tight..."
  },
  [210631] = {
    diary_text = "In the garden, a butterfly exhibition had many rare specimens. As we admired them, I learned that Lucien purposefully brought me here. As I looked at Lucien, I felt moved inside..."
  },
  [210641] = {
    diary_text = "Following the exhibit's butterflies, we came to a field of flowers. A butterfly landed on Lucien, and I found myself reaching out to touch it..."
  },
  [210711] = {
    diary_text = "My first year as a graduate student was packed with coursework and lab responsibilities. Dr. Lawson's lab offered state-of-the-art resources and a laid-back, open atmosphere."
  },
  [210721] = {
    diary_text = "As midterms loomed closer, my schedule became more demanding than ever. Just as I was struggling with my research progress, I was surprised to find my lab mates stepping in to help, their curiosity about my work leading to unexpected support..."
  },
  [210731] = {
    diary_text = "There seemed to be a tradition among the researchers: after returning from holidays, everyone brought small gifts to share with the lab. Lighthearted chatter filled the room, and while it would have once felt like a distraction, I found myself enjoying the camaraderie."
  },
  [210741] = {
    diary_text = "As the holiday drew to a close, another lab tradition emerged—a friendly card game session in the dorms. When I was invited to join, I decided to accept for one time. The holiday had been brief, but at that moment, I suddenly felt it was okay to take a short reprieve."
  },
  [210811] = {
    diary_text = "Ever since Lucien's passing, I had been plagued by constant nightmares. Tonight, I dreamed again of the wedding with Lucien. During the ceremony, we made our vows of love to each other, and it was as if two hearts became one..."
  },
  [210821] = {
    diary_text = "Simon—the actor who looked exactly like Lucien, but with a completely different personality—barged into my life. I knew full well he wasn't Lucien, but I couldn't help but see the shadow of my husband in him..."
  },
  [210831] = {
    diary_text = "Today was my birthday, and Simon said he wanted to perform a play for me as a birthday gift. But what he acted out sent me plummeting into an abyss of the past... Just who is he?!"
  },
  [210841] = {
    diary_text = "Lucien finally cast off his disguise of \"Simon\". He wanted to salvage everything we'd lost in the past, but it was already too late. The poison within me was beyond saving, and all we could do was watch as our story came to an end."
  },
  [210911] = {
    diary_text = "At the stroke of midnight, I came to Lucien with a freshly baked little cupcake to start the special day with him. He was busy finishing up his work so he could spend the next two days with me. I nestled in his arms, keeping him company. But to my surprise, when I woke up in the morning, I found out he'd just come back home!"
  },
  [210921] = {
    diary_text = "Lucien looked a little off, but I didn't press him any further, just hugged him instead. When he asked for help with something that was bothering him, I said yes, promising I'd help him in my own way. After a bit of fun with a random number game, we found ourselves back at an old, familiar place."
  },
  [210931] = {
    diary_text = "The open field from years ago was now occupied by a hospital. Lucien seemed to know it well and casually mentioned his partnership with it. Later, we wandered into a cafe, where the colors of time seemed to unfold before us through the window."
  },
  [210941] = {
    diary_text = "Sensing Lucien's mood, I dropped the pretense and cozied up with him at the B&B I'd booked. I listened to him, but I also made it clear that growing up doesn't mean losing ourselves. As the night wore on, fireworks lit up the sky, and we walked into that beautiful moment together."
  },
  [211011] = {
    diary_text = "Lucien and I, woken by the first ray of sunlight in the hilltop cabin, were leisurely lying in bed, starting our nice weekend with a sunbath."
  },
  [211021] = {
    diary_text = "Merely because I mentioned \"seasonal affective disorder\" during my chat with Lucien yesterday, he brought me to the log cabin of a suburban guest house boasting a view of the earliest sunrise and initiated this journey."
  },
  [211031] = {
    diary_text = "During our exploration of the cabin, we discovered a lot of old items left by its owner and gradually started to resonate with this vestige of their life."
  },
  [211041] = {
    diary_text = "After having a tour outside, we actually came across an Easter egg the cabin owner left behind for lucky future occupants—a secret fairyland..."
  },
  [211111] = {
    diary_text = "My hacky acting skills did not garner the good graces of the director, and he dismissed me from the set. While I was sulking, a playwright named Lucien actually expressed his appreciation of me..."
  },
  [211121] = {
    diary_text = "To escape from an arranged marriage, I came to this metropolis of dissolute indulgence. But if I still can't find my worth, then where else can I go? Lucien's suggestion is that I can go on a date with him and learn to be a... villain?"
  },
  [211131] = {
    diary_text = "The first stop on our date is actually a circus show. Here, I witness the dark underbelly of the city, but I don't let it discourage me. Rather, I want to try even harder to influence this era; however... does Lucien see through my facade?"
  },
  [211141] = {
    diary_text = "Sure enough, he knew all along that I was no diner waitress! With pomp and circumstance, Lucien sent me a letter of visitation, and I took him on a tour of my old-fashioned and boring mansion, hoping that he would discover my true heart hidden in this gilded cage..."
  },
  [211211] = {
    diary_text = "取材结束，我也终于可以迎来和许墨的城市观光小假期。乘电梯离开大厦时，团队里的摄影师为打发时间，讲起了流传在大厦间的怪谈……"
  },
  [211221] = {
    diary_text = "虽然被不稳定的电梯吓了一跳，也无法通过空间折叠离开，许墨清晰的思路让我重新冷静下来，跟他一起寻找离开大厦的方法……"
  },
  [211231] = {
    diary_text = "我在许墨的引导下，弄清楚了电梯间之谜，大厦在这一刻终于褪下颇具灵异色彩的外衣。"
  },
  [211241] = {
    diary_text = "庆功宴顺利举办，这次有惊无险的经历反倒激起了大家制作一档怪谈节目的兴趣。对我来说，和许墨共度的假期也终于来临，不想一通意料之外的电话打了过来……"
  },
  [211311] = {
    diary_text = "Lucien and I drove to this southern town, but the temperature was far lower than we imagined. After warming each other up in the living room, Lucien started organizing the equipment for the experiment he was here consulting for, and the device he was handling piqued my curiosity..."
  },
  [211321] = {
    diary_text = "When we went to take a little nap, we discovered the bedroom was completely bare. In our shock, Lucien sought out the organizer to confirm and learned that we had been entered into the social experiment too. We decided to go with the flow and take part in the experiment, and so we drove to a furniture gallery to outfit our bedroom. In the process, I seemed to understand the special reason the organizer set things up this way..."
  },
  [211331] = {
    diary_text = "The next morning, we were met with the second of the organizer's \"surprises\"—a power outage. I suppressed my somewhat dampened spirits in an effort to give Lucien positive emotional feedback. Fortunately, he also had a special method for making us happier."
  },
  [211341] = {
    diary_text = "The social experiment officially ended, and Lucien and I were treated to a \"shopping spree\" by the organizer. Little did I expect, Lucien was particularly \"picky\" about the groceries he bought. Seeing him vacillate between vexation and elation, I couldn't help but feel a tenderness come over me."
  },
  [211351] = {
    diary_text = "Lucien and I joined forces to cook dinner and tasted the fruits of our labor together. While it was still dusk, we went to a night market to enjoy the festivities and stock up on Chinese New Year's supplies... I wanted to invite him to experience with me every little joy and delight that I felt."
  },
  [211361] = {
    diary_text = "In the courtyard, Lucien and I set off a string of firecrackers and dispelled his \"stereotype\". Beneath a shower of fireworks, Lucien was tinged with a lively air. While getting warm in the car, Lucien told me through his actions how he was currently feeling. I similarly let him know that right now, our hearts were on the same wavelength. And so, I met him halfway and made this \"out with the old, in with the new\" night become even warmer..."
  },
  [211411] = {
    diary_text = "Due to the success of producing a program that consistently ranked first in viewership, my production team and I were invited to give a discussion session to the students of the Cinematography Department at Loveland University, where Lucien's unexpected visit brought me great confidence during my speech."
  },
  [211421] = {
    diary_text = "As the session drew to a close, the discussion turned to the concept of \"order\" that I had introduced, and the students enthusiastically shared their thoughts. Just then, to my surprise, Lucien raised his hand and asked me a question."
  },
  [211431] = {
    diary_text = "After the event, Lucien and I walked hand in hand through the campus. To our delight, we stumbled upon many of the beautiful scenes the students had described in their responses during the session."
  },
  [211441] = {
    diary_text = "We eventually arrived at the university library, where we saw many of the novels and poetry collections we had once read together. It felt as if countless things in this world were quietly witnessing the intersection of our lives. At that moment, however, I discovered something about him that he had never told me before..."
  },
  [211511] = {
    diary_text = "在去往一个露营小村的路上，我和许墨开心地进行着成语接龙的游戏。我问许墨此次出行的原因，许墨提及了上周我们看的话剧……"
  },
  [211521] = {
    diary_text = "原来许墨之所以带我去露营小村，是为了像话剧所表达的含义一样，多为我创造生活中的美妙瞬间！可就在这时，马路上突然冲出来一道白色的影子……"
  },
  [211531] = {
    diary_text = "许墨停车查看后，发现了一只走丢的小博美。我和许墨决定帮助它等待主人，趁这段时间，许墨带我们来到了附近的一片田园风光。"
  },
  [211541] = {
    diary_text = "为了让我更好地享受这里，许墨为我搭建了一个简易的“临时露营区”。我也明白过来，原来我一直在用心记录和他发生的所有美好。"
  },
  [211611] = {
    diary_text = "On the eve of Valentine's Day, Lucien and I made plans separately so we could spend the next day together. It snowed on the way home, and he surprisingly showed up with his Evol when I was on the phone with him!"
  },
  [211621] = {
    diary_text = "The romantic snow last night put a veil on Valentine's Day, and the fireworks show was canceled due to the fog. With nothing to do, we decided to put up the bead curtains that we bought a while back. To bestow a sense of ceremony and significance upon this day again, we decided to go do something else to celebrate. Who knew Lucien had the same idea, and even took the lead!"
  },
  [211631] = {
    diary_text = "We were greeted by rain after the movie. I could only laugh as the weather decided to toy with us, but every coincidence seemed to lead us to each other. While waiting for the rain, Lucien and I witnessed something wonderful and romantic..."
  },
  [211641] = {
    diary_text = "When the rain let up a little, we quickly ran home under Lucien's clothes. To our surprise, the weather cleared up and the sun came out after we showered! A beam of light happened to shine on the curtains that we put up earlier today, creating another wonderful coincidence..."
  },
  [211711] = {
    diary_text = "午后许墨接到一个电话便匆匆出门，看他的表情我总觉得不太好。直到深夜他回来时，尽管无言，我也瞬间明白了结果。许墨与我在沙发上说了很多关于杨院长的事，最后也告诉我他拒绝了杨院长的一个邀请。"
  },
  [211721] = {
    diary_text = "许墨又回到了往日的轨迹中，而我也没有多说什么，专心在杨老的拍摄中。后来许墨带我来到了杨老的工作室，我惊讶于这栋古宅的美丽，看着那一屋子的资料与书籍也陷入了深深的敬佩之中。"
  },
  [211731] = {
    diary_text = "没想到在我再去拍摄工作室时，竟看到许墨换了一身袍衫，在池边弹奏古琴的画面。从他的口中，我听到了其中的缘由，也感受到了他的敬意与怀念。在拍摄时我忍不住采访了许墨，而许墨也给了极为真诚的回答。"
  },
  [211741] = {
    diary_text = "时间被一页页翻过，不知何时许墨已经完成了杨老交给他的工作。最后他邀请我又来到了池边，为我弹奏起古琴。那些他未说出口的话，我都明了。"
  },
  [211811] = {
    diary_text = "被雨声和闹钟叫醒的我怎么都离不开被窝的怀抱，加上许墨的推波助澜，起床的难度大大上升，难道今天就真的这么在家里呆上一天吗？"
  },
  [211821] = {
    diary_text = "午后雨停，寻找标本素材的计划也再次开启。不想四下寻找一圈，却还是没有找到适合的东西……"
  },
  [211831] = {
    diary_text = "带着满满的零食和作为收藏品“保底”的集章卡回到家，许墨居然还从储物间拿来一个带茶桌的小暖炉。窗外阴雨绵绵，家中却温暖舒适，让我一时有些昏昏欲睡……"
  },
  [211841] = {
    diary_text = "我对许墨正在看的书产生了兴趣，由此，他也向我说出这几天的标本制作于他而言的意义。心中甜蜜的同时，我突然有了别样的发现……"
  },
  [211911] = {
    diary_text = "伦敦夜晚浓雾弥漫，在和许墨汇合后我忍不住与他感慨游戏的真实感，突然听到了尖叫声。担心发生什么意外，我们赶忙跑过去，接着我感觉自己踢到了什么……"
  },
  [211921] = {
    diary_text = "竟然真的有命案发生了，甚至根据许墨的判断，那个尸体看起来好像还是被什么野兽硬生生地扯断了脑袋……我和许墨暂时因为之前的案件得以借住在221B，没过一会竟有枪声响了起来！"
  },
  [211931] = {
    diary_text = "我和许墨交流了一下对案件的讨论，感觉事情没有这么巧合和简单。第二天我们便去了巴斯爵士的庄园，见到了将要继承他遗产的侄子，并发现了一些古怪的事。之后我们通过在图书馆的调查，判定巴斯爵士的死大概率不是意外。"
  },
  [211941] = {
    diary_text = "我和许墨在回程伦敦的马车上找到了猎户运送猎犬的痕迹，而后许墨又通过福尔摩斯专著找到了巴斯爵士特定抽的烟草，没想到爵士早已给自己庞大的遗产找到了归属。"
  },
  [212011] = {
    diary_text = "为了准备竞聘，我和许墨进行模拟答辩，却在他刁钻的提问中败下阵来。我有些气馁，许墨却提出可以帮我“开小灶”划重点。"
  },
  [212021] = {
    diary_text = "我因太过担心竞聘做了噩梦，许墨提出带我去自然基地实践学习，到了我才发现那就是我们拍摄短片的湿地公园。"
  },
  [212031] = {
    diary_text = "我向许墨学习捞鱼技巧，却引来了讨鱼吃的小猫。一番笑闹之后，我意识到许墨带我出门是为了让我放松心情。"
  },
  [212041] = {
    diary_text = "竞聘当天我走上答辩席，才发现许墨竟也是考官之一。答辩结束后我找到许墨，却意外发现他藏在笔记本里的“小秘密”……"
  },
  [212111] = {
    diary_text = "在得知常去的陶艺手工坊搬迁后，我和许墨决定周末一起去新店制陶。然而我们抵达时，却发现老板因病无法到店，只留下一串钥匙给我们。"
  },
  [212121] = {
    diary_text = "我们在手工坊内做准备，客人们却接二连三地造访。我忙得晕头转向，和许墨的相处也总是被意外打断。但在被问到制陶秘笈时，我想起了和许墨的制陶时光，心情变得柔软起来。"
  },
  [212131] = {
    diary_text = "营业告一段落，总算可以制作陶杯了。我们一边拉坯，一边聊起客人们做的有趣陶器，分析他们的性格和心情，令我没想到的是，许墨竟然因为我的提问，弄坏了基本成型的陶杯！"
  },
  [212141] = {
    diary_text = "面对坏掉的陶杯，许墨向我诉说了他喜欢陶器的理由——因为能从上面读到和我一起的记忆。在满心甜蜜中，我们重新制作出一只完美的陶杯，并在上面留下了我们的心意。"
  },
  [212211] = {
    diary_text = "我独自走在辐射区里，这里早已荒败一片，但还是从中找到了许多对许墨有帮助的书籍。等折返后，我和许墨又按照无数个往日那般，开始了新一轮的实验。"
  },
  [212221] = {
    diary_text = "合作的这大半年里，实验并没有什么特别好的进展，但X区的辐射却越来越严重。\n一次进城中，我看到了许多被辐射折磨的居民。而许墨永远都会耐心地帮助他们，无论是治疗还是传授知识……"
  },
  [212231] = {
    diary_text = "时间一点点推移，许墨仍然在追逐这个世界的答案，只是不知为何在与他交流的过程中，我的心总是隐隐不安。直到一个夜晚，我无意间撞见了许墨的秘密……"
  },
  [212241] = {
    diary_text = "在彼此坦诚相待后，我好像终于明白了许墨的想法，他想要的是进化，而他会带我见证到他眼中的那个世界。"
  },
  [212311] = {
    diary_text = "At the Magnolia Cup awards ceremony, after having won the \"Best Director\" award, I came within a hair's breadth of winning \"Best Variety Show\". Because of a situation at the bioresearch center, Lucien wasn't able to watch the live broadcast of the ceremony. When he offhandedly congratulated me on winning two awards, it made me feel a little hurt."
  },
  [212321] = {
    diary_text = "As I was immersed in the production of a summer special, I felt the shadow of failure start to creep over me. Meanwhile, Lucien would still check in on me from time to time. Today, I came clean with him that most of my feelings of inadequacy came from being unable to live up to his expectations, but he was a bit perplexed."
  },
  [212331] = {
    diary_text = "After being called away to a filming location due to an unforeseen circumstance, I was busy for a whole week before my colleagues and I finally had time to take a breather. After realizing the importance of rest, I proposed having a vacation here. Just then, Lucien suddenly appeared before my eyes. After hearing him explain his attitude toward expectations, I told him that I liked his expectations, which is why I wanted to keep pace with him."
  },
  [212341] = {
    diary_text = "During our ensuing vacation time, we seemed to have a role reversal. In imitation of me, Lucien bought some summer vacation outfits to get us in vacation mode. He also tried riding a wakeboard behind a speedboat. Even though it was arduous, he did his best throughout to keep up with my pace."
  },
  [212351] = {
    diary_text = "But it wasn't until we were on the beach volleyball court and Lucien proposed we have a rest that I finally got that important answer I had long been seeking. On the beach at sunset, we strolled aimlessly. Then, he bared his heart to me."
  },
  [212411] = {
    diary_text = "That night, I woke up to find the space beside me empty. Lucien was still working alone in the study. Feeling a bit concerned, I went to check on him. Out of nowhere, he looked up and suggested we go get dessert this weekend—exactly what I had been hoping for. He read my mind."
  },
  [212421] = {
    diary_text = "Over the weekend, I pulled Lucien along to the pop-up store by Dessert Master—a show I'd been following for a while. The sudden opportunity felt like a sweet coincidence, making the entire experience feel even more magical."
  },
  [212431] = {
    diary_text = "After the meal, I started to notice something odd: the desserts seemed unusually tailored to my taste. I brought it up, but Lucien dismissed it with just a few casual remarks. As we were leaving, the staff handed me a box of macarons with a knowing smile."
  },
  [212441] = {
    diary_text = "The next day, while using Lucien's computer, I stumbled upon something unexpected: the whole date had been carefully orchestrated by him—from the invitation to the dessert selection. As he called me, I rushed out to find him. And when he explained everything, the truth behind his quiet care stirred something deep in the depths of my heart..."
  },
  [212511] = {
    diary_text = "Having been cultivating my Qi for a millennium, I was sitting in a cave meditating on how to achieve a breakthrough when a little snake with feeble Stray energy slipped into my pool. He said he had always relied on my kindness, but how could I be expected to remember all these lesser Strays—until he suddenly bit me...!"
  },
  [212521] = {
    diary_text = "I never imagined that the little green snake that bit me all those decades ago and got a backlash of Stray energy had now transformed into a full-fledged Stray. He said his name was Lucien, and he even boasted that he could help me make my breakthrough. He also dangled the well-cultivated Pure Peace Sect as an offering to me. This measly little green snake was actually quite clever and interesting."
  },
  [212531] = {
    diary_text = "After digesting this sumptuous gift, I didn't forget to leave a few morsels for Lucien too. But sure enough, this enormous amount of power was difficult for him to absorb, and his cultivation was painful. Enjoying the spectacle, I decided to transform into a white snake and roam around him, observing in detail. In that pair of captivating eyes, I seemed to see another pair brimming with desire. This Lucien would be even more delicious once fattened up a little more."
  },
  [212541] = {
    diary_text = "After Lucien managed to make his Qi breakthrough, I was quite satisfied with him. This day happened to be the seventh day of the seventh month, Double Seventh Festival. I quite enjoyed human holidays, and upon hearing that Lucien had never been to a temple fair, I invited him to come experience the mortal world with me. Ultimately, we ended up in a sealed up ancient tower. With a little bit of Stray magic from me, we spent a dazzling time together. However, much to my chagrin, I wasn't the only one with designs to eat my companion..."
  },
  [212611] = {
    diary_text = "周末我和许墨约好在他的办公室见面，我到达时他却并不在。路过的阿明告诉我，许墨正在休息室喂猫，而这只猫，疑似是罗柯的小三花。"
  },
  [212621] = {
    diary_text = "许墨向我讲述了罗柯和小三花“晴天”命运般的相遇，因为这份机缘巧合，罗柯收养了晴天。最近他又进藏了，在他休假的那天，眼前这只小猫刚好出现在了研究所。"
  },
  [212631] = {
    diary_text = "我发现这只小猫和晴天长得非常像，很难不下意识地联想到一起。研究员们也通过各种“专业测评”不断论证着这只小猫的身份。但即使大家没有得到答案，还是认真在养猫，就连许墨也被排进了喂食排班表。"
  },
  [212641] = {
    diary_text = "罗柯回来的当天是个周末，我和许墨也跟同事们一起来到研究所，等待罗柯揭晓小猫身份的答案。然而他一眼认出这不是晴天，为此受到了全体同事的激烈反驳，最终只能和宠物店打视频来证明自己。我不禁感慨，朝夕相处带来的“熟悉感”有时就是这么不讲道理，但又很值得信任——动物如此，人也一样。"
  },
  [212711] = {
    diary_text = "我们此行住在距离实验室不远的卡弗山庄农场内，民宿颇具年代感的装修风格令我误以为回到七十年代，而我也从许墨口中得知，他曾来过这里。"
  },
  [212721] = {
    diary_text = "原来劳森博士曾带着整个实验室来过这座农场，而这里的主人，一对华裔夫妇也是博士的故友。我和许墨行走在农场的苹果园，听他说起曾在这里发生的故事。"
  },
  [212731] = {
    diary_text = "从农场离开后我们抵达了劳森博士的实验室。我从许墨口中得知，博士外出演讲，现在实验室的负责人是他当年的大师兄，今天也恰好不在。在许墨娓娓道来的往事中，我们开始了这趟故地之旅，令我像是跨越时间从他青春走过，触碰那些与他有关的人生碎片。"
  },
  [212741] = {
    diary_text = "回到民宿后，我将回来路上买的一串编织手绳送给了许墨。或许是碰巧看到一颗像是苹果的玛瑙装饰，又或许只是今天的经历让我想送他些什么。我告诉许墨，我希望自己也能成为一块特别的碎片，永远留在他的记忆中。而他也告诉我，他产生了一些新的感触……"
  },
  [212811] = {
    diary_text = "今天和许墨一起去吃我们预约抢了很久抢到的一家私厨，结果我因为味觉丧失，吃什么都不香，感觉好浪费钱，也好辜负这次约会。"
  },
  [212821] = {
    diary_text = "索然无味的吃完了这顿饭，回家发现买的零食也到了，我表示看许墨吃也可以，毕竟他如果吃得香，我也会觉得开心。"
  },
  [212831] = {
    diary_text = "第二天醒来我忽然发现，我能尝出牙膏的味道了！看来自己味觉已经在逐步恢复了，我兴奋地抱着许墨分享了这个喜讯，顺便也尝了尝许墨嘴里牙膏的味道……"
  },
  [212841] = {
    diary_text = "我们一起品尝了各种甜品，许墨向我描述着不同的口感与余味，引导我去逐渐恢复对味道的感知，我忽然发现在和我的相处间，许墨对这个世界的认知越来越精妙与鲜活了。"
  },
  [212911] = {
    diary_text = "直到抵达赛场，我才发现这场比赛的规模远超预想。在无数观众和转播设备的注视中，许墨和世界冠军卡尔同台竞技，却不输分毫。"
  },
  [212921] = {
    diary_text = "许墨赢了。不过在赛后的晚宴上，他却没有很快认出和自己交战了大半日的世界冠军。而我的调侃，似乎令他回忆起了存在于遥远过往中的某个人。"
  },
  [212931] = {
    diary_text = "我提出希望许墨教我三维国际象棋，他同意了，直接将我带到了一个有些神奇的教学场地。在他循序渐进的引导中，我玩得非常过瘾。"
  },
  [212941] = {
    diary_text = "在旅途的最后一日，我和他进行了象棋比赛。在惨败了三局后，我才发现他早已在民宿的花园里为我准备好了一场泳池派对。玩闹间，我忽然意识到自己似乎从来没有赢过他……"
  },
  [213011] = {
    diary_text = "诡异的古堡中，我一边听许墨在说着某个奇怪的黑童话故事，一边逃跑。直到我们躲在一个房间内，才避开了始终追在身后的脚步声，我也有机会终于能够好好欣赏一下许墨的万圣特别妆造……"
  },
  [213021] = {
    diary_text = "我和许墨简单分析了一下这个游戏，发现这个游戏只能有一个胜者。面对许墨的态度，我表示要和他认真进行这个游戏。在进行了短暂的合作之后，我们找到了一间特殊的玩具摆放室，随着进一步的探索，我发现了一件很奇怪的事……"
  },
  [213031] = {
    diary_text = "通过缺失的小丑玩偶，我越发怀疑许墨的身份，而他暧昧的话语也让我对自己的定位产生了怀疑。在许墨“消失”后，我下意识地跑到了女王的寝室中找到了后续的童话内容，那一刻我突然意识到我的一切行为似乎都在他的掌控之中……"
  },
  [213041] = {
    diary_text = "为了验证我的想法，我决定冒冒险。毕竟这是一场游戏，而这也只是一场游戏。我走到了许墨面前，接受了他的邀请，并在共舞之中被他装上了之前被丢弃的枷锁。逃脱的女王归位，重回小丑的掌控之中，但故事还未结束。"
  },
  [213111] = {
    diary_text = "我和许墨在清晨的寒意中醒来，城堡比我们想象中得要冷多了。我笑着称呼许墨为“城堡主人”，他却提出了一个让我有些意外的安排……"
  },
  [213121] = {
    diary_text = "吃过早饭后，我们决定在庄园内度过一段时间，正是秋意浓浓时，我想为许墨制作一份花果篮，他欣然参与，和我一起走向层林尽染的秋天中…… "
  },
  [213131] = {
    diary_text = "天色渐晚，许墨提议喝点城堡中的葡萄酒取暖。走在酒窖中，相似的季节，相同的场景，令我不由回想起那年秋日的我们。于是我找到了当年的那种酒，想看许墨的反应……"
  },
  [213141] = {
    diary_text = "夜幕降临时，就连天空也降下初雪，为许墨祝福。我们行走在下着小雪的街道上，我发现许墨似乎格外偏爱这场初雪……"
  },
  [213211] = {
    diary_text = "在异国小城出差期间，我每晚都会与许墨通话。聊起工作时，我含糊带过了最近遭遇停滞的状况，只提到打算自驾出门散心，权当放松休假。然而，第二天驱车出发后，我却接到了许墨的“求助语音”。"
  },
  [213221] = {
    diary_text = "我意识到许墨已经来到了我的身边，在沙滩上循着他的提示向他奔去，出现在铁轨上的许墨如梦似幻，原来他的工作已经结束了，而他的突然出现顿时让我对原本的行程规划有了不一样的期待。"
  },
  [213231] = {
    diary_text = "我改变了去寻景散心的计划，带着许墨来到我最熟悉的小镇闲逛，向他介绍起在这里的生活细节，没想到，许墨竟在我发给他的消息中早已对此处“了如指掌”。然而，温馨的游览被一通不速的工作电话打断……"
  },
  [213241] = {
    diary_text = "许墨似乎是察觉了我心中的情绪，领着我前往了一片芦苇地——原本是我要去找的景色被他缓缓带到了我的眼前，而在那片夕色如灼的芦苇荡里，他用他的方式让我更加相信了自己……"
  },
  [213311] = {
    diary_text = "我们站在府邸前，各自握着人物卡，期待着能抽中大婚角色。当我看到自己是个想逃婚的武林千金时，忍不住叹了口气。但许墨却笑着说，或许卡片上会有我们没料到的\"惊喜\"。带着这份期待，我翻开了详细的角色设定……"
  },
  [213321] = {
    diary_text = "在府邸的偏楼里，我见到了正在读书的许墨。他让我读读\"从善如流\"的典故，暗示我扮演好这个倔强的武林千金。考虑到许墨或许有着暗线剧情，我“恪尽职守”地演绎，跑出了偏楼，而他却追了上来……"
  },
  [213331] = {
    diary_text = "午宴后，我在枫树上找到了许墨。一根红绳让我们的距离突然拉近，他教我翻花绳，指尖轻轻相触。当误会终于解开，我们才发现原来彼此都在为同样的心意而互相狼狈靠近……"
  },
  [213341] = {
    diary_text = "红烛摇曳，铃声清脆，我们携手拜了天地，执起交缠的合卺杯。从最初指尖的红线，到掌心的红翻绳，再到今日臂间的红绸——每一次的缠绕，都让我们更靠近一分。而我们之间的这根红线，早就缠在一起，再也分不开了。"
  },
  [213411] = {
    diary_text = "我和许墨打算参加海滨烟花艺术节跨年，在我做攻略时，却发现共享相册的内存不足了。我们再一次开始了相册清理工程，但是这件事情似乎比以前困难许多。"
  },
  [213421] = {
    diary_text = "为了拯救“爆满”的相册，我和许墨约定，今天每个人只能使用胶卷相机拍摄一张照片。可刚刚来到海边，看着为彼此贴上纹身贴，我便有了拍照留念的想法。"
  },
  [213431] = {
    diary_text = "在咖啡馆里休息时，我们遇到了创作烟火画的艺术家，便也好奇地尝试了一下。通过许墨的“实践教学”，绘制烟火画的过程很顺利，但认真的他让我忍不住“犯规”，偷偷用手机记录下来。"
  },
  [213441] = {
    diary_text = "夜幕降临，我们在海滩上点燃烟火画辞旧迎新。在漫天的烟火中，我们决定新的一年不再克制记录的渴望，尽情感受对彼此的在意。"
  },
  [213511] = {
    diary_text = "许墨生科所的脑胶质细胞研究获得了成功的突破，为了庆祝，我这几天悄悄策划了一场短途旅行，作为惊喜庆祝。只是在许墨回到家后没多久，就通过观察推测到了我的惊喜准备，这让我有些挫败。于是许墨提出，会在接下来进行一场“无预判实验”，好好体会惊喜的感觉。"
  },
  [213521] = {
    diary_text = "这次旅行的目的地，是参加以前合作过的璐璐姐策划的文化交流节。开车途中，许墨给我投喂了以前我称赞过的马卡龙，并说惊喜的感觉是要相互回馈的。到了目的地后，我们为了融入环境，选择了墨西哥风情的情侣套装。在等待换衣服的时候，我听到窗外传来手风琴的声音……"
  },
  [213531] = {
    diary_text = "许墨将花菱草的花环戴在我头上，并邀请我同游。到了晚上，我在市集上购买了许多各国庆祝用的小吃作为晚餐。而许墨也在我做准备的时候，找到了一个可以俯瞰园区夜景的小屋楼顶作为用餐场所。享受着美味的食物，他回忆起了一段在英国留学时的往事。"
  },
  [213541] = {
    diary_text = "第二天一早，我摸黑起床，准备带许墨去看另一个惊喜——欣赏花田日出。为了保证惊喜效果，去往花田的路上我让他闭上了眼，牵住他的手走到花田中央。伴随着第一缕天光落入大地，我邀请他与我跳一支舞。伴随着舞步，他告诉我自己找到了这场实验的“答案”。"
  },
  [213611] = {
    diary_text = "为了跟知名品牌HOPER的山谷大秀现场，连轴转了一晚上的我疲惫不已，终于在清晨时分能够稍微小睡片刻，却由于思念梦到了许墨。"
  },
  [213621] = {
    diary_text = "梦中梦到的人醒来居然就在眼前，我顿觉梦幻般不真实，许墨解释说他是作为受邀嘉宾前来看秀，就在这时，一只突兀出现的狗打断了我们的谈话。"
  },
  [213631] = {
    diary_text = "这只名叫可颂的小狗是开场秀的狗狗模特，但此刻它却闹了脾气，不肯去彩排，就在我们束手无策的时候，许墨却发现了它闹脾气的原因……"
  },
  [213641] = {
    diary_text = "我们成功将可颂带上了T台彩排，结束后可颂围着我和许墨撒欢玩耍，似乎将我们当做了最好的玩伴，原来只要被记住，被在意，就会被真心地奔赴。"
  },
  [213711] = {
    diary_text = "我今天也拒绝了玩具们的请求，关上城堡大门，没有举办舞会。因为我知道，我有比跳舞更重要的事情要做，那就是——早睡早起！可万万没想到，居然有一个玩具直接砸坏了我的大门，来到我面前。他告诉我，他的名字叫许墨，而他有话要对我说……"
  },
  [213721] = {
    diary_text = "我从许墨那里得知，我是因为他的“实验事故”，才半夜从梦中醒来，见到了“黎明”的光。越来越多的好奇涌上心中，我决定接受他的邀请，与他一起去探寻更多的未知……"
  },
  [213731] = {
    diary_text = "许墨教会了我很多东西，我们也一点点探索着玩具王国的奥秘。有一天，他告诉我，他想做一个尝试……"
  },
  [213741] = {
    diary_text = "许墨大胆地假设，要是想掌握那股让玩具们得以活动的能量，需要足够的热度。眼前是熊熊火光，离我们所想完成的实验，只有一步之遥……"
  },
  [213811] = {
    diary_text = "周五的清早，我来蹭许墨的课。直到临近上课，教室里都空无一人。而这时，我们才知道由于运动会，今天停课。"
  },
  [213821] = {
    diary_text = "看了一会儿运动会后，我被一旁的体育社团活动吸引了视线。许墨见状，带我报名参加了乒乓球社团的活动。"
  },
  [213831] = {
    diary_text = "许墨借助发球机的帮助，很快令我上手了乒乓球。而在等球桌的间隙，我们却在体育馆里发现了一块告示板……"
  },
  [213841] = {
    diary_text = "上了球桌，我们之间的比分差距始终不大。而在我问他是不是给我放了水之后，许墨又出现了一个可爱的失误……"
  },
  [250111] = {
    diary_text = "I interviewed an old teacher of Lucien's, a reclusive professor. In the course of our discussion, I found out something about Lucien's past. Professor Forrest asked me to tell Lucien that he had an old photo of his, and that he should come and collect it."
  },
  [250121] = {
    diary_text = "After the interview, as I was making ready to leave, a crew member hurried over to warn me it had started snowing heavily. Watching the snow fall outside, I am reminded of a meeting, several weeks ago."
  },
  [250131] = {
    diary_text = "Braving the wind and snow, I arrived at the place we had arranged to meet. We waited for ages, but the Northern Lights do not appear. Lucien organized a \"surprise\" to make up for the fact we didn't see the Lights... I felt very moved by his gesture. Then, without warning, the aurora miraculously appeared in the sky."
  },
  [250141] = {
    diary_text = "On our way to find a better viewing point, we decided to drop in on Professor Forrest. During our conservation, I learned that the professor's wife had already passed away... Seeing him sitting there, all alone in his empty cabin, I felt conflicting emotions. At that moment Lucien reached out and held my hand."
  },
  [250151] = {
    diary_text = "We exchanged the notes from our Fortune Cookies. Seeing his note, an odd feeling came over me... Lucien let me see the photo Professor Forrest had kept for him—a picture of a pitch-black night sky. Lucien explained that when he was younger, he had tried to predict the time and location of the Northern Lights, but his calculations had been incorrect. Seeing his disappointment, Professor Forrest took a photo of the empty sky, and told him \"The Northern Lights bestow happiness on all who witness them\". When the day came Lucien found his own happiness, he told him to come and collect the photo."
  },
  [250211] = {
    diary_text = "I came to Lucien's classroom. He joked that I must have come for work again. I had to admit it was true, although not completely. Aside from looking for good materials for the next episode, I really just wanted him to go to this place with me."
  },
  [250221] = {
    diary_text = "The Matchmaker Temple that we were about to go to was a little mysterious, all because of a love story happened a few decades ago. On our way there, we discovered that the elderly lady who taught me how to make peace knots lived at the foot of the hill where the temple was..."
  },
  [250231] = {
    diary_text = "We bought some offerings at the store by the temple. I was just about to head out when Lucien spoke..."
  },
  [250241] = {
    diary_text = "The temple had a lot of visitors. It was about an hour later that we finished visiting every room and came to the courtyard. I put the red ribbon that the temple staff gave me up on the tree, and tied mine with Lucien's."
  },
  [250251] = {
    diary_text = "I tied the red ribbon that I got from the Matchmaker Temple into a true lover's knot and wore it around my wrist. I told Lucien that I not only figured out how to tie the knot well, but also had some ideas for the next episode..."
  },
  [250311] = {
    diary_text = "I accidentally learned that the announcement of the winner of the Kravo Prize, the most prestigious award in science, had been postponed. And that due to a change in assessment criteria, Lucien, originally the most hopeful to take home that honor, now faced a strong competitor. This news cast a pall on me..."
  },
  [250321] = {
    diary_text = "Lucien turned down an interview, saying that he didn't want to spend the vacation doing anything other than being with me. I was moved."
  },
  [250331] = {
    diary_text = "While we were drinking saki together, Lucien suddenly thought of a game he had played before. I was immediately intrigued. We started playing, and I found myself lightening up. Then Lucien told me that there was another reason he wanted to play this game with me..."
  },
  [250341] = {
    diary_text = "The snow got lighter, so we decided to take a spring bath. But we found to our surprise that the spring here was a bit different from the ones we had been to: it didn't have planks to separate bathers. Lucien and I had to share the same pond. A subtle tension arose..."
  },
  [250351] = {
    diary_text = "Back in the hotel room, the first thing I saw was the other gift I prepared for Lucien—an egg-shaped cake. He said he noticed that I really cared about the whole prize thing, so he turned on his phone to check the winner list with me. I got nervous again..."
  },
  [250411] = {
    diary_text = "I got an outdoor reality show that needed to be shot in the nearby province for a few months. To make up for the time apart, Lucien and I had been seeing each other every day, being almost inseparable from each other. But the day finally came when we had to say goodbye at the station."
  },
  [250421] = {
    diary_text = "After settling in at the shooting site, I found it hard to fall asleep on a strange bed, so I began to message Lucien, who happened to also be awake. We chatted on a video call, then I slowly drifted off to sleep. This night, I first tasted the bitterness of longing, which Lucien was also feeling..."
  },
  [250431] = {
    diary_text = "After a month of filming, there were a lot of troubles at work. This day after work, I left the village feeling depressed and homesick. Before I knew it, I had already bought a ticket back to Loveland City. A heavy downpour stopped my tracks. I phoned Lucien on a video call in a shop. As we expressed our longing for each other across the screen, my mood gradually lightened as my motivation was renewed."
  },
  [250441] = {
    diary_text = "Two months into the shoot, Lucien was having a difficult time at work. I told him to give himself something to look forward to that would help him get over this difficult patch. A few days later, Lucien appeared at a shooting site, and it turned out that he was looking forward to coming to see me..."
  },
  [250451] = {
    diary_text = "The shooting finally came to an end. Lucien came to pick me up at the station. When I saw the flowers he bought, I promised to look after them with him from now on. Lucien then gave me a gift—lipstick. As he applied it to my lips, I became greedy for more \"compensation\", so marked our colors on each other..."
  },
  [250511] = {
    diary_text = "A quiet holiday begins, but little did I expect the power would go out for the entire apartment complex, just as Lucien \"prophesied\". Even worse, the water was cut too, so I had to go out to take care of my half-washed laundry."
  },
  [250521] = {
    diary_text = "In the parking lot, I ran into Pete, who was out picking up a document for Lucien. On the spur of the moment, I decided to complete the task for him. When I see Lucien, a stray remark from Pete makes me take sudden notice of Lucien."
  },
  [250531] = {
    diary_text = "The heavy rain caused a huge traffic jam, but our conversation makes the time pleasant. Lucien's question puts me in deep thought, during which Lucien charges out the car and into the rain..."
  },
  [250541] = {
    diary_text = "I both happily and anxiously bring him back to the hotel room that the academic conference arranged for him. Lucien seemed secretly happy at my anger. I quickly ran hot water and told him to shower, but apparently he \"tricked\" me..."
  },
  [250551] = {
    diary_text = "I struggled to make sense of things and suddenly realized my car key was in my laundry bag, which I'd just sent out! Lucien and I raced to the laundry room to save my key. As we sat in the room, Lucien's hint made me finally realize the answer to his question. During my epiphany, I felt like Lucien brought new chemistry into my life."
  },
  [250611] = {
    diary_text = "A prince, \"Lucien,\" was sent by the nation of Jubilee to establish peace by way of a marriage alliance. But though he presented the sealed marriage contract, I still felt like something wasn't right about him. Late at night, I went to his bed chamber, only to find that a mysterious man in black was talking with \"Lucien\". After I was absconded from the palace by the man in black, to my surprise he told me that he himself was Lucien?!"
  },
  [250621] = {
    diary_text = "Naturally, I didn't believe him, but he gave me an official document and told me to look into it myself. So for the time being, I didn't return to the palace, but stayed on in the city to see how things would develop. To avoid arousing the suspicions of the commoners that someone was going to ruin this sign of peace, Lucien seemed to have a special plan..."
  },
  [250631] = {
    diary_text = "The story of a thief that stole a princess for love spread throughout West City. While evading assassination attempts and the pursuit of elite troops, Lucien still led me all around West City in broad daylight. He also kept probing me, trying to lower my defenses."
  },
  [250641] = {
    diary_text = "During this time, there was a heavy snow in West City. Seeing how novel this was to Lucien, I took him to the desert to the west of the city to appreciate the snowy desert landscape. In the heavy snow, Lucien told me all that he desires."
  },
  [250651] = {
    diary_text = "I took Lucien back to the palace and prepared a true wedding celebration. The day before the celebration began, Lucien came to my bed chamber in his formal clothes and told me that, greedy as he was, he wanted even more from me."
  },
  [250711] = {
    diary_text = "New Year's Eve was just around the corner, and Lucien and I were busy giving our home a festive makeover. As I was trying to capture these moments, I realized my phone was out of storage. There I was, curled up in Lucien's arms, scrolling through photos to delete, when we stumbled into a conversation about \"thrills\" that seemed to leave him pensive."
  },
  [250721] = {
    diary_text = "The next day, while on my way to the port, I learned from Lucien that he had, on a whim, booked a two-day cruise and had already boarded the ship. When I joined him, I sensed he had a playful game in mind for us."
  },
  [250731] = {
    diary_text = "I found him at the bar theater, dressed in a way that took me by surprise, and he pretended as if we were strangers. My curiosity piqued, I played along and even challenged him to a game of darts. After a clever victory, we shared a dance that sent my heart racing."
  },
  [250741] = {
    diary_text = "To my surprise, the man who had been stirring my thoughts was staying right next door! I accepted his invitation to experience cryo sauna. While changing in the lounge, as part of this \"chance romantic encounter,\" he cheekily asked for my help with his straps..."
  },
  [250751] = {
    diary_text = "In an intimate moment, Lucien and I shared our feelings, and I finally understood the reason behind his carefully planned \"romantic encounter.\" Hand in hand, we ran back to our room and danced once more in the empty hall. Under the fireworks, we moved together to a tender melody."
  },
  [250811] = {
    diary_text = "It had been a month since Lucien and I last saw each other. After I finished filming, I sneaked into the hotel where his seminar was being held, hoping to surprise him."
  },
  [250821] = {
    diary_text = "Perhaps because of the long separation, Lucien was particularly clingy when we reunited. Just as he was getting back to work, he made a strange request..."
  },
  [250831] = {
    diary_text = "When the experiment started, Lucien seemed really immersed in his work. Seeing this, I playfully decided to upgrade the variables to see how he'd react."
  },
  [250841] = {
    diary_text = "Surprisingly, his self-control was stronger than I had imagined. Just as I was feeling a bit frustrated, I noticed Lucien had forgotten his work badge, and an idea struck me."
  },
  [250851] = {
    diary_text = "After several attempts to tempt him, Lucien appeared unshaken. Just then, I heard footsteps in the hallway. Annoyed, I stood up to leave, but Lucien stopped me..."
  },
  [260011] = {
    diary_text = "春节前夕，我乘坐的私人飞机遇到了意外。与此同时，许墨正在处于混乱地区的L国的某个实验室里，为了拿到实验样本而和时间赛跑。"
  },
  [260021] = {
    diary_text = "飞机迫降成功，我死里逃生，但眼前混乱又恶劣的环境像是另一个绝境。我正恐惧着许墨也许会看到我生死未卜的消息，却像是幻觉一般的，看到了许墨出现在我眼前。"
  },
  [260031] = {
    diary_text = "许墨静静地听着我劫后余生的感慨，询问了意外发生的可能原因，又格外仔细地检查了我身上的伤痕。直到我得知了他在此处的实验和BS有着联系，我对自身的紧张彻底转移到了他身上。"
  },
  [260041] = {
    diary_text = "即便许墨保证他自己不会有危险，我仍然觉得此地有着说不出的诡异。此后几天每当我独处，就会隐约有一种被囚禁的感觉……好在许墨始终在我身边，并承诺我们很快便能离开。"
  },
  [260051] = {
    diary_text = "离开的时间比我想象中还要快。但动乱意外发生，实验室陷入危机，我们撤离时直升飞机再一次被硝烟波及，降落在一艘货轮上，而这艘货轮似乎与许墨的“合作方”霍尔顿教授，有着复杂的关系……"
  },
  [260061] = {
    diary_text = "在一场有些不合时宜的年夜饭后，我和许墨进行了只属于我们两个的除夕夜。正疑惑着他话中的告别意味时，我忽然失去了意识，醒来时发现整艘船被冰封了，许墨似乎已经处理完了一切。我渐渐清晰这些日子的端倪是什么，也有些话想要告诉他……"
  },
  [290211] = {
    diary_text = "After staying in Rarewood for a while, Lucien and I came to wander around Ninth Heaven Avenue. After buying a lot of delicious food, I wanted to rest my feet at a teahouse."
  },
  [290221] = {
    diary_text = "A cup of tea was suddenly splashed out the teahouse door. Lucien quickly unfolded his paper fan to block it for me, but the fan was ruined. Although he said he didn't mind, I decided to draw him a fan."
  },
  [290231] = {
    diary_text = "In Artistry Court, I couldn't seem to draw a fan I was happy with, but fortunately, a fan maker came to help. Yet what I was unaware of was that while I was chatting with the fan maker about my thoughts behind the painting, Lucien was listening in to everything in another room..."
  },
  [290241] = {
    diary_text = "I gave Lucien the fan after I returned to Rarewood. He said the fan was cute. When he asked why I gave him the paper fan and why I drew the lively bamboo forest, I began to feel embarrassed..."
  },
  [290311] = {
    diary_text = "On the day of the first snow in Serenos, I received a jar of fine wine from the owner. I then went to Rarewood, eager to share this wine with Lucien in the snow."
  },
  [290321] = {
    diary_text = "We warmed the wine and chatted as we listened to the snowfall outside. Then I thought about a story I heard at Three Dreams Quarter..."
  },
  [290331] = {
    diary_text = "Tipsiness made me feel playful and wanted to tease Lucien, yet it was me who ended up with red ears and rosy cheeks. I quickly opened the window to cover it up, then a plum blossom drifted in..."
  },
  [290341] = {
    diary_text = "The wine had gone to my head. I tangled my fingers with Lucien's waist belt to find that plum blossom, but then he grabbed my wrist and blocked my view with his handheld fan..."
  },
  [290411] = {
    diary_text = "I took Lucien to my room to give him the puppet I made for him as a gift, but the puppet's leg accidentally broke off when I performed. Just as I was getting despondent, he comforted me and asked me why I wanted to give him a puppet."
  },
  [290421] = {
    diary_text = "I said it was because he had taken such good care of me; and in the fox spirit stories, there's always this theme of showing gratitude, so I wanted to show my gratitude to him. Lucien teased me, saying that the shows of gratitude in the stories were all performances involving \"red robes and perfumed incense\", so why didn't I just go for that directly...? I couldn't help but blush at his teasing..."
  },
  [290431] = {
    diary_text = "Lucien suggested that we repair the broken puppet together, and that it would be the best way to show him gratitude. So I promised to repair it with him. Lucien finished painting the puppet, but I couldn't shake the feeling that the painted puppet looked a bit like me..."
  },
  [290441] = {
    diary_text = "The mended puppet could finally dance along to my machinations. As the sole audience member, Lucien told me he had a new-found appreciation for puppets. Most importantly, he had a companion willing to be with him always."
  },
  [300111] = {
    diary_text = "In my hurry, I fumbled my recorder pen into the cleaning lady's cart."
  },
  [300121] = {
    diary_text = "As I dug away trying to find it, Kiro came on the scene. I didn't imagine an experienced superstar like him would still be nervous about going on stage."
  },
  [300131] = {
    diary_text = "He was so down-to-earth and friendly for such a mega-superstar. He always makes me feel warm as if in sunlight."
  },
  [300141] = {
    diary_text = "He has that natural, incredible magnetic charm to make him undoubtedly the star of any stage he got on, and no one could hope to take the spotlight away from him."
  },
  [300211] = {
    diary_text = "It's my birthday today. After working overtime, I dropped by the night market where I had so much memory of me and my father."
  },
  [300221] = {
    diary_text = "I was feeling low when I ran into Kiro incognito. When he heard it was my birthday, he cryptically said he'd like to bring me to a place to celebrate."
  },
  [300231] = {
    diary_text = "All the bakeries were closed, so Kiro used a burger for proxy cake. I was moved by how thoughtful he was. He told me to cheer up and not to frown. I believe dad would want to see that too."
  },
  [300241] = {
    diary_text = "After the \"cake\", Kiro brought me to a music instrument store and played a tune for me with a violin. But I could hear his sorrows in the otherwise upbeat melody, as if he was hiding many secrets and pain."
  },
  [300311] = {
    diary_text = "A young fan of Kiro's was hoping to hear from him before her surgery. While he didn't show up in person, he video-chatted with her and greatly buoyed the little girl's spirit."
  },
  [300321] = {
    diary_text = "Kiro promised to see the girl in person after her surgery. He treated his every fan with genuine sincerity, no wonder everyone adores him."
  },
  [300331] = {
    diary_text = "Kiro dropped in unexpectedly to make the erstwhile despondent girl smile at last. He and the children sang and drew together. It warmed my heart to see such congenial side of the superstar."
  },
  [300341] = {
    diary_text = "I helped Kiro out of the animal costume and wiped the sweat off his forehead. He must've spent a lot of time planning the surprise. He thought playing with kids really kept him grounded and made him happier."
  },
  [300411] = {
    diary_text = "It was such a pleasure to just take a walk among the cherry blossoms in spring. Despite seeing couples everywhere, each serving to remind me I'm single, it was still therapeutic and relaxing."
  },
  [300421] = {
    diary_text = "I should share this on Moments and get my friends to come enjoy the spring with me."
  },
  [300431] = {
    diary_text = "Kiro came after tracking me through my Moments posts! And dressed up as a clown! I wonder what his agent told such a directionally challenged guy... \"Go to the cotton candy stand from the fish-n-chips, turn right and go straight through the oden hotpot joint to find her\"?"
  },
  [300441] = {
    diary_text = "I was almost never ready for the way Kiro hugged me. Luckily, hugging me from behind meant he wouldn't see my face as red as a monkey's rear. I have to get used to this and not blush so easily."
  },
  [300511] = {
    diary_text = "Thought we were going on a boat date, but Kiro insisted that I go over to his place."
  },
  [300521] = {
    diary_text = "I was taken aback by the huge blue mansion, a yard full of sunflowers and his lovely pet puppy. He cryptically led me to a gorgeous lake with no one else around. It was a \"secret base\" belonging to and just for the two of us. "
  },
  [300531] = {
    diary_text = "It was dark when I woke up, no idea what prank Kiro pulled on me when I was out. He took my fake anger for real… How gullible! I didn't care about anything like getting lost in darkness or concerned agents, except being with him in the tranquility. His smile was pure magic that drew me deeper and deeper in..."
  },
  [300541] = {
    diary_text = "What wish did Kiro make? I was curious and tried to sneak a peek, but he wouldn't show me because he thought that would jinx it… Did it have anything to do with me?"
  },
  [300611] = {
    diary_text = "The clip of a cowardly Kiro reaching into a box with his eyes closed made it online, and wouldn't you know it, it became the hottest viral."
  },
  [300621] = {
    diary_text = "The comments from fans greatly amused me. Then I got a call from Kiro, wanting to prove to me he was not a scaredy cat."
  },
  [300631] = {
    diary_text = "So he brought me to a haunted house! Although he was frightened out of his wits, he still tried to \"protect\" me. I didn't have the heart to break it to him. I mean, no one could stay calm at the prospect of possibly seeing a ghost, anyway."
  },
  [300641] = {
    diary_text = "I was still spooked from the haunted house that night. Got a call but it was silent on the other end. Had a feeling it might be Kiro but I wasn't sure. He laughed after I figured out it was him, and we talked for a long time. I wondered if he was terrified alone in his house too."
  },
  [300711] = {
    diary_text = "Kiro got sick so I went over to see what I can do."
  },
  [300721] = {
    diary_text = "I didn't figure a brilliant star like him could look so miserable. I made a full-course meal that he wolfed down. I was very glad he appreciated my cooking."
  },
  [300731] = {
    diary_text = "To ensure a smooth shoot for tomorrow, I read the script with Kiro. The lovey-dovey scenes and mushy lines made me laugh out loud. He told me to close my eyes and try again with feelings. When I opened my eyes, he stuffed a grape in my mouth."
  },
  [300741] = {
    diary_text = "I tried to put as much feeling into the lines with him encouraging me on the side. He suddenly said I love you following my line, which made my heart skipped a beat! I didn't know whether he was acting or confessing until he burst out giggling, so it couldn't be serious..."
  },
  [300811] = {
    diary_text = "I was shooting a documentary for Kiro, but even the camera went out in the freezing wintry weather."
  },
  [300821] = {
    diary_text = "Seeing me shaking like a leaf, he put his coat over me before turning his attention back to the matter at hand in thin garments. It is amazing how he managed to always be at his best for the camera."
  },
  [300831] = {
    diary_text = "As we walked to the next location, I slipped but luckily Kiro was there to stop my fall. We looked up and realized we fell behind and lost the crew. He clutched my hand so I wouldn't trip again. We couldn't make anything out in the snow-covered whiteness, so we navigated through intuition and instinct."
  },
  [300841] = {
    diary_text = "We reached the peak, with a view right out of a storybook. Kiro chucked snowballs at me and I returned the favor. I lost my balance and dragged him down with me. As we laid in the snow, I thought my heart was going to burst out of my chest from looking so closely into his eyes..."
  },
  [300911] = {
    diary_text = "A competitor just slammed my work online and that distracted me from scripting the show."
  },
  [300921] = {
    diary_text = "Kiro saw I was in a bad mood and came over to console me. He told me he was taking me somewhere for air. We traveled through a vast countryside and stopped at a beautiful coast."
  },
  [300931] = {
    diary_text = "He told me about the legend of the sea. I imitated him in telling all my troubles to a seashell, then tossed it into the ocean! Together we aired all our grievances to the sea, with the wave echoing our voice."
  },
  [300941] = {
    diary_text = "Back to the studio, I thought I finally realized from Kiro's lines what he meant to do for me. Thank you, Kiro, for the encouragement."
  },
  [301011] = {
    diary_text = "Kiro wanted to take me to a mystery place. He loved to be inscrutable as much as coming up with great ideas."
  },
  [301021] = {
    diary_text = "Kiro is like the sun, always so bright and brilliant. I can't even imagine how happy I'd be leading his life."
  },
  [301031] = {
    diary_text = "What is he worrying about? Stupid Kiro, why worry about losing your superpower, and if you do, so what? The way he behaved, I could sense he was really an insecure man."
  },
  [301041] = {
    diary_text = "It would be a dream to travel the world and go to all sorts of fun places with him! Well, actually, anywhere is fine as long as I'm with him."
  },
  [301111] = {
    diary_text = "The crew complained about working all night on Firework Day's eve, so I compensated each of them with some bonus. Meanwhile, the director had Kiro's full, undivided attention. That was a big thumbs-up in my book."
  },
  [301121] = {
    diary_text = "The production went well because of Kiro's diligence and the crew working as one. Kiro stopped me from drinking too much at the post-shoot party and said he wanted to take me somewhere. Where, I wondered?"
  },
  [301131] = {
    diary_text = "I followed Kiro to an empty studio and snow started falling! I was so touched when he said the snowfall was actually a gift for me. It was also the first time he told me the meaning of his name."
  },
  [301141] = {
    diary_text = "More and more snow fell. We gleefully made a snowman. He wrapped a scarf gently around my neck as my heart raced. He took out a headband and gave it to me. His lips then fell on my forehead, warm and gentle."
  },
  [301211] = {
    diary_text = "Kiro dozed off on the tour bus, yet still mumbling about the show in his sleep. He worked really hard, the poor thing..."
  },
  [301221] = {
    diary_text = "After much searching, we finally found the spot where Kiro visited in childhood."
  },
  [301231] = {
    diary_text = "He unearthed the time capsule he buried as a child and told me the story."
  },
  [301241] = {
    diary_text = "We imagined the future as we laid amid the bushes. We made a pact to come back here in thirty years."
  },
  [301311] = {
    diary_text = "Our company has partnered with Kiro's agency to make a show about Kiro and livestream it on our platform."
  },
  [301321] = {
    diary_text = "I thought Kiro knew about the livestream, but he answered the door half-asleep and brushing his teeth. The director said not to tell Kiro so we could get a more candid side of him."
  },
  [301331] = {
    diary_text = "He sang us a song on the way to his studio, but the studio itself was a mess, apparently made by a pet cat. We had no choice but to cut the stream, but I had a clever idea."
  },
  [301341] = {
    diary_text = "His story about the guitar was amazing. Before wrapping, Kiki told me Kiro had gained another 3 million fans. Instead of losing fans, even more people learned how cute Kiro is."
  },
  [301511] = {
    diary_text = "Kiro accompanied his agent back to the Northeast for the new year every year. This year he managed to coax me into the trip as well. After a long ride, we finally hit the land of White Christmas."
  },
  [301521] = {
    diary_text = "We made it to his agent's hometown before New Year's Eve. I horsed around with Kiro who already dressed like a local. The agent's mother thought we were married. He wrote my name on a window and said it belonged to someone he loves. "
  },
  [301531] = {
    diary_text = "Having a snowball fight with Kiro was probably the worst decision of my life. His agent eventually sided with me in pelting him. It was so fun I flashbacked to my childhood, when it was oh-so happy, innocent and carefree."
  },
  [301541] = {
    diary_text = "I caught a cold from playing in snow. As I laid in the warm bed, Kiro lifted the blanket and slid in next to me. In the frigid Northeast under toasty cover, we agreed to come back and spend New Year's here every year."
  },
  [301611] = {
    diary_text = "On Kiro's birthday, I took the cake and recorder pen to his party. The atmosphere was on fire. You could tell how much everyone truly loved him."
  },
  [301621] = {
    diary_text = "Surprisingly, Kiro ditched the dinner party to go to the shore with me. Just the two of us, enjoying some peace and quiet together, content merely with each other's company."
  },
  [301631] = {
    diary_text = "When I played him the birthday song, I didn't think it'd be taken as a \"confession of love\". His shyness was so cute. Actually, the song did contain my feelings for him."
  },
  [301641] = {
    diary_text = "Kiro really liked my cake, so all my hard work wasn't in vain. As we talked, I realized that he feels lonely sometimes too. But now he'll always have his fans, and of course, me."
  },
  [301711] = {
    diary_text = "After just getting finished working overtime, I got a call from Kiro's agent Savin. His hesitant voice made me immediately worried that something had happened to Kiro."
  },
  [301721] = {
    diary_text = "It turns out, because Kiro was unhappy about the new single, he had been in the studio working on it day and night for three days in a row. When I saw him, he looked exhausted and in despair. I really felt bad for him. To get him to take a rest, I said anything I could to get through to him, and finally he relented and agreed to sleep. He gave in a little too easily though, so I was skeptical. So after the doors were closed, I squatted by the entrance. Of course, when the sound of his voice reverberated in the room again, I gave Kiro a real piece of my mind..."
  },
  [301731] = {
    diary_text = "To get me to stop being mad at him, Kiro explained to me why he was so urgently trying to make a good song. He really was an idiot. Even if he had no talent at all, I would still love him. After, I sang a song to lull Kiro to sleep, but because I was so sleepy, I fell asleep too. When I woke up, it was to Kiro looking excitedly into my eyes. He told me, he knew how the song would go."
  },
  [301741] = {
    diary_text = "I went to Kiro's concert, and he sang his newly-released single \"My Treasure\". His song spoke volumes. Kiro, I understand everything... and to me, you're also my greatest treasure."
  },
  [301811] = {
    diary_text = "Although the Kiro on TV didn't look any different from before, the light in his eyes seemed a little dimmer. In the past, whenever I was in low spirits, without even asking, he would come and cheer me up. This time, it was my turn."
  },
  [301821] = {
    diary_text = "When the spring flowers were starting to bloom, I borrowed a private flower room from the old family friend \"Uncle Gu\". I was planning to take Kiro on a VIP-level flower exhibition. Who knew that as soon as the doors opened, I would get blindsided..."
  },
  [301831] = {
    diary_text = "Guided by Kiro, we came to the rose garden. I never would've imagined that Kiro was a rose expert. I was completely rapt listening to Kiro talk about his \"Monet\" origins. As a result I was accidently caught in his \"snare\"..."
  },
  [301841] = {
    diary_text = "Kiro would not take no for an answer and insisted that I dance with him, so I had to accept. Humming the tune to the \"little bear and doll dance\" song, we danced together. He said I wasn't the little bear nor the doll. I was his \"Miss Chips\" and his sunshine."
  },
  [301911] = {
    diary_text = "Today I challenged the 10km long-distance running. It can be traced back...to the serial calls from Kiro for a morning jog by the seaside."
  },
  [301921] = {
    diary_text = "The beautiful sceneries encouraged me in the first half of the jog. But the second half started to exhaust me. Just then, Kiro reached out to me and wrote a featured Cheer Up on my palm. Upon reaching the destination, he told me that the seaside path was not the wonder he intended to show me. What on earth did he want me to see?"
  },
  [301931] = {
    diary_text = "Finally, it turned out to be a mangrove, a \"Forest in the Water\". I never knew there was mangrove in Loveland City. And he told me that the forest was a miracle of creation."
  },
  [301941] = {
    diary_text = "Kiro brought me to rest in a small street park. He sat onto the swing and told me about the story of the Forest in the Water. When I was feeling depressed as he told the story, he said that my existence was indeed a miracle for him."
  },
  [302011] = {
    diary_text = "Early in the morning, Kiro and I moved into a seaside bed 'n breakfast. It was great, and the scenery was amazing, but Kiro's secretive behavior was making me really suspicious!"
  },
  [302021] = {
    diary_text = "I looked everywhere for Kiro and finally found him in the outside shower area. He's so charming even showering! Unfortunately, the undersea walk was closed. So much for my plan..."
  },
  [302031] = {
    diary_text = "Kiro quickly helped me get over the undersea walk and we moved on to-- a DIY ship in a bottle. We finished one together, but then it got dashed on the rocks in the rising tide..."
  },
  [302041] = {
    diary_text = "With nothing this day going my way, I finally broke down crying. Kiro tried to make me feel better, even plucking the stars from the sky... In his arms, I saw a beautiful future."
  },
  [302111] = {
    diary_text = "A live streaming was to be adopted in the publicity campaign for Kiro's new movie. On the one hand, I wanted him to show the best of him to his fans; on the other hand, I couldn't restrain my selfish desire to wholly possess him."
  },
  [302121] = {
    diary_text = "Before the live streaming started, Kiro sent Savin away purposely to stayed alone with me. He said he would \"reward\" me, but insisted on telling me after the live streaming, making me confused with secret expectation."
  },
  [302131] = {
    diary_text = "The live streaming went on well. Even though it ran overtime, Kiro still devotedly interacted with the fans till the end, capturing the hearts of his fans again. After that, he told me the reward as promised. It turned out to be about the Moment which I had thought I would never receive a response."
  },
  [302141] = {
    diary_text = "Kiro's vacation finally came. As promised, I went to his home to play games with him. He guided me to complete the missions all the way, but I was entangled with the power cord at the final save point. The room went black, but he didn't seem to care."
  },
  [302211] = {
    diary_text = "For Double Seventh Festival, Studio City held a huge role-playing event in which you could experience traveling back to ancient times, and with Kiro's luck I drew the female lead!"
  },
  [302221] = {
    diary_text = "Before meeting Kiro, I was \"hurried off\" by the staff. I wasn't found out, but I was shocked to learn Kiro was the foreign prince. Then, there was an announcement..."
  },
  [302231] = {
    diary_text = "Now that I'd been recognized, how would I escape from the crowd? Then, Kiro came riding in on horseback to save me. The foreign prince grew closer, but was interrupted by a kitty."
  },
  [302241] = {
    diary_text = "An announcement gave away our location again, so we hid inside a house. On its roof we enjoyed the beautiful night scenery. Then Kiro completed the pendant and told me his request."
  },
  [302311] = {
    diary_text = "On the last day, we were told an extra set of shooting was temporarily added. I felt a little bit disappointed as I thought we could have time to stroll around before going back."
  },
  [302321] = {
    diary_text = "After the shooting, Kiro stalked off with me. Then I just knew he had prepared a surprise for me. We drove down State Route 1 toward Santa Monica to spend our time together."
  },
  [302331] = {
    diary_text = "After meeting something unexpected along the way, we finally had to walk forward. Fortunately, with Kiro right beside me, I accepted this new way of traveling with pleasure."
  },
  [302341] = {
    diary_text = "Luck turned in our favour! We received help from a kind-hearted man and changed into clean outfits. The setting sun, the cute whale...everything seemed pleasant because of him."
  },
  [302411] = {
    diary_text = "I had planned to stay home for the weekend, but Kiro paid a surprise visit. Speaking of looking for Spring, I could only think of the spring outings in primary school, but this time I had Kiro with me."
  },
  [302421] = {
    diary_text = "At the spring market, a Teddy Bear gave us a balloon, which reminded us of a shooting we did together before. Kiro suggested us exchange gifts like back then, so, our \"Project X\" began!"
  },
  [302431] = {
    diary_text = "I picked the gift and went to the designated place. To my surprise, Kiro took out a bunch of daisies like me. Not only that, I also received a vast sea of flowers."
  },
  [302441] = {
    diary_text = "I heard that daisies could deliver wishes, so I tried daisy divination and the result was exactly what I wished for! As we lay in the sea of daisies, I saw Kiro's heartfelt wishes in his eyes."
  },
  [302511] = {
    diary_text = "On the way to the office, I saw the photo of Kiro on the cover of a magazine. In the last set of photos taken before he quit acting, only this one was unexpectedly chosen as the cover."
  },
  [302521] = {
    diary_text = "As I recalled, that day, all went smoothly, but in the end, Kiro suddenly asked me a strange question. Although he looked the same as usual, there seemed to be something different."
  },
  [302531] = {
    diary_text = "After sending an SMS to Kiro, I reached the location alone and happened to see Helios whom I met once. Before I made it out why he was there, an accident happened suddenly."
  },
  [302541] = {
    diary_text = "In the unknown space, danger might come at any time, but Helios beside me gave me a familiar sense of security. Would the bird soar higher and higher after getting out of the cage?"
  },
  [302551] = {
    diary_text = "On the way to work, I saw Kiro on the cover of a magazine. This was the last photo shoot he would do before retiring from public life. I never thought the photographer would choose this shot."
  },
  [302552] = {
    diary_text = "I thought back on the shoot from that day. Everything was going smoothly, but at the end Kiro suddenly asked me a strange question. Although he looked the same as he usually did, there seemed to be something different."
  },
  [302553] = {
    diary_text = "I finished sending the text to Kiro and arrived at the site of the shoot by myself. There I unexpectedly ran into Helios, who I had only ever met once before. Before letting me ask what he was doing here, an accident suddenly occurred."
  },
  [302554] = {
    diary_text = "We were in an unknown place, and danger could befall any time, but with Helios by my side I felt a familiar sense of safety. A bird saved from a cage will fly higher than ever, and nothing will ever stop it, right?"
  },
  [302611] = {
    diary_text = "With the warm spring weather here, nobody could focus on work. I started yearning for vacation too, and just then, Kiro sent me an invitation to visit an old friend in Japan..."
  },
  [302621] = {
    diary_text = "Instead of visiting Kiro's friend right away, we went to a Shinto shrine first. He said he made an important wish here once. I was really curious what it could be. "
  },
  [302631] = {
    diary_text = "I never knew 16-year-old Kiro had been through a rough time like that. After hearing his story, we each made a wish and made a promise to come back."
  },
  [302641] = {
    diary_text = "After seeing Kiro's old friend, I gained a deeper understanding of him. No matter his past, this boy who gives me so much warmth and beauty will definitely have a sunny future."
  },
  [302711] = {
    diary_text = "As agreed, Kiro and I came to the New Light Mall first thing in the morning. Kiro told me this was his first time shopping for Christmas goodies, so I told myself I'd give him the happiest Christmas he ever had."
  },
  [302721] = {
    diary_text = "The mall always had its heating on in winter, but Kiro was too bundled up to enjoy its benefit. I dragged him to a corner to help him remove his thick scarf, only to find myself pulled into his arms."
  },
  [302731] = {
    diary_text = "Not wanting Kiro to suffer from the heat any longer than necessary, I decided to cut the shopping short--but Kiro took me to a shop in an alley where a variety of creative Christmas goodies lines the shelves."
  },
  [302741] = {
    diary_text = "After buying everything we wanted, we went back to Kiro's home and set everything up. I couldn't help looking forward to Christmas Day, but Kiro told me he couldn't spend that day with me because of his work schedule..."
  },
  [302811] = {
    diary_text = "The church clock struck twelve, and it was our appointed time. Thinking of Kiro who's waiting outside the door, my heart was pounding uncontrollably."
  },
  [302821] = {
    diary_text = "The wedding gown, church, wedding march, red carpet... Why was it like a real wedding when I was just shooting an ad for Elena's studio?"
  },
  [302831] = {
    diary_text = "At the end of the red carpet, Kiro's vow was sincere and solemn. As my heart was racing, the photographer interrupted me. But I didn't expect the shooting after this to be so difficult..."
  },
  [302841] = {
    diary_text = "The garden with flower fragrance and warm wind, the quiet and romantic \"Mariage d'Amour\" from afar, and the kiss on the ring finger along with the vow told me that it's no longer a wedding in the dream."
  },
  [302911] = {
    diary_text = "I can still recall that year when Kiro and I had a long-awaited spring vacation together. To really hit the reset button, we went camping on the outskirts of Loveland City."
  },
  [302921] = {
    diary_text = "Step one, the tent, was complete, but there was still plenty of work to be done! Just as we were preparing to start the next step, an \"uninvited guest\" appeared."
  },
  [302931] = {
    diary_text = "The corgi turned out to be a campground pet named Mango. Kiro showed me the selfie they took together, and I took a new one for them.Then, he suddenly darted off..."
  },
  [302941] = {
    diary_text = "We chased Mango into a cave. To stay calm, Kiro talked about the last time he came here camping. We finally made it out and found Mango. A bamboo grove appeared before us..."
  },
  [303011] = {
    diary_text = "I was invited to a Loveland TV party. I didn't want to go at first until Kiki mentioned that Kiro might show up there and that changed my mind."
  },
  [303021] = {
    diary_text = "In my dream, I saw Kiro singing on the stage but as I tried to get close, his figure suddenly faded away... Thankfully it was just a dream."
  },
  [303031] = {
    diary_text = "Surprisingly, I met Helios at the party and was forced to tango with him. Why is this mysterious man here and why did he approach me?"
  },
  [303041] = {
    diary_text = "Helios was like a difficult puzzle. When I couldn't help getting close to him, he walked away with ease. We were so close in distance, yet always one step away from each other."
  },
  [303111] = {
    diary_text = "This year, Kiro's birthday party was held at a large B&B. At the end of the birthday party live streaming, Kiro said a lot of heartfelt words to his fans."
  },
  [303121] = {
    diary_text = "Kiro canceled this year's birthday arrangements again and continued to stay at the B&B with me. Our alone time together was warm and beautiful."
  },
  [303131] = {
    diary_text = "After checking all birthday preparations, I went back and saw Kiro changing his clothes! I led him to the little birthday house I prepared for him, gave him the cake I baked myself and a pen recorder, then sang him his exclusive birthday song."
  },
  [303141] = {
    diary_text = "I asked Kiro to search for the only real gift from all the empty boxes and he found it at once. He opened the gift carefully, hoping that all my feelings could be conveyed to him."
  },
  [303211] = {
    diary_text = "Being an agent is harder than being a producer. When I was busy arranging his heavy and complicated schedule, he was actually making fun of me!"
  },
  [303221] = {
    diary_text = "Kiro took rehearsals very seriously and gave them his best. I was at a loss, feeling that I wasn't helping at all, but heard him telling me..."
  },
  [303231] = {
    diary_text = "In the lounge, I overheard him talking on the phone and think that it was about him saying that he was going to leave. As I tried to sound him out, he just laughed it off, leaving me feeling at sea."
  },
  [303241] = {
    diary_text = "The concert was finally about to begin, and my job as his agent would be over soon. After the concert, with mixed feelings, I passed him a bouquet but he rejected it and pushed it aside..."
  },
  [303311] = {
    diary_text = "Invited by Hitachi High School, Kiro and I came to Tokyo. In this sports-focusing institution's celebration, the sports meet was given a special touch. We were excited."
  },
  [303321] = {
    diary_text = "Walking around the school, the atmosphere of the sports meet brought me back to my younger days. Amidst countless cheers, the Scavenger Hunt, a warm-up event, kicked off the games."
  },
  [303331] = {
    diary_text = "In the culminating event, the baseball game, Kiro played as a guest fourth batter. It was the first time I knew he played baseball. Hopefully the mystical tradition would bring him luck!"
  },
  [303341] = {
    diary_text = "He led the team's victory by virtue of his excellent performance. I was deeply touched by seeing him and his teammates celebrate together. We met the mascot cat by the water fountain. I always seemed to be lucky when I was with Kiro. Even the little incident that day was a youthful romance."
  },
  [303411] = {
    diary_text = "Kiro was still busy at the film set the day before the Double Seventh Festival. He invited me to his wrap party. I accepted the invitation but felt a little disappointed..."
  },
  [303421] = {
    diary_text = "I went to the film set as promised but found the on-site decorations to be unusual. The staff asked me for the 'Admission Ticket', which I had no idea about. Just then, Kiro appeared behind me..."
  },
  [303431] = {
    diary_text = "Kiro left the tickets on the trolley! So we could only find a way to find that mysterious trolley. While chasing the trolleybus, I sensed that Kiro was hiding something from me..."
  },
  [303441] = {
    diary_text = "We finally caught up with the trolley! It turned out that the set was turned into a pedestrian street and the banquet tonight was its opening ceremony. Everyone was heading to the banquet, and on the empty trolleybus, Kiro finally told me his secret..."
  },
  [303511] = {
    diary_text = "As I was headed to the location in the email by bus, I dreamed of what I saw when Helios was injured before, as if it was a hint."
  },
  [303521] = {
    diary_text = "But unexpectedly, I really met Helios, quickly realizing that he was injured. It took me a lot of effort to make him go get himself treated, but why is he always so badly hurt?"
  },
  [303531] = {
    diary_text = "Helios and I went to the clinic he mentioned, and his injury was more serious than I imagined.He suddenly opened his eyes and looked at me when I peeped at him through the monitor."
  },
  [303541] = {
    diary_text = "Eventually, Helios still left, but he did not deny that he was Kiro. Looking at his back, my eyes were blurred with tears, but I couldn't help smiling: I knew I finally found him."
  },
  [303611] = {
    diary_text = "I finally stepped out of the train onto the small town in the mountains, but there’s still one more car ride with Kiro before we arrive at the village... this ride seems a bit... special?"
  },
  [303621] = {
    diary_text = "After a bumpy ride, Kiro and I finally arrived at our destination. The tranquil scenery seemed to have washed away all the dust on our bodies. Kiro showed me around and told me he had a mysterious surprise for me—seems like he’s always full of surprises!"
  },
  [303631] = {
    diary_text = "The \"surprise\" was upon a mountain! Kiro and I even raced up the hill, and I beat him by only two steps! Hooray! When we set up our tent halfway up the mountain, he finally told me the starlight gift he had prepared on the weeping willow at the peak... I’ve never heard something so romantic!"
  },
  [303641] = {
    diary_text = "To our disappointment, the sudden rainfall prevented us from making it to the peak. This series of setbacks had dispirited even the little sun Kiro, but he regained his smile with my encouragement. We even added to our promise with the mountain god as our witness, so it will certainly be fulfilled!"
  },
  [303711] = {
    diary_text = "I made great efforts to beat competitors and became a maid in the castle, but gradually I sensed the unusual situations here..."
  },
  [303721] = {
    diary_text = "After weeks' investigation, I finally located the underground back-room. There, I met a gorgeous lad lying in the coffin, who seemed to have a weird disease that kept him away from the sunshine."
  },
  [303731] = {
    diary_text = "I became the prince's maid, but the secrets of the castle were still concealed to me. The full-moon night was the best time for unveiling the truth."
  },
  [303741] = {
    diary_text = "When finally finding out the prince was a vampire, I gave myself away. When I fled from the high-rise tower, I thought this might be our farewell."
  },
  [303811] = {
    diary_text = "\tWhile waiting at the roadside for Kiro to join his MV shooting session for his new album, I was suddenly 'kidnapped' by him.\t"
  },
  [303821] = {
    diary_text = "\tIn the bumpy van, I dozed off in his warm embrace, later waking up to Kiro attentively reading the script... It's not a look I get to see often.\t"
  },
  [303831] = {
    diary_text = "\tThe MV was about a stream-of-consciousness story. Looking at the Kiro from '20 years later', I couldn't help wondering what kind of person he might be in the future\t"
  },
  [303841] = {
    diary_text = "We saw a rabbit in the flower field and followed it to through a 'tunnel' in the forest. Eventually, we arrived at a colorful flower sea, just like a wondrous adventure in stories. The world seemed to be extra vibrant every time we were together.\t"
  },
  [303911] = {
    diary_text = "I waited for Kiro in his house. Just as I was opening the door to wait for him outside, he happened to come back. Looking at the snowflakes on his clothes, I knew Christmas had arrived with him."
  },
  [303921] = {
    diary_text = "I gifted Kiro a blank music sheet while he gifted me the decorative star he received in the church. I was extremely flattered by this thoughtful gift, but he told me there was more to come."
  },
  [303931] = {
    diary_text = "I didn't expect Kiro to gift me a real Christmas tree! While decorating the tree, we put the decorative star on top of it. The shining tree was like a silent promise..."
  },
  [303941] = {
    diary_text = "In order not to waste this night, Kiro proposed to compose a song together. As we were finishing the song, Kiro suddenly said he didn't want to publish this song as usual..."
  },
  [304011] = {
    diary_text = "The company's show was a big hit, so we decided to celebrate. Unfortunately, Kiro was busy with his anniversary album and wouldn't be able to join in..."
  },
  [304021] = {
    diary_text = "On the day of the party, I was in low spirits until a mystery DJ took the stage! I just knew it was Kiro! He dropped in out of nowhere-- and let me drop a beat!"
  },
  [304031] = {
    diary_text = "We ran to a park nearby. The winter jasmine in full bloom were like rays of sunshine, and even more dazzling was Kiro's smile. And we ran into Cello in the flowers..."
  },
  [304041] = {
    diary_text = "Kiro wrote \"Congratulations!\" on the ground, with Cello as the \"O\". I became the first listener of Kiro's anniversary album, and he sang all the spring for me."
  },
  [304111] = {
    diary_text = "I came to Kiro's house, ready to celebrate his winning the annual award. Halfway through putting up the lights, he came back."
  },
  [304121] = {
    diary_text = "To ensure Kiro got the rest he needed, I made him lie in the bed. Just when I felt relieved, he got bored and started playing with my fingers. I had to gave him his phone back so he could make a post on social media to comfort his fans."
  },
  [304131] = {
    diary_text = "Kiro's sudden move startled me. Luckily he was okay. The prank reminded me of the gift I prepared, so I offered to give him a massage."
  },
  [304141] = {
    diary_text = "The romantic vibe in the dimly lit room left me short of breath. Kiro started to undo the ribbon he had wrapped around me, telling me he'd unwrap the \"gift\" slowly, bit by bit..."
  },
  [304211] = {
    diary_text = "I finally figured out how to solve Kiro's puzzle, but I was only half way through the whole thing. No worries, I wouldn't give up until I rescued the trapped knight!"
  },
  [304221] = {
    diary_text = "I got to see Kiro! But he still had a birthday livestream to do. I waited for him next door, feeling both excited and nervous..."
  },
  [304231] = {
    diary_text = "When the livestream was over, Kiro and I changed into matching animal pajamas to have a party of our own, but it was soon interrupted by an international video call..."
  },
  [304241] = {
    diary_text = "I couldn't believe Kiro cheated during the game! Well, I guess I could go easy on him since it was his birthday after all. Anyway, what I really cared about was whether he saw my second birthday gift for him..."
  },
  [304311] = {
    diary_text = "由于节目取景需要我带领团队到了国外，虽然知道周棋洛此时也在临近的城市制作新专辑，但为了不打乱他工作计划我还是忍住了联系他的欲望，没想到他却突然出现了。"
  },
  [304321] = {
    diary_text = "趁着我们各自难得的空闲时间，我们决定前往当地著名的主题游乐园共度一个悠闲舒适的周末。但没想到，到了约定的时间周棋洛却还迟迟没有出现……"
  },
  [304331] = {
    diary_text = "原本悠闲的度假计划，却因为记者的出现而被打破了。为了不被他们发现，我和周棋洛进行了一番伪装，在游乐园里与他们展开了一场“游击战”。没想到获得短暂胜利后，我们却不小心坐上了过山车。"
  },
  [304341] = {
    diary_text = "从过山车下来后，我已经完全没有了再去玩其他项目的精力。坐在树荫下休息时，没想到有一只小松鼠被吸引了过来。看着周棋洛和小松鼠亲昵的样子，我不由感慨原来周棋洛不仅受人欢迎，连小动物都这么喜欢他。"
  },
  [304411] = {
    diary_text = "Kiro needs to put on more muscle for a new photoshoot and invites me to join him in the gym. Stuck for an excuse, I go along with it..."
  },
  [304421] = {
    diary_text = "As we are working out, I discover Kiro is far more hardworking and dedicated to his craft than I thought."
  },
  [304431] = {
    diary_text = "At the studio, during the dessert-themed photoshoot, Kiro reveals a cool and mature side I'm not expecting."
  },
  [304441] = {
    diary_text = "After the shoot and interview are over, we share the cake that was used in the photoshoot. What other little secrets is Kiro keeping from me?"
  },
  [304511] = {
    diary_text = "I tagged along with the crew of the reality show \"Go Travel Together\" to film the early-morning knock on Kiro's door to start his trip."
  },
  [304521] = {
    diary_text = "After arriving on the island, filming officially began. I thought the arduous tasks would trip up Kiro, but he breezed through, always dazzling for the camera."
  },
  [304531] = {
    diary_text = "At a break in shooting, the host Lance proposed a game of volleyball. Kiro and I teamed up, and we beat our muscley competition with superior team chemistry."
  },
  [304541] = {
    diary_text = "In a surprise segment, Kiro and I both got singled out for some tricky challenges. But even more surprising, my answer in the game made Kiro show a rare side of himself."
  },
  [304611] = {
    diary_text = "I hopped on a car to the filming station in the northern outskirts to check on Kiro's filming progress. He called me and flirted, to the point that even the driver started suspecting that I had a relationship with this superstar."
  },
  [304621] = {
    diary_text = "Kiro was filming a shootout scene, and the atmosphere on the set was tense. The staff were moved by his gripping performance. Perfectly in character, this unfamiliar version of him was nothing like the friendly Kiro who joked with me over the phone."
  },
  [304631] = {
    diary_text = "Kiro raised his gun and cocked it under his own chin, shocking everyone. The director realized he was improvising and excitedly motioned at everyone to continue filming. After the scene was done, the crew burst into applause over Kiro's flawless performance."
  },
  [304641] = {
    diary_text = "After the filming, Kiro and I finally got to hang out. We discussed the scene shot today, and Kiro asked me what I'd do if I were in the situation and had to choose one out of us two to die. Gazing into his eyes, I said without hesitation that I wanted us both to survive."
  },
  [304711] = {
    diary_text = "When I heard that Kiro was back in Loveland City, I had mixed feelings. Father told me Kiro was making his first attempt to partner with a domestic firm, which was meant to pave the way for his official return to the home market. He said he hoped I'd take this opportunity to familiarize myself with the business."
  },
  [304721] = {
    diary_text = "I came to the supermarket where Kiro and I met for the first time, and I saw him again. Everything felt like déjà vu. Words rolled off my tongue without me thinking about them. It seemed that whenever I stood before him, I automatically reverted to my old self."
  },
  [304731] = {
    diary_text = "Leaving the supermarket, I took Kiro to the company and we completed the signing ceremony. Things went more smoothly than expected."
  },
  [304741] = {
    diary_text = "Kiro proposed that we try making a pact about the future. We exchanged our dreams, but little did I know that so far I had only seen a tiny fraction of who he really was..."
  },
  [304811] = {
    diary_text = "This Christmas, Kiro was taking part in a \"Santa Claus Special Event\". I was at home with little Ruby, who didn't seem to believe in Santa. But then he suddenly showed up!"
  },
  [304821] = {
    diary_text = "Ruby had secretly written Santa a letter, so Kiro appeared playing the part. Kiro told Ruby some stories about Santa, and then a \"gift\" arrived for her."
  },
  [304831] = {
    diary_text = "After Ruby left, I took the ticket Kiro had given me and tried to track him down. I soon found the film crew. Kiro had prepared a special present for me..."
  },
  [304841] = {
    diary_text = "Back at home, I helped Kiro with his injury, and also gave him his \"Christmas present\"..."
  },
  [304911] = {
    diary_text = "As I was worrying about work, a knock came at the door. I could just tell it was him. To my surprise, he gave me a custom-made business card, which said: Mr. Kiro - \"Joy Detective\"."
  },
  [304921] = {
    diary_text = "He was secretive the whole way out to a serene forest. After following a series of \"relaxation\" prompts that he'd meticulously prepared, I really was feeling much happier."
  },
  [304931] = {
    diary_text = "Aside from the prompts, he also took me to a little \"paradise\" where he soothed away my worries."
  },
  [304941] = {
    diary_text = "I thought today's surprises had come to an end, but he played his trump card-- a sweet shop, where I opened up about my feelings, and we celebrated with cake."
  },
  [305011] = {
    diary_text = "For this year's Fair, I didn't join my friends as usual, but sneaked into the forest with a package I'd prepared earlier."
  },
  [305021] = {
    diary_text = "Inside the palace I found Kiro deep asleep. He was pleased when I handed him the cake and story books, but what I hadn't counted on, was the saucy storyline in one of the books!"
  },
  [305031] = {
    diary_text = "I took Kiro to the Fair in the city. Previously he had only ever watched the world from above. Today he would experience all the noise and drama of the mortal world for the first time."
  },
  [305041] = {
    diary_text = "After an incident in the tavern, we left the city and headed back into the mountains. Amid a sea of flowers, Kiro made a promise—to stay with me, forever, until the end of time."
  },
  [305111] = {
    diary_text = "Kiro said he had a secret he wanted to tell me, so I set aside a whole day and let him do the planning. When I heard the secret, it knocked my socks off."
  },
  [305121] = {
    diary_text = "Kiro indeed bought a garden! I couldn't believe my ears when he told me. But this garden was a little different from what we imagined."
  },
  [305131] = {
    diary_text = "The tidying up of the greenhouse veered off into a treasure hunt. We found a lot of interesting baubles that reminded me of my teenage years. I wonder what Kiro was like as a teen."
  },
  [305141] = {
    diary_text = "On a spur of the moment, Kiro and I got into a harmonica competition. When we were done, the rain stopped. We started imagining what we would do to this place. Then he gave me a flower, the first one in this garden, and invited me to dance with him. I accepted the invitation and we danced away."
  },
  [305211] = {
    diary_text = "When I was wondering if I needed to give the notice to cancel the show, Kiro entered the room—what was he doing here instead of resting at home?"
  },
  [305221] = {
    diary_text = "Kiro assured me he would not push himself, which put my heart at ease a little. But then when he was getting changed at the intermission, I found that he was having a fever again..."
  },
  [305231] = {
    diary_text = "There wasn't much time left before Kiro had to get back on stage again. He hid his ill look with perfect makeup, but it didn't stop me from worrying about him. He gave me a hug before he returned to the stage, which made my heart more settled..."
  },
  [305241] = {
    diary_text = "After escaping from the models and the press, we finally had the time to breathe. I wanted Kiro to rest well from now and take a long holiday, then he suddenly started talking about his holiday plan excitedly..."
  },
  [305311] = {
    diary_text = "Once upon a time, there’s a long hair prince named Kiro, who was locked up in a tower by a witch. I came to the prince’s rescue on the king’s order, but the prince didn’t believe me."
  },
  [305321] = {
    diary_text = "The prince refused to leave with me. We introduced ourselves. He showed me the bookcase in the tower, and promised to give me a beautiful swing, so I gave him my liqueur in return."
  },
  [305331] = {
    diary_text = "After a few drinks, Kiro kept his promise by making a swing appear with the magic in his blonde long hair. We fell asleep while hugging each other. But then, the witch appeared out of the blue. When I was on the verge of death, Kiro retaliated and attacked the witch with his magic."
  },
  [305341] = {
    diary_text = "It turned out that Kiro learned magic since young. The reason why he refused to leave was because he wanted to give up his power to bewitch people. I wanted to prove to him that many people have genuine love for him in this world..."
  },
  [305411] = {
    diary_text = "Because of an urgent assignment, Kiro and I had to spend this beautiful weekend working at home. Fortunately, being in each other's company made the otherwise tedious work easy and somewhat pleasant."
  },
  [305421] = {
    diary_text = "But then came a point where my inspiration ran dry, which was made worse by the tight deadline. Kiro was not doing so well either, stuck in a creative rut. Just as things seemed hopeless, Kiro hit on something..."
  },
  [305431] = {
    diary_text = "Now inside the \"mental box\" Kiro built for us, I felt more empowered to face up to the unpleasant. And my mood was improved by the companionship of a cute cat, and more importantly, Kiro, who started drinking hot chocolate with me."
  },
  [305441] = {
    diary_text = "By the time I finished the first draft of the proposal, Kiro finally made progress with his new song. I listened to the demo and heard something different from his previous works. I felt confident that I would hear—and see—a more versatile Kiro in the future."
  },
  [305511] = {
    diary_text = "We strolled all day, and, without our realising it, it was already dusk. When I suggested that we go back to the hotel, Kiro said he'd like to take me to one last place. Little did we know, we went the wrong way and happened up a pile of iron pipes."
  },
  [305521] = {
    diary_text = "Instead of turning back around, we decided to try to get over the pipes. To our surprise, we found an arcade not yet officially open. The owner, seeing that Kiro is an aficionado, happily let us try all the games for free."
  },
  [305531] = {
    diary_text = "The arcade happened to have a teddy bear gacha machine, but after 5 or 6 tries, Kiro fails to get the red bear he wanted. I decided to give the final pull and managed to get it. As I pretended to mull over whether I'll give it to him or not, Kiro proposed a competition!"
  },
  [305541] = {
    diary_text = "I let Kiro pull me into his \"scam\" as we decided to play a music game from his childhood for winner-take-all. Little did I expect, Kiro helped me without realizing it, and I ended up getting the higher score. Kiro admitted defeat, but what I demanded for winning is..."
  },
  [305611] = {
    diary_text = "On this rare weekend on a sunny day, Kiro and I decided to go out for some exercise after finishing work early."
  },
  [305621] = {
    diary_text = "The sunshine was perfect for us jogging through the streets. During a break, Kiro grabbed me and trotted in the other direction. We soon reached our destination. I was amused as I looked at what was in front of me—it turned out we arrived at this internet-famous dessert street he had always wanted to visit."
  },
  [305631] = {
    diary_text = "With so many food shops before us, we were eager to start, but then we were disrupted by an unexpected guest—A TV host wanted to interview us. I looked at him warily and was about to refuse when the TV host seemed to recognize Kiro, which quickly made Kiro the center of attention..."
  },
  [305641] = {
    diary_text = "Kiro and I went home again. After some discussion, we decided to play a game called \"Heartbeat\". Although we both played it for the first time, Kiro gradually got ahead of me. Seeing me feeling demoralized, Kiro took the initiative to be my personal coach..."
  },
  [305711] = {
    diary_text = "Kiro and I attended Mme. Seidel's benefit solo concert, the proceeds of which were to be donated to help autistic children. However, as we were expecting the performance, an odd autistic child caught the attention of the audience."
  },
  [305721] = {
    diary_text = "Kiro tried to soothe the boy, and he gradually calmed down. The crisis is over, and the concert began. After that, Kiro took me to meet with Mme. Seidel and she inadvertently revealed Kiro's another plan for me..."
  },
  [305731] = {
    diary_text = "I asked Kiro about his plan, but he said it was just something fun to do in this sunny day. He rented a bike and rode me to a square, where there was an old accordionist and a young girl singing beside him. We walked along a flower wall and on the other side of it I was surprised to find a flowered boat on the river."
  },
  [305741] = {
    diary_text = "We got into the boat, which was the other surprise he had prepared for me. I leaned on his shoulder and suddenly remembered..."
  },
  [305811] = {
    diary_text = "I produced a \"cloud tourism\" variety show that became popular in the locality. As a result, the local TV station invited me to go on a tour, during which I would be interviewed on camera. When Kiro got to know this, he made a video call to teach me how to act."
  },
  [305821] = {
    diary_text = "Since I behaved unnaturally in front of the camera, I followed the \"relaxing tips\" offered by Kiro to adjust myself in front of the window. But when I opened my eyes again, I saw Kiro behind the glass window."
  },
  [305831] = {
    diary_text = "In the subsequent filming, Kiro secretly removed all the \"obstacles\" for me. With him by my side, I somehow managed to get into the swing of things."
  },
  [305841] = {
    diary_text = "Kiro disappeared half an hour before the end of the filming. I rushed to the train station, just to find he hadn't left yet due to the delayed train. We sat on a bench, recounting the past day..."
  },
  [305911] = {
    diary_text = "We agreed to meet up at my house that evening to go to a street dance event, but to my surprise, Kiro showed up that morning, and discovered I'd been practicing a wrestling game."
  },
  [305921] = {
    diary_text = "To have more fun gaming with Kiro, I'd been secretly practicing, and it was actually working! Maybe it was my training, or my insane desire to win, but I actually defeated Kiro!"
  },
  [305931] = {
    diary_text = "After dark, we arrived at the event venue where a few young guys were eyeing us. I thought Kiro's identity would get exposed, but they actually challenged Kiro to a dance-off!"
  },
  [305941] = {
    diary_text = "Soon, the two started dancing one after the other. Kiro shocked everyone when he took the floor, and to my surprise, the \"zen\" Kiro I gamed with earlier was now determined to win."
  },
  [306011] = {
    diary_text = "It was Kiro's birthday. This year, he was invited by his high school in California to perform on a special occasion."
  },
  [306021] = {
    diary_text = "After the performance, I gave my best wishes to Kiro and told him I wanted to let him do what he wanted to do for his birthday this year. He was a little surprised but accepted my suggestion, but the first thing he wanted to do was... \"skipping class\"?"
  },
  [306031] = {
    diary_text = "I followed Kiro and did what he always wanted to do back then. He finally took me to a small bay, where a boat was docked..."
  },
  [306041] = {
    diary_text = "Kiro shared that somewhat lonely song with me on the beach, and it was a gift that I had prepared in advance. I pulled him back together to the observation deck where he was competing that year. The duet melody was drifted softly under the stars. Dear Kiro, happy birthday."
  },
  [306111] = {
    diary_text = "At the market, I rescued a blonde young man named Kiro and discovered that we shared an enemy—the domineering tycoon, the Gold Spice Master. To achieve our shared goal, we decided to partner as a pair of wandering entertainers."
  },
  [306121] = {
    diary_text = "To my surprise, Kiro had an incredible voice! As a pair of exceptional entertainers, we soon were invited to the Gold Spice Master's residence. Not long after we arrived, Kiro was summoned away. I was worried about him, so I followed along and unexpectedly discovered another side of Kiro..."
  },
  [306131] = {
    diary_text = "The houseboys wanted to seize me and Kiro! In a hurry, we ended up hiding in the Gold Spice Master's vault. After the danger had passed, we were about to leave when we found something unusual about a tile—it turned out that there was a secret underground chamber!"
  },
  [306141] = {
    diary_text = "We finally found the evidence of the Gold Spice Master's crime in the chamber, but then the Gold Spice Master caught us. In the face of danger, I blocked an arrow for Kiro, hoping he could uncover the evil in the dark..."
  },
  [306211] = {
    diary_text = "Kiro's making an appearance to generate buzz for a new show. To spice things up a bit, we threw in a cooking competition segment. So I decided to go talk the matter over with Kiro."
  },
  [306221] = {
    diary_text = "When I got to Kiro's house, I found that he was secretly practicing. With my help, he seemed to gain some confidence in his cooking skills."
  },
  [306231] = {
    diary_text = "On the day of the shoot, I found Kiro in the break room. I asked him what he was planning to make, but he said it was a secret, and he'd have a surprise for me soon..."
  },
  [306241] = {
    diary_text = "Kiro did indeed surprise me, and the food he made won the award for \"most popular\". He told me I deserved part of the credit too..."
  },
  [306311] = {
    diary_text = "To add some special elements to the new song Kiro was writing recently, we came to a remote village to record some sounds. But on our way, we ran into the big boss and bully of the village—a goose, blocking our way and flapping its wings arrogantly..."
  },
  [306321] = {
    diary_text = "Surprisingly, the big bully eventually succumbed to the gentle stroke, which Kiro claimed no one could resist. To prove this, he lowered his head to give us a sincere invitation."
  },
  [306331] = {
    diary_text = "Our sound recording trip officially began. Kiro had even brought the porcelain doll with him, which the song was about. He believed if the song was about the doll finding its lost \"pieces\", then it had to be present."
  },
  [306341] = {
    diary_text = "On the way back, we found a pond in the backyard, which we walked in to cool down from the heat. As we chatted away, an inspiration suddenly came to Kiro—that we could adorn ourselves with the beauty around us to make us who we were and create a better version of ourselves."
  },
  [306411] = {
    diary_text = "Kiro was injured when filming, so Savin told him to stay in the hotel for a couple of days. I sat on the bed with Kiro looking through video clips of his shooting. Kiro said he didn't get to experience it properly when filming, but he really wanted to go in a hot-air balloon again, so I came up with an idea..."
  },
  [306421] = {
    diary_text = "My \"Escape Operation Plan\" with Kiro was successful. When I was relieved, Kiro said the best part was yet to come."
  },
  [306431] = {
    diary_text = "Kiro and I finally went in a hot-air balloon. The hot-air balloon rose slowly, but we couldn't see the scenery we wanted to see because of the morning mist. I was slightly disappointed, then the balloon suddenly shook and I accidentally bumped Kiro's wound..."
  },
  [306441] = {
    diary_text = "As the mist dispersed and the sun rose, we were surprised to see the sunrise. Kiro suggested that we could shout out our wishes and feelings to the sky like in the movies."
  },
  [306511] = {
    diary_text = "At the new gods weekly assembly, the dual-god of day and night, Kiro, proposes spending a day with me in the name of comparing notes on work experience. I feel confused by this because after all, a week ago I was just turned down by him..."
  },
  [306521] = {
    diary_text = "Kiro drives the chariot of the sun and takes me to scatter the sunshine. Then in the valley of the elves, we cheer on an elf deer. I suddenly realize that he's still that dazzling Kiro from my memory."
  },
  [306531] = {
    diary_text = "He takes me to a traditional elven festival -- Sunshine Day. He also, strangely, gives me a love-pledge ornament and dances a dance of togetherness with me. When I sense some chaos, a devil beast disrupts the scene. As I try to chase down the devil beast, I accidentally uncover Kiro's secret."
  },
  [306541] = {
    diary_text = "A secret scroll finally reveals to me the whole truth. It turns out the real reason Kiro turned me down was to keep me away from the curse of darkness. Wracked by regret and guilt, I take him to plant a star, and we make a wish -- to be together our whole lives."
  },
  [306611] = {
    diary_text = "Kiro and I arrived at the last stop and happened to see an exhibition held by some art university students. After asking what the behavioral experiment was, we decided to participate."
  },
  [306621] = {
    diary_text = "Due to the rules of the game, Kiro and I didn't know which locations the other had chosen, nor did we know when the other would go to these places. The journey for two suddenly became a one-person journey."
  },
  [306631] = {
    diary_text = "After the City Park, I followed the route I had planned to my next destination—the temple. Kiro called and said that he happened to be at the temple and had left me a little surprise."
  },
  [306641] = {
    diary_text = "Kiro thought that maybe the goal of this experiment wasn't for us to meet at the destination, but it was for us to see different sights when we were apart. That was because a couple didn't have to be physically together all the time to be \"together\"."
  },
  [306711] = {
    diary_text = "One weekend morning, because of a cute nightmare Kiro had, we decide to shoot a vlog as we're having a spat."
  },
  [306721] = {
    diary_text = "We decide to film a vlog about how we dress, so we choose some accessories for each other. Kiro's professionalism in this process leaves me speechless."
  },
  [306731] = {
    diary_text = "Our second vlog topic is food. While making jam, Kiro butters me up. My lips get stained, leading to a frantic toothbrushing experience..."
  },
  [306741] = {
    diary_text = "Kiro edited the vlog the same day and used his hacker skills to upload it. While watching, we both realize we focus on the other's actions in life."
  },
  [306811] = {
    diary_text = "When I woke up in a thatched hut, I found that I had been kidnapped. Just when I was planning to escape myself, Helios came to my rescue...!"
  },
  [306821] = {
    diary_text = "I dreamed about the first time I met Helios. He picked up my precious photo which was where our story began. When I woke up, Helios had been watching over me and had even prepared food for me. But then, to my surprise, he suddenly asked if I wanted to leave him..."
  },
  [306831] = {
    diary_text = "His question sent me into deep thoughts. I went to his room with my bags late at night and asked if I could learn some self-defense techniques from him..."
  },
  [306841] = {
    diary_text = "The 7th of July was here. Some foreigners came to the tavern, offering a big trade to Helios. After it had been dealt with, Helios finally explained everything to me. He had been shouldering a huge secret on his own. In the end, he pulled me toward the temple and asked me to pray for love with his real name."
  },
  [306911] = {
    diary_text = "Kiro and I planned to create a song for Cello and Apple Box. I arrived early, hoping to surprise him, but the distinctive cries from Apple Box gave me away. Kiro found me and promptly led me to his \"studio\"."
  },
  [306921] = {
    diary_text = "During the recording, Kiro accidentally played the wrong audio cue, sending Cello into a panicked dash around the room. Our usual techniques to calm the him proved ineffective. Just when we were at our wits' end, Kiro managed to soothe Cello with a cool new trick."
  },
  [306931] = {
    diary_text = "Seeing my piqued interest, Kiro offered to teach me his new trick. However, throughout the process, it felt as if he was trying to playfully tease me and make me blush..."
  },
  [306941] = {
    diary_text = "As our lesson concluded, Kiro candidly shared his thoughts with me. It was then that I realized the importance of always making a sincere effort to express my feelings, no matter how long I've known someone..."
  },
  [307011] = {
    diary_text = "Having been invited by Tony's film crew, I arrived at the set for Star Explorer. I was surprised to see Kiro here, to which he responded by saying that he was the surprise for me and that he was about to take me to the second surprise..."
  },
  [307021] = {
    diary_text = "The brand-new imaging amplifier combined with EVOL made the whole scene incredibly lifelike! It was as if Kiro was really fighting a monster! Just as I was about to inquire further, a commotion came in from somewhere on the set..."
  },
  [307031] = {
    diary_text = "While being the Star Explorer beloved by everyone on the set, Tony didn't get along quite well with his peers off the set. Seeing the director's refusal and the parents' quarrels, Kiro and I couldn't help but feel a sense of injustice. Just at this moment, the amplifier suddenly went haywire!"
  },
  [307041] = {
    diary_text = "In the pinch of the moment, Kiro saved me, just as Tony saved his friends. As the machine ground to a halt, everyone breathed a sigh of relief. Deep down inside, I firmly believe Tony's passion will be reignited again."
  },
  [307111] = {
    diary_text = "I was looking for a way to make my wings white in the forbidden library, but then ran into Light Angel, Kiro, who told me that he was there to arrest me..."
  },
  [307121] = {
    diary_text = "I told Kiro that I had fallen. He was surprised and told me the reasons that would make angels fall. We went through them one by one, only to find that none of them matched my circumstances."
  },
  [307131] = {
    diary_text = "We walked on the grass of the forbidden place and found the honey fruits that we once loved. We sat on the tree and ate the honey fruits like we did when we were kids, but I felt that something had changed between us..."
  },
  [307141] = {
    diary_text = "Master found out that I had fallen. The regular meeting of angels was held in the temple as usual. As the corrupted angel, my soul entered the sacred vessel waiting to be purified. However, just as my every memory with Kiro were gradually being erased, a familiar voice rang out in my head..."
  },
  [307211] = {
    diary_text = "Having just returned from abroad, Kiro picked me up for dinner, and our conversation in the car made me realize that my life had been very dull. At this moment, Kiro gave me a little surprise with \"magic\"."
  },
  [307221] = {
    diary_text = "During dinner, I decided to add excitement to my tedious life. I decided to take Kiro's suggestion and learn guitar, and Kiro said he would find me a guitar teacher."
  },
  [307231] = {
    diary_text = "The next day, I arrived at the class venue chosen by my guitar teacher—Flower Park, and saw Kiro as expected. He called himself \"Mr. Flower\" and gave me an interview."
  },
  [307241] = {
    diary_text = "Kiro taught me how to \"say hello\" to the guitar in an innocent and fun way. I successfully finished my first guitar lesson under his guidance. To express my gratitude, I said many heartfelt words from the bottom of my heart, to which he responded in a special way."
  },
  [307311] = {
    diary_text = "I wanted to give Kiro a surprise since he'd pulled an all-nighter working, so I arrived at Studio City to pick him up from work early in the morning. However, I heard him discussing with Savin that there was a problem with the publicity livestream they had planned for Kiro's new show..."
  },
  [307321] = {
    diary_text = "After hearing the whole story from Kiro, I began to help him think of solutions. The fact that he was able to depend on me gave me a sense of accomplishment. Kiro said I was his \"family\"."
  },
  [307331] = {
    diary_text = "Through our combined efforts, the livestream proceeded as usual. Kiro also didn't fail to deliver. Although he let his exhaustion show around me, when in front of the lens, he was positively beaming!"
  },
  [307341] = {
    diary_text = "When the livestream ended, we headed for home. I received a bag of bear cookies that he'd made himself. They may not have looked very refined, but I could see that Kiro had put his heart into them—and they were just like Kiro's everyday self, a side of him that he would only show to me. I made a promise to Kiro that from now on, I would be that \"family\" that he could share all his joys and troubles with."
  },
  [307411] = {
    diary_text = "In response to plummeting temperatures, Kiro and I chose a heart-and-belly-warming chicken stock hotpot place to begin our hotpot spree."
  },
  [307421] = {
    diary_text = "On the first snow of winter, Kiro and I were preparing our hotpot reviews and brought up lots of happy memories in the process. We decided to give an objective final score after the final hotpot restaurant!"
  },
  [307431] = {
    diary_text = "For our final stop, we went to a Sichuan hotpot place with excellent service, and Kiro's special sauce to boot. But he was so busy cooking food that he didn't have time to eat. And so, I held up a meatball to his lips..."
  },
  [307441] = {
    diary_text = "Halfway through dinner, the owner taught us how to make authentic dipping sauce. It was then I realized something different about Kiro. He seemed to really care about this sauce..."
  },
  [307511] = {
    diary_text = "On a cold winter day, as I was scrolling on my phone lying in bed, Kiro suddenly showed up. It was a rare sunny day, so he dragged me out to enjoy the sunshine with him."
  },
  [307521] = {
    diary_text = "While walking around the street, we came across a colorful tents market, where we found many New Year snacks from our childhood. We ended up at a lollipop tent and decided to learn to make our own lollipops."
  },
  [307531] = {
    diary_text = "Lollipops with crystal fillings were difficult to make. We tried many times and the products were not satisfying, but we indeed made some progress. Finally, a perfect lollipop was made! However, when Kiro held it up, it was his smiling eyes that got my full attention..."
  },
  [307541] = {
    diary_text = "It was dark when we left the market. I was a little sad that today's sun-filled journey was at an end. Kiro told me mysteriously that if I wanted the sun to stay longer, he could grant me my wish. The next second, as if by magic, the whole street was lit up with soft \"sunlight\", which turned out to be..."
  },
  [307611] = {
    diary_text = "Kiro wrote a song for us, called—\"Marry me on Valentine's Day\", for which we wanted to film a music video. Dressed in our wedding outfits, we sang this song on the stage by the sea."
  },
  [307621] = {
    diary_text = "Before we set off, we gave away our \"candy invitations\" to many strangers, hoping many could take part in our happy day."
  },
  [307631] = {
    diary_text = "I felt my heartstrings tug when I watched Kiro on the stage. Then the people who received the \"invitations\" gradually arrived. They tossed the flowers in their hands to Kiro to give us their blessings. Kiro then made them into a bouquet and gave it to me."
  },
  [307641] = {
    diary_text = "After the \"wedding\" was over, we sat on the swings etched with \"Happiness\". There he confided in me the reason behind filming this music video, then we exchanged rings with our fondest love."
  },
  [307711] = {
    diary_text = "Kiro had held a \"Wish Collection\" event, and one of the wishes he drew was a special one: to celebrate Nina's upcoming fourth birthday. But the request came with some mysterious details. To be safe, Kiro asked me to join him."
  },
  [307721] = {
    diary_text = "We were in for a surprise, though—Nina wasn't a child, but a goofy, adorable Corgi dog! Despite the surprise, and even though there were some hiccups with the special doggy cake, Nina quickly stole Kiro's heart. Amid laughter and fun, we celebrated Nina's birthday together."
  },
  [307731] = {
    diary_text = "Nina's owner went to pick up the cake from the pet shop, leaving us to look after Nina. What we didn't expect was that Nina wasn't just cute—she was well-trained, and very clingy, practically claiming Kiro as her own. Watching her antics, I felt a sudden urge to see who would win Kiro's heart."
  },
  [307741] = {
    diary_text = "In the ensuing showdown, I won by a slight edge, and that edge was simply Kiro's bias toward me. As I watched him covered in Nina's fur, I couldn't help but wonder if Apple Box would get jealous when it smelled Nina's scent once we got back. When I brought it up, Kiro just shrugged and said he had a plan..."
  },
  [307811] = {
    diary_text = "Kiro had been asked to write a new song but a few lines needed more work. I took him outside while there was still light to help him find inspiration. He played something impromptu and the onlookers all applauded."
  },
  [307821] = {
    diary_text = "We found a cafe called Luck Exchange. The owner said that if there was anything we liked, we could exchange it for something of our own."
  },
  [307831] = {
    diary_text = "We found a bear hand puppet. There was a story about giving behind it, which fits perfectly with the theme of Kiro's new song. Seeing it brought him new inspiration, and giving this stroke of fated luck, I traded my recorder pen for it."
  },
  [307841] = {
    diary_text = "Kiro told me I was his muse and I couldn't have been happier. He snuck away to get something important after the performance the day after..."
  },
  [307911] = {
    diary_text = "Kiro's concert is about to begin. I dressed up in a bear suit and was planning to head to his rest area to cheer him on but ran into him in the corridor leading up to it..."
  },
  [307921] = {
    diary_text = "Kiro returned to the rest area after the concert and told me that he was all mine for the time being. I led him to the birthday venue I had prepared—the stage. Naturally, it was different from the concert. It was as if we were standing on a field beneath a sea of stars."
  },
  [307931] = {
    diary_text = "The present had honestly been at the stage all along, but one had to be high up to see it. As we sat atop the tree, I pressed a button in secret to start the real surprise—a mysterious treasure hunt."
  },
  [307941] = {
    diary_text = "We went to France, California and Loveland City where we saw Kiro during different stages of his life. A faint light came toward us in the dark and I pretended to take hold of it. I told him that the star in my hand was the embodiment of his efforts. He said if that was the case, then I should see his heart too..."
  },
  [308011] = {
    diary_text = "Kiro had been working around the clock for days to organize the debut concert for young singers, so I asked him to help put up posters so that he could take a break. The image on the poster caught my attention, which Kiro told me was a starling."
  },
  [308021] = {
    diary_text = "We came across a few fans who worried their idol wouldn't be able to see the cardboard they put up on the street, but Kiro reassured them that they would. When we went back to the venue, the sight of everyone working hard for the concert made me seem to understand why Kiro was so certain."
  },
  [308031] = {
    diary_text = "Right before the concert was about to start, many reporters arrived on the scene. One of them questioned why Kiro took the trouble to organize the concert and whether he had cut a deal with my company. Just as I was about to deny these accusations, Kiro came to my rescue and declared me as his spokesperson."
  },
  [308041] = {
    diary_text = "After the concert began, Kiro and I watched contentedly from backstage. When the song started, Kiro hugged me and told me what the starling on the poster meant—each starling stood for one melody."
  },
  [308111] = {
    diary_text = "After not seeing each other for a few weeks, Kiro came to pick me up at work and planned a spontaneous trip."
  },
  [308121] = {
    diary_text = "On the plane, Kiro \"lured\" me into telling him about the troubles I faced at work. We then agreed not to talk about work anymore, but I accidentally did it again, which prompted Kiro to blurt out his true thoughts."
  },
  [308131] = {
    diary_text = "As soon as we arrived at the hotel, we tried out the steam room. Kiro was unusually acting like a diva and asked me to wipe his sweat for him. It made my heart race, then I realized Kiro was messing around with me."
  },
  [308141] = {
    diary_text = "When we were enjoying a rest in the hotel room, Kiro suddenly leaned in to \"bother\" me and confessed that he wanted me to be the only person in my eyes."
  },
  [308211] = {
    diary_text = "Lately Kiro has been shooting a show called \"Furball Cafe\". With a day off coming up, I made a surprise visit to the set, not expecting he and I would get sent on a mission..."
  },
  [308221] = {
    diary_text = "Life after Evolification has been a lot busier than normal, and Kiro barely has any blank spaces in his schedule. Seeing how tired he looked, I felt bad for him. Maybe he should just use the day off to sleep?"
  },
  [308231] = {
    diary_text = "With all my film experience, I thought we'd finish the job handily, but at the start we got held up by some naughty bears. Just then, I had an idea..."
  },
  [308241] = {
    diary_text = "I didn't expect this dessert feast for a picky foodie director was Kiro's date surprise for me. With these desserts and my little bear, my heart was filled with sweetness."
  },
  [308311] = {
    diary_text = "It's like there's no game Kiro isn't good at! As we played games and watched cartoons during our long break, Kiro suddenly received a phone call from France..."
  },
  [308321] = {
    diary_text = "Surprised, I never thought I would get a chance to visit where Kiro grew up. But now I have! However, it's just... I didn't expect him to have lived somewhere so decrepit."
  },
  [308331] = {
    diary_text = "Listening to Kiro's past, I could feel my heart melt away. I tightened my hand around his. It was suddenly as if I could see a young Kiro standing right before me in the gloam..."
  },
  [308341] = {
    diary_text = "Surprisingly, we encountered one of Key's staunch fans in this unlikely place. It soon became apparent that Key has many loyal followers, no matter where. What message did the last Key leave behind for Kiro in this place? Together, we embarked on a quest to find out..."
  },
  [308411] = {
    diary_text = "As Kiro and I drank and danced together in a crowded and gloomy bar while talking about the DJ, a figure approached me on the dance floor and extended an invitation."
  },
  [308421] = {
    diary_text = "Thanks to Kiro's dramatic performance and the sudden roaring of the music, we managed to sneak outside of the bar. We laughed heartily on the empty street as a flash of brilliance suddenly washed into Kiro's head."
  },
  [308431] = {
    diary_text = "As the Wild Music Festival began, I looked forward to the surprise that Kiro had in store for me. As he made his appearance, the atmosphere suddenly became electric."
  },
  [308441] = {
    diary_text = "Kiro and I wandered around in the open field. Our hearts raced as I presented Kiro with a special gift. We began to sprint after Kiro caused a small stir. Suddenly, a familiar song drifted in from afar..."
  },
  [308511] = {
    diary_text = "我与动物救助机构合作了一期有关救助流浪动物的公益综艺。来到救助站的那一瞬间，我和周棋洛就被这个充满毛茸茸的小“世界”深深吸引了……"
  },
  [308521] = {
    diary_text = "在温馨而又“猫飞狗跳”的氛围中，节目有条不紊地进行着。而在节目之外的时间，“小猫英雄”周棋洛也负责地照顾着小家伙们。"
  },
  [308531] = {
    diary_text = "我和周棋洛励志要将小猫咪们养育成健康可爱的宝宝们，但有一只虎斑纹毛色偏杂的小猫一直有点“高冷”……"
  },
  [308541] = {
    diary_text = "这只高冷的小虎斑猫也找到了主人，在送它去新家的之前，我们一同给它打理毛发，周棋洛也与我诉说了，自己作为“小猫超级英雄”的使命……"
  },
  [308611] = {
    diary_text = "Kiro had lost his memory! I was at a loss when I saw the confusion on his face..."
  },
  [308621] = {
    diary_text = "As we talked, it dawned on me that something didn't feel right, so I decided to play along to expose his tricks. But after that, I noticed that he wasn't quite himself."
  },
  [308631] = {
    diary_text = "To allow Kiro to let off some steam, I planned a \"kidnapping\" operation and \"kidnapped\" Kiro to a water park. We then participated in an intense water roller race."
  },
  [308641] = {
    diary_text = "After the group activities, I took Kiro to our little world with no one else around and performed a special concert for him. After Kiro confided in me, I dragged him under the water with me..."
  },
  [308711] = {
    diary_text = "While everyone was three sheets to the wind, I slipped into Kiro's room looking for a clue about my father's disappearance; but I was caught red-handed by him..."
  },
  [308721] = {
    diary_text = "I have no idea what's going on in Kiro's head! Why would he name me first mate of the [i]Morning Star[/i]?! Since he made it clear that he looks down on me, I need to be a great first mate and make him think twice!"
  },
  [308731] = {
    diary_text = "The [i]Morning Star[/i]... has no anchor? So has it never come in to shore? The homesick sailors have had enough of this interminable drifting and are preparing to leave the [i]Morning Star[/i]. What is Kiro going to think of this?"
  },
  [308741] = {
    diary_text = "A sudden storm cut short the group's journey home, and in the end, Kiro and I saved everyone. At that moment, I had no aim of my own in mind. All I thought was that I wanted to keep moving forward alongside this grumpiest of captains."
  },
  [308811] = {
    diary_text = "Because of the media frenzy following the paparazzi affair, and at Savin's strong urging, Kiro and I had no choice but to move to this B&B in the western suburbs, kicking off an unexpected \"vacation\"..."
  },
  [308821] = {
    diary_text = "The place was perfect, but I could tell Kiro was a bit down. As I was trying to figure out how to get him to open up, I realized he'd gone missing one morning..."
  },
  [308831] = {
    diary_text = "I found him later, all alone in the garden, clearly bothered by the whole situation. It wasn't even his fault, yet here we were, stuck. Even the prettiest place can feel like a jail when you're forced to stay. I made up my mind right then—we had to break free."
  },
  [308841] = {
    diary_text = "So, when midnight rolled around, we made a run for it. With the wind of freedom in our hair, I saw the sparkle return to Kiro's eyes, and it felt like we made a silent promise about all the adventures waiting for us..."
  },
  [308911] = {
    diary_text = "Late at night, I went to pick up Kiro from the airport and found he'd gotten a lot thinner... If I knew, I wouldn't have put him through the trouble of coming back. But he said if he didn't come back, he'd have run out of battery. As he talked, his head really did dip down like a robot losing power."
  },
  [308921] = {
    diary_text = "But the next day, I actually overslept. By this time, we should've been out eating brunch already! While I started panicking, Kiro told me he had canceled the alarm because he could see that I was exhausted from working overtime in order to free up time for him. So, he decided to just stay in today, but that didn't mean we wouldn't have a good time."
  },
  [308931] = {
    diary_text = "But Kiro's idea of staying in and having fun was to make me brunch?! Just as I was about to ask him if he had this plan all along to cancel our itinerary, Kiro instead informed me of his thoughts..."
  },
  [308941] = {
    diary_text = "Kiro told me softly that one should never have to tough it out or cover up when with one's closest, most loved person. So I should've told him about my exhaustion instead of trying to tough it out through my fatigue all for a rare weekend together. Because he thought that us being together was the best way to relax."
  },
  [309011] = {
    diary_text = "My prospective landlord Kiro and I agreed to meet at the station. He showed me the house and his painting studio. I signed the contract eagerly, but his attitude about me renting the place was a bit odd..."
  },
  [309021] = {
    diary_text = "I brought breakfast to Kiro's studio, and as I was shown around. Kiro told me there was one room I was absolutely never to enter. I noticed that the student coming out of that room seemed scared out of his wits, just like the art dealer!"
  },
  [309031] = {
    diary_text = "My trip to the supermarket with Kiro let me see another side of him. Though my heart trembled, I decided to enter the secret room and investigate. In there, I saw a truth that left me dumbfounded."
  },
  [309041] = {
    diary_text = "Kiro in his monster form was extremely cold. After the misgivings I had deep down were dispelled, I came clean to him about everything. Kiro drew near me, and I closed my eyes..."
  },
  [309111] = {
    diary_text = "Kiro and I are celebrating the New Year in France and decided to go see a musical the locals adore. In order for me to rendezvous with him more easily, he even customized a navigation app for me..."
  },
  [309121] = {
    diary_text = "Before the performance, Kiro told me about his childhood memories of the musical. While we were speaking, someone came up to us and interrupted our conversation."
  },
  [309131] = {
    diary_text = "One of the staff spoke with Kiro in French. As I stood there somewhat confused, the performance began, and I found myself entranced. Kiro excused himself, and before long, a beautifully dressed elven prince entered the stage..."
  },
  [309141] = {
    diary_text = "Naturally, that was Kiro's character. Following the performance, I told Kiro that he wasn't the only one who had prepared a surprise..."
  },
  [309211] = {
    diary_text = "我独自来到拍摄现场探班周棋洛，与舞台上的周棋洛偷偷打过招呼后准备离开时，现场却突发停电事故……"
  },
  [309221] = {
    diary_text = "我决定留在原地等待电力回复，可手机电量已所剩无几，当我在黑暗中越来越紧张时，“向日葵勇者”周棋洛来到了我的身边。"
  },
  [309231] = {
    diary_text = "由于停电事故，部分画面需要补拍，在现场等待的周棋洛提议一起玩一款双人桌上游戏。在游戏中，我们将用骰子与选项体验游戏人物“苹果糖”的人生。游戏的前期一直很顺利，直到我们遇上了一个“棘手”的问题……"
  },
  [309241] = {
    diary_text = "节目的补拍结束时，我们的游戏也告一段落，“苹果糖”在我与周棋洛的帮助下成功与恋人相见。就像“苹果糖”一样，相信我与周棋洛也一定能够达成独属于我们的美好结局。"
  },
  [309311] = {
    diary_text = "周棋洛发现了我偷吃雪糕的蛛丝马迹，正准备和装傻的我核对真相。就在这时，隔壁房间传来了苹果箱和新来的小狗汉堡打架的声音……"
  },
  [309321] = {
    diary_text = "周棋洛从受惊的汉堡爪下保护了我，在收拾过屋内的狼藉后，面对应激的汉堡，我们决定采取音乐疗法来帮助它放松下来。"
  },
  [309331] = {
    diary_text = "在成功帮助汉堡重新建立起安全感后，周棋洛接到了一通电话。在电话中，我们得知汉堡是一条来自救助站的小狗……"
  },
  [309341] = {
    diary_text = "在通过监控查询汉堡跳出栏杆原因的过程中，我和周棋洛的重点双双跑偏，对彼此在监控中的行为互相揭起短来。磨合过后，我们决定互相给对方一个小小的惩罚……"
  },
  [309411] = {
    diary_text = "Kiro accompanied me to a seaside town to help me shoot a promotional video. We brought Apple Box and Cello along as we set out on our road trip."
  },
  [309421] = {
    diary_text = "Having arrived, we came upon a second-hand shop during our search for inspiration. And there's where we found an old video camera and a travel diary with obvious stories behind them."
  },
  [309431] = {
    diary_text = "Having gone through them both, we learned that the diary's owner had found a nearby islet—the Islet of Eternity, which he had described incredibly vividly. Being unable to contain my curiosity, Kiro and I decided to find it that very night."
  },
  [309441] = {
    diary_text = "But before setting off, we learned that the islet had long been submerged underwater and that the diary's owner had simply made up the scenery entirely. When my mind was transfixed by this conundrum, Kiro came up with an enticing speculation."
  },
  [309511] = {
    diary_text = "I received an award at the Gold Star Film Festival and was invited to take part in an associated event. It was here that I ran into Kiro. But we maintained our distance, whether at the awards ceremony or the after-party."
  },
  [309521] = {
    diary_text = "Because the filming on Kiro's movie wasn't going well, I proactively suggested we keep our distance so he could focus on his craft. But when I saw him, I couldn't resist wanting to get close. And he seemed like me, pining for me..."
  },
  [309531] = {
    diary_text = "When I woke up the next day, Kiro was gone. I was a little disappointed, but I dutifully avoided contacting him. My red carpet date had some last-minute work and couldn't go with me, and just then, Kiro suddenly appeared, inviting me to walk the red carpet with him. After the red carpet event ended, Kiro took me to his recording studio and had me help him record the soundtrack for a movie."
  },
  [309541] = {
    diary_text = "Kiro indicated that there was one piece of personal background music that he needed my help with too. As he instructed me on how to sing, he furtively made some mischievous movements that attracted my attention. When I couldn't hold back any longer, he finally bared his heart to me. He told me why he kept having trouble acting like an AI, and he made a declaration of love that made me weak in the knees..."
  },
  [309611] = {
    diary_text = "Kiro was gearing up for his fan meeting, but I found myself struggling to come up with ideas for the \"surprise segment.\" To spark some inspiration, Kiro took me to a warehouse out in the countryside. Just as we were about to enter, he hesitated, looking a bit conflicted..."
  },
  [309621] = {
    diary_text = "It turned out that this warehouse was Kiro's \"Museum of Cringe,\" a place where he'd stashed memories he found embarrassing. As I glanced around, my eyes landed on an old, dusty CD tucked away in a corner. Even Kiro couldn't quite recall what memory it held..."
  },
  [309631] = {
    diary_text = "When we played it, we discovered a video of Kiro as a kid performing a rap routine. He watched his younger, slightly awkward self and turned beet red with embarrassment. But I reassured him, telling him, as a devoted Soda, that his fans would love seeing how he had always been brave enough to try new styles and put his best self forward."
  },
  [309641] = {
    diary_text = "On the day of the fan meeting, I suggested we include the \"embarrassing\" video as part of the surprise segment. Fans got to see a new side of Kiro, and the response was overwhelmingly positive. Surprisingly, Kiro embraced the moment, even asking to change into the outfit from the video so he could recreate his childhood performance for everyone..."
  },
  [309711] = {
    diary_text = "Owing to bad weather, the birthday surprise I intended to give Kiro—his boathouse in California—would get to Loveland City later than scheduled. On my way to the set where Kiro was directing a movie, I had to start considering an alternative plan."
  },
  [309721] = {
    diary_text = "On the set, Kiro gave me a tour, showing me all kinds of novel things, and let me have a try of acting training. Afterward, the film crew and I gave him a birthday surprise together."
  },
  [309731] = {
    diary_text = "During the chit-chat, I learned that Kiro had his birthday alone on the street in the year when he shot the Three Kingdoms. While my heart ached for him, I thought of the best birthday plan."
  },
  [309741] = {
    diary_text = "After Kiro got off work, I took him home, told him about the original birthday surprise I'd meant to give him, and cooked a meal for him. In the flowery yard, we hugged and professed feelings for each other."
  },
  [309811] = {
    diary_text = "Kiro was planning a special joint art exhibition with a renowned performance artist, and—worried that I wouldn't be able to get what was being expressed—I had been cramming art-related information lately, but I still wasn't feeling confident. I asked Kiro if he had any similar training he could give. He thought it over and agreed."
  },
  [309821] = {
    diary_text = "The next day, Kiro's \"perception training\" for me began. However, it was done in a way I wasn't expecting. With my senses constrained, I tried to perceive Kiro with my available senses... "
  },
  [309831] = {
    diary_text = "It was during this unique \"perception training\" that I truly grasped Kiro's intention: the focus was solely on him. Feeling more at ease, I attended the art exhibition and discovered the house specially designed by Kiro."
  },
  [309841] = {
    diary_text = "Inside a birdcage, I encountered a version of Kiro \"closer\" to me than ever before, and I could sense all his yearnings and desires from his perspective. Whether it was a performance or not became irrelevant. Through this manifestation of \"freedom,\" we both willingly allowed ourselves to be bound by the other."
  },
  [309911] = {
    diary_text = "When I handed Kiro the international package, he was surprised to find out it was from the summer camp he attended as a kid. After examining it closely, he realized that KEY had signed him up for the camp's special \"time-traveling adventure\" on a whim."
  },
  [309921] = {
    diary_text = "After confirming our participation with the summer camp, we flew to Hawaii and followed the map through the rainforest. Along the way, Kiro shared stories of his childhood adventures with his Teddy Bear in the jungle. But just as he was getting into it, we suddenly fell into a trap!"
  },
  [309931] = {
    diary_text = "With \"Captain\" Kiro's guidance, we managed to escape and reached the final destination—a cabin with his and Teddy Bear's names on it. Inside, we found a wall covered in photos from his time at the camp, though many memories had faded for him."
  },
  [309941] = {
    diary_text = "As we explored, we noticed that Teddy Bear's stitching had come undone again. While \"fixing\" him, we discovered a hidden note and a piece of old candy inside—turns out, it was a promise Kiro and Teddy Bear made as kids."
  },
  [310011] = {
    diary_text = "On the second-to-last episode of the show I Am Gamer, Kiro's opponent caught up to him on the leaderboard. To tighten up for the arcade challenge in the next episode, we decided to go to the arcade for some practice."
  },
  [310021] = {
    diary_text = "Kiro broke one high score after another in the arcade, and some gamers noticed Kiro on this record-breaking streak. They came up to him for tips, and before a bigger crowd formed, we left the arcade."
  },
  [310031] = {
    diary_text = "Because of something we overheard from other gamers, Kiro realized that climbing the leaderboard was missing the point of why he played games. I consoled him by saying that I just wanted to win games together with him."
  },
  [310041] = {
    diary_text = "Kiro took me to a racing game, and with his coaching, we used a special technique to shatter the record at the top of the rankings—a record that others wouldn't be able to break."
  },
  [310111] = {
    diary_text = "Kiro and I agreed to go on a vacation to the wetland park. On the train, I called him and wished him good luck with the audition. Unexpectedly, after reaching the guest house, I got \"robbed.\""
  },
  [310121] = {
    diary_text = "Kiro, the \"robber,\" took all my chocolate and told me he'd failed the audition. We agreed to cheer up and enjoy our vacation to the fullest, but we got \"mobbed\" by a herd of deer when feeding them."
  },
  [310131] = {
    diary_text = "Kiro was struck by inspiration and composed the song \"The Deer and My Dear\" and asked me for a reward. In the evening, when we had a barbecue in the yard, Kiro intended to impress me with his barbecue techniques, only to discover that he had brought the wrong seasonings. Just then, I perceived Kiro's absent-mindedness..."
  },
  [310141] = {
    diary_text = "To cheer Kiro up, I roasted some marshmallows. Delicious food and our smiles lightened our moods. After the barbecue, neither of us could sleep. I told Kiro how I usually dismissed my vexations, and Kiro shared with me his distinctive \"new discovery.\""
  },
  [310211] = {
    diary_text = "Little did I expect that a prime-time show would completely expose my identity as an entertainer to my classmates. I started praying that people wouldn't look at me differently and that I could get through the remaining year smoothly!"
  },
  [310221] = {
    diary_text = "After half a year had gone by, I finally found a trace of Key, my mentor, again. It made me late to a class, but it was worth it. If Trina sitting behind me would stop poking me, then all the better..."
  },
  [310231] = {
    diary_text = "My grades were already good enough for Berkley! I guess I'd better work even harder! As for Mr. Lawrence's nagging, I just gotta let it go in one ear and out the other ^ ^"
  },
  [310241] = {
    diary_text = "After so many days of practice, the football game was finally about to kick off. I hoped it would be a perfect victory so I could start summer vacation off on a happy note!"
  },
  [310311] = {
    diary_text = "Kiro invited me to join him for pizza in a small town in Sicily, but our arrival was met with rejection and harsh words from a man named Pietro!"
  },
  [310321] = {
    diary_text = "Through Kiro, I learned about Pietro's past and the unintended consequences of Kiro's actions. Kiro wanted to help him, and naturally, I was right there as his \"partner in crime\"."
  },
  [310331] = {
    diary_text = "Kiro spent a lot of time figuring out how to talk to Pietro. In the meantime, he handled some troublemakers behind the scenes, but trouble always found its way to Pietro. When Pietro raised his gun, I stepped forward...!"
  },
  [310341] = {
    diary_text = "Pietro retreated to one of the mafia family's bases, but we were not ready to give up. In the end, we finally got his answer and tasted the \"best\" pizza ever."
  },
  [310411] = {
    diary_text = "在小区草坪见识了其他狗狗的技能后，我感受到了周棋洛无法经常陪伴苹果箱的遗憾，所以决定帮他训练它的定力。但经过一上午的努力，苹果箱却丝毫没有长进。"
  },
  [310421] = {
    diary_text = "我正一筹莫展时，周棋洛回到家中帮我一起进行训练，他对苹果箱进行了《成功学》的洗脑，但也没有成效。"
  },
  [310431] = {
    diary_text = "我告诉周棋洛，苹果箱除了在定力训练中会一直追着我们之外，其他方面的技能都学得很快。他由此得出苹果箱太喜欢我们了，所以才想黏着我们。"
  },
  [310441] = {
    diary_text = "我们开始数点苹果箱无条件喜欢我们的表现，我借由这个话题问周棋洛喜欢我的理由，而他给了我最甜蜜的答案。"
  },
  [310511] = {
    diary_text = "In a group selfie from a coworker, I was surprised to see not only the baseball rookie sensation Caleb—who was visiting Loveland City recently—but also Kiro?! Just then, I got a message from Kiro too saying he wanted to introduce a new friend to me..."
  },
  [310521] = {
    diary_text = "I couldn't believe Kiro and Caleb were actually high school classmates and teammates! At the batting cages, the duo decided to rekindle their old competition, but unfortunately, Kiro was narrowly defeated due to a back injury. Kiro didn't let that get him down though—it only fired him up more. At the charity baseball game, he would have another shot at victory. Go, Kiro!"
  },
  [310531] = {
    diary_text = "Lately at home, Kiro has been doing \"hardcore training\", and I've been documenting his hard work and fighting spirit on camera. During a break, we also turned up some videos from back at Hitachi High. The relationship between Kiro and me was so innocent and sweet back then. It made me feel so nostalgic..."
  },
  [310541] = {
    diary_text = "Kiro's training got progressively harder, and his injuries were piling up. I could hardly bear to watch, but seeing all the hard work he was putting in, I decided to give him a surprise—to become a member of the charity game cheerleading squad! I would cheer for him as loud and proud as possible!"
  },
  [310551] = {
    diary_text = "The day of the big game was soon here. We both took the field, and then I revealed the second surprise I'd prepared for Kiro: I threw out the opening pitch for the game, tossing him a ball filled with all the luck and good wishes in the world."
  },
  [310561] = {
    diary_text = "Kiro won! I could read that news a hundred times and never get tired! After the game, we skipped out on all the post-game celebrations and went home, and enjoyed the time just for the two of us. Then, I suddenly remembered that I'd been praising Kiro all day, but he hadn't praised me yet. I was going to make sure I got what I had coming..."
  },
  [310611] = {
    diary_text = "In a little chapel, Kiro and I solemnly vowed to act as marriage witnesses and to offer up our blessing and our affirmation of the wedding couple. Meanwhile, the bride and groom of this wedding were none other than a teddy bear and a bunny rabbit..."
  },
  [310621] = {
    diary_text = "When the wedding ended, we set off on our own \"stall tour.\" Before leaving the chapel, a worker told us the fair also had a special challenge event..."
  },
  [310631] = {
    diary_text = "Kiro and I put on cute T-shirts and \"disguised\" ourselves as popcorn stand workers so that the stall worker who wasn't feeling well could take a break. But what we didn't know at the time was this was the start of our market fair meet-cute..."
  },
  [310641] = {
    diary_text = "We thought we'd missed our teddy bear and bunny rabbit mascots, but they made it back home with us in an unexpected, but also reasonable, way. With a big fair outing now over, Kiro's attitude seemed to hint that perhaps we left behind a regret after all...?"
  },
  [310711] = {
    diary_text = "我和周棋洛来到水族馆游玩，却因狗仔偷拍被游客发现。汹涌的人潮将我和周棋洛冲散，还好他用经验化险为夷，最终与我顺利会合，离开了水族馆。"
  },
  [310721] = {
    diary_text = "周棋洛带我到游艇吃烛光晚餐，温馨浪漫的氛围下，我们诉说着这半个月来的思念。不料狗仔居然又追了上来，甚至威胁到了我们的安全。"
  },
  [310731] = {
    diary_text = "周棋洛从容地解决了危机，带我回到酒店，但是我却发现他隐藏的情绪，在交流中我们都发现了彼此共同的“坏习惯”。"
  },
  [310741] = {
    diary_text = "第二天早上周棋洛想到了一个绝佳的计划，在“周棋洛小队”的帮助下，我们终于安心地游玩，并在美丽的向日葵花海里，坦诚地表达了彼此的心意。"
  },
  [310811] = {
    diary_text = "Kiro and I were driving over the vast steppe, happily chatting away, when I learned that the equestrian instructor who invited us was about to move his family out of the village and into the city..."
  },
  [310821] = {
    diary_text = "After arriving at our destination, Kiro's instructor, Big Hal, brought out his family to greet us and asked if there was anything we wanted to do here. So, I told them some things I'd always wanted to try—archery and horseback riding!"
  },
  [310831] = {
    diary_text = "Unfortunately, my riding chops weren't quite up to par, so I was forced to double up with Kiro as we rode to the archery range. Seeing Big Hal and his wife riding around like they were tied at the hip, I felt an itch inside to gallop side by side across the plains like that with Kiro too..."
  },
  [310841] = {
    diary_text = "After a shocking archery experience, I started waking up early and sneaking out to practice shooting by myself. In the afternoons, I trained in horseback riding. This continued until the day of Double Seventh, when Big Hal told us they had their own traditional custom: the \"Couple's Contest\". And so, Kiro and I galloped off side by side, and the contest had begun..."
  },
  [310911] = {
    diary_text = "The latest astrological observations seemed to foretell that a great disaster was to befall the Kingdom of Kylos. Just as I was overcome with anxiety about this, I heard my master Pasha conversing with the king, and I was dumbfounded to learn that Prince Kiro's entire life had been meticulously planned out."
  },
  [310921] = {
    diary_text = "I told Kiro the truth in a hurry, but he responded with total equanimity, which made me totally confused and agitated... However, our relationship wasn't as close as in the past, so all I could do was stick to the promise I made in our childhood and use my position as stargazer to keep his life as free from trouble as possible."
  },
  [310931] = {
    diary_text = "But as I continually sought solutions, I discovered that many recorded astrological signs from the past didn't square up with their corresponding history, and this opened up a tiny crack in my long-held faith. However, the subsequent coronation ceremony left me with mixed feelings."
  },
  [310941] = {
    diary_text = "War was imminent, and Kiro really seemed about to embark upon his predestined fate, but I didn't believe in it anymore. I wanted to tell Kiro that destiny is meaningless, and that I wanted him to come back alive. But when he really did make a triumphant return, I witnessed a heart-rending scene..."
  },
  [311011] = {
    diary_text = "Kiro was crouching among an army of toys, trying to conceive ideas for the children's play. Seeing that he was having trouble finding inspiration, I walked up to him and asked the reason. He told me that he wanted to write a good story from the perspective of children, so I suggested that we put our heads together to figure something out. But first, he needed to go out and get some fresh air."
  },
  [311021] = {
    diary_text = "After we strolled through the forest for a while, Kiro hunkered down, saying he wanted to look at the world from a child's perspective. Soon, he discovered some ants on the ground, and it seemed to spark inspiration in him!"
  },
  [311031] = {
    diary_text = "He eagerly put on an improvised stage show based on the ideas in his mind—it was a story about little angels. With the help of my \"co-starring\" efforts, he gradually conceived an outline for his children's play."
  },
  [311041] = {
    diary_text = "One day, I secretly went to the kindergarten to check on him, only to behold a picturesque scene—a group of \"little angels\" romping around Kiro. I was just about to call him to enjoy the lunch I'd prepared when he heard a strange sound coming from a tussock..."
  },
  [311111] = {
    diary_text = "远哥得了肠胃炎，周棋洛再次拜托我作为临时经纪人上阵。我虽然答应了下来，可看着剧本中周棋洛跟搭档的甜蜜互动，心里不由泛起了一丝酸味……"
  },
  [311121] = {
    diary_text = "造型打点完毕后，我跟周棋洛牵着手前往拍摄现场。却从焦急的导演口中得知，跟周棋洛搭档的模特不小心擦伤了手指，需要在现场寻找合适的人选……"
  },
  [311131] = {
    diary_text = "接受了周棋洛的“表演课教学”后，我的心情放松了不少。然而面对镜头时，还是微微有些僵硬。就在这时，我的手忽然被他拉住。周棋洛低声告诉我不要注意别人，只需要看着他就够了。"
  },
  [311141] = {
    diary_text = "拍摄顺利结束，我和周棋洛到了一家火锅店“庆功”。我笑着感谢周棋洛在现场的引导，周棋洛却一本正经地告诉我，他只是临场发挥。而能实现这一切的原因，是跟我在一起……"
  },
  [311211] = {
    diary_text = "To help Kiro focus fully on his suona training, I moved with our two little furry companions into a house right across the street from the master's. For the time being, this would be our temporary home!"
  },
  [311221] = {
    diary_text = "Waking up in the quaint, traditional house felt like a breath of fresh air. Everything was peaceful and serene. I followed Kiro into the courtyard, where he explained that before starting suona practice, he needed to work on his lung capacity. So Apple Box and I joined him for his morning breathing exercises. Midway through, we suddenly heard a clear, powerful note—someone was playing the suona."
  },
  [311231] = {
    diary_text = "It turned out to be his master practicing at the same time. As we listened, Kiro shared stories about the master, and I found myself genuinely moved by the unique power and emotion in the instrument's sound. Intrigued, I asked if I could sit in and quietly observe his lessons."
  },
  [311241] = {
    diary_text = "In the days that followed, I not only attended his classes but also helped him brainstorm ideas for the film's soundtrack. The deadline was fast approaching, yet Kiro seemed noticeably more at ease than usual. When I asked why he wasn't stressing out like he normally would, he told me the reason behind his newfound calm..."
  },
  [311311] = {
    diary_text = "The girl that I'm playing, Jenny, came to a newly-opened club in town to see a magic show. Although I had missed the show by the time I arrived, I unexpectedly met the magician Kylo, played by Kiro."
  },
  [311321] = {
    diary_text = "While Kiro and I were resting in the dressing room, an assistant director informed us that there was a last-minute change to the script; and I learned that my part was a bit risqué... To ensure filming stayed on schedule, I did my best to keep my nerves in check and get him ready for our scenes together."
  },
  [311331] = {
    diary_text = "Kiro and I have started to shoot our newly-changed parts. I thought he would be nervous, but to my surprise, his performance was totally natural. On the contrary, I was the one starting to get nervous... After filming ended, Kiro came forward and asked for my contact information. I started looking forward to a phone call from him."
  },
  [311341] = {
    diary_text = "One month later, Kiro and I met again at an ad photo shoot. Because he hadn't contacted me for a month, I was carrying a bit of a grudge against him. However, during filming, the misunderstanding was slowly cleared up, and he gradually revealed his heart to me..."
  },
  [311411] = {
    diary_text = "On our first night upon arriving in Los Angeles, I actually dreamed Kiro and I were in a band performing together on stage. When I excitedly shared the dream with him, he made an enticing invitation that I couldn't turn down—to turn the dream into reality and form a band with him."
  },
  [311421] = {
    diary_text = "In the afternoon, he took me to his former band's home base: a \"musical instrument store\" that was never open. I heard a lot about his past here, and we officially formed our band \"TwinkLe\". However, he seemed to notice my nerves, and \"Mr. Flower\" made another appearance."
  },
  [311431] = {
    diary_text = "One night, Kiro mixed up a sweet cocktail. Slightly tipsy, he led me in creating a musical world together. Here, I felt unmatched joy and pulse-pounding excitement, but this was far from over. With one kiss after another, we kept discovering the charm of music."
  },
  [311441] = {
    diary_text = "After I woke up, I could still hear the melody from last night. Just as I was recreating the tune, Kiro told me that my tempo wasn't right. After one attempt after another, I got more and more immersed in it. Kiro suddenly grabbed my hand and said: \"Mr. Flower\" is off the clock."
  },
  [311451] = {
    diary_text = "After our first single got released, we actually got an invite to perform by the WMA. I was both excited and hesitant, worried it would have a negative effect on Kiro. But he said that wasn't important. More important was whether I wanted to perform on stage with him or not... For that, I gave him the firmest reply I could."
  },
  [311461] = {
    diary_text = "Unsurprisingly, Kiro won the award for best pop vocal album, and our band \"TwinkLe\" officially ended its first performance. For the next day's music festival performance, we arrived early at the venue to get a feel for it. Little did I expect, one short text message would allow me to feel his true emotions once again."
  },
  [311511] = {
    diary_text = "Not only was our planned vacation ruined by B.S., but then Kiro came back injured! Argh! Could this day get any worse? Being hurt, Kiro was going to need some rest. As for his unfinished game? Leave it to me. I'll beat it for him!"
  },
  [311521] = {
    diary_text = "Of course, in classic me fashion, I finished the level but totally forgot to claim the rewards! While I was drowning in guilt and self-reproach, Kiro just waved it off, and even invited me to go to the amusement park. But that little trip turned out way more turbulent than I expected."
  },
  [311531] = {
    diary_text = "It became clear we were both wrestling with the same struggle—caring so much about the other that we didn't know where to draw the line. Maybe... we just need to stop being so \"nice\" to each other?"
  },
  [311541] = {
    diary_text = "Before I realized it, Kiro and I had gone from cautiously accommodating each other to this playful, almost competitive back-and-forth. And surprisingly, this little clash of wills sparked something new between us—a warmth that felt different but unmistakably real. Even the folks at B.S. seemed shocked."
  },
  [311551] = {
    diary_text = "Sometimes, being overly considerate only creates distance between two hearts. So I've made up my mind. From now on, even if I'm in a bad mood or feeling cranky, I'm going to show him all of me. After all, he's the person I love, and if I can't be completely myself around him, who else could I be willful with?"
  },
  [311611] = {
    diary_text = "下班回家时，我发现周棋洛正在和吨吨“对峙”。周棋洛今天吨吨打碎了我送给他的水杯，还啃坏了电源线。我好奇周棋洛为什么平时对我那么宽容，他说因为是我，所以什么都可以纵容，这让我有些好奇他究竟能纵容我到什么地步，于是我发起了一个“挑战”……"
  },
  [311621] = {
    diary_text = "第二天一早，挑战就在周棋洛一个未完成的早安吻中开始了。他出门后，我用他的账号玩游戏，并一不小心把他的积分输掉了很多。谁知周棋洛回来时候只是哈哈笑着，并教我在游戏里迅速通关。到晚上睡前我才想起，早上那个吻还没有“回击”。"
  },
  [311631] = {
    diary_text = "天气晴朗的好日子里，我们带着吨吨出去赏花野餐。吨吨在周棋洛的三明治上留下猫毛并叼走了他的面包片，我想起之前的“挑战”，趁机“火上浇油”拿走了最后一个甜甜圈。没想到他不但沉住了气，居然还演奏了一首给我写的歌……"
  },
  [311641] = {
    diary_text = "吨吨给我叼来一枝很美的花，我顺口说出吨吨是我最喜欢的宝贝后，周棋洛一把将我抱到小帐篷里，表示“薯片小姐”最喜欢的这个位置，他永远都不会让出来。这场“挑战”虽然是我获胜，但我们都知道，此刻拥抱住的人，就是我们寸步不让的底线……"
  },
  [311711] = {
    diary_text = "I went home early to prepare my Valentine's Day surprise for Kiro, who also came home early to do the same... I had to make a change of plans..."
  },
  [311721] = {
    diary_text = "I decided to resume my work after he went to bed. Just when I was finishing up in the backyard, I realized that the tent I needed to set up was still in the storage room..."
  },
  [311731] = {
    diary_text = "I opened the door and saw a sea of flowers where it should have been full of boxes! Someone then hugged me from behind while I was trying to understand what happened. It turned out that Kiro also had a surprise for me..."
  },
  [311741] = {
    diary_text = "Our Valentine's Day started earlier than expected after a string of surprises. When the sun came up, I picked the four-leaf clover that I saw the in backyard the night before and wove a ring of luck. I then confessed my feelings to Kiro..."
  },
  [311811] = {
    diary_text = "In a press video for a new show, Kiro told everyone some background about the character he portrayed and fielded questions from a reporter. Then, when asked about his own Myers-Briggs personality type, Kiro decided to keep everyone in suspense."
  },
  [311821] = {
    diary_text = "Kiro and I went to the supermarket together to buy ingredients for tonight's hotpot feast. On the way, I mentioned his press appearance for the new show was trending online. Everyone was curious what Kiro's personality type was, but he said that right now was our time off and we couldn't discuss work!"
  },
  [311831] = {
    diary_text = "After we had eaten and drunk our fill, Savin called. He told us the topic of Kiro's Myers-Briggs personality type was too hot right now. To get public sentiment under control, they decided Kiro would reveal the answer himself. But Kiro had other ideas..."
  },
  [311841] = {
    diary_text = "Apparently, he had taken the test three times and gotten three different results. We took this as an opportunity to get out the message that people shouldn't let themselves be defined by these things. Everyone plays different roles with different personalities from time to time. But luckily for us, when we're with each other, we just have to be our happiest selves."
  },
  [311911] = {
    diary_text = "This year, Kiro's birthday fell on the day that the most influential comicon in Asia was holding its convention in Loveland City. He'd also been invited as a special guest to attend the opening ceremony. During the performance, I could see from the crowd how excited he was up there, so I decided to move up tonight's unveiling of his birthday surprise..."
  },
  [311921] = {
    diary_text = "With Savin's help, I got the luggage and waited in the underground parking garage for Kiro to finish giving an interview. When we met, I took out the birthday surprise I had prepared earlier. Even though it was supposed to be for that night, I thought now was a better time to unveil it."
  },
  [311931] = {
    diary_text = "After Kiro and I changed costumes, we cheerily roamed the convention floor, taking selfies with lots of fellow enthusiasts along the way. In the end, we went to the Firelight Warrior booth and got lots of \"spoils of war\"."
  },
  [311941] = {
    diary_text = "I took Kiro to the mountainside behind our villa to see the surprise I'd originally prepared for him. Surrounded by scenery straight out of a comic book, we revealed our deepest feelings for each other and realized we had once again found \"common ground\"."
  },
  [312011] = {
    diary_text = "进入游戏后，我们收到一封来自詹姆斯先生的信，正当我们惊讶着游戏里的世界和小镇做的任务有了联动时……信中的内容更让我觉得十分诡谲，他竟然请求我们为杀害他的凶手脱罪！"
  },
  [312021] = {
    diary_text = "考虑到福尔摩斯此时正在法国，周棋洛便决定乔装打扮成他来接近案发现场，然而在我们搜索现场的线索时，一位警探表示有一位可疑的女人下午来找过詹姆斯。"
  },
  [312031] = {
    diary_text = "得知女人的名字为Rachel后，警探表示她就是杀人凶手，并带回了警局问话。可周棋洛却觉得疑点重重，在他反复搜寻现场的线索时，一个巧妙的机关令他发现这场凶杀的真相。"
  },
  [312041] = {
    diary_text = "原来詹姆斯是想让所有人认定这是一场他杀，才委托我们嫁祸给瑞秋。但考虑到原则问题，我们便用了个讨巧的方式，将“真相”交由福尔摩斯先生来还原，为瑞秋洗清罪名……"
  },
  [312111] = {
    diary_text = "Because of a partnership with Leezy, I went abroad to the city where they're headquartered and also attended a charity banquet with Kiro, who was here filming. After discussing business, we both simultaneously had the idea to spend some time to ourselves, and so we left the banquet..."
  },
  [312121] = {
    diary_text = "Back at the hotel, Kiro put me on the sofa, and I wrapped him in a hug. The decorative chains on our clothes got tangled together. While he was undoing the chains, I would \"make trouble\" from time to time, until he grabbed both my hands..."
  },
  [312131] = {
    diary_text = "With the Leezy publicity partnership on the horizon, I still didn't have any ideas for their \"Entanglement\" theme. Luckily, Kiro had just returned from abroad. He said he'd help me find inspiration using a technique I was at home in—photography. While setting up for the shoot, he gradually wrapped me up with silk ribbon, letting me tactically experience the sensation of being entangled."
  },
  [312141] = {
    diary_text = "He was also very receptive when I got the idea to \"entangle him\". Imitating him, I wrapped the ribbon in circles around him, getting him all tangled up, and then caught this inspirational image on film. Then, he took my hand and said that getting untangled was a whole other experience in itself..."
  },
  [312211] = {
    diary_text = "这周《舞台的背后》要拍摄慈善夜盛典的总导播，而周棋洛恰好是这次晚会的慈善大使，他十分期待我们在工作中相遇。"
  },
  [312221] = {
    diary_text = "结束上午的跟拍后，我发现不苟言笑的总导播竟是周棋洛的“安利粉”，毕竟彩排时的周棋洛用舞台魅力征服了所有人，然而开幕临近，却发生了大意外。"
  },
  [312231] = {
    diary_text = "经过一番纠结，我决定揽下重任成为临时总导播确保慈善晚会顺利进行，但是因为直播车问题，最终这份担子被周棋洛接过，可是他还要负责重场表演，我不禁忧心忡忡。"
  },
  [312241] = {
    diary_text = "在不到半小时的开场倒计时里，我和周棋洛分秒必争，以接力成为总导播的方式完成了超高难度的直播晚会，并且双双创造收视奇迹。"
  },
  [312311] = {
    diary_text = "我原本以为这是和平常一样的赐福日，我们接受完人们的朝拜后正准备离开，却被一队陌生的雇佣兵拦住了，而他们居然认出了我们，在所有人面前揭穿了我们的真面目……"
  },
  [312321] = {
    diary_text = "我和周棋洛不知道该如何面对大家的质疑，于是趁乱逃离，回到安全屋后，我和他都想起了那些不堪回首的过去，我们不想再经历了。"
  },
  [312331] = {
    diary_text = "我们在安全屋里待了很久，也没有想到能完美解决的办法，这时候有人来敲响了我们的门，居然邀请我们继续去进行赐福仪式？可当我们来到仪式现场时，可怕的事发生了……"
  },
  [312341] = {
    diary_text = "如果太阳神不应该存在，那就让它消失好了！所有的信念都不应该借神的嘴来说，而是应该由我和周棋洛自己来说，只有这样，才能真正让Z区的大家在这个世界里好好活下去。"
  },
  [312411] = {
    diary_text = "《逐光》巡回演唱会在港岛开启之际，资方按照当地传统，准备了最高规格的开机仪式，而就在仪式进行到一半时，一场滂沱大雨诡异地降临了。"
  },
  [312421] = {
    diary_text = "而后几天，在演唱会的筹备过程中，离奇的突发状况层出不穷，几百人的团队一时间人心惶惶，而周棋洛却始终从容稳重。这时，资方负责人突然提出了一个想法……"
  },
  [312431] = {
    diary_text = "考虑到或许可以安抚团队伙伴的不安，周棋洛答应配合。于是在一天清晨，我们与资方一道坐着大巴前往深山拜访大师。抵达古庙时天光已然大亮，在肃穆庄严的环境里，我恍然觉得似乎真的有神灵正静静庇佑着什么。"
  },
  [312441] = {
    diary_text = "按照大师的嘱咐，我们抵达了一间地下商场，在演唱会场馆的“命脉之处”涂抹了符纸灰。大功告成后，我接到了一个电话，得知筹备中的意外状况也正在被一一解决，正悄悄松了一口气，却发现周棋洛不见了……"
  },
  [312511] = {
    diary_text = "After twisting his leg on set, the production team granted him two weeks off to recover at home. He had originally planned to use that time to be with me, but when he learned I was thinking of dropping the workshop to be by his side, something in him seemed to shift."
  },
  [312521] = {
    diary_text = "I'd heard there was a well-known local remedy for sprains, so the moment I got off the plane, I went to buy some. I messaged Kiro to let him know and remind him to pick it up—but he didn't reply. Growing anxious, I checked the surveillance camera at home... only to witness something completely unexpected."
  },
  [312531] = {
    diary_text = "Though I valued this rare opportunity to study, I couldn't stop thinking about Kiro's condition. That internal conflict left me feeling unsettled. During a video call, he seemed to read me perfectly. Looking straight at me, his tone serious but gentle, he said that being in a relationship means moving forward together, and becoming better together."
  },
  [312541] = {
    diary_text = "The next morning, to my surprise, Kiro showed up at my hotel. My heart swelled at the sight of him, but my concern returned just as quickly. He was still injured, after all. Then, as he stepped into the bathroom, I suddenly heard a loud banging noise from inside—!"
  },
  [312611] = {
    diary_text = "One perfectly ordinary morning, Kiro suddenly asked me if I wanted to shoot a music video for TwinkLe. I blearily agreed to board his ship, and when I realized what was going on, the locations for the shoot were all listed out before me..."
  },
  [312621] = {
    diary_text = "I never would've guessed that the destination we chose by throwing a dart would be an island that we'd visited before! Since it was summer, we decided to make a song with summertime vibes!"
  },
  [312631] = {
    diary_text = "We tried to do all of the quintessential summer experiences, but the theme of \"summer\" was still too big. After talking it over, we decided to find one of the key words associated with summer, and that was: water."
  },
  [312641] = {
    diary_text = "Kiro prepared several arrangements and asked me which one felt closest to my sense of \"water\". With our whole being, we experienced a musical vibe that alternated between cool and warm, and even our senses of touch seemed to blur."
  },
  [312651] = {
    diary_text = "When our new song and music video both were finished, Kiro told me a little secret: Upon arriving on this island, he had wanted to remedy a past regret and bring everything full circle. Fortunately, we managed to do it this time."
  },
  [312711] = {
    diary_text = "In accordance with Kiro's preferences, I \"marinated\" myself to smell like watermelon. However, when I presented myself to him, he reneged and said he didn't feel like having watermelon today—he wanted tangerines instead. He was always messing with me like this, but there was nothing I could do. I went to look for tangerines, but then my old illness flared up and I fainted."
  },
  [312721] = {
    diary_text = "When I opened my eyes again, I was surprised to find that I was in the underworld... Had I actually died? Just as I was about to reluctantly accept this reality, a strange force suddenly pulled me back—all those terrible things just now were just a dream. Kiro had taken my passed out body from the market back to the ancient temple..."
  },
  [312731] = {
    diary_text = "Because my dress had gotten dirty, he took me to a nearby clothes shop to get a new change. However, a new playful urge seemed to come over him, because he wanted to do my clothes and makeup himself. He also hinted between the lines that I was his beloved little dress-up doll..."
  },
  [312741] = {
    diary_text = "Today was Double Seventh Festival, and Kiro and I unexpectedly came upon a marriage ceremony. However, my illness flared up mid-way through, and I once again saw the underworld spirits Black & White Impermanence come to take me away—but Kiro rescued me. This time, I realized that night before wasn't a dream after all. All this time, it was Kiro keeping me alive. He even demanded an answer from me: how long would it take for me to know him, to understand him..."
  },
  [312811] = {
    diary_text = "我买了宠物的益智玩具，希望培训Cello学会一些简单的沟通，可是训猫比我想象中得要困难不少，正当我对这个不配合的小家伙感到无奈时，周棋洛却神秘告诉我他有办法……"
  },
  [312821] = {
    diary_text = "原来周棋洛这些天在悄悄研究一个寻宠功能的程序，现在已经能够准确地定位Cello。我非常兴奋，感觉或许还可以帮助寻找最近小区里那只走失的小猫，没想到周棋洛也有相同的想法。"
  },
  [312831] = {
    diary_text = "我们根据寻猫启事一起来到丢失小猫的老爷爷家，收集了小猫的部分数据用于程序的测算，离开时老爷爷再三感谢周棋洛。回去后周棋洛向我坦露了他做这个程序的初心，柔软而赤诚……"
  },
  [312841] = {
    diary_text = "我和周棋洛一起前往程序提示的地点寻找小猫，因天色将雨，便分头搜寻，但结束后我却没看到他，忍不住担心地去找他，却意外找到了丢失的小猫，它引我看见怀抱流浪小狗的周棋洛，凉雨落下，却渗出暖意……"
  },
  [312911] = {
    diary_text = "从下午一觉睡到晚上后，我发现周棋洛已经从健身房回来了。见他如此自律，我不由想到自己的To do list一个都没完成，但周棋洛说他有一个“秘籍”，可以帮助我提高行动力。"
  },
  [312921] = {
    diary_text = "原来他的秘籍叫“五分钟法则”，是指当脑袋里冒出一个想法时，就要在五分钟内行动起来。但这时一个突如其来的电话，让周棋洛决定拉着我跟他一起去攀岩……？！"
  },
  [312931] = {
    diary_text = "来到攀岩馆后，周棋洛又化身花老师来教我。他先是为我简单介绍了这项运动，随后又让我试着去抱石区感受一下……"
  },
  [312941] = {
    diary_text = "在周棋洛的指导下，我成功完成了V0的入门路线，而周棋洛也继续挑战着他最近一直难以攀登的“高峰”，但无论他失败了多少次，他总是能立刻重头再来。看着他坚定的背影，我意识到这样在他人眼里是天才的人，其实只是重复了无数次“五分钟法则”和“坚持”吧……"
  },
  [313011] = {
    diary_text = "我正满意地看着镜子里自己的万圣节扮相，智能手表上收到了这场真人RPG游戏的任务说明。作为“欲望女巫”，我要尽可能利用游戏官方给出的攻略和资源，让我的同伴周棋洛说出“满足”。看着眼前一身圣职者扮相的他，我怦然心动的同时也止不住地好奇，他的个人任务又是什么呢？"
  },
  [313021] = {
    diary_text = "我顺利地利用攻略，带周棋洛碾压式通关，当我与他一起触发了一处隐藏任务时，他不似平时开心，反倒若有所思般地突然说有问题想要问我……"
  },
  [313031] = {
    diary_text = "见我还在犹豫，周棋洛直直走向关卡陷阱。我这时才意识到，他早察觉了我的心思，决定用自己做“人质”，问清我的任务和目的——比起一帆风顺地通关，或是就此落入我的计划，他选择用最有趣的方式和我一起享受游戏。眼看他即将因为陷阱出局，我也做出了自己的选择……"
  },
  [313041] = {
    diary_text = "我们彼此都有想让对方说出的词语，也彼此都想让对方度过最开心有趣的万圣节。在我早早布置好的套房内，我们选择用我们的方式，让这场游戏再延续一会儿……"
  },
  [313111] = {
    diary_text = "因天气原因降落在别的城市的我，却得知周棋洛也在这个城市。我打开手机，发现了周棋洛给我的留言。在听闻他打算进行一场“圣地巡礼”之后，我果断打过去了电话……"
  },
  [313121] = {
    diary_text = "跟随着周棋洛在电话里的指引，我成功在天桥与他相会。身处漫天雪花之中，我得知了他想要偷偷展开巡礼的理由，我决定一起和他寻找游戏密码的线索。"
  },
  [313131] = {
    diary_text = "我们一路走着，路上到处都是星星的装饰，可我们期待的密码线索并没有出现。犹豫之中，周棋洛把我拉到星星雕塑旁。"
  },
  [313141] = {
    diary_text = "巡礼接近尾声，我们却依然没有找到线索。提着刚买好的蛋糕坐在长椅上，我们开始设想这个游戏的隐藏结局会是什么样的。而当我们打开蛋糕盒，却在上面看到了一串八位字符。"
  },
  [313211] = {
    diary_text = "在我和周棋洛抵达工厂后，各个部门便带着方案来找周棋洛审批。见他十分专业又从容自如的状态，我不由暗自感慨他对这份“新事业”的认真和重视……"
  },
  [313221] = {
    diary_text = "周棋洛策划了一个快闪店的宣传方案，并希望我能一起把关。只是没想到这个“快闪店”内有玄机——里面竟然是一间有着多巴胺风格的超市……！不过问题来了，我们的薯片要如何冲出重围，变成最闪亮的存在呢？！"
  },
  [313231] = {
    diary_text = "原来周棋洛早就想好了解决方案，通过一个现实版的接物小游戏来隆重推出我们薯片。只是在测试过程中，我发现了一个巨大的BUG，那就是我们的薯片从头至尾都没有掉落。但他却用实际行动来告诉我这并不是BUG……"
  },
  [313241] = {
    diary_text = "在紧锣密鼓的筹备中，我们的快闪活动正式启动。当天的一切十分顺利，每一个参与其中的游客也都收获了快乐，作为“STAR”的品牌老板周棋洛更是如此。在休息间里，他告诉我他对快乐又有了新的定义……"
  },
  [313311] = {
    diary_text = "面对那些带节奏的黑稿，我和周棋洛一致认为不去理会，而是专注在彼此身上。他对三天后的百人成亲活动有着无限的憧憬和期待。当然，我也是一样的心情。"
  },
  [313321] = {
    diary_text = "眼前的古色古香，如此身临其境不由令我们以为自己穿越回了古代，甚至开始畅想起来到古代的生活，就在越来越开心的时候，一句轻飘飘的话语从巷间传来，霎时打破了当下的美好。"
  },
  [313331] = {
    diary_text = "一场突如其来的大雨，令我们匆匆赶回了小院，为这些马上就要盛开的桃花遮风挡雨。今天接二连三的小事不断发生……我突然就睡不着了，思绪乱得很。"
  },
  [313341] = {
    diary_text = "我和他一起分担着彼此的心绪，在相依的深夜里，那场无尽的大雨悄悄停了。第二天阳光明媚，而他也穿上了大红色的婚服来迎娶我，在漫天的桃花林里，他告诉我他最真挚的心意。"
  },
  [313411] = {
    diary_text = "下班回家后我不顾吃饭，急于在直播间抽盲盒，周棋洛对此提出了不满。我解释是因为直播间有一款我心仪的水晶小熊，他听后决定帮我找渠道购买。"
  },
  [313421] = {
    diary_text = "我婉转拒绝了周棋洛的好意，并解释自己更喜欢抽盲盒过程中的期待感，他闻言主动承诺要送我一个惊喜的盲盒体验。跨年这天，这份由周棋洛精心策划的盲盒特等奖出现在了我面前。"
  },
  [313431] = {
    diary_text = "周棋洛神秘地包下专机，带我来到了一个未知的国度。我们来到了当地的跨年集市，在其中的摊位发现了水晶小熊，这时周棋洛却不见了。"
  },
  [313441] = {
    diary_text = "通过他留下的线索和道具，我得知周棋洛希望我能自己肆意享受年末的时光，并暗示他会在这份特等奖的终点等待着我。当时针指向新岁的那一刻，我终于在烟花绽放中看到了那个切切于心的身影。"
  },
  [313511] = {
    diary_text = "我和周棋洛乘船从多瑙河启程，兴致勃勃地讨论着他新年计划筹备的全新形式的演唱会，还决定趁今天采集一些充满想象力的音乐素材，然而伴随低沉的船笛声传来，他却像是听到了意外之“喜”……"
  },
  [313521] = {
    diary_text = "我追随周棋洛的耳朵，和他一起找到了传出歌声的地方——是一家典雅的甜品店小楼。天台上的表演者技艺娴熟，周棋洛和我讲解了这种形式的专业性难度，而沉溺于音乐之中的他总是如此熠熠生辉。"
  },
  [313531] = {
    diary_text = "在与那位表演者交流过程中，周棋洛展现了自己超强的乐器学习能力，引得对方忍不住邀请他一展身手。周棋洛在台上创造了一首即兴歌曲，还悄悄在改编的旋律里藏入了对我的告白，只是聚集的观众也愈发增多……"
  },
  [313541] = {
    diary_text = "我们巧妙地从天台的热闹中抽身，重新去寻找能够激发灵感的音乐素材，路上恰巧遇到了花车巡游，于是在不期而遇的喧嚣里，在新年的人潮之外，他为我献上一份独特的祝福。"
  },
  [313611] = {
    diary_text = "傍晚，我开车来接周棋洛下班一起去机场，前往南方的度假胜地。但我意外发现周棋洛的嘴巴有些红肿，像是唇炎的症状……于是我当机立断，带他去最近的医院看看。"
  },
  [313621] = {
    diary_text = "果不其然，周棋洛真的患了急性唇炎，虽然暂时并不严重，但未来几天需要忌口以及不能亲亲，他对此很是烦恼，并试图投机取巧来亲我，我万不得已，便颁布了一条“亲亲”准则。"
  },
  [313631] = {
    diary_text = "虽然颁布了这条准则，但这人也太会钻漏洞了！开始频繁向我索要亲亲……于是乎，我又重新修正了这条准则，为每日的亲亲增加了次数限制！"
  },
  [313641] = {
    diary_text = "在度假的这几天里，为了下个通告拍摄顺利的同时不二次伤害到周棋洛的嘴巴，我在一家手工店做了一根天然植物口红，正想让周棋洛来欣赏我的成果时，他却忽然吻了下来……"
  },
  [313711] = {
    diary_text = "半夜，我和周棋洛被客厅的宠物交流按钮声吵醒，迷糊中反应过来这是别人暂时寄养在我们家的橘猫——桃酥的手笔。面对它想玩耍的要求，我和周棋洛无法硬下心来抵抗，只得“屈服”。"
  },
  [313721] = {
    diary_text = "陪桃酥玩耍了一会后，它终于酣然睡去。我和周棋洛意识到，我们需要想办法让桃酥不再打扰我们的正常作息。于是次日周棋洛起了个大早寻找解决方案，却屡屡受挫。"
  },
  [313731] = {
    diary_text = "我们决定教桃酥学习新宠物交流按钮，消耗它的精力。一番大张旗鼓的准备后我们正式开始尝试，家中三只宠物却因此而兴奋异常，吵闹无比……"
  },
  [313741] = {
    diary_text = "面对鸡飞狗跳的场面，我们只好重新斟酌按钮的选词。这时我们阴差阳错发现，桃酥居然对毛线团十分痴迷，而周棋洛也意外找到了去年我原打算送他的圣诞礼物……"
  },
  [313811] = {
    diary_text = "在无数次被森林的小动物啃家后，糖果屋已经修得破破烂烂了，我终于下定决心要抓住一只偷吃的“肇事者”，而此时我刚好听到了可疑动静，只是没想到拆我家的……竟然是一位金发美少年！"
  },
  [313821] = {
    diary_text = "他说他叫周棋洛，只是一位普通的吟游诗人。在他轻巧地救下我后，我选择相信那双诚挚的蓝眼睛与他好听的声音。我和他达成了交易，让他留在我的家里帮我修好房子……"
  },
  [313831] = {
    diary_text = "和周棋洛待在一起的时间超过了我的预期，我们之间的关系也愈发亲密。这间糖果屋变得更加完善的同时，似乎也逐渐生出了他的位置，可我依然还不敢离开这片森林，也不明确这些比甜味要复杂的味道到底是什么……"
  },
  [313841] = {
    diary_text = "我答应了周棋洛要和他一起去城里的庆福节游览，那是我第一次走出森林，可是其中最令我心潮澎湃的是他一直都紧紧握着我的手，正当我打算把握机会向他袒露心绪时，他却告诉我他骗了我……"
  },
  [313911] = {
    diary_text = "我深知寂海的可怕传闻，但为了实现在这片海上开演唱会的想法，我毅然决然来到岸边，开始一点点亲身去测试，直到靠近寂海中央，我被巨浪卷入海底时，竟看到一座墓地和一条异常美丽的人鱼，原来那些传闻都是真的……？"
  },
  [313921] = {
    diary_text = "虽然这条名叫1562的人鱼有些淡漠和内向，但在用音乐开启话题后，我发现他简直就是天才，教他的小提琴简直无师自通，只不过当提起普通人和人鱼之间的差异后，他整个人变得紧绷又戒备……"
  },
  [313931] = {
    diary_text = "因为一场高烧，我与1562失约了。同时，一个叫叶辉的中年男子突然告诉我，我就是他们研究所里曾经丢失的“核心”。他们在十七年前曾经通过我，改造出第一例由人类变成人鱼的实验体，而对方就是1562！"
  },
  [313941] = {
    diary_text = "我和1562被研究所重新禁锢起来，直到BS基因改造成果展示会发布的那一天，一切发生了剧变！看着地上蜿蜒着“红色长河”，看着牢笼里的1562，我的心被狠狠揪痛着……于是，我慢慢走进笼子，来到了他面前……"
  },
  [314011] = {
    diary_text = "我和周棋洛正在欧洲度假，享受懒洋洋的二人世界的时候，BS发来了一封邀请函，邀请周棋洛去参加某个晚宴——我当然不会让他一个人去！"
  },
  [314021] = {
    diary_text = "宴会上，Hephaestus向我们介绍了BS的一些在欧洲的投资家族，然而对方和我们接触时他们身上那股的傲慢让我和周棋洛忍不住直吐槽……"
  },
  [314031] = {
    diary_text = "等这帮人被我们噎得无话可说走开时，我们终于可以歇一口气吃点东西了，但不知道是不是因为刚刚遇到了讨厌的人，明明是很精致的餐点，吃起来也没有感觉很好吃呢。"
  },
  [314041] = {
    diary_text = "从烦人的宴会“逃回”酒店，我和周棋洛继续回到了度假的正轨，在享受了他的“叫醒服务”后，他笑着说要不要去参加“午宴”，而且是只有我和他的美食午宴。我忽然发现，明明都是一样的美食，但环境不一样后，口感也变得不一样了呢。"
  },
  [350111] = {
    diary_text = "Savin and Apple Box had been plotting something in the other room for ages. Kiro dragged me along to discover their plans! It turned out Savin wanted Kiro and Apple Box to enter a Pet Competition!"
  },
  [350121] = {
    diary_text = "On the day of the competition, Kiro and I are playing computer games, waiting for the contest to begin. Kiro has a lot more confidence in Apple Box than Savin, who is fretting like a worried parent."
  },
  [350131] = {
    diary_text = "The first stage seemed very tough. Even Kiro was looking panicked there for a while. I didn't know he was capable of embarrassment! Anyway, Apple Box passed the Code Breaker section easily. Everything went wrong in the \"Treats Stage\", however, when a fluffy white Samoyed unexpectedly dropped into Apple Box' course."
  },
  [350141] = {
    diary_text = "I had my doubts Kiro was the \"Hopeless romantic\" he claimed to be. Finally, our silly argument ended when we agreed to have \"Pizza for Dinner\". The owner of the Samoyed turned out to be the old lady Kiro and I met making a TV program. Kiro was happy to see her and proposed going to see her again and taking some cotton candy with us as a gift."
  },
  [350151] = {
    diary_text = "Apple Box lived up to expectation and won the competition. I tell Kiro he did a good job, but that wasn't enough praise for him, so I pull out a pocky and give it to him. He grabbed it out of my hand with his mouth, touching my thumb with his lips... As for Apple Box' amazing performance, Kiro had this to say: Happiness comes with security. There's nothing to fear if every day is filled with happiness."
  },
  [350211] = {
    diary_text = "I got an urgent call from the hospital from Kiro. When I rushed to the hospital and saw him, he held my hand and told me a story."
  },
  [350221] = {
    diary_text = "The story about his fan made me sad. Before I could pull myself together, Kiro announced a plan. I agreed to help with the shoot, but deep down I wondered if this plan really would work."
  },
  [350231] = {
    diary_text = "I thought Kiro was acting on a whim, but it turned out that he had everything ready. I, the \"bride\", was the last piece of the puzzle."
  },
  [350241] = {
    diary_text = "The wedding was held at dusk. I could not see anything behind the red veil, but when I put my hand into Kiro's, I suddenly felt the gravity of this solemn ceremony."
  },
  [350251] = {
    diary_text = "The wedding shoot was over. Finally, we now had the room to ourselves. Being slightly drunk, Kiro was more candid, and I felt closer to his warm heart."
  },
  [350311] = {
    diary_text = "On a rare day off, Kiro and I took Apple Box to the pet store. After his new cute look came out, we both felt he should meet more friends."
  },
  [350321] = {
    diary_text = "Apple Box ran into his dog friend when we arrived in the nearby pet park, so he was already a star in the neighborhood even without our help."
  },
  [350331] = {
    diary_text = "Shortly after we found a place to sit to watch Apple Box playing with his friends, a dog fight broke out on the lawn, and Apple Box rose to the occasion like a superhero, who really deserved an extra can when we got home."
  },
  [350341] = {
    diary_text = "Apple Box got himself all dirty again because of this episode, so we decided to bathe him at home, who was surprisingly uncooperative and splashed us all over with water. The three of us, a drenched family…"
  },
  [350351] = {
    diary_text = "After everything settled down, I found a magazine that did an interview on Kiro and was totally absorbed in it when Kiro crept behind me and slyly suggested a personal interview that would help me know him better…"
  },
  [350411] = {
    diary_text = "Kiro had been unusually quiet after shooting a new movie. I went to his house to check on him, only to realize that he was ill..."
  },
  [350421] = {
    diary_text = "Kiro was probably down with a cold. When I was searching for a cold patch, I noticed some changes in his habits. This baffled me until I read the script of his new movie..."
  },
  [350431] = {
    diary_text = "Kiro was too immersed in the character, so I decided to fill the void in his heart—starting by filling his stomach. I went to buy groceries while he was asleep but soon found that I was followed by two sneaky figures."
  },
  [350441] = {
    diary_text = "When eating hotpot, Kiro retold interesting things that happened during the shoot. As I learned more about what he experienced, I felt sad that I couldn't be there with him..."
  },
  [350451] = {
    diary_text = "Something urgent came up at work. Despite Kiro telling me to go, I returned midway and decided to change the meeting to online. When I got back, Kiro was tying a wool flower on the bald spot on Cello's tail. Surprised by my return, Kiro said he would give me the exclusive performance that I missed."
  },
  [350511] = {
    diary_text = "At a hoity-toity royal feast, I met Kiro. I knew that I would have to get close to him for my mission, but when he got fresh with me, I really got the sense — this guy earned his moniker as a \"dilettante monarch\" alright!"
  },
  [350521] = {
    diary_text = "After three months, I still had no idea where the treasure was that my foster father had me investigating. But after spending time with Kiro, I was gradually warming up to him. This hint of good feelings toward him nagged at me, because I knew it was wrong. While I was playing a flute to lift my spirits, I suddenly heard someone echoing me..."
  },
  [350531] = {
    diary_text = "I never thought Kiro and I could bond over music like this! This made it even harder for me to know how to face him. In the tussle, my jade pendant fell into his hand. To get it back, I snuck into the imperial bed chamber..."
  },
  [350541] = {
    diary_text = "Kiro was none other than my \"Brother Evergreen\"! We used a story to get to know each other, but we didn't dare to speak candidly. The next day, I went back to my room with a lot on my mind, but on the way I saw my foster father."
  },
  [350551] = {
    diary_text = "Great Minister Vance was the real culprit behind everything! I can't believe he'd pulled the wool over my eyes for so long! Thankfully Kiro made it in time and not only had the Great Minister executed, but also brought an imperial edict that caught me totally by surprise..."
  },
  [350611] = {
    diary_text = "I came to an airship for the premiere of a love movie starring Kiro. He had reached out to me before the trailer was released. I managed to resist the jealousy and tried to be supportive..."
  },
  [350621] = {
    diary_text = "I hadn't seen Kiro for a long time until the premiere. I didn't expect that he would do that to me using the shadow onstage...! Kiro expressed his view on love at the event for the first time. I was so moved yet embarrassed. My phone rang at that moment."
  },
  [350631] = {
    diary_text = "Kiro pulled me into the room before I could react. The main crew members were back in the room now and began to talk. Though just next door to them, he didn't care at all even if we may be seen together..."
  },
  [350641] = {
    diary_text = "Kiro seemed to notice that I felt hesitant and confused by his questions. As I tried to hide in the kitchen, he followed me in. I finally confessed to him after seeing how determined he was."
  },
  [350651] = {
    diary_text = "Kiro and I reached the airship lobby by a special elevator. He dragged me on the stage to confide in me. As the elevator rose, my heart beat much faster as if I had climbed to the top of the clouds with him."
  },
  [350711] = {
    diary_text = "Upon my arrival in Bern, the first thing that struck me was how much Kiro, the man I had been longing for, had slimmed down. Even though I knew it was for his role, my heart couldn't help but ache a little. A deeper conversation revealed that his ballet mentor was infamously strict..."
  },
  [350721] = {
    diary_text = "That evening, back at our place, Krio recounted his childhood experiences with ballet training. His descriptions of the stern teacher were both intriguing and humorous, yet they couldn't mask the underlying struggles he endured. Curious, I asked why he would choose to return to the teacher. He explained through an expressive dance."
  },
  [350731] = {
    diary_text = "The following day, after sorting out some work issues, I found Kiro practicing alone in the courtyard. Watching him in that moment stirred an indescribable emotion within me. When he finished, I walked over and gently helped him out of his dance attire..."
  },
  [350741] = {
    diary_text = "After Kiro's ballet class, I had to tell him how impressed I was. It's not easy to keep smiling when you're being pushed both mentally and physically like that... He told me his secret was seeing something that kept him going. I pressed him to elaborate, and he asked me to join him for a practice session the next day."
  },
  [350751] = {
    diary_text = "The next day, as we started our warm-up, I got a call about a tricky problem at work. As I was stressing over it, Kiro, in his unique way, showed me a new perspective, filling me with newfound confidence."
  },
  [360011] = {
    diary_text = "我们公司被悬疑女王萨拉女士看中，于是春节期间，我前往P岛和她商议关于影视改编的事宜，没想到迎接我的却是一群黑手党，以及……他们怎么知道我是QUEEN？"
  },
  [360021] = {
    diary_text = "原来他们想以我为诱饵将BS的BOSS引到P岛，我和大洋彼岸的周棋洛用默契的演技争取了一些时间，本以为他会在白天以BS的BOSS身份前来和黑手党交涉，却没想到他竟然出现在了午夜的窗台……"
  },
  [360031] = {
    diary_text = "我和周棋洛决定趁着夜色将大家都救出来，而萨拉也为我们提供了一条更安全的小路。正当周棋洛开锁时，我却不可置信地发现萨拉举起了枪，指向了周棋洛……"
  },
  [360041] = {
    diary_text = "我和周棋洛分头行动，最后在灯塔碰头，看着他身上的伤，我只觉心如刀绞。萨拉到底是什么人，为什么黑手党要找周棋洛，在一边检查伤口一边互相慰藉时，我们也将彼此心里的疑惑与心情一一像对方说明……"
  },
  [360051] = {
    diary_text = "然而我们并没能在灯塔里躲藏很久，到了傍晚的时候黑手党的搜查已经向着灯塔靠近了。我紧张地表示要和周棋洛并肩战斗，杀出一条血路，周棋洛却表示不想和我搞这么血腥，因为他已经听到了船声——BS的支援终于到了。"
  },
  [360061] = {
    diary_text = "解决了一切后，我和周棋洛乘上了离开P岛的游艇。在船上我们感慨着这一日的刺激经历，也更坚定了我们的心——我们不会像萨拉那样，我们有真正想要活出的人生，不会被任何人摆布。"
  },
  [390211] = {
    diary_text = "On one quiet night, I was writing at the Three Dreams Quarter, when the wind suddenly rose, and the window opened wide, then a man in black barged in and took me away!"
  },
  [390221] = {
    diary_text = "When the man in black finally stopped on a roof in the suburbs, I pulled down his mask and found that he was Kiro! After exchanging pleasantries, he said there was no particular reason for his visit, but he said he would come to me. But for some reason, his detaching himself made me feel low."
  },
  [390231] = {
    diary_text = "At this moment, a group of villagers suddenly came to the clearing below for a celebration. They were happily singing and dancing around the bonfire, reminding me of the wedding celebration Kiro and I passed by when we were kids. I suggested joining in might jog his memory."
  },
  [390241] = {
    diary_text = "Under my persistent persuasion and the villagers' enthusiastic invitation, Kiro finally agreed to dance together. The firelight made Kiro's face seem softer, and the joyful atmosphere also made us relax. Our hearts that had been separated for too long gradually grew closer in the firelight..."
  },
  [390311] = {
    diary_text = "I was attacked by the enemy's Occult during a fight, then Kiro came to my rescue. I was about to thank him when I realized I had been turned into a cat..."
  },
  [390321] = {
    diary_text = "Despite trying everything, Kiro didn't seem to recognize me. As I watched him leave, I had no choice but to employ my last resort—cat hug."
  },
  [390331] = {
    diary_text = "It turned out Kiro knew it was me! He brought me to watch Serenos from up high. Enjoying the view together made me wish time could slow down..."
  },
  [390341] = {
    diary_text = "After some rest, Kiro took me back to Three Dreams Quarter. Seeing my room from a cat's perspective led to many discoveries. And my biggest gain was to have someone else sleeping by my side..."
  },
  [390411] = {
    diary_text = "Upon stepping foot in Shadow Tower, I was informed of the news: Apple's gone missing! And a boy and a girl told me that it seemed to have something to do with Kiro."
  },
  [390421] = {
    diary_text = "On the street, I saw a notice for a missing dog. Just as I was griping about the poor resemblance of the drawing and wondering who drew it, Kiro got an embarrassed look on his face."
  },
  [390431] = {
    diary_text = "At my urging, Kiro agreed to search for Apple with me. As we searched, I seemed to touch upon an anxiety and fear that Kiro had hidden deep down inside..."
  },
  [390441] = {
    diary_text = "We found Apple in the \"secret base\"! Returning here after all these years, Kiro and I both got a bit emotional, and we made good on an abandoned promise."
  },
  [400111] = {
    diary_text = "Colleagues took me to a bar to chill out from work."
  },
  [400121] = {
    diary_text = "I didn't really like the crowd and the thumping music, especially when strangers tried to hit on me. Then I saw Gavin and couldn't believe the lonewolf actually brought a friend."
  },
  [400131] = {
    diary_text = "I left quietly but was cornered in an alley by the creeps who hit on me. I don't even want to think what might've happened had Gavin not come to my rescue."
  },
  [400141] = {
    diary_text = "Gavin brought me to a boxing gym. He was good enough to fight professionally if he wanted to. Under his watch, I put the gloves on for the first time. I took a shot at the punching bag and froze when it swung back toward me! Fortunately, he pulled me out of the way and shielded me."
  },
  [400211] = {
    diary_text = "I was still rattled by what happened last night in the alley, so I decided to text Gavin a thank-you but was shocked to find a note from him asking me out on the weekend."
  },
  [400221] = {
    diary_text = "I got nervous just thinking about the date all week, but I admit I was also full of anticipation. After days of mixed emotions, the weekend finally arrived."
  },
  [400231] = {
    diary_text = "I was so occupied with picking out accessories that Gavin was gone when I was done. In my frenzy to look for him, a shopping cart would've blindsided me if he didn't pull me into him in time. He showed off a plush rabbit that he claimed to resemble me. It was the first time I ever saw a child side in him."
  },
  [400241] = {
    diary_text = "Fantasies ran through my mind as I stared at the models. I laid down on a bed and accidentally touched a button that turned on the star light. It felt like I was in a dream. Gavin slid over beside me and time stopped when our eyes locked. I've never seen such gentleness in someone's glance."
  },
  [400311] = {
    diary_text = "For a new show segment, I went to the police station for a day's ride-along."
  },
  [400321] = {
    diary_text = "I didn't figure to see Gavin there. The attention that a tall, pretty policewoman showered him with was putting the wrong ideas in my head. I stashed away the sandwich I bought for him and avoided him the whole morning."
  },
  [400331] = {
    diary_text = "While Gavin was busy leading the squad, I sneaked into the building occupied by robbers with my camera. A trigger-happy policewoman sparked a firefight. A shot rang out near me as Gavin took out the robber who crept up behind me."
  },
  [400341] = {
    diary_text = "After it was over, Gavin was understandably mad about the dangerous stunt I pulled. He demanded his sandwich but it was squashed, so I decided to make him a meal to atone for my thoughtlessness."
  },
  [400411] = {
    diary_text = "I got Gavin to be the featured guest for the first episode of new show, but then received another anonymous express letter in the studio."
  },
  [400421] = {
    diary_text = "It was from a secret admirer. I thought about telling Gavin, but didn't because it might be just a prank. The Gavin was certainly a different person on camera than he was off."
  },
  [400431] = {
    diary_text = "He demonstrated self-defense techniques live, but I kept feeling another pair of eyes watching me. A man in black followed me after the taping. It was the anonymous guy who sent the letters! Gavin eventually found me and subdued the perv. I thank my lucky stars he was always around when I needed him the most."
  },
  [400441] = {
    diary_text = "The stalker turned out not to be a perv but a crazy fan. Gavin chatted with me and gave me a private lesson in self-defense. His company settled me down. I thanked him for being there, and he said he had always been by my side, even when I didn't see him."
  },
  [400511] = {
    diary_text = "Gavin called tonight to ask how I've been. I went to sleep feeling so sweet inside."
  },
  [400521] = {
    diary_text = "I worked as the director of the press conference for Kiro's new album the next day, only to have Gavin show up when I was fiddling with Kiro's tie! He wanted to talk to me so we went to somewhere private."
  },
  [400531] = {
    diary_text = "Gavin insisted more security for the conference and divulged he was looking into a case involving Kiro, who must've heard his name and started addressing Gavin. Soon enough, chaos ensued and I was knocked off the stage by some crazed fan, but Gavin caught me. The man sure knew when I was in danger."
  },
  [400541] = {
    diary_text = "Kiro thanked me but for some reason I recalled the warm embrace. I went to Gavin trying to explain and almost tripped again. He grabbed me in one fell swoop into his chest. All my worries and anxieties vanished as I listened to his powerful heartbeat. He just has the knack for making me feel completely safe."
  },
  [400611] = {
    diary_text = "I was sick but I insisted on coming to the taping. The romantic set reminded me of my time with Gavin yesterday."
  },
  [400621] = {
    diary_text = "Gavin came to pick me up from work. He gently corralled me around the waist and as our faces inched closer... I sneezed. He took me home and told me to take days off to recover."
  },
  [400631] = {
    diary_text = "I was so out of it, I found more than 10 unanswered calls from Gavin on my phone. I called back but couldn't get through. When Gavin came to the studio, he gave me no chance to refuse before hoisting me over his shoulder and carrying me out as the crew watched. Embarrassing, but kind of sweet too."
  },
  [400641] = {
    diary_text = "He threw me on the bed and asked if I forgot something. As he lowered his head I remembered the unfinished kiss from yesterday. I closed my eyes nervously, and when I opened them again, he already tucked me in. I could sense the warm, caring heart that beat underneath his cold exterior."
  },
  [400711] = {
    diary_text = "As soon as the taping was over, I rushed to meet Gavin for our dinner date. He called to remind me to be careful and get there in one piece."
  },
  [400721] = {
    diary_text = "I got there and couldn't believe the always-casual Gavin was in suit and tie! I teased him but he pretended to be mulling over the menu. A little bashful, was he? But frankly, he looked FINE!"
  },
  [400731] = {
    diary_text = "We went for a stroll in the park after dinner. He got deathly serious when he noticed we were being followed. He told me to run while staying behind to cover my escape. I ran like a lunatic, but one full of anxiety and guilt for leaving him."
  },
  [400741] = {
    diary_text = "I got help from cops and went back for Gavin. His bloody face made me cry out loud. I took him home and dressed his wounds. I felt so terrible seeing how tired he was. Still, he pulled me close and said he now had a meaning in life. I guess I do too."
  },
  [400811] = {
    diary_text = "Gavin took me to visit his old high school teacher, who apparently looked and acted the same as he ever was."
  },
  [400821] = {
    diary_text = "I never would think a master of hookey in school could have a great relationship with a teacher like Mr. Keller. Gavin hid his true profession from Mr. Keller, probably because he didn't want Mr. Keller to worry about him."
  },
  [400831] = {
    diary_text = "We meandered the campus and saw a student bully another. Gavin quickly stepped in. I flashbacked to the alley. He explained the story and now I know the truth! I found the more I know about him, the more wrong notions I had about him go away."
  },
  [400841] = {
    diary_text = " We wandered into the school music hall. He smirked lightly listening to me playing the piano. I asked him why, and he said he was jumped by a mob of gangsters here. He had no idea where they are now. I played the tune from seven years ago again and he smiled at me."
  },
  [400911] = {
    diary_text = "For the carnival, I specifically picked out matching outfits for me and Gavin. But he didn't wear his, complaining it was ugly!"
  },
  [400921] = {
    diary_text = "He took a long call when we were on the ferris wheel. I sat through the ride quietly and alone, all the while feeling I hit rock bottom."
  },
  [400931] = {
    diary_text = "We ran across a boy who was lost, so I took him all around the carnival, with Gavin following behind us, and forgot about the inauspicious start for a while. My personal cop showed off his skills and won the happy boy a prize in a shooting game. That did serve to smooth things between us."
  },
  [400941] = {
    diary_text = "The little boy was a conduit. After we dropped him off safely, Gavin took me to a place and when I opened my eyes, I saw fireworks! Turned out the boy told him I wanted to see fireworks. The previous displeasure I had with Gavin all went away in an instant."
  },
  [401011] = {
    diary_text = "Gavin, who was nowhere to be found for several days, suddenly showed downstairs at my house."
  },
  [401021] = {
    diary_text = "He wanted to take me somewhere, putting a helmet on me and sitting me on the back of his motorcycling before I could even answer. What exactly was he up to now?"
  },
  [401031] = {
    diary_text = "Gavin brought me to the mountain top for stargazing. It was a starry night. He pointed at the brightest one and said that is Jupiter, guardian of the moon. He held me up by the waist toward the sky and, with indescribable lovingness, told me he is my Jupiter."
  },
  [401041] = {
    diary_text = "I told Gavin about the self-defense topic for tomorrow's show. He then simulated a kidnapping with me that scared the bejesus out of me! Afterwards, he made it clear I would never be in any danger because he would always be there to protect me. At that moment, his eyes shined like stars in the sky..."
  },
  [401111] = {
    diary_text = "It was one hour till the firework show starts when Gavin and I left the restaurant in disgust. Having the worst gourmet meal at an alleged top restaurant was the most regrettable thing all year."
  },
  [401121] = {
    diary_text = "As we walked down the festive street, a whiff of delicious food made my belly growl. Gavin told me to stay put and came back with a box of loaded mashed potatoes in no time. He blew on the hot bites to cool them off and fed me with a gentle stare all the while."
  },
  [401131] = {
    diary_text = "We got to the city square only to find out the fireworks show was cancelled here… I was disappointed, until Gavin pulled out a few sparklers for us to light as we were counting down till the midnight. Unfortunately, my phone picked that time to ring and I was needed at work."
  },
  [401141] = {
    diary_text = "It was five in the morning when I got done working. Snow started to fall. I apologized to Gavin since he was due to leave in four hours. Without a word, he grabbed my hand and pulled me off to see sunrise. As the sun slowly ascended above the horizon…"
  },
  [401211] = {
    diary_text = "Got an urgent assignment in Japan, but the flight was delayed when I got to the airport."
  },
  [401221] = {
    diary_text = "A thunderstorm was holding up schedules all around. I supposed I was running around like a chicken with its head cut off when I happened to see Gavin. The warmth of his hands settled me down."
  },
  [401231] = {
    diary_text = "Something happened outside for Gavin to stride toward a crowd. The storm intensified and I found myself greatly concerned for him."
  },
  [401241] = {
    diary_text = "The sun re-emerged soon enough and it was sunny again. Gavin came back and I felt relieved. We said our goodbye and he quietly watched me board."
  },
  [401311] = {
    diary_text = "I went to meet an aunt whom I had not seen in a very long time in a restaurant. But I was surprised to find it was no ordinary meal but a mini-banquet!"
  },
  [401321] = {
    diary_text = "I turned down a date with Gavin for this, but I didn't know Aunt Susan had actually set this up as some sort of blind date for me… I couldn't believe this was what I missed Gavin for."
  },
  [401331] = {
    diary_text = "I certainly didn't think Gavin would show up as I was chatting with the blind date! Minor was such an instigator and made it the most unbearable lunch I'd ever have."
  },
  [401341] = {
    diary_text = "I saw Gavin's countenance gradually soured and he eventually left my sight. When I went to look for him, he grabbed me and pulled me into him…"
  },
  [401511] = {
    diary_text = "The message from my aunts to bring my boyfriend back home for New Year's caught me completely off-guard. I had lied about it to get out of stupid blind dates they tried to fix me up with. Minor, though, gave me the idea of getting someone to pass off as my boyfriend and I immediately thought of Gavin."
  },
  [401521] = {
    diary_text = "So, a Gavin dressed in suit and with gifts in hands showed up at their door on New Year's Day. He actually handled my relatives' interrogation quite well. I was very appreciative, but he held my hand and told me he cared about making a good impression on them."
  },
  [401531] = {
    diary_text = "At dinner, they asked Gavin about his family and he admitted that he hasn't seen them in years. An awkward pause followed and I reflexively defended him. Later I saw him tired and weary in private. I told him he could lean on me. He took my hand and kissed it."
  },
  [401541] = {
    diary_text = "Later still, Gavin confessed that he had not feel like part of a family for too long, and that he would stay with me and care for me for the rest of his life. I learned on our way home that Minor taught him to say all that, but he embraced me and told me that was truly how he felt."
  },
  [401611] = {
    diary_text = "Gavin was already waiting for me to get off work. I tried to play a prank but it backfired. He saved me again and, seeing I was under-dressed, wrapped me in his big, warm jacket."
  },
  [401621] = {
    diary_text = "As we walked hand-in-hand, I suddenly felt the scar on his palm. I decided I'd buy him a pair of gloves. The way he held me and cherished his gift filled me with sweet joy."
  },
  [401631] = {
    diary_text = "I saw a dress I liked that Gavin said he'd buy for me, but the price tag was way too high, so I dragged him to a coffee shop and we shared a Valentine's Special. It was very nice."
  },
  [401641] = {
    diary_text = "Gavin noticed I was limping and bought a band-aid for my heel. At a fountain, we tossed coins and made wishes. He carried me home, leaving me a Valentine's Day gift-- that dress!"
  },
  [401711] = {
    diary_text = "With the New Year just passed, I had my first piece of good fortune. My application to observe the Loveland City SWAT team practical skills exercise was finally accepted. Looking at the venue before me, I was feeling really excited."
  },
  [401721] = {
    diary_text = "I never expected that I would see Gavin at the training ground. Called \"The Star of SWAT\", he fired off ten rounds and all ten hit their mark. He really was incredible. When he saw me, he looked excited, but because he was so busy, like the wind he quickly disappeared again into the army of people there. Knowing that he was there, I felt completely at ease."
  },
  [401731] = {
    diary_text = "While Gavin was having a break, he taught me how to shoot. In that instant when his body and mine made contact, my mind went completely blank and my heart went wild. But seeing how serious he was about teaching me, I calmed down again, and I even hit 7 rounds! I felt a little concerned about whether or not Gavin got so intimate when he was teaching others, but thankfully he said he only ever gave private lessons to me. That made me happy."
  },
  [401741] = {
    diary_text = "At this place, I saw Gavin's past. Gavin had told me before about his stories with the police dog Farley. I also talked to him about my father dying, and once again we got to know each other a lot better. But the most memorable part was that kiss from Gavin. It was all like a dream. Did it really happen?"
  },
  [401811] = {
    diary_text = "I had to work on weekends, so I had to get up early. When I woke up, I received a message from Gavin, who proposed to drive me to the shooting scene."
  },
  [401821] = {
    diary_text = "Today's program was about pranking. The stage director delivered a tray of mustard flavor biscuits to Gavin but as a super fan of spicy food, he ate them as if nothing happened."
  },
  [401831] = {
    diary_text = "As I tied up Gavin's hair, he woke up from a nap. Faced with his question, I lied to him that I was tidying up his hair. With a All Back hairstyle, he appeared to be differently handsome."
  },
  [401841] = {
    diary_text = "Gavin and I were locked in the dressing room. To relieve my uneasiness, he proposed to braid for me. As he got closer, the light veiled my flushed face but my heartbeat betrayed me."
  },
  [401911] = {
    diary_text = "I paced around the gym for a long time and still couldn't find an empty place. Just as I was planning to give up and leave, I ran into Gavin. He invited me to play some outdoor sports-- basketball!"
  },
  [401921] = {
    diary_text = "Saturday we arrived at the court as agreed. The court was packed, and my fear of the ball made me hesitant to get out there. As I was trying valiantly and awkwardly to learn, Gavin suddenly grabbed my wrist and started teaching me..."
  },
  [401931] = {
    diary_text = "I never thought we'd encounter people who would try to knock us off the court. To keep our practice court, Gavin played three on one and made the winning shot to keep the court. This was the first time I realized that Gavin could be so fierce when he played basketball..."
  },
  [401941] = {
    diary_text = "After finally getting to have a rest at halftime, a flying basketball threw me off my game. But I didn't give up, and after a lot of practice, I finally attained my goal today. I got a ball in the net! I thought that Gavin had long forgotten the thing I said before about being afraid of basketball, and the time we met in the gymnasium, but it turns out..."
  },
  [402011] = {
    diary_text = "Anna told me about this mysterious cooperation in the morning. The famous photographer worldwide wanted to work with us! I gladly agreed, but there's a test waiting."
  },
  [402021] = {
    diary_text = "Based on the high requirements, there's no way to find a suitable model in the industry . Minor reminded me of Gavin who seemed to refuse the limelight, but I dared not ask. Unexpectedly, Gavin agreed, and said I could ask him directly."
  },
  [402031] = {
    diary_text = "The photographer was impatient and ill-tempered. I was worried Gavin wouldn't be able to stand him. But Gavin did as he was told. I was asked to be a model, but the clothes were very revealing. To protect me from being more embarrased, Gavin took me away."
  },
  [402041] = {
    diary_text = "When taking off my clothes, the zipper got stuck, so I had to ask Gavin for help. The atmosphere was subtle and intimate. Suddenly, the power was off. Gavin held me tightly in his arms, asked me to protect myself, and said I can only wear such clothes in front of him."
  },
  [402111] = {
    diary_text = "On Gavin's birthday, I arrived at his place early, but to my surprise, nobody was home. As I was getting nervous about what to do, he appeared looking totally shocked!"
  },
  [402121] = {
    diary_text = "After finding out that Gavin's kitchen didn't even have salt, we went out to a supermarket. As we were preparing to leave, he made a stubborn request in the children's section."
  },
  [402131] = {
    diary_text = "Preparing his birthday meal had some hitches, but when the first course finally came out, it succeeded in capturing Gavin's stomach. I want to do this every year from now on."
  },
  [402141] = {
    diary_text = "After dinner, I put the eye mask I had prepared on Gavin. I wanted to give him a back massage, but to my surprise he pulled me to the couch and made a birthday wish from his heart."
  },
  [402211] = {
    diary_text = "I overestimated my bravery agreeing to learn surfing with Gavin, and as a result I almost got knocked unconscious by a huge wave..."
  },
  [402221] = {
    diary_text = "I finally got to see Gavin surf, and it was unforgettable. That night, we went to the beer festival concert, but Gavin and I didn't seem to have the same taste in bands…"
  },
  [402231] = {
    diary_text = "A little incident led to one of my fantasies coming true: seeing Gavin play bass live. I couldn't resist crying out \"Gavin, I'm crazy for you.\" I just don't know if he heard..."
  },
  [402241] = {
    diary_text = "By the moonlit lighthouse, Gavin and I were both a bit tipsy. I boldly lunged for him and told him how I really felt. Gavin laughed as he held me tight and soothed all my worries."
  },
  [402311] = {
    diary_text = "Gavin and I had made a date to see a play, and we happened to meet Mr. Keller from high school. It turns out he wrote the script, but it seemed like something was bothering him..."
  },
  [402321] = {
    diary_text = "Sitting backstage, I suddenly realized Mr. Keller need us to fill in as actors, and we actually found something of our old selves in the story..."
  },
  [402331] = {
    diary_text = "This was the first time I'd seen Gavin dressed up in traditional clothes. I was dumbstruck. But an unasked question and a broken wire crisis overwhelmed my tear ducts..."
  },
  [402341] = {
    diary_text = "At the fair, I was really looking forward to the lantern show. I bought a veil and a mask, and I finally asked the question that had been on my chest the whole evening..."
  },
  [402411] = {
    diary_text = "On the day when Gavin and I promised to meet and he would take Pearly back... I never thought he would be late until the night fell..."
  },
  [402421] = {
    diary_text = "When I murmured to myself with Pearly, Gavin suddenly appeared by the window, weary and a hard smile on his face. I couldn't help but worry..."
  },
  [402431] = {
    diary_text = "Gavin and I were making a new whistle for Pearly. In a world of colors, Gavin wrote my name on his window, declaring my domain over his world..."
  },
  [402441] = {
    diary_text = "Pearly wearing the new whistle looked like an emperor. Was it the freedom he really wanted? What I pursued was the freedom to embrace the sunshine and wind. Could I get it one day?"
  },
  [402511] = {
    diary_text = "I wanted to bring Gavin to see the double rainbow I saw in front of a church years ago, so I set a date with him. We were excited even though we didn't know if we could manage to see it."
  },
  [402521] = {
    diary_text = "Our plan was upset by heavy rains on consecutive weekends. On the third weekend, Gavin took me to the church regardless of the weather because it would undergo maintenance soon."
  },
  [402531] = {
    diary_text = "The weather cleared up by the time we arrived, and we also saw a rainbow but the church had been sealed off. A granny invited us to wait for the double rainbow in her glasshouse garden."
  },
  [402541] = {
    diary_text = "Gavin and I watered her flowers to thank her for the flowers she gave us. Finally, we saw the double rainbow. Gavin even made me a triple rainbow miracle. We blessed each other and kissed under the triple rainbow."
  },
  [402611] = {
    diary_text = "As it was my first time playing paintball, everything in the club was interesting to me. When talking with Gavin, I remembered the first time he took me flying and me looking forward to the coming brand new experience."
  },
  [402621] = {
    diary_text = "Although I was clumsy, under Gavin's instruction, I slowly learned how to reload the gun. Stunned by what Gavin said, I made up my mind to always fight with him shoulder in shoulder."
  },
  [402631] = {
    diary_text = "We decided to participate in a 2v2 battle. To protect me, Gavin wanted to look for the hidden enemies himself but I insisted on going together with him. When approaching the opponents' hiding place, we were suddenly attacked..."
  },
  [402641] = {
    diary_text = "We hid behind a section of wooden pillar and Gavin told me his plan. At the right opportunity, we fought back together perfectly and ended up with a victory. In the warm light, I leaned on Gavin's chest and confided to him my thoughts..."
  },
  [402711] = {
    diary_text = "With Gavin's likes in mind, I planned a trip with lots of exciting water activities. First up was snorkeling, but I never expected I'd throw in the towel so soon."
  },
  [402721] = {
    diary_text = "After nearly drowning myself snorkeling, I was still determined to do the jet ski. But yet again, I had to raise the white flag."
  },
  [402731] = {
    diary_text = "At Gavin's request, we decided to sight-see on the island. While I was taking Gavin's picture, a little girl passing by mistook him for a movie star."
  },
  [402741] = {
    diary_text = "On the last day of the trip, it dawned on me that Gavin didn't like the activities I'd planned. When he asked me about my choices, I finally came clean with him."
  },
  [402811] = {
    diary_text = "The company's Valentine's Day proposal was \"Group Fairytale Wedding\". Since a couple couldn't make it, I had to take their place. But my original partner Minor stood me up that day."
  },
  [402821] = {
    diary_text = "Minor said that he prepared me a surprise though he couldn't come. I was still confused when I heard a familiar voice behind me. Turning around, I saw Gavin in a white suit. There was a pair of Crystal Shoes in his hands."
  },
  [402831] = {
    diary_text = "My shooting location was on the third floor of the castle. I'd been secretly looking at Gavin through the veil. Although the wedding was fake, my palpitation and nervousness were real."
  },
  [402841] = {
    diary_text = "As the shooting began, Gavin moved closer to me, released the balloons as planned, and put his hand around my waist. I could see the smile in his eyes."
  },
  [402911] = {
    diary_text = "I looked for Gavin's figure in my memory, but he disappeared in the thick fog. As the fog cleared, I realized I was back in high school, and saw Gavin who was skipping class..."
  },
  [402921] = {
    diary_text = "Gavin was confused and shocked when he saw me, and in a hurry, I lied that I was my cousin and asked him where I was. He barely believed me, but told me where I was then disappeared. Students passing by told me that he was besieged outside the school, so I rushed over."
  },
  [402931] = {
    diary_text = "Many people were on the ground in the dark alley. Gavin was injured and when I found him, he left again without looking back. I met him again in the piano room and persuaded him to go to the infirmary."
  },
  [402941] = {
    diary_text = "Suddenly, the image faded, and time and scene changed again. I suddenly understood something about the bloody letter, and finally found Gavin whom I had been waiting for a day in the library."
  },
  [403011] = {
    diary_text = "On Saturday evening, Gavin came over to my house as promised. I kept him guessing and led him to the kitchen, ready to reveal the \"surprise\" I prepared for him."
  },
  [403021] = {
    diary_text = "After learning I would be teaching him how to cook, Gavin seemed reluctant, but accepted the request anyway. Gavin seemed to know how to cook, so I went to the supermarket."
  },
  [403031] = {
    diary_text = "I only left for a while but came back to find the kitchen in a mess. Turned out Gavin's eyes were irritated by the onion, so he failed to attend to the food in the pan, which ended up burnt. Since there was not much time left, I had to cook myself."
  },
  [403041] = {
    diary_text = "Finally the last dish was done. Although the dishes looked so-so, they tasted great. I cheered up and enjoyed the cozy meal with Gavin."
  },
  [403111] = {
    diary_text = "It was still snowing in early spring in Loveland City. In pursuit of the truth behind the heavy snow, I followed the missing cases to West Harbor, only to inadvertently get lost in my memory with Gavin."
  },
  [403121] = {
    diary_text = "Loveland City was peaceful back in the days, and I visited an immersive theater with Gavin. We saw a lot of paper planes on the theater's terrace. When we talked about our high school days, a long-lost appellation escaped my lips..."
  },
  [403131] = {
    diary_text = "In the theater, I accidentally parted with Gavin and was in crisis. Luckily he showed up in time and managed to piece the truth of the story together. In the sunset, Gavin stood by the long steps, looked back at me, and we walked out of the theater hand in hand."
  },
  [403141] = {
    diary_text = "When I finally arrived at the harbor, I accidentally fell into the other dimension during my investigation. Just as I was lost, a small paper plane brought me out of danger. Gavin saved me again, which ensured me that our bond always existed, albeit yet to awaken."
  },
  [403211] = {
    diary_text = "With two plane tickets, I lured Gavin to the airport on his birthday. Despite being aware of my lame lies, he still came to me with change of clothes anyway."
  },
  [403221] = {
    diary_text = "We made it to LA without a hitch, only to find that I booked a wrong hotel room…"
  },
  [403231] = {
    diary_text = "Gavin took me into his arms happily while we waited at the arena entrance, and I was so happy that he liked the gift. He told me a lot about his basketball idol, and why he started practicing dunking back in the days. It turned out that I was always there in his memories during our lost time."
  },
  [403241] = {
    diary_text = "Gavin showed me his dunk after the game, and that dunk would be forever engraved in my memory. We celebrated his birthday back in the hotel and he made a wish to me again. I hoped that he felt my sincerity in the last little gift."
  },
  [403311] = {
    diary_text = "这是我和白起重逢之后，第二次因为工作之外的理由出来见面，而我们对于约会要去做什么这件事，产生了一些理解偏差……"
  },
  [403321] = {
    diary_text = "我和白起人生里的第一次钓鱼体验正式开始，我们决定把每年的今天都定为“钓鱼纪念日”。"
  },
  [403331] = {
    diary_text = "虽然选了一个相对阴凉的位置，但夏天的温度还是让我不由心浮气躁起来，就在这时，一阵清风拂面而来。"
  },
  [403341] = {
    diary_text = "等了许久，平静的湖面上随即以上下扑腾的浮标为圆心，泛起了圈圈涟漪，但白起一鼓作气钓上来的“猎物”居然是……"
  },
  [403411] = {
    diary_text = "It was the second time I went out with Gavin for reasons that are not work-related after our reunion and we had a slight misunderstanding on what we were going to do for the date..."
  },
  [403421] = {
    diary_text = "It's the very first fishing experience for both me and Gavin, so we decided to make the day our 'Fishing Anniversary'."
  },
  [403431] = {
    diary_text = "Although it was a relatively shady spot, I still became impatient and flighty in the summer heat. Just then, a fresh breeze hit me."
  },
  [403441] = {
    diary_text = "After a long wait, the still lake rippled as the fishing float bobbed, but the 'prey' Gavin fished was actually a..."
  },
  [403511] = {
    diary_text = "The company organized a Double Seventh event and due to an incident that occurred, I had to fill the resulting vacancy. Just as I was thought that I might miss my date with Gavin, he suddenly showed up..."
  },
  [403521] = {
    diary_text = "The train reached a fork in the road and we had to make a decision whether or not to stay on it. Getting off the train, I gave Gavin the token 'Lily', and told him that it belonged to only him. Gavin was surprised a moment, then smiled and pulled me onto the train."
  },
  [403531] = {
    diary_text = "We had a 'flipped' moment at the gangway that made me blush. After getting off the train, we arrived at the tunnel the staff mentioned about. In the dark, I told Gavin what I hadn't had time to finish telling him on the train and received his earnest response. We seemed to become closer than ever."
  },
  [403541] = {
    diary_text = "Finally, we reached the destination. After successfully imitating movie clips, Gavin flew me to the roof of the train and only did I realize that the 'shortcut' route at the fork was a dead end. I was even more surprised to know that Gavin's token was an aviation badge. He could actually fly a plane! What touched me even more was the reason behind him giving me the badge..."
  },
  [403611] = {
    diary_text = "I receive an invitation to a book launch for one of Gavin's favorite crime writers. Sadly, he can't accompany me, and I become lost in my thoughts... when suddenly the fire alarm goes off."
  },
  [403621] = {
    diary_text = "I bump into Gavin at the Police Station while collecting a witness statement. He's on a mission and isn't able to join me at the book launch that evening. I'm disappointed because I haven't seen him in ages, so I suggest we go out and grab a meal together."
  },
  [403631] = {
    diary_text = "We haven't eaten at the Lynn's Kitchen in a long time. The familiar smells and friendly faces fill us with nostalgia and leave is feeling warm and content. We discuss the recent spate of fires in the city and Gavin warns me to take care."
  },
  [403641] = {
    diary_text = "The book launch is about to start. Gavin calls me to tell me the arsonist's next target is the Conference Center! The signal is bad and we lose contact. Thinking quickly, I smash the fire alarm in the foyer..."
  },
  [403711] = {
    diary_text = "Things weren't going well and I was feeling melancholy these days. Gavin seemed to notice that I was down and invited me on a weekend stroll."
  },
  [403721] = {
    diary_text = "Gavin brought me to a quiet park on a bike. I felt better in nature and also a bit excited as it was rare for us to go out together on a bicycle."
  },
  [403731] = {
    diary_text = "We folded paper boats under the tree. Gavin told me that paper boats carrying lit candles could bring messages to our loved ones who passed away. Would that really work?"
  },
  [403741] = {
    diary_text = "I fell asleep using Gavin's thigh as pillow. Night fell. The boats, carrying warm flames and our yearning for our loved ones, set off on their journey to somewhere far, far away..."
  },
  [403811] = {
    diary_text = "I was living alone near the deserted city. I encountered an exorcist one day and decided to assist him with the investigation of his missing comrade."
  },
  [403821] = {
    diary_text = "As the legend goes, a devil will appear on the full-moon night, so Gavin and I decided to explore the city tonight."
  },
  [403831] = {
    diary_text = "Out of expectation, his comrade showed up! To chase after him, we were led to and carelessly locked in the toppest building of the city, the tower."
  },
  [403841] = {
    diary_text = "In blood-red recollections, the devil showed up at last, while Gavin and I were faced with hard choices. When I made the step to the outside, would the swaying hyacinth bloom as promised?"
  },
  [403911] = {
    diary_text = "Gavin and I got on the snowmobile early in the morning and our Christmas trip began. The accelerating snowmobile against the soft white snow added thrills to this romantic festival."
  },
  [403921] = {
    diary_text = "We nestled together in the mountain rest area and in the rising sun, the memories I spent with Gavin emerged. Enjoying and relaxing with our fingers intertwined was happiness."
  },
  [403931] = {
    diary_text = "After making a snowman together, Gavin tossed the snowflakes on the ground into air. In the shining ice crystals and blowing wind, our Christmas was sealed in the crystal ball of memory."
  },
  [403941] = {
    diary_text = "I fell down when driving a snowmobile but this thrilling experience became an interesting one under the protection of Gavin. Am I getting closer to Gavin, trying new things and becoming braver?"
  },
  [404011] = {
    diary_text = "I received a call from Ms. Zheng, a teacher of Loveland High whom I hadn't heard from in many years. She told me the renovations to the school building were completed, which reminded me of one summer day when Gavin and I went back to the school together..."
  },
  [404021] = {
    diary_text = "Gavin and I returned to Loveland High once again. However, the alumni gathering became a bit awkward after he showed up, as quite a few schoolmates had misunderstandings about him. This upset me a lot, and I couldn't help but defend for him..."
  },
  [404031] = {
    diary_text = "After a group photo, I asked Ms. Zheng for the band's yearbook, but she surprised with a \"request.\" She wanted Gavin and me to play a song for her!"
  },
  [404041] = {
    diary_text = "Gavin and I searched around in the greenhouse for the box that had the yearbook inside. Finally, I found the box, but it almost fell on me. Luckily Gavin showed up and saved me. When we opened the yearbook, all the good old memories were brought back to us. I pasted the group photo inside and asked Gavin to also write something there..."
  },
  [404111] = {
    diary_text = "On some rare time off, Gavin and I go hit the slopes! The sunshine is amazing today, so warm and cozy."
  },
  [404121] = {
    diary_text = "I feel so bright and cheery looking out over the majestic view, holding hands with the most important person in the world to me. I hope Gavin can feel it too through the warmth in my palm."
  },
  [404131] = {
    diary_text = "I actually developed a talent for skiing! Even the very first try was a success! Of course, I did crash into Gavin, so I can't say it was a total success..."
  },
  [404141] = {
    diary_text = "Not only did Gavin carry me exhausted back to the car, he even thoughtfully changed me into a pair of dry socks. As the sun set, I leaned on his shoulder, wishing this moment would last forever."
  },
  [404211] = {
    diary_text = "Gavin and I saw a beautiful water fountain, but I didn't notice the steps and almost tripped. Gavin caught me just in time and said no matter what happens, he always will."
  },
  [404221] = {
    diary_text = "At a park near the fountain, there was an amateur relay race, which we were invited to join. I wanted to say no, but with Gavin's promise not to drop the baton, I finally agreed."
  },
  [404231] = {
    diary_text = "The race began! Focusing on Gavin up ahead, I felt a surge of strength and ran faster than ever! Gavin grabbed the baton when our hands touched, running on to take first place!"
  },
  [404241] = {
    diary_text = "As Gavin wiped his brow, he stared at me. Deep in his eyes, I suddenly understood his assurance, determination, and faith; and I knew he would always catch me if I fell."
  },
  [404311] = {
    diary_text = "After working overtime, it was raining once again. As I shielded two little cats from the rain with my umbrella, I found Gavin's umbrella over my own head."
  },
  [404321] = {
    diary_text = "I invited Gavin to the mountain, but the view was covered with mist. Back at our cabin, while it drizzled outside, I found a guest book."
  },
  [404331] = {
    diary_text = "The rain caused an unexpected disaster, and the owner asked Gavin for help. I waited in the cabin for a long time before finally deciding to go find him."
  },
  [404341] = {
    diary_text = "The rain fell harder, but with Gavin by my side, I felt alright. We huddled together, and between the freezing rain and his warmth, we formed a new rainy day memory."
  },
  [404411] = {
    diary_text = "I secretly arranged a couple photoshoot. Worried that Gavin might be unwilling to get on board, I asked Willow to be my \"wing girl\". To my surprise, Gavin gave me a quick yes."
  },
  [404421] = {
    diary_text = "Gavin and I tried very hard to express our feelings in front of the camera, but the photographer was not impressed. During the break, I had the idea to fix Gavin's makeup..."
  },
  [404431] = {
    diary_text = "I finally received the photos, which I was very pleased with. I couldn't wait to share them with Gavin, who happened to be back from his mission. We came to his house and came up with a new definition of \"home\"..."
  },
  [404441] = {
    diary_text = "As we were sorting this year's photos together, Gavin fell asleep. Since he had been overworked and needed the sleep badly, I decided not to disturb him. Even so, I couldn't help getting up to a little mischief. Before I could complete my prank, Gavin grabbed my hand..."
  },
  [404511] = {
    diary_text = "When I finished the outdoor shooting, I found out that Gavin had been waiting for me outside. Gavin not only asked me out for dinner, but he also asked me for a favor."
  },
  [404521] = {
    diary_text = "On the weekend, Gavin took me on Sparky to a greenhouse. The place was like a paradise in a residential area. We both felt out of our depth in taking care of the various plants. The first step was to find the gardening tools."
  },
  [404531] = {
    diary_text = "We started to water the plants according to the manual left by the owner. This apparently simple task required much care and patience. When it came to the succulents, I found some white spots on a plant. I soon realized what they were..."
  },
  [404541] = {
    diary_text = "To satisfy my curiosity about the owner, Gavin showed me the owner's bonsai trees. It was hard to imagine the rough-looking owner to be the one who nurtured such exquisite plants. Some people may not be good at words, but plants can convey their feelings the same way flowers do. If we ever meet someone who understands us, we should hold on to them and never let them go!"
  },
  [404611] = {
    diary_text = "恋语市游乐园决定举办一场春日游行庆典，原本我打算邀请白起一起来，但他却恰好在这天有工作安排。就在我兴致缺缺地一个人在游乐园游玩时，白起突然出现了。"
  },
  [404621] = {
    diary_text = "我迫不及待地迈出摩天轮跑到白起面前，游乐园的色彩好像因为他的出现而变得明亮。或许每个游乐园都有着让人快乐的神奇力量，最最重要的是……有他在我的身旁。"
  },
  [404631] = {
    diary_text = "游乐园里的每个项目都给我们带来了不同的惊喜，白起渐渐也融入了这里的氛围。当我因为泡沫破灭时的美丽景象感慨时，白起却用泡泡枪为我带来了一场别样的演出。"
  },
  [404641] = {
    diary_text = "没想到会被围观的我们在众人反应过来之前离开了游乐园，虽然没有看成表演有些遗憾，但只要和白起在一起我就已经足够满足。不过我没有想到，最后白起用了这样一种奇妙的方式为我弥补了这小小的缺憾……"
  },
  [404711] = {
    diary_text = "Gavin and I plan to meet at the Coffee House to go through some documents. He calls to say he'll be late. Something's come up."
  },
  [404721] = {
    diary_text = "I overhear two girls talking and rush to a nearby alley. There I find Gavin in a brutal street fight with some thugs! He flattens each one with cold efficiency, cleverly placing himself between me and his assailants."
  },
  [404731] = {
    diary_text = "Gavin takes me to the homes of an old lady where I discover he was protecting her grandson from bullies. Gavin is friendly and polite, a completely different person to the vicious streetfighter I saw earlier. The old lady mistakes us for a couple, causing us both to blush."
  },
  [404741] = {
    diary_text = "As we leave, the old lady hands us a Sugar Figurine as a thank you gift. Walking back, under the soft streetlights, I tell Gavin that I approve of his actions earlier that evening. I encourage him to eat the sweet we've been given. Sitting next to him on the park bench, watching him struggle to eat the lolly, I can't help smiling. Gavin certainly is a man of many faces."
  },
  [404811] = {
    diary_text = "In a cliffside town overlooking the sea, Gavin and I planned the next move of our free-wheeling trip over a lovely breakfast..."
  },
  [404821] = {
    diary_text = "In the end, we decided to drive to a neighboring town. I got the bags packed up, and Gavin pulled up in a sports car..."
  },
  [404831] = {
    diary_text = "A robbery occured while we're on our stroll. We sprung into action, hopped in the car, and gave chase, with me as the navigator. Can I pull it off...?"
  },
  [404841] = {
    diary_text = "Gavin catched up with some ace driving down the winding seaside highway, brought their car to a halt, and subdued the bad guys. After the incident, we continued on our way..."
  },
  [404911] = {
    diary_text = "On the day of Loveland High's school celebration, I snuck off to the piano room. Gavin found me there, and I joked with him about being on duty as \"Outstanding Alumni\" today."
  },
  [404921] = {
    diary_text = "We talked about coming to back to campus, and Gavin seemed to have something on his mind. I took his hand and we played piano together while I talked about school back in the day."
  },
  [404931] = {
    diary_text = "The topic turned to what if Gavin and I had started a relationship in high school. If there weren't all the misunderstandings and going round in circles, high school would've been completely different."
  },
  [404941] = {
    diary_text = "Gavin kneeled on the piano bench, pinning me to the piano. I looked out the window at the dancing gingko leaves and surrendered my all to him."
  },
  [405011] = {
    diary_text = "The dandelions were the same as Gavin remembered, gently swaying along with the wind in the courtyard. Gavin found the spare key within the wall and opened the dust-covered door."
  },
  [405021] = {
    diary_text = "Seeing the dusty room before us, we started to give the old cottage a deep clean and discovered some surprises..."
  },
  [405031] = {
    diary_text = "Faced with a broken washing machine, we decided to wash the bed sheets and curtains ourselves outside. In the sunny courtyard, our teamwork made doing the laundries warm and sweet."
  },
  [405041] = {
    diary_text = "The accidentally-fallen photo prompted Gavin to recount his past. After the weight being lifted off his shoulders, I knew the future awaiting us was boundless."
  },
  [405111] = {
    diary_text = "At the cabin on the cliff, I found out Gavin was also nearby. Just when I decided to sneak away, he caught me and brought me before him."
  },
  [405121] = {
    diary_text = "A few days later, I located the hotel the man was staying in using the Special Task Force's intelligence. Using the building's fire sprinkler system as a cover, I looked for the U disk, but I never thought that Gavin would suddenly break into the room from the window..."
  },
  [405131] = {
    diary_text = "I got the news that the man would leave Loveland City from the port tonight. After planning thoroughly, I suddenly discovered something, so I asked Gavin for help. To my surprise, he came to be by my side at the moment of crisis..."
  },
  [405141] = {
    diary_text = "Finally, we dealt with the man we had been looking for, and I found the U disk I wanted. Before the Special Task Force arrived, Gavin gave me the keys to his car and told me that I could shout his name next time I was in danger."
  },
  [405211] = {
    diary_text = "On the first day of school, it was pouring down with heavy rain, and I was hiding under the same roof with the little stray cat I rescued. Suddenly, a familiar figure put a warm uniform jacket over me."
  },
  [405221] = {
    diary_text = "Gavin was the same as the person I knew—the intimidating bully in our school, the star of the school legends. On a surprise encounter outside school, I found that young Gavin was still the lone wolf he used to be..."
  },
  [405231] = {
    diary_text = "It turned out Minor was often in trouble as a student. This time, he was targeted by a few hooligans who wanted to beat him up, but I couldn't just leave him alone. But the hooligans noticed me as soon as I approached. Just when I asked Minor to leave so that I could sneakily deal with these people with Evol, a familiar figure appeared."
  },
  [405241] = {
    diary_text = "After the crisis was resolved for now, the night had already started to fall. Under Minor's suggestion, the three of us went for noodles at Lynn's Kitchen. Returning to this familiar location with familiar people stirred up mixed feelings in my heart..."
  },
  [405311] = {
    diary_text = "When I arrived at the Holy Mountain, the legendary haunt of the Qilin, I encountered a man clad in white. He bandaged my scrape and told me his name was Gavin."
  },
  [405321] = {
    diary_text = "Gavin took me up to the summit where the Qilin was said to be found, but all I could find was a sheer drop. Suffering the effects of poison, I fell off the cliff, and glimpsed Gavin in his true form..."
  },
  [405331] = {
    diary_text = "Gavin saved me, but the people from the Temple had arrived at the mountain. I decided to go back with them to the Temple to spare Gavin from their prying eyes. Then one night during my captivity, the jade ring Gavin had given to me broke..."
  },
  [405341] = {
    diary_text = "Gavin easily put an end to the disaster, and the village held a big celebration. During the ceremony, Gavin appeared, out of thin air, and asked me if I wanted to go with him. Looking into his eyes, I slowly nodded."
  },
  [405411] = {
    diary_text = "On the last day of our visit, Gavin and I were informed that the shooting location was temporarily closed. We had no choice but to film the university's open day."
  },
  [405421] = {
    diary_text = "Gavin joined the basketball contest for my sake. I was once again dazzled by the Gavin on the basketball court... As expected, he won the biggest doll as the prize. With the giant doll in my arms, my heart was stuffed with satisfaction."
  },
  [405431] = {
    diary_text = "A male student requested to buy our doll. We soon learned that he was the president of the optical fraternity, who wanted to confess his love to a girl. We ended up helping his fraternity attract customers. Out of personal interest, I saw Gavin wearing glasses for the first time."
  },
  [405441] = {
    diary_text = "Gavin chose a pair of glasses for me. His honest compliment was sweet and made me blushed. The male student finally confessed his love with our encouragement. A young and touching love story thus began in our witness..."
  },
  [405511] = {
    diary_text = "The news broadcast on TV was showing that a building collapsed on the outskirts of Loveland at around 10 pm tonight. The city council suggested that the collapse might have been caused by Evol and the Special Task Force had taken part in the search and rescue operation."
  },
  [405521] = {
    diary_text = "I woke up in the pitch dark and felt my head that had been hit, recalling how I had ducked under the corner of the wall the moment the building collapsed. The priority now was to get out of here. I fumbled for my phone in the dark and found two missed calls from Gavin on it."
  },
  [405531] = {
    diary_text = "After learning that I was trapped in the collapsed building, Gavin took his search and rescue dog to the site. He asked me detailed questions about the route I took after entering the building, so as to gauge my current location. When I was close to the light of rescue, the second collapse happened."
  },
  [405541] = {
    diary_text = "Every second felt like years in the dark. When I was almost too exhausted to keep my eyes open. A glimmer of light suddenly appeared. I quickly turned away, then a strong wind soon lifted the bricks and stones around me..."
  },
  [405611] = {
    diary_text = "On the airplane, Gavin and I re-watched a Christmas movie. Soon, we would be landing at our destination: Northern Europe."
  },
  [405621] = {
    diary_text = "It was still early, so after dropping our bags, Gavin and I went for a stroll. In the festive Christmas atmosphere and falling snow, we decided to try some gingerbread cookies."
  },
  [405631] = {
    diary_text = "It was getting later, and as the clock struck, I decided to give my mystery gift -- a reindeer carriage from Santa and a red scarf. I proudly told Gavin I'd embroidered it myself."
  },
  [405641] = {
    diary_text = "The countdown to Christmas in the square was about to start. Somehow, Gavin and I were chosen to press the countdown button! I couldn't believe it, but something about Gavin told me..."
  },
  [405711] = {
    diary_text = "Rumor has it that Little Red Riding Hood and her grandmother were eaten by a big bad wolf, who was then locked up in a castle on the hill. I came to the castle, and instead I met a wolf-earred young man in the depths of the castle..."
  },
  [405721] = {
    diary_text = "The young man turned out to be the big bad wolf “Gavin”! I decided to go ahead with my original plan. With my persistent persuasion, Gavin finally agreed to my plan."
  },
  [405731] = {
    diary_text = "The more I spent time with Gavin, the more I got to know the hidden side of him. It’s full moon tonight. Gavin warned me not to see him on a full moon, but I couldn’t bear the thoughts of him being alone in the castle. So to the castle I went, but I never thought that I’d meet...!!"
  },
  [405741] = {
    diary_text = "Gavin defeated the wizard, but then I found out his long hidden secret! I finally found out where the story of Little Red Riding Hood came from and why Gavin had been locked up in the castle..."
  },
  [405811] = {
    diary_text = "I scratched the glass slippers Gavin gave me, then despite my worry about his mission, I told him I'd take care of Thorny. When I got to Gavin's, I found a fashion magazine!"
  },
  [405821] = {
    diary_text = "Just then, a private-label designer called to tell me someone had ordered a gift for me. With great curiosity, I went to their shop and found Gavin back from his mission."
  },
  [405831] = {
    diary_text = "Gavin's shirt had a tear in it, and I noticed his shoulder was wounded. But he told me it was fine, then asked if I wanted to know what gift he ordered for me."
  },
  [405841] = {
    diary_text = "Gavin took me to a glass showroom in the back of the shop, where I saw my repaired glass slippers. Just to lift my spirits, Gavin brought them here on the night before his mission."
  },
  [405911] = {
    diary_text = "Gavin came to pick me up from work when I was working late for the next day's variety show. He told me to go home and rest, as everything would be fine with him there."
  },
  [405921] = {
    diary_text = "At the shooting site, Gavin joined the contest as a special guest, and I was his director. Gavin led the team to gain one victory after another and won by a landslide, which made an opponent question the rules. In the face of the opponent's resentment, Gavin told him to prove himself in the third game, which would be a single-player match."
  },
  [405931] = {
    diary_text = "Gavin quickly found eleven clues during the single-player match, but the countdown warning began just as we were about to find the last one. Everyone was leaving the building, but I trusted Gavin and followed him deeper into the building. Just as the countdown was about to end, Gavin led me to the clues and managed to leave."
  },
  [405941] = {
    diary_text = "The new recruit who questioned Gavin didn't make it out in time and got rescued by Gavin. At the end of the show, Gavin told the recruits that, instead of victory, the safety of themselves and the others was what mattered most in missions. On the way home, I asked Gavin the reason for saying that, and his answer was related to me..."
  },
  [406011] = {
    diary_text = "In the office, Willow and Kiki tested me on the viral \"relationship sustainability test\", in which I got an incredibly low score. I said that circumstances altered cases and quickly changed the subject, while Minor made a sneaky move behind my back..."
  },
  [406021] = {
    diary_text = "I planned to take the day off for a barbecue with my colleagues in the afternoon to celebrate the success of a project. But for some reason, Gavin suddenly showed up outside the office building and asked me out on a date..."
  },
  [406031] = {
    diary_text = "Since everyone else claimed to be busy, I got on Sparky and went to a large shopping mall with Gavin. Gavin told me he brought me here because Minor said I wanted to do some shopping, but we could also do something else. After understanding Gavin's intention, I told him I was happy as long as I was with someone I liked."
  },
  [406041] = {
    diary_text = "Late in the afternoon, we finally got home with bags of shopping. When I was sorting out the haul of the day, my eyes accidentally caught the unopened nail polish set on the table, then a \"mischievous idea\" came to my mind..."
  },
  [406111] = {
    diary_text = "When I went to pick up my official pilot's license, I saw a small plane land with a familiar figure in the cockpit. When it came to a stop, I saw none other than Gavin waving a hand at me."
  },
  [406121] = {
    diary_text = "Gavin pulled strings with the flight school to give me a surprise. After all, I'd worked so hard, so my graduation day should be special. Now was the time to be his co-pilot."
  },
  [406131] = {
    diary_text = "He started to buckle me up, then suddenly moved me over to the left seat. He said he almost forgot that, now that I have my pilot's license, I could fly solo. Today, he would be my co-pilot."
  },
  [406141] = {
    diary_text = "I told him that I wanted to fly and scuba dive, and scale mountains and traverse deserts, because I had support to rely on in my heart. He told me that he started branching out more because he had a support too."
  },
  [406211] = {
    diary_text = "To make a deal with the thief Gavin, the slave master brought me to his camp. However, I had my secret plan in mind. The king promised me freedom if I could help him get rid of Gavin, so I had to give it a try."
  },
  [406221] = {
    diary_text = "To my surprise, Gavin was not interested in the deal and drove the slaver master out of the campsite. I did everything I could to stay, only to learn that Gavin planned to rob the palace!"
  },
  [406231] = {
    diary_text = [[
I was officially allowed to stay. I observed that Gavin would rob the rich every day and return at night with a full load.
I would treat Gavin's wounds whenever he was injured. Gradually, I found myself unable to carry out the King's order...]]
  },
  [406241] = {
    diary_text = "In a conversation with Gavin, I was deeply moved by his words. A surge of guilt tore me apart. I decided to confess everything to Gavin but never expected that I would be captured by the king again..."
  },
  [406311] = {
    diary_text = "Gavin calls to talk to me about a case, so we arrange to meet at a nearby cafe. As I'm rushing out, I suddenly receive a strange invitation letter."
  },
  [406321] = {
    diary_text = "I tell Gavin about the invitation, and he says it's related to the case. It appears to be advanced notice of a crime, and from the vague details we guess the criminal's location."
  },
  [406331] = {
    diary_text = "Gavin takes me to the planetarium. We end up borrowing a motorcycle, and as the wind howls and I grip Gavin's waist, I feel transported to the past by my memory."
  },
  [406341] = {
    diary_text = "We make it to the planetarium. The squad disperses the crowd, and Gavin and I enter. Gavin foils the criminal's plot, and the shooting starlight is immortalized in our memory."
  },
  [406411] = {
    diary_text = "I was finally almost done with overtime. As I was thinking about how I'll make up for lost time, Gavin suddenly appeared at the elevator, luggage in hand as he whisked me away from the office!"
  },
  [406421] = {
    diary_text = "Before I knew it, we were sitting on a train. I realized Gavin had meticulously planned out this whole \"sneak attack\". He even brought along my work computer...!"
  },
  [406431] = {
    diary_text = "We finally arrived at our destination -- the seaside. Not only did we chill on the beach, but also go sailing. There were some waves, but Gavin navigated them fearlessly."
  },
  [406441] = {
    diary_text = "I lay on the deck with Gavin, enjoying the tranquility and releasing from stress. And Gavin told me that he would do it again if I fell into another stress-vortex."
  },
  [406511] = {
    diary_text = "I came to the road I knew the special ops team was going to come back through and waited for them. Gavin could hardly believe it, but a tender smile showed on his face."
  },
  [406521] = {
    diary_text = "I took Gavin to a city park and had a \"surprise trip\" for a day with him. He asked me if this aviation park was the \"surprise\", but I shook my head enigmatically."
  },
  [406531] = {
    diary_text = "A formerly amazing plane was now just a tourist attraction. Perhaps only the ginkgo leaves remember. Gavin told me about making a model airplane in middle school, which makes me regret."
  },
  [406541] = {
    diary_text = "Back at the bed and breakfast, I gave the little airplane and medal to both 14-year-old and current Gavin. He took the gifts and told me he'd never let me go."
  },
  [406611] = {
    diary_text = "Gavin arrives in my forest, bringing a cake for me like always. Thinking back to when he first came to my forest, I can't help but sigh. When I bring up the matter of succeeding to the throne again, Gavin still seems averse."
  },
  [406621] = {
    diary_text = [[
But to my surprise, this time Gavin suddenly says he's willing to take the throne. However, thinking of the future, he wants to collect various treasures recorded in an ancient tome before ascending to the throne, and get a powerful divine spirit to become his new divine protector. As his current protector, I set out on this journey with Gavin.
In the land of the pixies, Gavin flies me up to the top of the World Tree to get a legendary crystal druse. When Gavin makes a bracelet for me out of some smaller crystals, the fun-loving pixies rush up to wish us well...]]
  },
  [406631] = {
    diary_text = [[
To obtain the next treasure -- a pure gold belt forged by the dwarves -- we came to the land of the dwarves. At a lively market fair, a dwarf loses in a drinking contest to Gavin. But apparently made bold by drink, the dwarf hand-crafts a weapon for his crush and proposes marriage to her.
Gavin is also taken to the fireside by the dwarves and urged to make his own weapon. For some reason, I see a vision of him giving a scepter that he made to me...]]
  },
  [406641] = {
    diary_text = [[
The journey is finished. The treasures are all gathered. Gavin and I return to my little courtyard. Seeing all the myriad treasures laid out before us, and thinking about how Gavin would go find a new divine protector -- and even seek out a maiden to be his queen -- I felt a pang in my heart.
But Gavin did not depart from my courtyard. Instead, he placed all the treasures we'd collected before me, then told me his true aim in undertaking this journey...]]
  },
  [406711] = {
    diary_text = "Gavin's colleagues entrusted him with looking after a Husky who had found his way into the police station, and I excitedly proposed that we take him for a walk together. Filled with delightful expectations of the adorable dog, I met the Husky, Leapy, for the first time."
  },
  [406721] = {
    diary_text = "Our first meeting was a little rough as he continued to ignore and reject my attempts to connect..."
  },
  [406731] = {
    diary_text = "Learning from each failed interaction and guided by Gavin's careful instruction, I slowly gained some experience in handling the dog. After successfully training Leapy to follow me, I became overly excited and accidentally let the leash slip from my hands, losing my balance..."
  },
  [406741] = {
    diary_text = "True to the nature of a Husky, Leapy immediately disappeared from view. Despite our extensive search, we couldn't find him anywhere. However, this mischievous little dog eventually turned up in a place we least expected."
  },
  [406811] = {
    diary_text = "When Gavin came to my place, I vented to him about my unlucky streak. To comfort me, Gavin asked if I wanted to get something to eat, and I immediately thought of this recently popular fortune-telling cafe."
  },
  [406821] = {
    diary_text = "When we arrived at the cafe, it wasn't even afternoon tea time, yet the place was packed. After seeing several girls at a neighboring table having a lively discussion about their fortunes, Gavin and I delved into the topic as well."
  },
  [406831] = {
    diary_text = "The owner revealed to us the secret of how coffee augury can change their customers' fortunes—by putting flowers into their memories. After trying it once, I seemed to get how it worked."
  },
  [406841] = {
    diary_text = "Gavin and I promised that if either of us were unhappy, we would do something right away to make the other feel better. We would be flowers in each other's memory, forever fresh and blooming and swaying in the breeze."
  },
  [406911] = {
    diary_text = "I'm on a joyride with Gavin on some roads he used to drive often. We're enjoying ourselves when the car suddenly makes strange noises. Gavin gets out to check and says it's not major. We can keep driving. Nearby there also happens to be a familiar repair shop, so we can go take a break there."
  },
  [406921] = {
    diary_text = "At the shop, we discover no one's there. Gavin says the owner must be out on business. After talking with the owner, Gavin decides to do some \"self-service\" repair."
  },
  [406931] = {
    diary_text = "Gavin has me help, so I become his little assistant. I hand him tools, but also cajole him into playing with a little puppy, \"Beanie\". As everything's almost finished, I suddenly tell Gavin there's one more thing I can help him with."
  },
  [406941] = {
    diary_text = "We wash the car together, and I ask if he's pleased with my help. He gives me a surprising answer..."
  },
  [407011] = {
    diary_text = "In order to transfer intel, Gavin and I came to Loveland City disguised as a newlywed couple and made initial contact with our target, a foreigner named Booker. One day, he visited us unannounced."
  },
  [407021] = {
    diary_text = "We invited Booker to a cocktail party scheduled in three days, and he accepted. After he left, I checked the gift he had brought and found to my surprise a well-hidden bug!"
  },
  [407031] = {
    diary_text = "Under the guise of delivering coffee, I went into the study to warn Gavin, who was in the middle of sending a telegram. After searching the study, I felt relieved. At that moment, my clothes caught on a rouge-box bracelet in Gavin's pocket. Looking at the rouge box, I recalled that many years ago Gavin said he would give me something like this if I wanted. A faint blush came up my face..."
  },
  [407041] = {
    diary_text = "The party took place as scheduled on the evening of July 6. Despite a series of mishaps, Gavin and I accomplished the mission and helped our colleagues complete the intel transfer. By the time everyone had left and there were only me and Gavin in the villa, he took out the bracelet and put it on my wrist while telling me that..."
  },
  [407111] = {
    diary_text = "With a show deadline breathing down my neck, I received a call from Gavin. Maybe he could help me deal with the pressure. But after hesitating, I still decided not to tell Gavin..."
  },
  [407121] = {
    diary_text = "The racing team Minor arranged for me had a last-minute substitution, and it was Gavin of all people! My surprise was tinged with guilt. I was out of sorts after burning the candle at both ends for a few days. When I snuck off to buy coffee, I was snatched up by Gavin..."
  },
  [407131] = {
    diary_text = "Due to an accidental injury, Gavin became an official team member. As training progressed, I also ran into trouble with filming. In my restless state, Gavin proposed taking me for a late-night spin so I could experience racing first-hand."
  },
  [407141] = {
    diary_text = "After racing the course with Gavin, I understood winning was the core of competition. The competition was heated on the day of the race, but Gavin pulled off the victory. He said he had more courage and strength because I was there. His being there gave me support and hope too."
  },
  [407211] = {
    diary_text = "I had been living in Felminero for six months. I was supposed to judge Gavin, but gradually lost my mission as I spent days with him. Until one day, the Heavenly Sphere sent an angel to remind me that I had to make the ultimate judgment on Gavin."
  },
  [407221] = {
    diary_text = "Why were Gavin's wings restrained by strange flame spells? Was this because of his fall? I wanted to figure it all out. I headed to Gavin's house but was treated harshly by him in his demon-like form."
  },
  [407231] = {
    diary_text = "I infiltrated the Heavenly Sphere to find out the truth about Gavin's wings but nearly got caught by the Divine Court's patrolling angel. In the nick of time, Gavin appeared and took me away. I told him I was willing to take over his duties and pain, but he firmly refused."
  },
  [407241] = {
    diary_text = "I returned to the Heavenly Sphere and found the way to lift the flame spells. I was willing to become a prison for sin for Gavin. Gavin saved me when I was tortured by the pain."
  },
  [407311] = {
    diary_text = "I wanted to invite Gavin to the New Year Fair at Loveland High School, but he told me that he might have to go to Special Task Force and give a speech at the New Year's Eve event especially held for agents who couldn't go home."
  },
  [407321] = {
    diary_text = "Before New Year's Eve, I went with Gavin to Loveland High School to help the students prepare for the fair. I found out that Gavin actually knew how to perform the lion dance!"
  },
  [407331] = {
    diary_text = "On New Year's Eve, I spoke to Gavin on a video call and shared with him what I had seen on the spot. After the lion dance performance, I was going to return the silk ball to the performer, but unexpectedly, I found my most familiar face..."
  },
  [407341] = {
    diary_text = "The performer was no other than Gavin. This was the surprise he had prepared for me. \"Good things will come when a lion plays with a silk ball.\" He wanted to hand over this auspicious ball to me himself. Under the fireworks and away from the crowd, we held each other and entered the new year together."
  },
  [407411] = {
    diary_text = "Gavin called me saying there was something he needed my help with. When I got to the fast-food place, he hesitated a moment, then broke down and asked if I'd help him polish up a work report."
  },
  [407421] = {
    diary_text = "After carefully reading Gavin's rough draft, I understood what his problem was and helped him revise it."
  },
  [407431] = {
    diary_text = "Time flew by, and when I got home, I learned that Gavin's report was due tomorrow! I was fatigued, but I found the energy to ensure the final draft showed how hardworking, brave, and tenacious Commander Gavin was."
  },
  [407441] = {
    diary_text = "After Gavin delivered his report and came back home, I didn't even have to ask: I could tell by the look on his face that everything went as smoothly as I'd imagined. But I discovered he'd also written something else on the report, and while he wasn't paying attention, I was surprised to find out..."
  },
  [407511] = {
    diary_text = "I was sitting on the couch with Gavin watching a movie and enjoying some well-earned vacation downtime. As I reached for a snack, my hand inadvertently grazed past Gavin's waist, which elicited a few teasing remarks from him. I wasn't having any of that, so as a \"comeback,\" I pinched his waist, which got a reaction from Gavin which surprised me..."
  },
  [407521] = {
    diary_text = "After that day, Gavin's behavior was getting weirder, and he was coming home much later. I thought it was a last-minute mission with the STF, but today I pieced together some clues from social media and realized that Gavin was actually going to the gym behind my back..."
  },
  [407531] = {
    diary_text = "I surreptitiously \"infiltrated\" the gym to find Gavin, but I accidentally blew my cover and was quickly found out by Gavin. Seeing my confusion, Gavin finally came clean..."
  },
  [407541] = {
    diary_text = "Feeling motivated by Gavin, I broke my long workout hiatus and got on a treadmill too, running forward in lockstep with him. As long as it's with him, no matter what we're doing, I don't want to miss out..."
  },
  [407611] = {
    diary_text = "A \"wedding\" was being held at the hotel. Standing quietly in my wedding dress, I listened to the priest read the bride's vows. No one expected Gavin to show up and snatch me from my \"wedding\"..."
  },
  [407621] = {
    diary_text = "Gavin revealed that it was a surprise he had prepared for me for Valentine's Day. Holding up the card that was going to be my \"wedding certificate\" on the show, he said he wanted to finish making it together and make my wish come true."
  },
  [407631] = {
    diary_text = "We took a walk to gather ideas for making the \"wedding certificate.\" When we came to the park, I found another big surprise Gavin had prepared for me! He even said there was a \"wedding\" on the way."
  },
  [407641] = {
    diary_text = "We came to the \"wedding\" venue Gavin had arranged and finished making the \"wedding certificate\" together. As a symbol of our love, we vowed to always help each other fulfill their wishes. Tenderly, Gavin asked me to go through the most romantic tradition at a wedding..."
  },
  [407711] = {
    diary_text = "Seeing me have a hard time falling asleep, Gavin told me some of the cases the Special Task Force had solved. To his surprise, I became even more awake after hearing those compelling cases. Feeling somewhat upset, he made a decision to address my insomnia through other approaches tomorrow."
  },
  [407721] = {
    diary_text = "Gavin told me the next morning that we were going to the Ice Park, and that he had figured out what I really needed after days of observation. My task for today was to have fun and exhaust myself."
  },
  [407731] = {
    diary_text = "At the Ice Park, we chose the sledding project first. I told him I was much more daring thanks to my skiing experience. He made a point of toying with me on the sled ride for this reason. But anyway, I felt reassured with him by my side."
  },
  [407741] = {
    diary_text = "Then we went to a B&B. While playing with a puzzle book, I found myself thinking in a way more like Gavin. He said he was just as much influenced by me in every snippet of his life. Tonight in his arms, I slept like a baby."
  },
  [407811] = {
    diary_text = "When I got up, I discovered that clothes from the balcony had mysteriously vanished, and the soil in the potted plants had been overturned, as though someone had been rummaging through the place. After thinking it over, I decided to leave the matter to an expert. So, I called Gavin and invited him to come over and help me check things out."
  },
  [407821] = {
    diary_text = "Later that night, there was a sound that came from the balcony! With Gavin and I working together, we eventually caught the \"thief\"—but to our surprise, it was a chubby orange cat! He had a bell on his collar, so he clearly belonged to someone. I quickly sketched his portrait and put up a lost cat notice."
  },
  [407831] = {
    diary_text = "The next day, we returned the orange cat to his owner, who thanked us by inviting us to dinner. That's when I noticed they also had a little kitten at home, so I picked up a cat toy and started playing with them. But then, something strange about the orange cat caught my eye."
  },
  [407841] = {
    diary_text = "On the way home, I asked Gavin what made him notice the orange cat's odd behavior. He told me it was because he could understand the cat's feelings. When you cared about someone, you couldn't help but want to monopolize their attention and keep them focused solely on you."
  },
  [407911] = {
    diary_text = "Gavin received a mission to go undercover in a fashion show. The Special Task Force \"invited\" me to help dress up Gavin for the occasion. I seldom got a chance to join Gavin on a mission, so I began to look forward to helping him out on the case."
  },
  [407921] = {
    diary_text = "During the show, the target appeared and began talking to Gavin, seemingly showing his great interest. I couldn't help but imagine Gavin being an actual model. He would definitely excel at the role."
  },
  [407931] = {
    diary_text = "Due to an unforeseen circumstance, Gavin had to become an impromptu model for the show. The sudden turn of events made him feel nervous. Despite his worries, he excelled at the role spectacularly. However, he was solely concentrated on the mission and did not care a single bit about the spotlight that was focused on him. He only becomes his true self when outside of the hustle and bustle."
  },
  [407941] = {
    diary_text = "As the mission concluded without a hitch, Gavin and I found a quiet place to unwind and chat. I jokingly asked him if he wanted to walk on the catwalk again, to which he responded with a conflicted expression. I knew he didn't like these things, but I hadn't realized it was because he had other things that he loved more. Having chosen the best, he will fixate on it with his undivided attention."
  },
  [408011] = {
    diary_text = "Ever since Gavin came home, he had been staying away from me and avoiding body contact. Each time I approached him, he would run away to take a shower. What was up with him?"
  },
  [408021] = {
    diary_text = "After the call with Eli, I set myself a plan. I decided to pretend I was asleep and gave Gavin a massage when he let his guard down. But then Gavin was very resistant. I complained that he hadn't even kissed me since he got home, so he gave me a kiss. But... this kiss seemed to become a bit strange..."
  },
  [408031] = {
    diary_text = "To continue my plan to help Gavin relax, I brought Gavin to a private hot spring resort. But he continued to act strangely, so I was determined to find out what was going on!"
  },
  [408041] = {
    diary_text = "It turned out that Gavin had been forcing himself to be strong for his dream. I couldn't bring myself to grumble against him, because this was who he was. I was willing to stay with him no matter what he faced."
  },
  [408111] = {
    diary_text = "I was sitting on the yacht, brushing up on fishing techniques, when I noticed the Special Task Force agents using a shortcut—Evol—to fish. This piqued my curiosity, and I asked Gavin if his wind abilities could be useful too. He answered not with words, but with actions."
  },
  [408121] = {
    diary_text = "After preparing our gear, Eli invited us to join their fishing contest. I insisted that we not use Evol, and then we got started. But as the sun grew hotter, I couldn't help but seek shade under Gavin's shadow."
  },
  [408131] = {
    diary_text = "While we waited, Gavin told me that fishing wasn't so different from his usual missions. To catch an enemy, you need the right bait and patience. As he was explaining, the bell on the fishing rod rang—we got a bite!"
  },
  [408141] = {
    diary_text = "Encouraged by our first catch, we decided to aim for a bigger one! But as we waited, Gavin received a mysterious phone call and started keeping his distance. After several attempts to probe what was going on, I ended up unexpectedly in his embrace..."
  },
  [408211] = {
    diary_text = "Gavin and I were planning a short vacation when we saw a sunset photo taken by Mr. Keller on an island. Attracted by the scenery, I decided to travel to the island with Gavin."
  },
  [408221] = {
    diary_text = "We arrived at where Mr. Keller was staying and saw the astonishing changes in him. He told us to enjoy our time here as \"the pleasure of lazing around\" had become a rare luxury."
  },
  [408231] = {
    diary_text = "After bidding farewell to Mr. Keller, Gavin and I arrived at the place in the photo with the address he gave us but found no seats available. I wanted to leave when Gavin took me in the opposite direction."
  },
  [408241] = {
    diary_text = "It turned out there was a bonfire party on the beach, which was Gavin's plan B. We blended in and stumbled across the \"blue tears\". Gavin even let me watch an exclusive sunset by the sea, never failing to make my heart flutter."
  },
  [408311] = {
    diary_text = "After a plethora of setbacks, including traffic jams and a long detour, Gavin and I finally arrived at the amusement park, but we were barred from entering because they had trouble verifying our tickets. What a terrible day!"
  },
  [408321] = {
    diary_text = "The queue to the Log Flume is two hours! But thankfully, we were given free ice cream for the trouble. That seemed like the only good news so far today..."
  },
  [408331] = {
    diary_text = "The queue was long and dull. Gavin probably felt the same way. We glanced at each other from across the queues. It was then that I saw a side of him that I had seldom seen before... Suddenly, the line didn't seem that unbearable anymore."
  },
  [408341] = {
    diary_text = "We found the mystery route for the Log Flume! The ride was as exhilarating as the surrounding scenery was beautiful. I suddenly felt like the wait was totally worth it. Gavin and I began looking forward to what else the park had in store for us."
  },
  [408411] = {
    diary_text = "Though the provided venue was not a place to stay away from the scorching heat, Gavin and the special agents didn't slack off for a second. Then I felt a breeze around me..."
  },
  [408421] = {
    diary_text = "The case the Special Task Force was investigating was complicated. Little progress was made after several days of investigation. But I believed they cared less about the result of the competition than getting the case solved for the citizens. I also wanted to do my part..."
  },
  [408431] = {
    diary_text = "I brought some treats for the special agents, only to find Gavin collating the cases alone in the meeting room and having bread as lunch. I felt sorry for him and hoped the videos I shot would show the public the people who served Loveland City quietly behind the scenes..."
  },
  [408441] = {
    diary_text = "New progress was made under Gavin's leadership. I stayed overnight at the venue in order to follow up. Late at night, while I was half-asleep, Gavin came to me, telling me about his \"mission\" and his determination to fulfill it."
  },
  [408511] = {
    diary_text = "At night after our showers, I sat on the bed helping Gavin dry his big wolf tail. Knowing how sensitive his tail was, I didn't hesitate to..."
  },
  [408521] = {
    diary_text = "Gavin and I arrived at a nursery to help the little kids with their tea party. The nursery director used her Evol to make lots of little imitation animals, and she gave two cute bunnies to me. When I proudly showed them off to Gavin, he said that he had a \"little bunny\" too."
  },
  [408531] = {
    diary_text = "The tea party was boisterous, and the kids expressed both like and distaste for the fresh new smells. We ran into a kid who hated broccoli as much as Gavin, as well as a kid who smelled like sea salt just like Gavin..."
  },
  [408541] = {
    diary_text = "When the event ended, Gavin and I took an end-of-day wrap-up photo. When responding to the kids' messages, I asked Gavin whether he likes people based on their scent, and his reply was very affirmative."
  },
  [408611] = {
    diary_text = "After Gavin gave his report, I brought him to an old man he once saved before we went back to Loveland City. Meeting Gavin again had been an emotional moment for the old man. After the joyful and touching moment, we left and Gavin asked whether he could see the cable car that the old man had designed."
  },
  [408621] = {
    diary_text = "We arrived at the cable car, but there was something strange going on with Gavin. He looked both happy and sad at the same time. He expressed his gratitude to me for allowing him to ride on the cable car, but I said he should thank himself instead."
  },
  [408631] = {
    diary_text = "As the temperature dropped, Gavin wrapped his clothes around me and thanked me for the present. Sensing something as I got off the cable car, I witnessed a very special encounter and a subsequent farewell. It was like seeing two similar people walking on completely different paths. After Gavin said he wanted to go home, I smiled and told him there was one more place we needed to visit after we went back to Loveland City."
  },
  [408641] = {
    diary_text = "I arrived at the Special Task Force with Gavin. There were a lot of people already waiting for him in front of his former office. As the clock struck midnight, everyone wished him a happy birthday. Gavin made his wish while in everyone's loving embrace. After the commotion, Gavin and I sat on top of the roof. I wished him a happy birthday as the sun slowly rose."
  },
  [408711] = {
    diary_text = "我和白起一起收拾着给蹲蹲的见面礼，一想到可以见到许久不见的蹲蹲，我和白起都十分期待。谁知这时，我收到了电话，得知蹲蹲不见了。"
  },
  [408721] = {
    diary_text = "根据监控显示，蹲蹲居然是自己打开笼子，叼着饭盆大摇大摆离开的！为了将这只小吃货“缉拿归案”，我和白起一起开始追寻它的踪迹。"
  },
  [408731] = {
    diary_text = "在白起的安慰下，我焦急的心逐渐冷静。根据路边的实时拍照广告屏留下的“线索”，我们也成功找到了脑袋卡在栏杆里的蹲蹲。"
  },
  [408741] = {
    diary_text = "在拍摄节目的公园里，蹲蹲为我和白起叼来两朵小花。在草坪上，我靠在白起的怀抱中，感觉自己也到了最安心的港湾……"
  },
  [408811] = {
    diary_text = "To witness the Moon-Jupiter Conjunction, Gavin and I arrived at the Astronomy Center over the weekend. As we set foot inside, Gavin had to take a phone call from Eli. I was wandering around by myself when a familiar voice called out for me."
  },
  [408821] = {
    diary_text = "It was one of my old love interests, Chandler. I barely remembered much about him as we tried to make awkward small talk. Just as he began asking about my current affairs, Gavin suddenly appeared, wrapped his arm around my waist, and answered the question for me."
  },
  [408831] = {
    diary_text = "After that awkward conversation with my \"acquaintance\", I was amused by Gavin's jealousy. During the tour, I tried to tease him through the Jupiter-shaped ice cream but Gavin spoke what was on his mind."
  },
  [408841] = {
    diary_text = "Observing from the designated spot, we were finally able to witness the marvelous cosmic event. At this memorable moment, I wished that I would always be the moon in Gavin's life. Under my inspiration, Gavin also made a wish—that he can be forever greedy in his desire for me."
  },
  [408911] = {
    diary_text = "As a naval recruit, I get assigned nothing but odd jobs every day. Just as I was trying to keep my spirits up, I happened to hear the news of a suspect in a big robbery case. After successfully getting myself put on prisoner guard duty, I encountered the bounty hunter Gavin on death row."
  },
  [408921] = {
    diary_text = "I attempted to question Gavin about the whereabouts of the stolen tribute. Even though he was on death row, Gavin showed no sign of cracking. In fact, I was the one who ended up on the receiving end. However, through our subsequent dealings, I got to learn more about Gavin."
  },
  [408931] = {
    diary_text = "Because of Gavin's news, the navy destroyed Pardo's arsenal, which led the officer to punish Gavin severely. I asked Gavin about the true story behind this case, but I didn't get an answer."
  },
  [408941] = {
    diary_text = "On Pardo's ship, I saw Gavin again and found the stolen tribute. Now not only was Gavin's name cleared, but he also offered me a job that was hard to refuse."
  },
  [409011] = {
    diary_text = "Today was the day Gavin came back from a business trip and also the day of the STF sports meet that he was competing in. I got up bright and early to find that Gavin was already downstairs waiting for me... After I came down, I discovered he must've fallen asleep, and on a seesaw of all places..."
  },
  [409021] = {
    diary_text = "After playing on the seesaw for a bit with Gavin, we headed toward the STF sports meet, where to my chagrin, I learned that Gavin had signed up for every event so that I wouldn't get bored in the stands! Not only that, Tang secretly signed me and Gavin up for a three-legged race..."
  },
  [409031] = {
    diary_text = "After accompanying Gavin to the registration table, I wrote a cheer for Gavin and did my best head cheerleader impression as I cheered him on from the stands. As I watched him win event after event, I couldn't help feeling proud of both him and myself."
  },
  [409041] = {
    diary_text = "As time passed, the medals hanging around my neck multiplied. It was now time for the final event: our three-legged race. Before the race, I told him why I never stopped cheering for him..."
  },
  [409111] = {
    diary_text = "Because the STF organized two months of closed field exercises in a remote city, I decided to go visit Gavin on their day off. Gavin, however, refused my request to visit out of concern that I'd find the journey out there long and hard. But I still missed him too much, so I came out to the field exercise base in secret."
  },
  [409121] = {
    diary_text = "Reunited with Gavin, I was surprised to learn that he had given himself a day of extra training on the rest day. I was worried he'd wear himself out, but he still talked me into promising to let him complete the final exercise."
  },
  [409131] = {
    diary_text = "As I watched Gavin complete 400 crunches, I hastily used everything I brought to make a comfortable chair. Then I told Gavin I started learning to cut hair just so I could help him cut his."
  },
  [409141] = {
    diary_text = "As I cut Gavin's hair for him, he accidentally fell asleep. I knew he was exhausted, and I was also surprised to find that he was covered with scars. I told Gavin that I'd be worrying about him from now on, and he told me that actually, my coming there provided him with a soothing feeling."
  },
  [409211] = {
    diary_text = "After Gavin's been away on a mission for over two months, the first phone call I got regarding him was actually—\"Not good!\" After I rushed to the STF and saw the situation, I went back home with Gavin. Seeing him struggling under the surface, I proposed a little game."
  },
  [409221] = {
    diary_text = "Our \"temper liberation\" game started. I had Gavin pretend to be a willful person and not suppress any thoughts as he planned everything for a holiday."
  },
  [409231] = {
    diary_text = "Gavin took me to a B&B in the mountains where we went for a stroll and stargazed in the forest. Gavin also faithfully followed the rules of the game."
  },
  [409241] = {
    diary_text = "After our holiday was over, Gavin and I chatted off and on outside the shower room. I told Gavin that even though he'd start work again tomorrow, he shouldn't go back to his old self. After I gave him some ideas for himself, he decided to check the progress of his \"liberation\"."
  },
  [409311] = {
    diary_text = "As soon as I arrived in this storied village, I was held captive by villagers in the old River King mansion. They seemed to be planning to use me as a sacrifice to the River King. As I was thinking of a way to escape, a mysterious youth suddenly appeared."
  },
  [409321] = {
    diary_text = "The young man's name was Gavin. He untied my binds and said he knew a secret passage leading out of here and could help me escape. Only half-trusting him, I followed him to the passage, where I unexpectedly saw a historical record about the River King."
  },
  [409331] = {
    diary_text = "The villagers discovered my escape attempt and blocked the passage exit. Gavin promised he'd get me safely out, at which point I became vaguely aware of what made him different. After some hesitation, I told Gavin that I was willing to completely destroy this sacrifice ceremony with him."
  },
  [409341] = {
    diary_text = "My binds were broken, but the thrallworm in my body still needed to be transferred. While Gavin helped me do that, we had a memory-meld, and I experienced his entire past. After I woke up, Gavin told me he wanted to have a future with me in it."
  },
  [409411] = {
    diary_text = "On Saturday morning, Gavin went out to play basketball as usual, but he came back a bit late. While we ate lunch, he suddenly put in a request with me, saying that tomorrow he also had to go to practice because he would be playing for our district in a city-wide tournament...!"
  },
  [409421] = {
    diary_text = "When I got to the court, I saw a group of people practicing intensely. While the group made a big to-do out of it, Gavin introduced me to the members of the team."
  },
  [409431] = {
    diary_text = "In a break between drills, I heard the team tell a story of Gavin's playing recently, and I realized Gavin had never told them what he does for work. Guessing that this was probably a little world Gavin was keeping separate for himself, I needed to keep the secret too."
  },
  [409441] = {
    diary_text = "After determining what to practice next, soon Gavin and I were the only two left on the court. We chatted on the court, and as the sun set, I obliged Gavin's request and gave him some \"encouragement\". Even though they lost the game in the end, Gavin was still happy—and he was ready to play in next weekend's tournament."
  },
  [409511] = {
    diary_text = "I took part in a New Year check-in event hosted by a review app in order to win a planetary model for Gavin. Just as I felt at a loss for the New Year celebration, Gavin told me that he already had something planned out."
  },
  [409521] = {
    diary_text = "After a long journey, Gavin and I arrived in Greenwich. We had breakfast on the balcony before falling asleep in each other's arms, preparing ourselves for the next part of the journey. However, we were awoken by a rude and annoying noise..."
  },
  [409531] = {
    diary_text = "Gavin and I visited the Prime Meridian. It was at that moment I realized how bothersome the check-in event was. I decided to turn off all notifications and focus on enjoying this wonderful trip together with Gavin."
  },
  [409541] = {
    diary_text = "As night fell, Gavin and I returned to the hotel. Just as I was preparing to welcome the new year on the balcony, Gavin suddenly lifted me into the night sky! As the New Year's bells tolled, he told me why he took me here to Greenwich. As I stared into his solemn and gentle gaze, I wanted to tell him that I would share my days and nights with him from this night until my last day."
  },
  [409611] = {
    diary_text = "我在家准备大扫除，寄养在我家的三只小猫却不停捣乱，无奈之下，我只好向白起发送了一条求救短信。"
  },
  [409621] = {
    diary_text = "白起很快赶过来，并说要帮我驯服这三只小猫，然而在特遣署无论多皮的警犬都能成功驯服的白Sir，面对这三只小猫时，却意外遭遇了滑铁卢……"
  },
  [409631] = {
    diary_text = "白起决定启用Plan B——用猫草的吸引小猫的注意。虽然策略成功了，但是由于小猫们太过兴奋，和白起一个冲撞后将猫草洒了他一身，三只小猫顺势把白起当成了“人形猫草”，黏在他的身上又踩又蹭……"
  },
  [409641] = {
    diary_text = "就在我有些疲惫的时候，白起却通过接连的尝试，成功用逗猫棒引起了小猫们的兴趣，在向我说明使用逗猫棒的诀窍后，白起还使坏地对我做了一个“恶作剧”……"
  },
  [409711] = {
    diary_text = "While on a mission, Gavin texted me, saying he might make it back in time for the holiday. Just after midnight, as I was starting to get hopeful, the familiar sound of a motor echoed outside. The person who had been silent on the phone suddenly appeared in front of me..."
  },
  [409721] = {
    diary_text = "After a brief moment of tenderness, Gavin had to return to the Special Task Force to deal with follow-up work. Unable to sleep, I decided to add something to our date plans. But before long, Gavin reappeared with the season's first snowfall, and we decided to start our \"Valentine's Day\" early. However, while making cotton candy, Gavin casually said something to me..."
  },
  [409731] = {
    diary_text = "Those three words made my heart race, leaving me somewhat bewildered. I wanted Gavin to experience this heart-fluttering sensation too. I prepared some romantic props and took him to the Love Tree in the square, ready to confess my feelings. Just then, the street lights went out. I felt a bit down, but Gavin said he thought the atmosphere was just right..."
  },
  [409741] = {
    diary_text = "Riding on Sparky, he whisked me through the city. With the confession looming, he too seemed nervous. As dawn approached, we earnestly and solemnly said those three words to each other, words that had long lingered in our hearts..."
  },
  [409811] = {
    diary_text = "When we got to the countryside manor, he told me I wouldn't be bothered by anyone here. But I was convinced this place was just far from crowds—if I did a web search, I'd still be able to see stuff... Gavin laughed and said he forgot to bring a phone charger, so we needed to save our battery."
  },
  [409821] = {
    diary_text = "I instantly understood what he was up to. I made up my mind not to let him down, so I started to ration my phone's battery, the first step of which was to put all social media apps away. However, later I still accidentally saw some bad news..."
  },
  [409831] = {
    diary_text = "Actually, the best way to get rid of a bad mood was to hug and kiss the person you love... and after I did just that, I felt like the entire world was gentler. Then, Gavin proved his tried-and-true method with concrete action..."
  },
  [409841] = {
    diary_text = [[
After a little "horsing around", I was cheering right up. Even though my phone was almost out of battery, I didn't even mind...
Just one conversation made me briefly remember those days of feeling locked down by stress. Just as I was feeling "suffocated", Gavin helped me his way and allowed me to completely unload my burden.]]
  },
  [409911] = {
    diary_text = "I had no idea Gavin's grandmother's home was near the ancient town we were touring. Seeing the look of nostalgia on Gavin's face, we decided to go revisit his old stomping grounds tomorrow."
  },
  [409921] = {
    diary_text = "We didn't go overland, instead, we got on a boat and went by river. On the way, the captain said that thanks to a philanthropist putting in a road, the village has had a lot of development. For some reason, upon hearing this, the look on Gavin's face seemed a little strange..."
  },
  [409931] = {
    diary_text = "In the home of Gavin's childhood friend, I saw photos of Gavin when he was little, and they were so cute!! I never would've guessed how angelic he looked as a kid—no wonder he grew up to be so handsome ^_^ Brian, who had saved the picture, agreed to let us borrow them so we could have them scanned. I really can't thank him enough!"
  },
  [409941] = {
    diary_text = "It turns out, the person who funded the village's road was none other than Gavin's dad... Why did he hide his contribution and treat the people he loved with cold indifference? Neither Gavin nor I could understand this kind of \"love\", and we made a promise to always show our loving sides to each other, and to make sure we both always felt loved."
  },
  [410011] = {
    diary_text = "While skipping class and wandering the streets, I found myself blocked by another group of people. I never really understood why others kept picking fights with me, but I didn't mind; it was a way to pass the time. After the fight, dazed and exhausted, I thought I recognized a familiar road..."
  },
  [410021] = {
    diary_text = "Going to school felt like a loud and boring routine. I wasn't sure why I kept coming back, but I did, like I was driven by some unspoken promise. People either feared me or whispered about me behind my back. Despite that, a sports department teacher approached me one day, asking me to join the school basketball team."
  },
  [410031] = {
    diary_text = "That teacher was relentless, and in frustration, I ended up ditching class again. As I wandered off, I started wondering if I could actually make it onto the team. Just then, another group of people confronted me, more aggressive than before."
  },
  [410041] = {
    diary_text = "I was confused and angry when I got accused of hitting a teacher. It felt like no one could hear me or care about the truth. At that point, the school, the basketball team—none of them seemed to matter. Standing alone on the rooftop, I found myself facing yet another person who had come to see me..."
  },
  [410111] = {
    diary_text = "Today, Gavin looked worried, and when I asked, he explained that he had been asked to speak at the closed-door training and share his expertise with others! And he wanted my help. As his plus one, I was excited and agreed to join him at the training center..."
  },
  [410121] = {
    diary_text = "Life at the training center was more fun than I expected, with great facilities and accommodations that really impressed me. Amid the structured daily routines, I got to see a different side of Gavin—the model student..."
  },
  [410131] = {
    diary_text = "As the day of his lecture approached, Gavin was wracking his brain for ideas, and as his plus one, I was right there to help. We spent nights together in front of his laptop, making sure he was ready. I couldn't wait for him to take the stage..."
  },
  [410141] = {
    diary_text = "Right after the training, Gavin didn't waste a moment to take me into the air and start our vacation. The vast blue skies and the sound of the waves promised many more moments to celebrate together..."
  },
  [410211] = {
    diary_text = "After a solid thirty hours of traveling, Gavin and I were relaxing in our hotel bed. But after not long, a phone call disrupted our brief peace. Seeing the serious look on Gavin's face, I got a vague feeling that something bad had happened..."
  },
  [410221] = {
    diary_text = "Apparently, the evil organization of human traffickers and organ sellers had put out a bounty on me on the dark web... I didn't want to drag Gavin into this, so I first proposed we go back to Loveland immediately. However, he said the sooner we settle this, the sooner we rest easy. He also knew how important tonight's talk was for me, so he would make sure this got taken care of."
  },
  [410231] = {
    diary_text = "With long-distance support from the STF, we arrived inside one of Interpol's safe rooms. As I watched Gavin \"preparing\" for tonight's speech and packing firearms of various sizes, I couldn't help but feel like we were in a real-life movie..."
  },
  [410241] = {
    diary_text = "Before the speech began, our enemies showed no sign of themselves. All we could do was proceed to the theater as scheduled. Not long after we set out, though, we were ambushed. Gavin instantly sensed something was up and took me back to the rooftop of the safe room. Soon, the sounds of gunshots and wind mixed into one big hubbub. However, I didn't feel scared because I knew as long as he was there, I was as safe as could be."
  },
  [410311] = {
    diary_text = "I took Gavin to a planetarium that I was an investor in. Today was the day before their grand opening, and insiders could bring family and friends for a tour. In an imitation space capsule, we experienced a \"moon landing\" journey."
  },
  [410321] = {
    diary_text = "Walking through the exhibition hall, Gavin excitedly expounded on a multitude of astronomical knowledge. When we came to the hands-on interactive area, I keenly noticed that we were quite interested in a children's rollercoaster attraction..."
  },
  [410331] = {
    diary_text = "After riding the rollercoaster, I took Gavin to a hidden movie theater in the planetarium not yet open to the public to give him an early viewing of a movie he'd been wanting to see: an outer space film produced by our company. During the climax of the film when the female lead professes her love for the male lead, I leaned in to Gavin's ear and whispered something."
  },
  [410341] = {
    diary_text = "When our day at the planetarium was finished, we went back home. In a room decorated like the Milky Way, Gavin's formal birthday celebration began. The gift I'd gotten for him also left him pleasantly surprised. Under a wall of stars, we were as close as could be, pressing tightly against each other. In this universe for two, he was the most important planet."
  },
  [410411] = {
    diary_text = "恋语市警犬大赛在即，这段时间，白起隔天就会去训练基地帮飞飞稳住状态。我到达时，正好看到了他帮飞飞“加练”的场景。"
  },
  [410421] = {
    diary_text = "为了给飞飞准备赛前补给，我和白起来到了超市选购。趁挑选宠物用品的时机，我偷偷为白起买了一个小礼物……"
  },
  [410431] = {
    diary_text = "比赛当天，我和白起前往现场。在艰难的挑战前，飞飞表现得格外勇敢。赞叹之余，我也从白起口中听说了飞飞此前的经历。"
  },
  [410441] = {
    diary_text = "比赛结束后，我和白起将飞飞带回训练场洗澡，拿出了给它的奖励。在玩具面前，飞飞忽然表现得调皮起来……"
  },
  [410511] = {
    diary_text = "Although I had my doubts, I followed Eli to a wellness center. After seeing Gavin there, I calmed down. To my surprise, as soon as Gavin saw me and Eli, he instantly saw through Eli's plot and retaliated."
  },
  [410521] = {
    diary_text = "I followed Gavin back to the room where we both got some things off our chest, after which he agreed to stay and recuperate here. He showed me around the wellness center, and our days became simple and carefree. Just when I was thinking the rest of our days here would be just as peaceful, someone knocked on our door."
  },
  [410531] = {
    diary_text = "As requested, we came to the office of Director Mencken. Director Mencken came right out and told us about Gavin's condition. I had overlooked those hidden injuries completely all this time. Apart from shock, I felt incredibly sorry for him..."
  },
  [410541] = {
    diary_text = "Gavin went along with the arrangement and underwent therapy and rehabilitation exercises. When I saw his body recovering due to the rehab, I realized more and more how many \"unavoidable\" aches and pains he had lived with on his own. When night fell, I couldn't contain my emotions anymore, and just then, there was Gavin standing before me..."
  },
  [410551] = {
    diary_text = "Gavin threw himself more and more into his rehab exercises. This afternoon, he snuck me out to a little room by the sea where he displayed his interior decorating progress. We were planning to amuse ourselves here all afternoon. Noticing how intense the ultraviolet rays were, I took out some sunscreen for Gavin..."
  },
  [410561] = {
    diary_text = "During this brief stretch of rehab training, Gavin's health improved through science and through proper technique. He shared the things that he had come to understand over this time. After listening to his true feelings, I couldn't resist the urge to give him a kiss..."
  },
  [410611] = {
    diary_text = "During our trip to Europe, Gavin and I found some really tasty milk pastries in the hostel that we were staying in. Seeing how much I enjoyed them, Gavin suggested that we should find the store that made them."
  },
  [410621] = {
    diary_text = "We embarked on a journey aboard a scenic train ride, taking in the breathtaking views along the way. In my intention to tease Gavin, I inadvertently discovered how much he knew about me."
  },
  [410631] = {
    diary_text = "Despite our prolonged efforts with our hand-drawn map, our quest seemed to lead nowhere. Just as I began to feel a mix of frustration and disarray, Gavin suddenly picked me up and flew into the air..."
  },
  [410641] = {
    diary_text = "With the help of Gavin's Evol, we finally found the pastries that we were looking for. It was at that moment that I revealed to Gavin the true motive behind my desire to find them..."
  },
  [410711] = {
    diary_text = "On the way to Hannah and Ally's wedding, Gavin was in a cheerful mood and started \"spilling the tea\" about the couple with me. Sensing how much he cared about this marriage of his good friends, I also started to take it seriously too."
  },
  [410721] = {
    diary_text = "After we got to the hotel, we realized the folks from the STF were all already there, and I took a big group photo for them. In all the rowdy commotion, I also offered my well-wishes to the bride and groom."
  },
  [410731] = {
    diary_text = "The wedding ceremony was overflowing with happiness and touched the hearts of every guest present. When the newlyweds were about to make a toast, Gavin wished them happiness and also made a promise."
  },
  [410741] = {
    diary_text = "At the reception at the end of the wedding, I unexpectedly heard something cute and fun about Gavin from Tang's lips. As downy feathers fluttered down from above, I heard his profession of love on the wind."
  },
  [410811] = {
    diary_text = "After Gavin finished the Nuo opera rehearsal he was doing for work, he and I were planning to take a stroll around the Tujia tribe settlement. But right when we walked outside, we were tightly surrounded by lots of people and cameras..."
  },
  [410821] = {
    diary_text = "To avoid public notice, Gavin and I put on disguises before going out again. At first, I thought we'd enjoy a carefree day, but after river rafting, we attracted people's attention again."
  },
  [410831] = {
    diary_text = "On the day of Double Seventh, Gavin's Nuo opera performance was a huge success. When we talked about how we both immediately spotted each other in the crowd, both of our minds went spontaneously to memories past..."
  },
  [410841] = {
    diary_text = "With our brush with \"internet fame\" behind us, that night Gavin brought me to a campfire singing and dancing session with Tujia tribespeople. Although we were separated by the group, Gavin still somehow managed to return to my side. He led me away from the group and lit a fire for just us two..."
  },
  [410911] = {
    diary_text = "Before the competition, Gavin and I ran into Black in the rendezvous hut, who had quit the team because he looked down on me. Gavin deftly hit back at his doubts, and I felt totally determined to prove myself in the match."
  },
  [410921] = {
    diary_text = "The chemistry between Gavin and me helped our team take back control of the match. Just when we were putting away the losers' gear, Black's squad came driving toward us from a distance..."
  },
  [410931] = {
    diary_text = "We took a brief mid-match break in the treehouse. Gavin's encouragement gave me strength again, and after we discussed our strategy going forward, Gavin actually left the vast majority of the ammunition with me..."
  },
  [410941] = {
    diary_text = "After a nail-biting contest, Gavin and I won the championship! Gavin said that my outstanding performance was all due to myself, not because he \"carried\" me. I also wanted to tell him that with him there, I had no fear whatsoever."
  },
  [411011] = {
    diary_text = "I was in the chapel awaiting Gavin's return from completing another mission of revenge. At that time, the Seven Nations ganged up and toppled our kingdom, slaughtering its people. Having lost all his subjects, Gavin took vengeance against the kings of the Seven Nations, one after another. He would take their heads back to the Chapel of the Goddess of War as a sacrifice to his departed people. As of now, there were only two people still left."
  },
  [411021] = {
    diary_text = "Back then, the Northlands was a self-sufficient place that kept its distance from warring nations. Gavin and I once slipped out of the chapel into the spring sunshine and attended a post-hunt fair. The streets then were lively, the people were merry, and he had a tender smile when he looked at me..."
  },
  [411031] = {
    diary_text = "After resting in the chapel, Gavin went storming off again toward his next revenge target. This time, after he left, one of the former invading kings led a large troop into the ruins of the Northlands..."
  },
  [411041] = {
    diary_text = "Gavin was about to embark upon his final revenge. The adversary was the villain behind the destruction of the Northlands, and also the country with the strongest military. When it looked like everything was coming to an end, I prayed that Gavin could return safely..."
  },
  [411111] = {
    diary_text = "Gavin and I were playing Aeroplane Chess: Love Edition at home, and he finally moved onto one of the challenge spaces. I was giddy with anticipation. Faced with a challenge to \"make your partner laugh in under one minute\", Gavin actually chose a joke that..."
  },
  [411121] = {
    diary_text = "A surprise text message made me realize that Gavin's behavior had been a bit mysterious lately. And so, I prepared a sumptuous feast and planned to sneakily fish for information while he was watching the ball game, but it didn't go as I'd hoped."
  },
  [411131] = {
    diary_text = "After finally finishing a busy day at work, I discovered a vacation resort brochure that Gavin had hidden in the house. Realizing this possibly had something to do with Gavin's recent secret, I decided to launch a surprise inspection."
  },
  [411141] = {
    diary_text = "The resort was a surprise he'd been planning to give me for a long time. When I was reluctant to leave here, Gavin said he had already taken out a long-term lease on it. We could go vacation there whenever we wanted. He always takes those things I used to fantasize about and helps me turn them into reality..."
  },
  [411211] = {
    diary_text = "At a party, Gavin—who had now become \"new money\"—asked me to have a dance with him. He suggested we play Russian roulette, with his reward being to be my only guest at my next party."
  },
  [411221] = {
    diary_text = "The party just for Gavin started. After seeing all the huge changes in the house, we realized that there was a huge gulf of time between us now. As we talked, the conversation naturally veered toward old poems we used to like..."
  },
  [411231] = {
    diary_text = "With Gavin, I never seemed able to put up a pretense, but could we really go back to the way things were? Just as I was feeling down about this, Gavin suddenly made an unexpected gesture."
  },
  [411241] = {
    diary_text = "Gavin took me cruising around New York at night, showing me what he's been doing these past years. I came to his home, and together we lingered on the hopes and love we had for each other. All of the hope-filled prospects of this era lay at our feet."
  },
  [411311] = {
    diary_text = "早早来到香薰馆的我遇见了一款很适合白起的香水，正在我挑选之际，白起悄然出现在我的身边并拿出了一对情侣围巾。在被香气与温暖的包裹之中，我们短暂的假期开始了。"
  },
  [411321] = {
    diary_text = "白起拿起我刚才给他挑选的香水，我却忽然想和他玩一个猜香游戏。在他不断猜测谜底的过程中，我们之间的距离也靠得越来越近……"
  },
  [411331] = {
    diary_text = "在街上逛了很久的我们忽然感觉有些冷意，白起提议可以去街边的奶茶店取暖，却意外发现这里卖的本土饮料味道相当苦涩。在舌尖淡淡的苦味中，我们似乎品尝到了别样的甜蜜。"
  },
  [411341] = {
    diary_text = "来到今天行程的最后，在雪坡上白起告诉我这里能闻到“雪的味道”。半信半疑的我听完了白起的解释，在彼此逐渐靠近的距离中，我好像明白了这个有关幸福传说的真相。"
  },
  [411411] = {
    diary_text = "With Chinese New Year's approaching, it was coming up on one month since Gavin rushed off on a mission. Suddenly, a malicious news story connected to him made a big splash. At the same time, I felt from time to time like I was being watched, making me uneasy. I went to the STF for help, but I walked into an ambush and got taken to a warehouse by the kidnapper. Little did I expect, when I looked up, I saw someone I'd recognize anywhere..."
  },
  [411421] = {
    diary_text = "I guessed that this man looking exactly like Gavin was someone Eli mentioned before... a dangerous person codenamed \"Snipe.\" However, as I matched wits with him, I got a faint feeling that something was fishy..."
  },
  [411431] = {
    diary_text = "I instantly recognized the man before me, and I knew that he knew too. As we stared silently at each other, neither of us broke. It was only through a kiss that we communicated our thoughts and worries. I knew that Gavin was out on a limb, and since I was here now, I had to do what I could to help him."
  },
  [411441] = {
    diary_text = "With Gavin's plan still moving along, he took me to a bar which was apparently the turf of someone named \"Big Ben\". He extended an invitation to Big Ben as a setup to some bigger ploy, but I could also clearly tell that he was under extreme pressure... Even if only a little bit, I hoped I could help him relax for a moment."
  },
  [411451] = {
    diary_text = "To my surprise, \"Snipe\" brought me straight back home. I guessed that he hoped to ensure my safety as much as possible and also not wear me out or worry me too much. Half-jokingly I checked on his physical condition, and I also saw the uneasiness and paranoia he had been keeping under wraps, but I told him—I had absolutely no regrets."
  },
  [411461] = {
    diary_text = "On the eve of Chinese New Year, I was tied up by Snipe as part of a ploy with Big Ben and thrown in a place where a \"rat\" was imprisoned... The moment I finally saw him, I realized the whole scope of Gavin's plot and his faith in me. With the operation a success and Chinese New Year's Eve fireworks rattling off in the background, my beloved returned safely to my side with a firm, loving embrace."
  },
  [411511] = {
    diary_text = "I got a call from Eason, who had helped me out in the past, telling me that he needed someone to step in and salvage the quickly foundering Lantern Festival Gala. Although I wanted to enjoy a peaceful holiday with Gavin, I couldn't ignore the favor I owed Eason. Just as I was debating, Gavin said, \"I'll skip work and go with you.\""
  },
  [411521] = {
    diary_text = "When we arrived, Gavin smoothly led me to the motorcycle he had prearranged and drove me to the venue. On the way, I couldn't help but ask him how he explained his absence to his team. Before he could answer, my phone buzzed with a call from Eli..."
  },
  [411531] = {
    diary_text = "I quickly dived into the job, while Gavin made a habit of dropping me off at the venue each day and exploring the city on his own. On the fourth day, during an outdoor shoot, I caught sight of Gavin nearby. Seeing him standing there patiently, I felt bad for keeping him waiting so long. When I apologized, he simply smiled and said that he liked waiting for me."
  },
  [411541] = {
    diary_text = "That day, we wrapped up a few hours earlier than planned. I quickly changed into a dress and rushed to find Gavin, not wanting to keep him waiting even a minute longer. When I finally found him, we embraced in a field of blooming flowers. With a flower in his hand, he invited me on a date, and I couldn't have been happier... A week later, we returned home. After a phone call, Gavin turned to me with a playful smile and expressed his desire to skip work again."
  },
  [411611] = {
    diary_text = "白起特意带我去家具店挑选窗帘，只因为我前段时间无意间的一次吐槽。看他如此上心，我决定把今天的逛街权交给白起，而在逛了一圈后，他带我走进了正在举办宠物联动的手工店。"
  },
  [411621] = {
    diary_text = "进门后我们抽选了要合作的小猫，却发现它的名字也叫做“小黑”。这份意料之外的缘分让我们格外欣喜，可小黑无精打采的样子同时也让我们有些担忧。"
  },
  [411631] = {
    diary_text = "在白起细心的接触下，我们终于发现了小黑有些抗拒人类的原因。同时我们也决定为它量身打造一套“蜘蛛服”，而就在完成服饰之后，我却收到了白起的“惊喜”。"
  },
  [411641] = {
    diary_text = "拍合影的时候小黑显得格外活泼，多亏了白起的建议照片才顺利完成。结束后我们相约下次再来看小黑，而白起也袒露了自己制造惊喜的过程。"
  },
  [411711] = {
    diary_text = "After the last wave of influenza, I decided to exercise more and asked Gavin, who was on vacation, to play basketball with me. My skills got better with his help, and I managed to learn a few techinques from videos online as well. One day, however, Gavin told me that there was something wrong with those videos..."
  },
  [411721] = {
    diary_text = "I performed some moves from the videos, and Gavin pretty much stopped me immediately. I knew he was a lot better than me, but that didn't stop me from being frustrated. Sensing my mood, Gavin started fumbling here and there to go easy on me, but he was caught red-handed by the area's basketball team..."
  },
  [411731] = {
    diary_text = "Since we couldn't \"play fair\" when it came to basketball anymore, I tried to duel him in a game that neither of us had played. He was still going easy on me, so I decided to provoke his competitive spirit."
  },
  [411741] = {
    diary_text = "And I finally beat Gavin fair and square! I took the prize that I had always wanted while enjoying the fruits of my victory."
  },
  [411811] = {
    diary_text = "我带着导演来到特遣署，看到许多队员都在练习各种乐器，有的人去忙，不需要值班的人都自愿来练习。我调侃白起很少会搞这种折磨人的东西，白起笑了笑，说他想要和这群人一起再多做点什么。"
  },
  [411821] = {
    diary_text = "白起带我来到了准备拍摄的场地，在平台上我们遇见了一位严肃的阿婆，看到她和白起对话的态度，我感觉这个人好像不太一般……"
  },
  [411831] = {
    diary_text = "很快便到了特遣署表彰大会与誓师大会的这一天，在白起先去特遣署进行内部表彰的同时，我先来到了拍摄场地进行最后的演练，并且迎接他邀请的“客人”。下午在一片灿阳中，特遣署新一年誓师大会正式开始了。"
  },
  [411841] = {
    diary_text = "转而十首曲子都演奏完毕，白起进行最后的总述，他诚恳地面前那群退休的前辈们，希望能够得到帮助。在大会结束后，我终于在白起口中明白了这次主题“拾壹”的含义……"
  },
  [411911] = {
    diary_text = "顺利解开“首饰柜消失案”后，我们接下了伯爵夫人发来的新委托——参与贵族小姐辛西娅的晚宴，偷回夫人失窃的蓝宝石项链。这份有些特殊的委托让我们都饶有兴趣，只不过第一次扮演“小偷”的我们，也一时有些不知如何下手……"
  },
  [411921] = {
    diary_text = "我们刚碰巧捡到目标项链不久，庄园中竟发生了凶案！不仅如此，凶手留下的一封“恐吓信”，更是让我和白起有可能成为嫌疑最大的人。在一切暴露之前，我们需要思考一个完全的策略……"
  },
  [411931] = {
    diary_text = "通过调查书房和死者的房间，我们基本掌握了案件真相，也了解了凶手一系列行为的意图。白起大胆决定，我们直接将计就计，诈真凶自露马脚。"
  },
  [411941] = {
    diary_text = "与案件真凶——庄园管家对峙时，对方关键时刻竟一改之前的怯弱，用隐藏的指环枪向白起开枪射击，同时拉动暗道开关，触发了死者辛西娅留下的机关，书房赫然化为一片火海。幸而白起对机关早有预料，迅速反应过来，带我逃离。我们在安全的地方重新梳理起案件前因后果，也逐渐靠近一切的谜底……"
  },
  [412011] = {
    diary_text = "我和黄老板寒暄完走出会客厅，在路过长廊时我注意到在隐秘角落处的一个小神龛，老板则表示他的这个地仙很灵，推荐我也许个愿。但我听起来有点害怕，就先离开了。等我想要联系白起时，一辆重型机车停在了我的面前。"
  },
  [412021] = {
    diary_text = "白起在这里也是因为一件诡异的事，他的同事小郑在上次执行任务后好像在哪里许了个愿，而当任务顺利结束后，他在休假之余决定也顺路去还个愿。没想到前几天还很正常，但突然从某一天开始人就失联了。白起按照他的行动轨迹，最后带我停在一个幽密的森林前。"
  },
  [412031] = {
    diary_text = "森林有些诡异，在我们走进以后甚至光都透不进来。不久后，我闻到了一股很浓的檀香味，但却怎么都找不到源头。而在我们决定离开时，却发现怎么都走不出去了……"
  },
  [412041] = {
    diary_text = "看到斜躺在地上的神龛，我感觉有点头皮发麻，而后甚至莫名出现了一部正在响铃的老旧手机！而白起似乎毫不在意，我们直接通过了这个神秘的消息找到了那个失踪的同事，我问白起会不会真的有什么在注视着我们，他说了自己的想法。"
  },
  [412111] = {
    diary_text = "听说植物园新引进了一批花卉植物，我和白起趁休息日再次来访观赏。白起用新的命名方式 给不同的仙人掌取了名字。我们还看到了珍贵的金花牡丹，让白起燃起想要养花的心思。"
  },
  [412121] = {
    diary_text = "我们在花鸟市场买长寿花花杆回家，白起将它们栽入小花盆中，我抱住他提醒白“花匠”还有一个成员忘记照顾了。温存之刻，白起忽然接到电话，说植物园的金花牡丹失窃了，怀疑是Evolver作案。"
  },
  [412131] = {
    diary_text = "勘测完监控和现场，白起通过嫌疑人名单迅速锁定了嫌疑最大的人。在我的询问下，他解释了怀疑的理由。白起带领警方缉拿嫌疑人，并在嫌疑人使用Evol试图逃离时，果断地将他控制住……"
  },
  [412141] = {
    diary_text = "事件处理完后，白起告诉我小偷偷盗的原因是因为觉得花没有被植物园照顾好，这个理由让我不能理解。得知植物宣传片可能还会继续拍摄后，白起问会不会还邀请他。我开玩笑说他最近只顾得养盆栽，他一把将我抱住，说怀中的我，才是他最最想要养护好的。"
  },
  [412211] = {
    diary_text = "这一天，我被流弹击中，马上要死了。弥留之际，我看到白起走到我面前，想着我这些年来一直靠跟在他身后捡了不少东西，所以打算把我囤积的物资都送给他，可他不要，甚至以为我要谋害他。"
  },
  [412221] = {
    diary_text = "我竟然没死，被人救了下来。正当我准备回到住所时，有人拿着武器就向我袭来，一番对抗后，我发现那个人竟然就是白起！而他一直都知道我跟在他身后，但令我万万没想到的是，他竟然一直在想我什么时候会杀了他……"
  },
  [412231] = {
    diary_text = "当天晚上，白起被一群人围住，让他对斌哥投诚。这些年总是有这样的人来找白起的麻烦，而白起也都用斧头来一一回应。但这一次，我不小心也被牵连了进去，白起得知后，来到电话亭给B区所有人发话。"
  },
  [412241] = {
    diary_text = "这场纠纷还没有结束时，更可怕的战乱再次来袭了。我不由拼尽全力找到白起，但他身上全部都是伤口，似乎马上命不久矣。当然，我也没有好到哪里去……于是在我们都无路可退的时候，我问他有没有想做的事情。他告诉我，希望我杀了他。"
  },
  [412311] = {
    diary_text = "我和白起一起前往户外用品店为山林救援队的朋友挑选慰问礼物，但是在挑选的过程中，我因为过于想要尽善尽美而异常纠结，白起敏锐地觉察出我的情绪，打消了我的顾虑。"
  },
  [412321] = {
    diary_text = "我们来到了山林救援基地，白起的朋友秦队推拒了我的节目邀请，但我意外发现这里竟然是和白起以前曾经来过的地方，昔日恋曲回旋，冲刷了所有繁杂的心绪。"
  },
  [412331] = {
    diary_text = "在“物非人是”的感慨里，我们再逢秦队，他也回想起昔日的缘分，便邀请我参加夜巡，是我拉着白起的手踏上这段新奇的体验，亲身感受这份工作的不易，而白起似乎发现了秦队的“异常”。"
  },
  [412341] = {
    diary_text = "工作结束后，白起带我去深夜的雨林里散步，因此我意外拾得秦队遗失的勋章，一切疑惑迎刃而解。物归原主后，白起向我传达了秦队的感谢，而我却觉得让更多的人看见像白起这样的守护者本就是我努力的方向。"
  },
  [412411] = {
    diary_text = "Gavin took me to a celebration banquet hosted by the National Aerospace Bureau to commemorate a new collaboration with the Special Task Force. A few elite officers were selected to join an upcoming manned spaceflight program. Being able to attend such an occasion at his side filled me with pride."
  },
  [412421] = {
    diary_text = "We soon boarded the Polar Express and officially began our journey to the Arctic. The scenery along the way was breathtaking. As we traveled, I found myself thinking again about the banquet. Knowing his lifelong fascination with the sky and the cosmos, I couldn't help but wonder—was there a part of him that felt wistful, watching others go where he had once dreamed of?"
  },
  [412431] = {
    diary_text = "That night, we watched the stars one last time, knowing it would be the final night sky we'd see before crossing into the Arctic Circle. Outside our window, forests gave way to open tundra. Even in this faraway land, summer filled the world with life. It felt as if, as long as summer remained, everything would stay bright and full of promise."
  },
  [412441] = {
    diary_text = "At last, I brought Gavin to a spot I had carefully chosen in advance—a vast, open field blanketed in wildflowers. Under the soft, endless glow of the midnight sun, with the sky never darkening, I gave him my heartfelt birthday wish."
  },
  [412511] = {
    diary_text = "I recently took part in an event where people took turns shooting short videos about graduations, and I filmed lots of high school students currently gearing up for theirs. As I was stressing over the monotony of the footage I was getting, I realized Gavin had come to wait for me to get out of school. After asking him some questions about graduation, I suddenly realized he'd never had a graduation ceremony himself."
  },
  [412521] = {
    diary_text = "For the film, I came to the beach to scout locations, and Gavin just happened to come too for a reexamination at a wellness center. After the examination, he took me to stay in a hotel with an ocean view halfway up the mountain. As we talked about growing up, I asked him what his high school life was like before he met me."
  },
  [412531] = {
    diary_text = "Gavin didn't answer my question and even became a little sullen, which made me feel a bit regretful and sad. Then, after catching him sneaking looks at me but then averting his eyes, I couldn't help but shout, \"Gavin, this summer, let's be high school students again so you can have another shot at courting me.\""
  },
  [412541] = {
    diary_text = "After discovering that I wanted to learn surfing from another instructor, all of his awkwardness and standoffishness instantly disappeared. It was like he'd come out of hiding as he took me to the water to learn to surf. Amidst the crazy, turbulent waves, he gave me a tender kiss."
  },
  [412551] = {
    diary_text = "Gavin wouldn't hide himself away anymore, and he'd let me know it every time he looked at me. This day, when he took me to a beautiful cave, I got to give him a long-overdue congratulations on graduating. I also beat him to the punch and declared my love for him. In his smile, I heard his declaration of love too."
  },
  [412611] = {
    diary_text = "Lately, everything had been going wrong, and my mood had hit a low point. Hoping a change of scenery would help, I thought spending a quiet day outside with Gavin might lift my spirits, but the rain left us stuck at home. Noticing my gloom, Gavin asked if I could do him a favor..."
  },
  [412621] = {
    diary_text = "It turned out he wanted to reorganize the balcony and living room. We divided the tasks, and I started by sorting through our storage area. That's when I stumbled upon a drawer full of old odds and ends—little things full of memories. I found myself torn: they weren't useful anymore, but it felt wrong to throw them away. Gavin gently reminded me that those memories were already preserved in other ways. Just as I decided to let go, a new sofa he'd secretly ordered arrived at our doorstep."
  },
  [412631] = {
    diary_text = "After setting up the sofa, we rearranged the entire layout of the living room to make room for the newly assembled plant shelf. While placing the potted plants on it, Gavin suggested we put the ones that hadn't bloomed next to the ones that had—maybe the blooming ones could help encourage the others. He said it reminded him of how his teacher used to arrange student seating, and then shared a few stories from his high school and police academy days."
  },
  [412641] = {
    diary_text = "Once everything was in place, I curled up beside Gavin and looked out at our refreshed living room. Feeling happier, Gavin smiled and said that I looked like Thorny when it finally perked up after a long rest. As I took in the new space, it felt like life itself had been gently reset, and in that quiet moment, Gavin leaned in close and told me softly where his energy comes from."
  },
  [412711] = {
    diary_text = "为了探店我提前来到老街的分岔路口，不见白起的踪影，却接到了他的电话。原来他刚结束便衣任务往这边赶来，不过路况不熟要待会才到，听他这么说我决定在电话里帮他指路。"
  },
  [412721] = {
    diary_text = "顺着林荫道来到同事给我的地址，却发现甜品店已经搬走，悻悻然的我被白起拉起了手，尝试在周围找找看。就在回到一开始等他的路口时，我们在街边发现了一个可爱的小狼玩偶。"
  },
  [412731] = {
    diary_text = "在店员的指引下我们成功找到了搬迁后的甜品店，伴随着不断上来的甜品，我也开始拍起了小狼玩偶的照片。可就在不经意之间，我好像察觉到了白起眼神中的某种“异样”。"
  },
  [412741] = {
    diary_text = "在拍摄完照片后，我们享受了精美的甜品大餐。白起看着店铺里有不少人带着玩偶拍照，好奇地问我其中的原因。看着他翘起的发梢，我一边给他解释，心里动了某种“心思”……"
  },
  [412811] = {
    diary_text = "白起这趟出任务回来时，身后跟了一位“小客人”，正是他之前提到的受重伤导致后腿永久性残疾而即将退役的警犬阿旺，我对阿旺表示了友善的欢迎。"
  },
  [412821] = {
    diary_text = "我放下原本正在拼的沙盘模型，陪白起一起先将阿旺在客厅的临时驻扎地布置好了。白起拉着我在沙发边坐下，诉说这几天的思念，接着他也陪我拼起了沙盘，阿旺则在客厅角落窝着。"
  },
  [412831] = {
    diary_text = "许久过去，我们发现阿旺居然不吃不喝且情绪依旧很消沉。白起想了想，下了几个指令，没想到阿旺反而来了精神，我也有学有样地扔出模型让阿旺捡回来，谁知阿旺却一跃而起将我撞进了熟悉的胸膛……"
  },
  [412841] = {
    diary_text = "署里决定将阿旺送去动保机构成为陪伴辅助犬，我和白起一起将阿旺送过去，这些天的相处让我有些不舍，但更让我和白起深有感触的则是这过程中的满足和幸福感，因为陪重要的人做任何事，本身就是一种窝心的慰藉。"
  },
  [412911] = {
    diary_text = "终于到了白起结束调研的日子，我带着下午茶来到特遣署，准备给他一个惊喜。谁知一进门就得知白起竟然在办公室里研究一首儿歌！"
  },
  [412921] = {
    diary_text = "白起告诉我，他受邀参与了派出所的儿童Evol科普活动，但练习主题舞蹈的过程并不顺利。我在帮助他找出问题的同时，也想到了一个更好的主意。"
  },
  [412931] = {
    diary_text = "经过我们的精心筹备，活动当天一切都很顺利，孩子们热情的提问让白起都有些难以招架。然而一场意外让现场的气氛低落下来，这时我准备的“秘密武器”派上了用场……"
  },
  [412941] = {
    diary_text = "活动结束后，我收到了小朋友“表白”的花束。在那之后白起偷偷和小朋友“较劲”，想送我更好的礼物。听着他颇具孩子气的发言，我告诉他，我最想要的礼物，已经在我身边了。"
  },
  [413011] = {
    diary_text = "白起突然新鲜又特别的穿衣风格让我吓了一跳，但据我对他的了解，或许他准备进行什么“特殊行动”。面对我的猜测，他却难得卖起了关子……"
  },
  [413021] = {
    diary_text = "白起轻车熟路地拉着我走在路上，好像是在循着什么过去的记忆向前。我们去了各式新奇的小店，在气球门下合照，也在柳部长的怒吼中快乐地跑开了。一切放在白起的身上都好像很特别，但又好像也是他的样子。"
  },
  [413031] = {
    diary_text = "最后我们来到了一个叫“神秘体验馆”的地方，接待的小哥看起来和白起认识。只不过我们还是照常进入了某个小房间进行体验，跨越了各种关卡，在白起走出第一步的时候，我立刻扑了过去，告诉他我也想要更主动一些。"
  },
  [413041] = {
    diary_text = "在离开体验馆后，白起告诉了我他和那个小哥的故事，看着面前的人我满心骄傲和欢喜。我希望他能在我面前是最舒服的样子，还是让他去换了一套更舒服的衣服。在山顶之上，我听到了他曾经留下的愿望。"
  },
  [413111] = {
    diary_text = "Because I was born with an ability to see ghosts, the village people all saw me as bad luck. And so, I was cast into Rushwater River to be wed to a water ghost. When I regained consciousness, I saw a vengeful ghost dressed in red in the Rushwater, but his appearance reminded me of the past."
  },
  [413121] = {
    diary_text = "It turned out our paths had actually crossed when I was younger. This vengeful ghost told me that I was on my last wisp of a soul, and if I didn't want it to be completely snuffed out, I would have to marry him. I gladly agreed and learned his name: Gavin. Then, after that first night, I came to learn of his abhorrence for mortals."
  },
  [413131] = {
    diary_text = "Gavin and I came to the city where he used to live for Double Seventh Festival. We shared fine wine and enjoyed the scenery. I told him about what I wanted out of life, and he seemed to agree. At night, we passed by a horseback archery range, and Gavin suddenly challenged the champion soldier there..."
  },
  [413141] = {
    diary_text = "Gavin wanted me to play music to his sword dancing, so I just did my best and blew on the ghost-summoning flute, attracting countless ghosts and ghouls. Gavin's sword dance was lithe and graceful, winning over the admiration of the crowd. Feeling out of place amid the applause of people and ghosts, we returned to the underworld. It was here that I made a promise to Gavin that from now on, we'd come and go as we pleased between the mortal realm and the underworld, envying no one, either mortal or immortal."
  },
  [413211] = {
    diary_text = "在万圣节的氛围下，我和白起参加了一个沉浸式生存大逃杀。但才迅速闯了几个关卡，就被告知，我们已经刷新了他们店内有史以来最好的通关成绩。万万没想到，这场大逃杀最费时间的地方是在做造型上……"
  },
  [413221] = {
    diary_text = "原以为一切要就此结束，工作人员告诉我们这场游戏有额外的通关奖励——入场荒乐园的派对之夜！但由于我和白起的成绩远远超出平日玩家通关的平均时长，所以现在的乐园里并没有其他人，就连游乐设施也暂不开放。"
  },
  [413231] = {
    diary_text = "虽然没有开放设施，但我们意外发现了这里的“潜规则”。游乐园里潜伏着各种捣蛋鬼，我们要给对方糖果，才能停止捣乱。但最让我没有想到的是，今夜最大的捣蛋鬼就近在眼前……！"
  },
  [413241] = {
    diary_text = "我们彼此打闹了一阵后，游乐园仍然冷清。可是白起却有了什么想法，以他自己独有的方式带我在这里玩遍了一整夜，原来……除了游乐园有能够实现任何愿望的神奇力量以外，白起也同样有这样的力量。"
  },
  [413311] = {
    diary_text = "我和白起来到了位于北欧的驯鹿部落中，这里的一切都显得新鲜有趣。在雪地上试驾驯鹿雪橇时，这里的驯鹿对我发起了“突然袭击”，幸好关键时刻白起镇住了它们……"
  },
  [413321] = {
    diary_text = "试驾完驯鹿，我驾驶着雪地摩托，载着白起在雪原上尽情飞驰。当我们回到驯鹿园时，碰到一只格外狂野的驯鹿，白起帮助汉森制服了它，收获了一枚“鹿小弟”。"
  },
  [413331] = {
    diary_text = "平静的部落生活令我和白起十分自在，这天我们得知暴风雪即将到来，而我们的“鹿小弟”失踪了。我和白起决定在风雪来临前找回它，但中途的意外让我们只能选择分头行动。"
  },
  [413341] = {
    diary_text = "暴风雪提前到来了，我和白起只能靠着对讲机微弱的信号联络。当信号断开时，我竭尽全力为白起指引方向，帮助他穿越风雪平安归来。我知道，无论风雪多大，我们总能一起度过，直到天晴雪霁。"
  },
  [413411] = {
    diary_text = "参加了采买体验活动的我们来到布庄，在材质花纹各异的布料里挑挑拣拣。选定了为“久旱逢甘霖”所准备的衣服布料，我们挑选起“洞房花烛夜”的喜服……"
  },
  [413421] = {
    diary_text = "选过布料后，还需要挑选合适的纸张作为“请帖”。过程中，白起似乎格外中意一款撒着金箔的红纸，不知道这种纸藏着什么特别之处呢？"
  },
  [413431] = {
    diary_text = "就算经过了长久的挑选和比较，我们还有近一半的物品没有挑选。事到如今，我才意识到这个活动可能并没有看起来这么简单。察觉到我隐约的退缩念头，白起直接提议，我们先休息一会儿……"
  },
  [413441] = {
    diary_text = "没有了活动的束缚后，白起带我一间间重新走过每家店铺。由我们自己为自己筹备一场“喜事”。喜欢的东西环绕身边，喜欢的人则把最盛大的惊喜送到了我面前……"
  },
  [413511] = {
    diary_text = "元旦将至，我和白起却在一南一北的两座城市出差，距离相隔甚远。得知白起准备来找我，我提议去位于我们中间的一座小城跨年。"
  },
  [413521] = {
    diary_text = "抵达小城后，我们首先来到地下服装市场选购御寒的外套。当服装店老板报出虚高的价格时，不想做冤大头的我本想拉着白起离开，却没想到他不慌不忙地跟老板讲起价来。"
  },
  [413531] = {
    diary_text = "由于网络上鲜有小城的攻略信息，我和白起选择在夜晚的街头随便走走。这时，我们偶遇了一个卖蛋烘糕的小摊。面对恩爱的摊主爷爷奶奶，我仿佛也看到数年之后白发苍苍的我们。"
  },
  [413541] = {
    diary_text = "在零点到来前，白起带我来到一座废弃的摩天轮商场。我们一边享受美食，一边畅想着在小城里的生活。当远处的烟花冉冉升起时，白起为我点燃一束烟火，告诉我不论时光如何变幻，我们永远不会改变。"
  },
  [413611] = {
    diary_text = "下周，白起特别喜欢的一个球队要来C市打一场邀请赛，我抢到了门票，正在美滋滋做攻略，却听见了一个噩耗——球队，被淘汰了？"
  },
  [413621] = {
    diary_text = "票都买了，该去看的比赛当然还是得去。去看比赛的路上，我察觉到了白起的沮丧，但我有信心，能让他变开心起来！而我们开心第一站，就是先去当一个纯粹的观众感受氛围吧！"
  },
  [413631] = {
    diary_text = "进入比赛场馆后，我们便被竞技的气氛感染，不过我看中的却和白起不一样，是另一支队伍。我俩小小的当了一下“临时对家粉丝”，互相呐喊加油，手却一直是紧紧牵在一起的。"
  },
  [413641] = {
    diary_text = "大喊了一整场后，我俩都又饿又累，打算去吃一顿宵夜，白起感慨说虽然他没能看到A队很可惜，但这一点遗憾早就被我好好弥补了，他也真正的并不在意了，毕竟和我一起看比赛这件事，就是最快乐的。"
  },
  [413711] = {
    diary_text = "特遣署某个队员家的小猫失踪了好几天，正好白起结束任务来找我，顺便带着我一起寻找失踪小猫的踪迹。"
  },
  [413721] = {
    diary_text = "我们沿着蛛丝马迹在小区门口的街道一路追查，最终锁定了嫌犯小猫的最后出没地点——街角面包店！"
  },
  [413731] = {
    diary_text = "我们将找到的名叫芝麻丸的带回了家暂时代管，白起动手为它搭了一个简易的猫爬架，它似乎很是喜欢，玩性大发，却不小心一脚踩空……"
  },
  [413741] = {
    diary_text = "关键时刻，我冲过去接住了芝麻丸，而白起则接住了我和小猫，我们双双倒在了沙发上，干脆抱着闯祸小猫原地躺倒，享受起悠闲时光。"
  },
  [413811] = {
    diary_text = "在失忆后，我日复一日地照料温室里的植物，只是梦境深处，总有一个男人的身影萦绕心头。趁着“天空庆典”期间，我决心碰碰运气去寻找记忆的碎片，却撞见了意外的危险，还有梦里的他……"
  },
  [413821] = {
    diary_text = "那个男人告诉我，他是曾经和我一起旅行的冒险家，名叫白起。他将我的“精灵之心”交给我，试图让我恢复记忆，可是我却怎么样都无法吸收它，于是他带着我重新回到了梦幻岛。"
  },
  [413831] = {
    diary_text = "我和白起一起四处寻觅着旅途的记忆，我的梦境一天天变得清晰，我对白起也愈发在意。可当我以为，我的记忆会在这样的宁静生活中一点点复苏时，危机却在悄悄逼近……"
  },
  [413841] = {
    diary_text = "解决危机后的一天，我照顾多年的蓝槿树终于要开花了。我和白起坐在树下聊起各自的心绪，他将精心准备的琥珀挂坠送给我。伴随着他坦率而直白的话语，我的记忆终于苏醒。精灵簇拥着我们飞入云海，所有的画面都像梦一样美好。但我知道，这不是梦，而是新的开始。"
  },
  [413911] = {
    diary_text = "这次行业培训的选址风景优美、课程不忙，我在期待之余，也为要和白起分开一周而依依不舍。"
  },
  [413921] = {
    diary_text = "即使是偏远的市郊，白起也挤出时间飞到了我的窗外。既意外又在意料之中的见面，给往后的几天都增添了一丝雀跃。不过更值得心跳加速的是，白起似乎参加了羽毛球比赛……"
  },
  [413931] = {
    diary_text = "只一张照片完全不足以寄托思念，好在赢了比赛的白起又出现在我面前。不妙的是，一见面就被他发现了我偷偷熬夜的证据……"
  },
  [413941] = {
    diary_text = "因为想亲眼看到白起认真打球的样子，我们决定对打一场。起初和风细雨，但他一直没有忘记对我熬夜的“惩罚”，战况愈发激烈。好在最终，白警官作了一个可爱的弊……"
  },
  [450111] = {
    diary_text = "The first scene Gavin and I encountered when we entered a VR game world was an intel station set up by NW in Loveland City! Seeing such a secretive place in the virtual world made me uneasy."
  },
  [450121] = {
    diary_text = "It was the first time we met since the \"Eternal Winter\" incident. Gavin's casual clothes gave me an illusion of familiarity and I was just relieved to see him safe and sound. Unexpectedly, shortly after our separation, we met again in a VR game center."
  },
  [450131] = {
    diary_text = "We found a certain connection between the game world and reality, and we were experiencing a case that had really happened. Gavin had an unusual charm when he was calmly solving the case with his amazing logical reasoning. After completing the mission, a new one followed. When Gavin flew me over the cliff, I saw my imaginary snowflakes in the sky!"
  },
  [450132] = {
    diary_text = "We found a certain connection between the game world and reality, and we were experiencing a case that had really happened. Gavin had an unusual charm when he was calmly solving the case with his amazing logical reasoning. After completing the mission, a new one followed. When Gavin flew me over the cliff, I saw my imaginary shooting stars in the sky!"
  },
  [450141] = {
    diary_text = "We arrived at a training ground after we landed, and met the young Gavin who was still under training three years ago. I learned about the transformation lab from his snarky squadmates. Somehow, we ended up in the lab from back then. I became sentimental as I heard Gavin talking about his past again. We wanted to leave the game but we couldn't. Only did I know that Gavin wasn't here by coincidence, was here for Evolver."
  },
  [450151] = {
    diary_text = "Before me was Loveland High School with all my memories. I overheard a conversation about a fight involving off-campus students, and the boy who was betrayed and beaten up was actually young Gavin! Both \"Gavin\" worked together, found the betrayer, cleared the air and made peace. Young Gavin brought us to the rehearsal hall. He turned out to be the owner of the game center! In the end, Gavin took the star which was the key to completing the mission and brought me out of here."
  },
  [450152] = {
    diary_text = "Before me was Loveland High School with all my memories. I overheard a conversation about a fight involving off-campus students, and the boy who was betrayed and beaten up was actually young Gavin! Both \"Gavin\" worked together, found the betrayer, cleared the air and made peace. Young Gavin brought us to the rehearsal hall. He turned out to be the owner of the game center! In the end, Gavin took the star which was the key to completing the mission and brought me out of here."
  },
  [450211] = {
    diary_text = "Our last year's Double Seventh performance was quite a hit. Mr. Keller rounded up everyone involved last year to prepare a happy ending for the audience. Because of this, Gavin and I were on stage together again."
  },
  [450221] = {
    diary_text = "We had to shoot some stills for the new show in between rehearsals, so Gavin and I changed into traditional wedding outfits. The unusual colors and looks created a different air around us."
  },
  [450231] = {
    diary_text = "The photo shoot was not as easy as we thought. To satisfy the photographer's extremely high standards, eventually Gavin took a strand of my hair and tied it with his. The photographer was finally happy with his work, but I was blushing like a tomato and my heart was beating fast."
  },
  [450241] = {
    diary_text = "The performance had started. I was going to read off a letter but somehow there was nothing on the paper. Just when I was about to make a fool of myself on the stage, Gavin said my lines for me. He was always there for me when I needed him the most. There was nothing that Gavin could not fix."
  },
  [450251] = {
    diary_text = "The bride-snatching scene was the climax of the show. Gavin's stunning appearance made my heart skip a beat, and I did not expect that he would add in some improvisation. When the main characters' love story had a happy ending, he \"proposed\" to me on the stage. At the crew's celebration party, he even held my hand and extended a most sincere invitation..."
  },
  [450311] = {
    diary_text = "Gavin was away on a mission. I hadn't seen him since he came to my house late that night two months ago. There had been not a single message from him for a long time. Then I got invited to an engagement party together with Eason. At the party I kept feeling that someone was watching me. It turned out..."
  },
  [450321] = {
    diary_text = "Little did I expect that Gavin would be at the party too. But It seemed that he wasn't there as \"Gavin,\" but someone else. I was relieved at seeing him. I didn't approach him lest I jeopardize his mission. And then, as I was chatting with Eason, Gavin chimed in?!"
  },
  [450331] = {
    diary_text = "In the cramped room, Gavin and I talked about how we had missed each other. As I was about to leave, a knock came on the door. Whoever was it must be onto Gavin about his false identity. Instead of hiding as Gavin told me to, I pushed him onto the sofa to show him that we were in this together..."
  },
  [450341] = {
    diary_text = "We managed to get the intruder to leave us alone. Gavin and I each returned to our positions and continued to do what we were supposed to do. I prayed in my heart that Gavin would get through the mission safely..."
  },
  [450351] = {
    diary_text = "When Gavin told me the mission was accomplished, it felt too good to be true. He took his time telling me the mission objective and how he had bent over backward to achieve it over the past two months. I urged him to get some rest, but he made me lie down on the beanbag with him. Tonight, the man I had been longing for for two months was finally in my embrace."
  },
  [450411] = {
    diary_text = "Gavin led the Special Task Force to successfully solve an international case, and the municipal government gave a special award to him. However, rather than receiving the award after finishing the task, Gavin came directly to my home."
  },
  [450421] = {
    diary_text = "After acknowledging the story, I suggested that Gavin should organize a team building with those stouthearted team members. He thought for a moment and accepted my proposal. I excitedly booked a bar for him."
  },
  [450431] = {
    diary_text = "In the bar, I met the team members, who were different from usual times. Through the conversation with Eli, I knew some old stories about Gavin."
  },
  [450441] = {
    diary_text = "Gavin worried that I might get drunk and stopped me from drinking. However, I had already been a little drunk. I witnessed how elated Gavin was and couldn't help but give him a lot of promise when I began to recall his past."
  },
  [450451] = {
    diary_text = "Gavin said I needed to sober up. He took me to the lounge, and kissed me against the door. His mood seemed to fluctuate because of my words…"
  },
  [450511] = {
    diary_text = "Gavin walked into my ward with a pale face and panicked more than when he got injured. After explaining the situation to him, he decided to move in with me considering my leg injury and my upcoming work situation…！"
  },
  [450521] = {
    diary_text = "The nerve-wracking life of \"cohabitation\" began. My eyes were always drawn to him. No matter what I did, Gavin would always be the first to appear."
  },
  [450531] = {
    diary_text = "For my entry to move forward, I decided to print out the photos in the darkroom myself. But these photos reminded me of the vicious curses. At this moment, Gavin came up to me and found what I had been overlooking all along."
  },
  [450541] = {
    diary_text = "On the way home, we encountered an unexpected attack!? But Gavin calmly worked with his team to seize the criminal. After resolving the matter, Gavin somehow became very nervous, perhaps fearing that I would become fearful. But still, he told me things he had never told me before."
  },
  [450551] = {
    diary_text = "I became more absorbed in my entry, which I knew was an opportunity hard to come by. After all the shooting was over, I took Gavin to where the shooting took place and gave a special \"speech\"..."
  },
  [450611] = {
    diary_text = "Bearing an imperial edict, I arrive at Camp Sparrow. I happen to run into Gavin coming back from a reconnaissance of the terrain, but he just rides right past me. Just as I start to feel disappointed that he's forgotten his \"old friend\", he turns back and flicks off my fur hat with his horse whip."
  },
  [450621] = {
    diary_text = "I tell Gavin that in half a year, I have to return to the capital under orders to be wed to someone else. Gavin wants to say something, but seeing my polite and formal manner, he ultimately falls silent. As I'm under orders to inspect the army, I settle down to stay in Camp Sparrow. During this time, I see a more authentic and vivid Commander Gavin..."
  },
  [450631] = {
    diary_text = "A rift forms between Gavin and me regarding troop movement plans. I leave the tent in a huff and lead my horse away to vent my frustrations, but I end up being taken by Gavin to Redmoon Dunes. He tells me that this was the site of the Battle of Jade Gate two years ago. I too understand Gavin's reason for forming this risky plan, and Gavin promises he will make it back alive. But when the time comes, I'll have to tell him why I joined the court as an official."
  },
  [450641] = {
    diary_text = "Gavin wins a huge victory, toppling Redtower Palace. I come to Redtower with the army, and in Gavin's tent, I tell him as promised why I joined the court. Gavin also tells me a promise that he made to himself, which is when I finally learn that we long felt the same way about each other."
  },
  [450651] = {
    diary_text = "When the army returns to the capital, the emperor prepares to confer a new position on Gavin, but he refuses, saying that he wishes to guard the border his whole life, as long as the emperor rescinds the marriage edict. The emperor asks me what I think, and with a sure heart I reply that I would go my whole life without marrying as long as he rescinds the edict."
  },
  [450711] = {
    diary_text = "One night, I woke up unexpectedly to find Gavin's side of the bed empty. There he was, sitting by the living room window, quietly sipping beer. Without my asking, he told me that we might need to slightly change our New Year's plans."
  },
  [450721] = {
    diary_text = "Nervous about attending the special banquet, I bombarded Gavin with questions. He briskly sorted everything out and, after I got off work, helped me practice the waltz steps we'd need for the dance."
  },
  [450731] = {
    diary_text = "Shopping for banquet attire together, I stumbled upon a tango outfit perfect for Gavin. He tried it on without protest, seemingly more amenable to my idea after I said those words..."
  },
  [450741] = {
    diary_text = "The day of the New Year's Eve banquet finally arrived. As I followed Gavin around, meeting people and hearing his stories, his recent silence all made sense to me."
  },
  [450751] = {
    diary_text = "Gavin shared his thoughts with me in whispers, and I felt closer to him. Afterward, he whisked me away from the banquet. We found ourselves dancing and laughing freely on the streets, and unexpectedly, rain began to pour, as if to embellish our freedom. Amidst the downpour, we danced and kissed, affirming each other's presence in the most tangible way possible."
  },
  [450811] = {
    diary_text = "Before Loveland High School's renovation, graduates from different years were invited back for a photo shoot in our old uniforms. We were all buzzing with a mix of excitement and awkwardness, reminiscing over our shared memories. After chatting with everyone, I snuck off to the music room and there was Gavin, also in his uniform."
  },
  [450821] = {
    diary_text = "Seeing Gavin again was a mix of shock and joy. Maybe it was the old uniform or the way the sunlight hit his face, but for a moment, I felt sixteen again. The innocent boy I knew back then was once again standing in front of me. Tucked away in a corner, we playfully did all the little mischiefs we'd never dared to do back then."
  },
  [450831] = {
    diary_text = "I went back to the classroom for the group photo. When we were done, I saw Gavin waiting outside the classroom, just like old times. Ignoring curious stares, he grabbed my hand, and we wandered around the school. Eventually, we found ourselves near the library where we rediscovered the Byron's Poetry we'd both borrowed once."
  },
  [450841] = {
    diary_text = "Talking about the past, I imagined us studying together. Hand in hand, we walked around, leaving our mark on this school building before it changed forever. Back in the classroom, I fixed Gavin's shirt button and told him how I felt. After I was called away by the teacher, I heard his heartfelt words."
  },
  [450851] = {
    diary_text = "Gavin's confession made my heart flutter. On the rooftop stairs, I finally gave him my answer. After all these years, we finally shared those unspoken feelings."
  },
  [450911] = {
    diary_text = "当我在包间看到白起的时候，我便明白自己肯定是被当作了用于要挟他的“软肋”。此时与宴的其他人还试图用场面话向白起施压，我却非常明白这场聚会表面的太平，即将到此为止了……"
  },
  [450921] = {
    diary_text = "白起利落地收拾了那些人后，便急切地带着无辜卷入的我离开了。路上他告诉我，他什么也不能回答我，但其实我更好奇的是，他今天这样不管不顾保护我，会不会将自己推向更危险的位置……"
  },
  [450931] = {
    diary_text = "没想到白起竟然将我带到了一处灰色组织的“老巢”，将我托付给了一个神秘的女人兰姐。其间，我也暗暗地窥见在这些领域极具统治力的他的模样，而白起与她的交易似乎也暗藏杀机。"
  },
  [450941] = {
    diary_text = "在白起的任务进行到紧要关头时，兰姐“左右逢源”，想将我的这个“弱点”再度推至白起的谈判桌前，当我听见白起正在为之努力的事情后，我也决心绝不会允许任何人让他低头！"
  },
  [450951] = {
    diary_text = "复杂的清剿逐渐告一段落后了。我虽然没有正面问过任何事情，却明白眼前的白起会逐渐走向更高更难以裁决的领域里，思绪间，他却主动坦白了想法，并送给我一份特别的礼物……"
  },
  [460011] = {
    diary_text = "我穿过枪林弹雨，在废墟与烈火之中，眼里只剩下那个在战壕里鼎力支撑的白起，他看到我时，只觉得异常不可思议，我告诉他是因为我等他太久太久了，才忍不住找来的……"
  },
  [460021] = {
    diary_text = "思念如同混乱地带的战火一样，永无停息。白起的身上遍布各色严重的伤痕，却因为环境恶劣只能进行最基础不过的包扎，可当我心痛地抚上他的胸膛时，一把意外的尖刀却穿我而过。"
  },
  [460031] = {
    diary_text = "我揉着发麻的心脏醒来，眼前是苍白的病房，而白起正静静躺着，任凭周遭的医生一次又一次的抢救。其实梦中的任务早已顺利结束了，可是他却因此陷入重伤，而我只能选择最危险的、也是唯一的办法……"
  },
  [460041] = {
    diary_text = "在一片意识的虚无地，我在黑暗中大声地寻找着白起，此时的他离我是如此遥远，我看见了最强大的他对自己的叫嚣，他清醒而痛苦的模样让我也甘愿放弃一切，只想呆在有他的地方就好，不论生死……"
  },
  [460051] = {
    diary_text = "随着他狠下决心，某种巨大的欲望在他的世界里缓缓升起，连带着让我也在他的记忆里看见得以了他受伤的瞬间，我无从得知他究竟是靠着如何的意志力一步步坚持下来的，但是幸好，他回来了。"
  },
  [460061] = {
    diary_text = "醒来后的白起迅速康复着，一切像是没有发生过一般，那些细碎而普通的美好如约铺满了我们的日常，只是，他还有很多在意的事……"
  },
  [490211] = {
    diary_text = "I failed in my first exorcism mission. When Gavin heard about it, he asked if I would like to be his partner. At this moment, a special firework suddenly rose in the distance."
  },
  [490221] = {
    diary_text = "Gavin and I rushed to where the firework rose and found a pufferfish monster. I helped Gavin to subdue it, but the pufferfish monster didn't do any harm, so Gavin eventually freed this innocent being that accidentally intruded Serenos..."
  },
  [490231] = {
    diary_text = "We came to the Royal Occultist's Guild to record the new strange beings we encountered today. In the secret building where the exorcism records were kept, I saw many records about Gavin, who always seemed to be alone."
  },
  [490241] = {
    diary_text = "In the secret building, Gavin told me about an incident he had when he felt the need of having a partner. After it was all over, I told Gavin that I would always be his partner."
  },
  [490311] = {
    diary_text = "When I was on patrol, I confronted a demon and got muted by his poison. I then bumped into Gavin back in Royal Occultist's Guild, and he promised to take revenge for me."
  },
  [490321] = {
    diary_text = "Gavin and I retraced my steps and met a Persian merchant who seemed to have seen the demon earlier. But Gavin couldn't understand him. After a long and effortful conversation, we found out that the person he saw was me, not the demon..."
  },
  [490331] = {
    diary_text = "We took a break by the river. Gavin then pointed out that autumn was already here. As we admired the view, it felt like we were the only people left in the world..."
  },
  [490341] = {
    diary_text = "We finally captured the demon and obtained the antidote from him. Gavin came back to Three Dreams Quarter with me. I brew him a steamy pot of floral tea to express my gratitude."
  },
  [490411] = {
    diary_text = "I was in the Royal Occultist's Guild flipping through Gavin's work logs and discovered that he has been exceeding the mission quota every day. To give him some time to rest, the Guild and I formulated a \"burden-easing\" plan."
  },
  [490421] = {
    diary_text = "The first step of the burden-easing process was to help Gavin with his missions. I stole Gavin's work log and helped him chase demons. However, doing it all day didn't put a dent in his workload and wiped me out instead..."
  },
  [490431] = {
    diary_text = "Gavin carried my exhausted body back on his back. I told him the second step of the plan was to recruit new hires, but even though the guild put out a notice, they only found a few people. With all these setbacks in easing his burden, I was getting despondent. But Gavin misunderstood me, and thought it was because he wasn't spending time with me lately..."
  },
  [490441] = {
    diary_text = "After the new Royal Occultists took away the rest of the missions, Gavin was \"forced\" to have some downtime. We walked along Ninth Heaven Avenue, and amidst the hubbub, I told Gavin I hoped he'd always have missions to do, both big and small. Meanwhile, he told me that he was at his most relaxed when resting by my side."
  },
  [800111] = {
    diary_text = "I reluctantly went on the one-day date with Shaw. Thinking how everything was his trap, I was even more depressed."
  },
  [800121] = {
    diary_text = "After waiting in the Live House for long, I happily decided that Shaw has stood me up this time. Just as I was ready to go home, I found that the bass player on stage was Shaw?!"
  },
  [800131] = {
    diary_text = "I didn't expect having to be on the lookout on the date and couldn't accept having to do this of course. However, I had to accept this punishment since I lost the bet."
  },
  [800141] = {
    diary_text = "Seeing Shaw painting the graffiti, I was eager to try too. His imposing graffiti looked quite in harmony with my grinning bunny. Suddenly, the city management officers came..."
  },
  [800211] = {
    diary_text = "I finally \"lost my job\" at the antique shop, yet Shaw showed up to bring me somewhere. In our conversation, he mentioned the dragonfly eye bead he gave me the night before. Only then I realized it's no more on the table!"
  },
  [800221] = {
    diary_text = "We tried searching for it along the path we took last night, but ended up at an abandoned filming location. I got a little nostalgic remembering the TV series I've filmed on the set. Suddenly Shaw suggested that we go in and take a look."
  },
  [800231] = {
    diary_text = "We came before a villa, and I shared with Shaw about my previous filming here. The moment I turned to look at him, I found unexpected seriousness in his eyes, and wondered what he thought about..."
  },
  [800241] = {
    diary_text = "It suddenly started to rain as we were about to look for the exit. Shaw said that it was him controlling the weather but I wouldn't fall for that! I was just unlucky. Shaw kicked the door open to avoid backtracking, but something caught my shirt just as we were about to leave..."
  },
  [800311] = {
    diary_text = "Despite all the practice, I messed up on stage... Thankfully Shaw came to my rescue and the performance came to a successful conclusion."
  },
  [800321] = {
    diary_text = "The band decided to grab a late-night meal. When I hurried back from fetching my coat in the waiting area, everyone was gone except Shaw. He said late-night meals were boring and wanted to take me somewhere else."
  },
  [800331] = {
    diary_text = "The central lake mirrored the starry sky. Standing in the cold, I sneezed. He took my hand and warmed up my palm..."
  },
  [800341] = {
    diary_text = "I got back to the B&B with my arms full of snacks. I picked out Shaw's favorites and handed them to him, but he gave me the brush-off. Pissed, I decided to eat the hot pot flavor cakes by myself. Just then, he changed his mind..."
  },
  [800411] = {
    diary_text = "I came up with an excuse to ask Shaw to meet with me. What I didn’t expect was that he wanted to go to the library. I racked my brain and couldn’t figure out why, and he was running late again."
  },
  [800421] = {
    diary_text = "I demanded an explanation on why he was late again. He apologized and promised not to next time. He then leaned closer to tell me to be quiet in the library, which drew the gaze of surrounding students. I ignored him, only to see him taking a stack of books out from his bag."
  },
  [800431] = {
    diary_text = "Shaw loved the antique shore decorated with balloons and ribbons, but he told me that his old man would be outraged if he was alive. This was probably the third time he mentioned his mentor, so I couldn’t help to ask questions to find out more about him."
  },
  [800441] = {
    diary_text = "Shaw demanded a gift from me?! I was accustomed to his shamelessness by now. I took my phone out of my pocket, Shaw even thought I was transferring money to him as a gift. I put my headphone into his ears and played him a song from my phone."
  },
  [800511] = {
    diary_text = "As soon as the flight landed in Loveland City, I received a text message from Shaw saying he'd pick me up. I almost wondered if I had misread it."
  },
  [800521] = {
    diary_text = "To my surprise, Shaw showed up on his skateboard and asked me to treat him to dinner as a reward."
  },
  [800531] = {
    diary_text = "Being swung about on the subway, I fell asleep in a corner encircled by Shaw..."
  },
  [800541] = {
    diary_text = "When we finally got home, I finally relaxed after a long time, perhaps not only because of the smell of home but also because of having him by my side."
  },
  [800611] = {
    diary_text = "After getting off my internship at noon, I wandered into a 330 Bus. When the bus arrived at the platform where Shaw and I once met, I thought there was no way I would see him again this time. But then to my surprise, the bus door opened."
  },
  [800621] = {
    diary_text = "Once again, Shaw sat down next to me, music playing in his earphones. Just as I was looking for something to talk about, thunder rumbled and it began to pour. Shaw and I were stranded in the bus, which had pulled over to the curb. Like last time, he took the initiative to speak."
  },
  [800631] = {
    diary_text = "Under the pretense of an interview, we got to talking and learned more about each other. When the rain stopped and the bus reached its destination, Shaw left behind his transparent umbrella and walked off. Hating to miss out on him again, I caught up to him."
  },
  [800641] = {
    diary_text = "Shaw invited me to take shelter from the rain at the flower exposition on the street. I insisted that I was just trying to give him back his umbrella. Shaw said he thought I was coming for my key—which he found in the bus. He proposed a deal out of the blue, and we exchanged our numbers. A chance encounter turned into something of a date..."
  },
  [800711] = {
    diary_text = "I fell into the hands of bandits when visiting family in a neighboring town. Luckily I was saved, but was my rescuer even human?"
  },
  [800721] = {
    diary_text = "Deep in the mountains I witnessed a very strange scene and passed out in surprise. When I awoke, I was in the house of a man who called himself \"Shaw\". He claimed to be the one who had saved me..."
  },
  [800731] = {
    diary_text = "I stayed at Shaw's house for 7 days and nights to pay off my debt, but just as I was about to leave, he disappeared without a trace... and strange things started happening in the town where he was living."
  },
  [800741] = {
    diary_text = "After the evil was finally driven from the town, Shaw organized a boat for us, and he revealed to me his true identity. I think... it would take me a little longer to get to know him properly."
  },
  [800811] = {
    diary_text = "I went to see Shaw's show at Live House, but then I realized it was a themed night, which meant the audience had to wear specific costumes, so I had no choice but to ring Shaw on the phone..."
  },
  [800821] = {
    diary_text = "In the lounge, Shaw sized me up and said it was the first time he saw someone coming to a show in business attire. I was slightly bothered by my \"inappropriate\" outfit, but then Shaw found a solution..."
  },
  [800831] = {
    diary_text = "During the show, Shaw's charming performance blew the crowd away. However, something happened midway that surprised all of us..."
  },
  [800841] = {
    diary_text = "With Shaw and I working together, the show finally ended smoothly. At night, when we were leaving Live House, a thought suddenly crossed my mind, so I asked Shaw to play just for me..."
  },
  [800911] = {
    diary_text = "I came to Shaw's house with groceries to teach him how to wrap spring rolls, but he said it was boring and smeared my face with flour. After winding me up, Shaw suddenly suggested playing something interesting."
  },
  [800921] = {
    diary_text = "After I vetoed Pop-up Pirate, we finally decided to play Monopoly. After redeeming the card I wanted, I immediately used a card against Shaw, and the penalty was to \"tell an embarrassing story about yourself\"."
  },
  [800931] = {
    diary_text = "I finally convinced Shaw to tell an embarrassing story from his childhood, which made me laugh a lot. Shaw told me it would be my turn next, then it turned out like he said—I rolled the dice and received a penalty. I sneakily moved my token one more space, but then Shaw snatched away my little car."
  },
  [800941] = {
    diary_text = "I didn't expect my punishment to be to \"do whatever the other player tells you to do\". Shaw asked me to close my eyes and listen to his command. I fumbled forward in the dark. To my surprise, waiting for me at the end was Shaw holding a gift box. I opened the gift and found a book titled \"How to Manage Time Efficiently\". Looking at my crossed face, Shaw explained..."
  },
  [801011] = {
    diary_text = "I made a wood carving in a VR game, and really wanted to make one myself. Shaw just happened to call, so I took him to a DIY wood carving place."
  },
  [801021] = {
    diary_text = "With Shaw's intermittent help, I began to actually start carving. I shooed him away after getting mocked by him, but when I needed his help again, he refused."
  },
  [801031] = {
    diary_text = "Shaw asked for a knife and started making his own carving. A boy asked him why he was carving a fish, and Shaw said a fish was full of meaning."
  },
  [801041] = {
    diary_text = "His carving was like mine, a symbol of good fortune. His was soon finished, unlike mine. I liked his carving, and Shaw said I could have it, but there was a catch..."
  },
  [801111] = {
    diary_text = "I hear Shaw's back, so I go to his place, wanting to spend his birthday at a skate park, but apparently he had something come up and isn't home. Where could he be..."
  },
  [801121] = {
    diary_text = "Shaw is actually volunteering at a museum, and is showing around a bunch of little kids! I've never seen Shaw like this. It kind of changes the way I think about him..."
  },
  [801131] = {
    diary_text = "Shaw must truly love history. His eyes sparkle more talking about artifacts than when he's skateboarding or playing bass. After the event, I have a sudden whim, but there's a slip-up..."
  },
  [801141] = {
    diary_text = "Finally at the skate park, I try to show off how much I've improved, but I wipe out. Fortunately, the birthday plans still go smoothly, and I even get an \"unplanned\" gift..."
  },
  [801211] = {
    diary_text = "Shaw came to my place to spend the weekend, and he brought a collar for Chili Sauce—a poodle I was pet-sitting for a friend. However, Chili Sauce saw Shaw as an \"intruder\" in his territory."
  },
  [801221] = {
    diary_text = "The rambunctious Chili Sauce ran off with Shaw's clothes, and a silver accessory fell out of a pocket. Shaw quickly snatched it up, but he didn't look too happy..."
  },
  [801231] = {
    diary_text = "Shaw taught Chili Sauce to recognize symbols on cards and told him which ones he could touch and which ones he couldn't. However, Chili Sauce was a hard nut to crack and grabbed the silver accessory from Shaw's pocket again."
  },
  [801241] = {
    diary_text = "It turned out, this accessory was a gift from Shaw to me. I eyed it carefully and saw that it was very carefully crafted, yet there was no logo anywhere on it. Glancing at the collar Shaw had handmade, I suddenly had a hunch..."
  },
  [801311] = {
    diary_text = "A new group of passengers was about to board the ship. I was making the final preparations in the dining room when, surprisingly, a young man broke in through the window on a plank of wood I had never seen before. What was more surprising is that he was a first-class passenger!"
  },
  [801321] = {
    diary_text = "After getting on board, I learned the young man was named Shaw. Unexpectedly, he asked me to give him a tour of the cockpit. I was going to refuse, but he offered a tempting \"deal\"..."
  },
  [801331] = {
    diary_text = "The more time I spent with Shaw, the more surprises I got. He drew pictures of different landmarks around the world on the walls of my room, showing me how interesting and big the world was. One day, in the middle of a conversation, he asked me to take a day off."
  },
  [801341] = {
    diary_text = "On the day of the Magpie Festival, I changed into a cheongsam I had never worn before. Shaw, who seemed to have come prepared, gifted me a necklace and put it around my neck. When we walked out onto the deck, I found that the party was nothing like I expected—and it was all Shaw's idea..."
  },
  [801411] = {
    diary_text = "Shaw borrowed a vintage wedding dress for me to photograph, and I heard him take a threatening phone call after the shoot. To thank him for his help, I invited him to attend the company's wedding dress party as my companion."
  },
  [801421] = {
    diary_text = [[
Just when I thought Shaw couldn't make it, he showed up on roller skates at the venue and helped me
fend off the unwanted advances of Mr. Fany. I was pleased with his appearance
when a few men arrived at the entrance. Shaw quickly lifted up my veil and hid
with me under the white gauze.]]
  },
  [801431] = {
    diary_text = "When the men rushed over to catch him, Shaw quickly roller-skated across the floor and we worked with the security guards to subdue the bad guys. Shaw wanted to leave early and when I was about to go with him, Mr. Fany tried to interfere. Shaw smiled disdainfully, picked up a bouquet at the entrance, and said to me..."
  },
  [801441] = {
    diary_text = "After we left the venue, I asked Shaw what was going on and asked him to forewarn me of such things as he had just promised in his vows. He teased that he didn't seem to get any response from me, and now he'd like to confirm my answer..."
  },
  [801511] = {
    diary_text = "While I was looking for inspiration, I came across a cat and thought it would be a great idea to add an adorable animal to the video. I decided to follow her, but to my surprise, I ended up finding Shaw in an office preparing food for the cat!"
  },
  [801521] = {
    diary_text = "When I asked him about it, he explained that, as the archaeology department's sole student, he had been tasked with helping out with the promotional video as well. I assumed we both had our eyes on the same cute yellow kitten, but it turned out that his target was actually a fierce-looking gray cat."
  },
  [801531] = {
    diary_text = "It turned out Shaw wasn't just interested in the food. His goal was to lure out the cat named Big Boss by using food to attract the other little cat named Olive, because Big Boss was quite picky and only liked the yellow cat, which made him hard to tame. I suggested that both cats could be featured in the video together."
  },
  [801541] = {
    diary_text = "In the end, Big Boss reluctantly agreed to cooperate with us. I smiled at Shaw, telling him that even though the cat was very wary, the presence of something special could turn it into an ordinary kitten. When I said this, he gave me a look of disdain for the \"traitor\" partner and warned me not to be fooled by purring sounds."
  },
  [801611] = {
    diary_text = "A statue was unearthed at the Gold Sand Site! I raced to the Archeology Institute as soon as I heard the news, then I ran into someone I wasn't surprised to see..."
  },
  [801621] = {
    diary_text = "While we waited for Professor Shear and the institute staff to decide on whether to restore the statue, Shaw took me to the warehouse to see this statue."
  },
  [801631] = {
    diary_text = "I was astonished to find many hidden talents on Westmoon Street. If Shaw hadn't brought me here, I would never have believed that the rice cake shop owner was a craftsman. And I certainly wouldn't have imagined that Shaw was able to make up such stories when he was a child..."
  },
  [801641] = {
    diary_text = "Even though the restoration work was slow, I enjoyed spending time alone with Shaw. The time we spent together seemed to have pulled us closer."
  },
  [801711] = {
    diary_text = "Early one morning, Shaw called me to come to a cafe in the zoo—but he was splayed out on a table sleeping! I slipped in and sniffed his rich, minty aroma. Sure enough, my ears and tail wagged uncontrollably."
  },
  [801721] = {
    diary_text = "When I put on my work uniform, Shaw got a headband and helped me put it on. Pressed close together, his breath got me all stirred up again. Shaw noticed I was \"out of sorts\" too."
  },
  [801731] = {
    diary_text = "When Shaw came back with the day's ingredients, a red panda snuck in the door after him! He snatched an apple from Shaw's arms but was quickly \"thrown\" outside. Soon, the red panda led a bunch of animal friends swaggering into the cafe."
  },
  [801741] = {
    diary_text = "It turned out, this food was for the animals, and so we started making treats. In the process, I kept getting close to Shaw, and I noticed he was like me: his ears and tail always swaying. I thought it was because of our scents, but then Shaw told me he had a cold and couldn't taste or smell a thing..."
  },
  [801811] = {
    diary_text = "On the day of the graduation party at Loveland University. I set about Shaw's birthday surprise by the hillside lake behind the university without telling him. I headed back to the track field to find him but to no avail, when someone grabbed my wrist out of nowhere..."
  },
  [801821] = {
    diary_text = "I bought flowers for Shaw and told him what they meant. I was curious as to what pointers he had given the seniors with their performance but he remained tight-lipped, saying that they'll be sure to rock the stage."
  },
  [801831] = {
    diary_text = "Their performance began, and they'd turned a classical tune into a fast-paced rock song! Shaw pulled me closer to the stage so that I wouldn't miss a thing."
  },
  [801841] = {
    diary_text = "The performance was over, and I brought Shaw to the lake on the hill to reveal his birthday present. His face lit up in surprise just as I'd wished it would. The flowers exuded romance and the night view intoxicated us; I couldn't help but hope for the moment to last until eternity."
  },
  [801911] = {
    diary_text = "最近，一直在筹备的竞标项目宣告失败，不甘心的我决定在家复盘。而豆豆也一直陪在我的身边，直到一声门铃响起，我看了时间，想到应该是凌肖来了。"
  },
  [801921] = {
    diary_text = "之所以把凌肖喊过来，是因为想到上次他和辣条相处得不错，所以最后我用请吃十顿火锅的条件，让他想想办法让豆豆重新打起精神，可他试了几招，发现效果都一般……"
  },
  [801931] = {
    diary_text = "在凌肖神秘兮兮的言行下，我们带着豆豆来到海边。看着辽阔的大海，我的心里却有些不是滋味，毕竟我现在更应该在家复盘，而不是来放松。凌肖似乎发现了我的心思，伸手捏住我的脸颊……"
  },
  [801941] = {
    diary_text = "在和凌肖打闹中，我的心情渐渐地好了起来，而豆豆也打起了精神，十分活泼。这时，我才发现原来我的心情也会影响到豆豆，在我焦虑工作的那段时间，它一直不离不弃地陪在我身边……"
  },
  [802011] = {
    diary_text = "While sleeping in my bedroom, I was startled awake by marauding pirates. No stranger to this, I deftly knocked them out and then interrogated them, but I still didn't get any useful information from them. Just then, Shaw walked in. At first sight of him, the faces of the pirates instantly turned pale."
  },
  [802021] = {
    diary_text = "After dealing with the pirates, we came across a shipwreck on our voyage. Shaw decided to stop and salvage it. Seeing me still struggling over my lost memory, he suddenly took me and dove to the sea floor with me, saying it's to help me find my memory..."
  },
  [802031] = {
    diary_text = "On the sea floor, I recalled a few scenes, and then our ship was attacked by pirates. I fell into the sea again, and when Shaw saved me, I finally recalled the seed of my memories. It turned out what I was looking for was right in front of me..."
  },
  [802041] = {
    diary_text = "Shaw knew all along that I wanted to leave and search for my memory, but in his own way, he told me that he wouldn't let me go. While I crossed swords with him, I ended up venting what was in my heart..."
  },
  [802111] = {
    diary_text = "I received a text from Shaw. He said that he was in big trouble. I rushed to the scene only to discover that the \"trouble\" he was talking about was going shopping for the New Year."
  },
  [802121] = {
    diary_text = "While I shopped with enthusiasm, Shaw seemed to lack any interest. After we were done, I saw a fortune-telling stall while Shaw went to get a drink. The owner of the stall predicted that Shaw and I would have terrible misfortune next year."
  },
  [802131] = {
    diary_text = "With the prediction weighing heavily on me, I secretly bought two beads in a superstitious bid to turn my misfortunes around. On New Year's Eve, I went to Shaw's antique shop to welcome the new year with him. Shaw used his copper coins to predict my fortune for the coming year. To my horror, it still showed that we would suffer misfortunes next year."
  },
  [802141] = {
    diary_text = "Shaw told me of a method to turn my luck around. I did as he told, but it turned out he was just playing with me! I pretended to be mad at him as he took out the steamed sponge cake he made for me personally and wished me good fortune in the year to come. As the bells tolled, we entered the new year together."
  },
  [802211] = {
    diary_text = "我的家门口连续三天都被放了小鱼，我和凌肖通过监控找到了肇事猫大胖，正要兴师问罪时，大胖却不慎掉落鱼池，凌肖只好先去救猫。"
  },
  [802221] = {
    diary_text = "在路人的掺和下，凌肖的救猫行动变得愈发艰难。好不容易营救成功，大胖却又抓了条小鱼，并莫名其妙跟着一辆汽车跑走了。"
  },
  [802231] = {
    diary_text = "经过证实，我们得知原来大胖想和楼上邻居家的猫小咪亲近，这才误送了小鱼给我。感动之余，我决定拉着凌肖为两只小猫牵线。"
  },
  [802241] = {
    diary_text = "我和凌肖带着大胖来到宠物店进行了美容一条龙，蓬松又帅气的大胖果然引起了小咪的兴趣。在小咪被大胖不嫌麻烦的爱意表达所打动时，我才后知后觉地想到凌肖似乎也一直是这么对我的。"
  },
  [802311] = {
    diary_text = "I had been staying at Shaw's place due to work. Unexpectedly, he came home early the day before Valentine's. I hoped he wasn't too surprised by the changes I made to his house..."
  },
  [802321] = {
    diary_text = "Suddenly, Shaw pulled me into the bathroom to \"settle some scores.\" But it ended up with me reading his mind, which made me even more excited for Valentine's Day..."
  },
  [802331] = {
    diary_text = "It turned out Shaw's plan was to take me to a private cinema, where he'd write his paper while I watched the movie. Typical him! But... maybe spending a quiet, comfortable day with him would have its own kind of romance."
  },
  [802341] = {
    diary_text = "Then the movie came to an intimate scene. Professionally, I should have been unfazed, but it still felt awkward with Shaw. That's when he admitted he'd seen the movie before..."
  },
  [802411] = {
    diary_text = "Brimming with anticipation, I knocked on Shaw's door, but he told me he was going out on a last-minute errand! He also said if I wanted to celebrate his birthday, we'd have to do it quick, so I brought along all my \"surprises\" and followed him."
  },
  [802421] = {
    diary_text = "Following Shaw, we came to a tea house. He told me he came here today because the owner had a jade bead he wanted Shaw to pick up. When we got there though, the place was empty. There was just a note on a table saying, \"Please help yourself.\""
  },
  [802431] = {
    diary_text = "The story behind this jade bead had lots of twists and turns, and it turned out to be connected to his teacher. After getting the bead, Shaw put it in my hand so I could feel the weight of history."
  },
  [802441] = {
    diary_text = "With the bead procured, my birthday surprises for him could officially begin! After he picked birthday theme words, I took him somewhere and said... no matter which words he chose, I would make this day the most fun ever."
  },
  [802511] = {
    diary_text = "While I was struggling with a new crime film script, Shaw suddenly sent me this mysterious invitation to a party which he said might spark some inspiration in me. Curious, I decided to go..."
  },
  [802521] = {
    diary_text = "Shockingly, I found out Shaw had disguised himself as a thug and sneaked into the villa! To figure out what he was up to, I pretended I needed a personal bodyguard and kept him close for some \"intense\" questioning."
  },
  [802531] = {
    diary_text = "It felt like Shaw was leading me astray. I knew he was engaging in risky business, but I couldn't resist when he invited me to join him on an escapade in an armory."
  },
  [802541] = {
    diary_text = "Together, we found a warehouse dealing in smuggled antiques. We staged a little drama and managed to nab all the crooks. After the adventure, I got new ideas for my script and even decided to create a special role just for Shaw..."
  },
  [802611] = {
    diary_text = "我和凌肖约好在古董店会和，一起去吃猪肚鸡。却不想凌肖抓到了连续几天在他院子里捣乱的罪魁祸首——一只小黄狗。"
  },
  [802621] = {
    diary_text = "暴雨将我们三个困在了古董店。闲聊中我故意问凌肖如果他要去荒岛，他会带什么人或者什么物件，他数点了一堆答案，偏偏不说出我的名字。"
  },
  [802631] = {
    diary_text = "我们两个人的拌嘴吓到了小狗，看着它的反应，我想起网上的一种说法，便和凌肖逗了逗它。随后他又口是心非地抱着我给我取暖，并分给小黄狗食物。"
  },
  [802641] = {
    diary_text = "第二日一大早，凌肖为我和小黄狗买来了早餐，又一次印证了他的“口是心非”。于是我故意再次问他不肯带我去荒岛的原因，没想到这一次他却说出了心里话。"
  },
  [802711] = {
    diary_text = "Due to work reasons, I was planning to contact an archeology team on the other side of the mountain to see if they couldn't pause their work for a few days. Little did I know this was the team that Shaw was with..."
  },
  [802721] = {
    diary_text = "I not only managed to reach out to Professor Shear about our filming, I also managed to borrow Shaw away from them. Although, perhaps I was imagining things, but it seemed like Shaw got a little jealous when he got to the set and saw the models wearing the tribal clothing."
  },
  [802731] = {
    diary_text = "To my surprise, Shaw had actually prepared a whole set of authentic local garb for us! After getting changed, it seemed like my whole state of mind changed as well. After finishing a busy day of work, he and I \"snuck off\" together..."
  },
  [802741] = {
    diary_text = "We came to a village called Camp One Heart. Shaw and I had both been here before, and we compared notes on all the interesting things we'd discovered. When we both thought we had the other beat, Shaw brought me to a swing I'd never seen before..."
  },
  [802811] = {
    diary_text = "我和凌肖吃完大餐后，走到家附近的公园散步。在花坛边看到了一只饥肠辘辘的狸花猫，便把打包的鱼肉刺身分了一些给它。"
  },
  [802821] = {
    diary_text = "我回家后肚子不舒服，怀疑是刺身不新鲜，担心流浪的狸花猫也因此不适，便和凌肖来到公园找猫，没想到还有“意外发现”。"
  },
  [802831] = {
    diary_text = "气温骤降，我们去看猫时发现母猫状态不好，便把两只猫带到了医院。在安顿好母猫后，只能暂时先将狸花猫带回家，却不想经历了拆家风波。"
  },
  [802841] = {
    diary_text = "凌肖给我展示了他的训猫成果，我好奇方法却被他索要报酬。在聊到狸花猫并不像表面上那么凶后，凌肖的回答也在无意中暴露了他的心意。"
  },
  [802911] = {
    diary_text = "I woke up today and immediately noticed that something was off with Shaw's mood. After some persistent questioning, I finally got him to admit that the reason for his low spirits... was me."
  },
  [802921] = {
    diary_text = "Before diving into Valentine's Day celebrations, Shaw and I decided to prioritize something even more important—securing good fortune for the whole year! So, we stopped by an antique store to pay homage to the God of Wealth, hoping to bring good fortunes into our lives."
  },
  [802931] = {
    diary_text = "Later, at Yen's request, we visited a toy shop to find a replacement for his granddaughter's plushie. While browsing through the shelves, I somehow ended up capturing a red panda's disgruntled heart..."
  },
  [802941] = {
    diary_text = "With our arms full of treasures, we headed home. Nestled in Shaw's embrace while a variety show played softly on the TV, I couldn't help but feel that this simple, cozy moment made for the perfect Valentine's Day."
  },
  [803011] = {
    diary_text = "凌肖居然也有论文写不出来的时候？在他又一次拒绝了我的出门邀请后，我决定——去他家里找他~"
  },
  [803021] = {
    diary_text = "没想到凌肖写不出论文的时候这么低气压，看着他面若死灰的样子，我决定不仅在情感上支持他，还要在论文上也帮帮他……"
  },
  [803031] = {
    diary_text = "原来凌肖是想将文物修复和数学统计结合起来，拯救更多的文物，看到他此刻一筹莫展的样子，我忽然有了灵感……"
  },
  [803041] = {
    diary_text = "凌肖的论文被评优了，这里面可有我的一份功劳哦！听说他今天要在学校讲座里发言，我准备偷偷去给他一个惊喜……"
  },
  [803111] = {
    diary_text = "This year, I delivered happy birthday wishes to Shaw exactly on time! But his reaction was pretty \"meh\". Seeing that I was put off by this, he actually gave me a reasonable explanation..."
  },
  [803121] = {
    diary_text = "I made a deal with him to spend the whole day together, so when he was on stage performing, I had to join in as his assistant. However, his role he was playing seemed... a little particular..."
  },
  [803131] = {
    diary_text = "Having to perform an ancient magic trick, I couldn't help but feel a bit nervous and timid, and so Shaw offered to rehearse with me. I knew it was a simple trick, but his every move had me spellbound."
  },
  [803141] = {
    diary_text = "As the grand finale to today's birthday, I had a trick I wanted to do for Shaw too. However, when I went to run out of the secret passage, the person I held dear in my heart was already there waiting for me..."
  },
  [803211] = {
    diary_text = "Today, another villager came to me to complain about Shaw, saying my disciple was too brash and had the nerve to use people as bait when vanquishing demons. Shaw didn't seem to see it that way though. After all, he was only vanquishing demons in passing. He was really here because he was looking for someone."
  },
  [803221] = {
    diary_text = "As I was tending my garden, Shaw appeared again. This time, I could clearly sense the progress he'd made in Qi cultivation, and he seemed to be taking a liking to me, but between him and me... there had always been a woman in the way: the Faerie Maiden Mystic Crane."
  },
  [803231] = {
    diary_text = "I threw a fit and gave Shaw the \"cold shoulder\" for a month, when suddenly a villager came with a notice. He said that a fell air was brewing somewhere, and when Immortal Master Shaw went to vanquish the demons, he apparently became possessed by a demon aura. As his \"teacher\", the villager hoped that I'd go and rein in this wayward pupil..."
  },
  [803241] = {
    diary_text = "Unable to hide it any longer, I told him that I was in fact Mystic Crane. I had realized that my proclivity for deviant Qi cultivation put me at risk of turning full-demon, and so I disguised myself as a pure and lofty monk to lure in victims—and Shaw had taken the bait. I needed to engage in dual cultivation with him to neutralize the demon aura within me."
  },
  [803311] = {
    diary_text = "才将工作彻底收尾，我就收到了凌肖的“求救短信”。匆忙赶回家后，家中果然一片狼藉。被Fitch寄养在我们家的狗狗是罪魁祸首，它正用这样的方式表达对我的思念。"
  },
  [803321] = {
    diary_text = "原来，想念我的不仅是小布，还有几天没见的凌肖。闲聊中，他提到要带我去露营，享受难得的假期。"
  },
  [803331] = {
    diary_text = "随着凌肖来到郊区河畔，我发现他还准备了全套钓鱼道具。想到去年的海岛假日，我决定再和凌肖进行一次钓鱼比赛。抛下“战书”后，我却始终没有钓上一条鱼。为了赢下他，我搬出灵机一动的“特殊手段”。"
  },
  [803341] = {
    diary_text = "暴雨给比赛划上句号，我们也因此被困在房车里。眼看今晚的烤鱼宴泡汤，我心中觉得可惜。然而，凌肖却抛出了别的补救方案。"
  },
  [803411] = {
    diary_text = "因为某位扮演“相思小姐”的演员同事不太舒服，拜托我去如意镇顶班一天。凌肖虽然对我的玩心很无语，但还是将我送到了园区门口……"
  },
  [803421] = {
    diary_text = "干了没两个小时，我就觉得有点无聊了。还好凌肖提前过来找我玩，不然我都不知道时间怎么熬……只不过他怎么乱改我的人设啊！"
  },
  [803431] = {
    diary_text = "这家伙一不开心就走的毛病什么时候能改改，气死我了！既然同事回来接班了，我现在只想找到凌肖和他狠狠吵一架！但凌肖到底去哪儿了呢？"
  },
  [803441] = {
    diary_text = "看到凌肖穿着婚服要和别人“成亲”的时候，我终于明白了他今天的心情——从一开始就不行，演的也不行，成亲的不可以是别人，喜欢的更不可以是别人！我再也按捺不住，从人群冲出，大声抢亲……"
  },
  [803511] = {
    diary_text = "我收到凌肖的电话后，前往某个南方小镇和他一起迎接元旦。我意外打碎了房里的泥人像，凌肖为了安慰我，送了我一个声称可以辟邪的老银发卡。"
  },
  [803521] = {
    diary_text = "除夕当晚，凌肖送我的发卡意外不知所踪。我和凌肖在寒风中踏上寻找发卡之路，我想起当年他送我蜻蜓眼后又转头藏起来的事，但凌肖说他才不会故技重施......"
  },
  [803531] = {
    diary_text = "凌肖带我到镇上的“鬼市”找发卡。想着他肯定也对“鬼市”感兴趣，我便拉着他一起在里面游逛起来，开心之余，居然真的在某个小摊上看到了我丢失的发卡！"
  },
  [803541] = {
    diary_text = "凌肖为了替我拿回发卡，被鄙夷了继续和老板周旋。我看不得凌肖妥协，想花钱买下来，但凌肖显然有他的计划......"
  },
  [803611] = {
    diary_text = "凌肖这几日忙着整理一批古籍，我们已经将近半个月没能见上面了。在没提出任何预告的情况下，我出现在他们学校的图书馆门口，提出要带他逃离图书馆出门放松。"
  },
  [803621] = {
    diary_text = "我打算用毛茸茸的小动物治愈凌肖的疲惫，于是下午我带他去了猫咖。这家店有特制的员工手册，在翻阅的过程中，我们对一只叫“花生”的小猫产生了兴趣，凌肖还给它取了一个有个人特点的名字……"
  },
  [803631] = {
    diary_text = "花生和我想象中的一样慢热，看它始终对我爱答不理，我有些气馁。向凌肖抱怨时，我注意到他一直在记录我逗猫的每个瞬间。看过他的相册后，我想到这段时间的所有想念，而他也向我袒露了自己最不加掩饰的感受。"
  },
  [803641] = {
    diary_text = "经过一下午的努力，花生终于对我卸下心防！开心花生向我靠近的同时，我意识到离我的心更近的还有凌肖。比起以往，他似乎越来越会表达，我们都在大步闯进对方的世界。"
  },
  [803711] = {
    diary_text = "这一天，准备结束酒馆营业的我，遇到一个上门来“应聘”，可是一看到那条大尾巴，我就想起儿时不太美好的回忆，于是直接拒绝了他……"
  },
  [803721] = {
    diary_text = "但没想到眼前这个人与我那位悔婚的未婚夫都有着一样的特征，就在我认为他们是同一个人时，对方告诉我他叫凌肖，而不是我曾经的未婚夫莱特宁。而他这次过来，是来找我做一笔大生意，但因为各种原因的考量，我提出和他比试比试的提议。"
  },
  [803731] = {
    diary_text = "金钱当道，我最终答应了凌肖暂时入伙的合作。在制定计划的期间，我有一天不小心喝多了，向凌肖吐露了我埋藏多年的心声，也带着多年的悔意和不甘，抓住他的胳膊狠狠咬了下去。"
  },
  [803741] = {
    diary_text = "行动当天，我们顺利拿到了那枚价值连城的宝石，只是不小心触发了机关，在逃脱的过程中，我意外发现眼前的这个人其实就是我曾经的未婚夫。我心里顿时五味杂陈，但也有某一种心绪渐渐明了，于是我做下了一个决定……"
  },
  [850111] = {
    diary_text = "My company had been preparing an album promotion for a rock band. Shaw arrived after my interview with the bassist, Jack. His face instantly stiffened as soon as he saw the bassist. What happened between them?"
  },
  [850121] = {
    diary_text = "I saw the band's old videos and realized that they were bandmates. But Jack's betrayal almost stopped Isolated from attending the most important music festival. I asked Shaw about this, but he told me that he and Jack would settle it with a battle!?"
  },
  [850131] = {
    diary_text = "Shaw's first festival experience was too legendary! Hearing the band retelling what happened made my heart sing. I believed that Isolated would win!"
  },
  [850141] = {
    diary_text = "After the battle started, Shaw asked me to be the accompanist! I played the melody Shaw played at the festival, then Jack forfeited. Despite winning the battle, Shaw seemed blue. When I asked him what his trump card was, he gave me an answer under the hazy light..."
  },
  [850151] = {
    diary_text = "Shaw said he would pay me the lipstick back, so we went out to search for cosmetics stores in the middle of the night and drank a lot of beer. When we went back to Live House, I was a little drunk and laid down to rest on the sofa. Shaw gave me a new lipstick and held me in his arms as he said some heartfelt words..."
  }
}
